module.exports = [{"id":"cat-7a-1-1","title":"第1课 远古时期的人类活动","subtitle":"七年级上册 · 第一单元 史前时期：原始社会与中华文明的起源","grade":"7a","tags":["七年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第一单元 史前时期：原始社会与中华文明的起源"},{"k":"课时","v":"第1课 远古时期的人类活动"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"人类起源于非洲，约三四百万年前出现早期人类。中国境内已发现多处旧石器时代人类遗址：云南元谋人距今约 170 万年，是目前已知我国境内最早的古人类之一；北京人距今约 70 万—20 万年，遗址出土了大量石器和用火遗迹。"},{"type":"note","title":"本课主线 · 因果链","text":"中华文明不是外来传入的：从元谋人、北京人到河姆渡、半坡，再到良渚、陶寺，中国境内的远古人类与史前文化一脉相承，约五千多年前已进入文明社会。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约 170 万年前","元谋人生活在云南元谋","我国境内目前已知最早的古人类之一"],["约 70 万—20 万年前","北京人生活在周口店","会使用天然火、保存火种，过群居生活 · 重点"],["约 3 万年前","山顶洞人","已掌握人工取火与磨制、钻孔技术"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"约 170 万年前","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"元谋人生活在云南元谋","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"约 70 万—20 万年…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"北京人生活在周口店","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"约 3 万年前","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"山顶洞人","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。","explain":"常以「遗址—时间—特征」配对或史料选择题出现。记住「元谋人最早、北京人用火、山顶洞人会人工取火」。"},{"level":"次重点","text":"北京人遗址（周口店）是世界上出土人类化石与遗物最丰富的遗址之一。","explain":""},{"level":"选择题","text":"山顶洞人已会人工取火、磨制骨针缝制衣服，有审美意识（装饰品）。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["中华文明的起源具有**本土性**（元谋人、北京人一脉相承）与**多元一体**（黄河流域、长江流域等多点并发）两大特征。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为北京人会人工取火。","北京人会使用天然火并保存火种；人工取火是山顶洞人。","这是最常见的混淆点，选项常把两者对调。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["遗址配对与图像识读","给出遗址出土的实物（骨耜、彩陶、玉琮）判断属于哪一文化，考「实物—文化—区域」的对应。"],["史料实证：传说与考古","给出传说记载与考古发现两组材料，要求说明二者的关系，落脚在「考古发现是更可靠的依据」。"],["年代尺与时序","把元谋人、北京人、河姆渡、良渚打乱排列，考查时间先后与「距今多少年」的换算。"]]},{"type":"note","title":"跨学科视角","text":"地理：长江流域与黄河流域的气候、地形差异，解释「南稻北粟」与干栏式、半地穴式建筑。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"裴文中","v":"中国考古学家，1929 年发现第一个北京人头盖骨化石。 出处：《中国大百科全书·考古学》"}]},{"type":"list","title":"延伸阅读","items":["周口店的发现：1921 年安特生、师丹斯基在北京周口店龙骨山发现遗址；1929 年 12 月裴文中发掘出第一个完整的北京人头盖骨化石。此后陆续发现 40 多个个体的人骨化石。 出处：中国社会科学院考古研究所《北京人遗址》相关记述","山顶洞人的进步：山顶洞人距今约 3 万年，已掌握磨光和钻孔技术，会人工取火，用骨针缝制兽皮衣服，并制作穿孔兽牙、贝壳等装饰品。 出处：2024 部编版七上第 1 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版七上第 1 课","《中国考古学·旧石器时代卷》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】北京人遗址出土了大量打制石器、成堆的灰烬层，灰烬中有烧过的兽骨和树籽。\n【材料二】良渚古城遗址由宫殿区、内城、外城组成，外围发现由 11 条堤坝组成的水利系统；城内出土大量精致的玉琮、玉璧。\n【材料三】中华文明探源工程提出判断进入文明社会的中国方案：出现城市、出现阶级分化、出现王权与国家。","source":"材料研读 · 史前时期：原始社会与中华文明的起源"}],"questions":[{"id":"h7a-u1-m1-q1","type":"short","stem":"（1）材料一中的灰烬层能说明北京人已经掌握了什么技能？这一发现有何意义？（4 分）","answer":"说明北京人已经会使用火并能够保存火种。意义：火的使用改善了生存条件（烧烤食物、照明、取暖、驱赶野兽），是人类进化过程中的重大进步；周口店遗址是研究人类起源的直接证据。","explain":"","tags":["史料实证","史前时期"],"rubric":["答出「使用火、保存火种」","答出火的作用（取暖/熟食/驱兽任一点）","答出遗址的史料价值"]},{"id":"h7a-u1-q1","type":"choice","stem":"我国境内目前已知最早的古人类之一，距今约 170 万年，其化石发现于今云南省的是","answer":"A","explain":"元谋人发现于云南元谋，距今约 170 万年，是我国境内目前已知最早的古人类之一。","options":["元谋人","北京人","山顶洞人","半坡人"],"tags":["史前时期","时空观念"]},{"id":"cat-7a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 元谋人生活在云南元谋\n② 北京人生活在周口店\n③ 山顶洞人","answer":"A","explain":"按时间顺序应为：①元谋人生活在云南元谋（约 170 万年前）→②北京人生活在周口店（约 70 万—20 万年前）→③山顶洞人（约 3 万年前）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-1-1-g2","type":"choice","stem":"下列关于「远古时期的人类活动」的表述，错误的是","answer":"A","explain":"认为北京人会人工取火——这是最常见的混淆点，选项常把两者对调。正确表述：北京人会使用天然火并保存火种；人工取火是山顶洞人。","options":["认为北京人会人工取火。","北京人会使用天然火并保存火种；人工取火是山顶洞人。","中华文明的起源具有**本土性**（元谋人、北京人一脉相承）与**多元一体**（黄河流域、长江流域等多点并发）两大特征。","北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1921 年安特生、师丹斯基在北京周口店龙骨山发现遗址；1929 年 12 月裴文中发掘出第一个完整的北京人头盖骨化石。此后陆续发现 40 多个个体的人骨化石。（中国社会科学院考古研究所《北京人遗址》相关记述）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"远古时期的人类活动；北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。","explain":"材料出自中国社会科学院考古研究所《北京人遗址》相关记述。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-1-2","title":"第2课 原始农业与史前社会","subtitle":"七年级上册 · 第一单元 史前时期：原始社会与中华文明的起源","grade":"7a","tags":["七年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第一单元 史前时期：原始社会与中华文明的起源"},{"k":"课时","v":"第2课 原始农业与史前社会"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"约 1 万年前，人类开始栽培作物、饲养家畜，进入原始农业时代。中国是世界上最早栽培水稻、粟和黍的国家之一。浙江余姚河姆渡遗址与陕西西安半坡遗址，分别代表了南方水田农业和北方旱作农业的典型。"},{"type":"note","title":"本课主线 · 因果链","text":"中华文明不是外来传入的：从元谋人、北京人到河姆渡、半坡，再到良渚、陶寺，中国境内的远古人类与史前文化一脉相承，约五千多年前已进入文明社会。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约 7000 年前","河姆渡文化（长江流域）","种植水稻、干栏式建筑、木结构水井 · 重点"],["约 6000 年前","半坡文化（黄河流域）","种植粟、半地穴式圆形房屋、彩陶 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"约 7000 年前","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"河姆渡文化（长江流域）","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"约 6000 年前","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"半坡文化（黄河流域）","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。","explain":"这是「南北差异」这条大线索的起点，后面讲经济重心南移时会再回来对比。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["生产力决定生活方式：种植水稻需要水田 → 长江流域的干栏式建筑；种植粟、气候干燥 → 黄河流域的半地穴式房屋。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","记「南稻北粟」，与「南干栏北半地穴」一起记。"]]},{"type":"table","title":"河姆渡与半坡：不同自然环境下的两种史前生活（同一时期（距今约 7000—6000 年）的南北方对比）","head":["比较项","河姆渡（长江流域）","半坡（黄河流域）"],"rows":[["主要农作物","水稻","粟"],["房屋样式","干栏式建筑（防潮）","半地穴式圆形房屋（保暖）"],["生产工具","骨耜","磨制石器、骨器"],["共同点","都从事原始农业、都有陶器、都过定居生活","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["遗址配对与图像识读","给出遗址出土的实物（骨耜、彩陶、玉琮）判断属于哪一文化，考「实物—文化—区域」的对应。"],["史料实证：传说与考古","给出传说记载与考古发现两组材料，要求说明二者的关系，落脚在「考古发现是更可靠的依据」。"],["年代尺与时序","把元谋人、北京人、河姆渡、良渚打乱排列，考查时间先后与「距今多少年」的换算。"]]},{"type":"note","title":"跨学科视角","text":"地理：长江流域与黄河流域的气候、地形差异，解释「南稻北粟」与干栏式、半地穴式建筑。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["河姆渡的干栏式建筑：河姆渡人生活在长江下游，距今约 7000 年。遗址发现大量木构件和榫卯结构，说明当时已建造底层架空、防潮通风的干栏式房屋。遗址还出土炭化稻谷、骨耜和猪纹陶钵。 出处：浙江省文物考古研究所《河姆渡遗址》","半坡的人面鱼纹彩陶盆：半坡人距今约 6000 年，居住半地穴式圆形房屋，种植粟。著名的人面鱼纹彩陶盆出土于半坡遗址，现藏中国国家博物馆。 出处：中国国家博物馆藏品说明；2024 部编版七上第 2 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版七上第 2 课","《中国考古学·新石器时代卷》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u1-q1","type":"choice","stem":"我国境内目前已知最早的古人类之一，距今约 170 万年，其化石发现于今云南省的是","answer":"A","explain":"元谋人发现于云南元谋，距今约 170 万年，是我国境内目前已知最早的古人类之一。","options":["元谋人","北京人","山顶洞人","半坡人"],"tags":["史前时期","时空观念"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"cat-7a-1-2-g2","type":"choice","stem":"下列关于「原始农业与史前社会」的表述，错误的是","answer":"A","explain":"把河姆渡与半坡的农作物写反——记「南稻北粟」，与「南干栏北半地穴」一起记。正确表述：河姆渡→水稻（南方）；半坡→粟（北方）。","options":["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","生产力决定生活方式：种植水稻需要水田 → 长江流域的干栏式建筑；种植粟、气候干燥 → 黄河流域的半地穴式房屋。","原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：河姆渡人生活在长江下游，距今约 7000 年。遗址发现大量木构件和榫卯结构，说明当时已建造底层架空、防潮通风的干栏式房屋。遗址还出土炭化稻谷、骨耜和猪纹陶钵。（浙江省文物考古研究所《河姆渡遗址》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"原始农业与史前社会；原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。","explain":"材料出自浙江省文物考古研究所《河姆渡遗址》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7a-1-2-g5","type":"choice","stem":"「河姆渡文化（长江流域）」发生于","answer":"A","explain":"本课时间轴：河姆渡文化（长江流域）（约 7000 年前）。种植水稻、干栏式建筑、木结构水井。其余三个时间是同一单元相邻课时的事件时间。","options":["约 7000 年前","约 170 万年前","约 70 万—20 万年前","约 3 万年前"],"difficulty":1,"tags":["七年级上册","第一单元","本课练习"]}]},{"id":"cat-7a-1-3","title":"第3课 中华文明的起源","subtitle":"七年级上册 · 第一单元 史前时期：原始社会与中华文明的起源","grade":"7a","tags":["七年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第一单元 史前时期：原始社会与中华文明的起源"},{"k":"课时","v":"第3课 中华文明的起源"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"中华文明并非单一起源，而是在多区域同时孕育、相互交流，最终形成「多元一体」格局。浙江良渚、山西陶寺、辽宁牛河梁等遗址表明，距今 5000 年前后，长江下游、黄河中游已出现宫殿、城墙、大型水利和高等级玉器，进入早期国家阶段。"},{"type":"note","title":"本课主线 · 因果链","text":"中华文明不是外来传入的：从元谋人、北京人到河姆渡、半坡，再到良渚、陶寺，中国境内的远古人类与史前文化一脉相承，约五千多年前已进入文明社会。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约 5300—4300 年前","良渚古城（浙江余杭）","有宫殿区、水利系统与大量随葬玉器——**中华五千年文明的实证** · 重点"],["约 4300—4000 年前","陶寺古城（山西襄汾）","黄河中游的早期国家，与良渚同为文明起源的重要证据 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"约 5300—4300 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"良渚古城（浙江余杭）","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"约 4300—4000 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"陶寺古城（山西襄汾）","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。","explain":"结论要会写：「中华文明具有五千多年的历史，且是**多元一体**、在本土独立起源的。」"},{"level":"重点","text":"炎帝、黄帝被尊为中华民族的人文初祖；尧舜禹时期的「禅让」是推举贤能。","explain":"华夏族的形成与「炎黄子孙」的说法都出自这里，材料题常与考古发现并置考查。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["考古发现是研究史前历史的**唯一可靠依据**；传说（炎黄、尧舜禹）需要考古材料印证，不能当作信史。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把尧舜禹的「禅让」说成世袭。","禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","「公天下」到「家天下」的转折点是夏朝建立，不是尧舜时期。"]]},{"type":"table","title":"中国史前文明与世界早期文明（文明起源的共性与个性）","head":["比较项","中国（良渚、陶寺）","世界（古埃及、两河流域）"],"rows":[["起源时间","距今约 5000 多年","距今约 5000—5500 年"],["地理条件","黄河、长江两大河流域","尼罗河、两河流域"],["文明标志","宫殿、水利、玉器礼制","金字塔、楔形文字"],["共同规律","都诞生于大河流域，以农业为基础","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["遗址配对与图像识读","给出遗址出土的实物（骨耜、彩陶、玉琮）判断属于哪一文化，考「实物—文化—区域」的对应。"],["史料实证：传说与考古","给出传说记载与考古发现两组材料，要求说明二者的关系，落脚在「考古发现是更可靠的依据」。"],["年代尺与时序","把元谋人、北京人、河姆渡、良渚打乱排列，考查时间先后与「距今多少年」的换算。"]]},{"type":"note","title":"跨学科视角","text":"地理：长江流域与黄河流域的气候、地形差异，解释「南稻北粟」与干栏式、半地穴式建筑。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["炎黄子孙","炎帝、黄帝被后世尊为中华民族的人文初祖，中国人常自称「炎黄子孙」。","《史记·五帝本纪》；2024 部编版七上第 3 课"],["涿鹿之战","传说黄帝联合炎帝部落在涿鹿打败蚩尤，是华夏族形成过程中的重要事件。","《史记·五帝本纪》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"黄帝","v":"传说中中原部落联盟首领，被尊为「人文初祖」。 出处：《史记·五帝本纪》"}]},{"type":"list","title":"延伸阅读","items":["良渚古城：良渚古城位于浙江杭州余杭，距今约 5300—4300 年。古城外围有规模宏大的水利系统，由 11 条坝体组成，是中国已知最早的大型水利工程之一。2019 年良渚古城遗址列入《世界遗产名录》。 出处：联合国教科文组织世界遗产中心；浙江省文物考古研究所","陶寺观象台：山西襄汾陶寺遗址发现半圆形观象台遗迹，学者通过模拟观测认为先民可据此确定节气。遗址还出土彩绘龙盘、朱书扁壶等文物。 出处：中国社会科学院考古研究所山西队发掘简报"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版七上第 3 课","《中华文明探源工程》成果公报"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】北京人遗址出土了大量打制石器、成堆的灰烬层，灰烬中有烧过的兽骨和树籽。\n【材料二】良渚古城遗址由宫殿区、内城、外城组成，外围发现由 11 条堤坝组成的水利系统；城内出土大量精致的玉琮、玉璧。\n【材料三】中华文明探源工程提出判断进入文明社会的中国方案：出现城市、出现阶级分化、出现王权与国家。","source":"材料研读 · 史前时期：原始社会与中华文明的起源"}],"questions":[{"id":"h7a-u1-m1-q2","type":"short","stem":"（2）依据材料二、三，说明良渚古城为什么被视为已进入文明社会的证据。（4 分）","answer":"良渚古城有宫殿区与内外城，说明已经出现城市；大型水利系统说明有组织大规模公共工程的能力和王权；随葬玉器的规格差异反映出阶级分化。以上都与材料三「城市、阶级分化、王权与国家」的判断标准相符。","explain":"","tags":["文明起源","史料实证"],"rubric":["指出城市/宫殿区","指出水利工程与组织能力","指出玉器反映阶级分化","对应文明判断标准"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"h7a-u1-q3","type":"choice","stem":"良渚古城与陶寺古城的考古发现，最主要的价值在于","answer":"B","explain":"两处古城都出现城市、阶级分化与王权，是中华文明五千多年历史的实证，也说明中华文明本土起源、多元一体。","options":["证明中华文明是由西方传入的","为中华文明五千多年历史提供实证","说明我国最早的文字出现在长江流域","证明夏朝是我国第一个王朝"],"tags":["文明起源","家国情怀"]},{"id":"h7a-u1-q4","type":"choice","stem":"「禅让」制下，部落联盟首领产生的方式是","answer":"B","explain":"尧舜禹时期通过推举贤能者继位，称为禅让。父死子继的世袭制自夏启开始。","options":["父死子继","推举贤能者","以战功决定","由占卜决定"],"tags":["禅让制","历史解释"]},{"id":"cat-7a-1-3-g2","type":"choice","stem":"下列关于「中华文明的起源」的表述，错误的是","answer":"A","explain":"把尧舜禹的「禅让」说成世袭——「公天下」到「家天下」的转折点是夏朝建立，不是尧舜时期。正确表述：禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","options":["把尧舜禹的「禅让」说成世袭。","禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","考古发现是研究史前历史的**唯一可靠依据**；传说（炎黄、尧舜禹）需要考古材料印证，不能当作信史。","良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-1-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：良渚古城位于浙江杭州余杭，距今约 5300—4300 年。古城外围有规模宏大的水利系统，由 11 条坝体组成，是中国已知最早的大型水利工程之一。2019 年良渚古城遗址列入《世界遗产名录》。（联合国教科文组织世界遗产中心；浙江省文物考古研究所）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中华文明的起源；良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。","explain":"材料出自联合国教科文组织世界遗产中心；浙江省文物考古研究所。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-2-1","title":"第4课 夏商西周王朝的更替","subtitle":"七年级上册 · 第二单元 夏商周时期：奴隶制王朝的更替和向封建社会的过渡","grade":"7a","tags":["七年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第二单元 夏商周时期：奴隶制王朝的更替和向封建社会的过渡"},{"k":"课时","v":"第4课 夏商西周王朝的更替"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"约公元前 2070 年，禹建立夏朝，中国进入王朝时代。禹死后其子启继位，「公天下」变为「家天下」，世袭制取代禅让制。约公元前 1600 年，汤灭夏建商；公元前 1046 年，周武王在牧野之战中击败商纣王，建立西周，推行分封制。"},{"type":"note","title":"本课主线 · 因果链","text":"夏、商、西周确立了早期国家的制度（世袭、分封），春秋战国则因铁器牛耕带来的生产力飞跃，走向大变革：变法图强、百家争鸣，为秦的统一准备了条件。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约公元前 2070 年","禹建立夏朝","我国历史上第一个奴隶制王朝；启继位后世袭制取代禅让制 · 重点"],["公元前 1046 年","武王伐纣，牧野之战后建立西周","实行分封制，形成「封建亲戚，以藩屏周」 · 重点"],["公元前 771 年","犬戎攻破镐京，西周灭亡","次年周平王东迁洛邑，东周开始 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 牧野之战：一天之内改写王朝","caption":"示意图：牧野之战：一天之内改写王朝，详见下方「历史现场」","view":"wide","alt":"示意图：牧野之战：一天之内改写王朝，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"战前","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"周武王联合庸、蜀、羌等部族，率兵车三…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"公元前 1046 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"双方在商都朝歌郊外牧野决战，商军中的…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"当日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"商军溃败，纣王自焚于鹿台，商朝灭亡","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"战后","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"周武王建立西周，定都镐京，大规模分封…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"夏朝是我国历史上第一个王朝，世袭制代替禅让制，「公天下」变为「家天下」。","explain":"材料题常问「这一变化说明了什么」：国家权力开始在一家一姓中传承，是早期国家形成的标志。"},{"level":"重点","text":"西周分封制：天子把土地和人民分给宗亲、功臣，受封者需服从周王调遣、随从作战、缴纳贡赋。","explain":"要能写「作用」：稳定周初政治形势、扩大统治范围；也要能写「弊端」：诸侯势力膨胀导致王室衰微。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。"]]},{"type":"table","title":"西周分封制与秦朝郡县制（两种地方管理制度的对比（跨单元））","head":["比较项","西周分封制","秦朝郡县制"],"rows":[["依据","血缘、功劳","皇帝直接任免，不世袭"],["权力","诸侯有较大自主权（军队、赋税）","郡县长官只有行政权，受中央考核"],["结果","后期诸侯割据、王室衰微","加强中央集权，维护统一"],["共同目的","都是为巩固统治、管理广阔疆域","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度演变类材料题","给分封制与郡县制的材料，比较异同并说明「中央集权加强」这一趋势，落脚点通常在秦朝。"],["思想主张与人物配对","给出主张原文（「兼爱」「无为」「以法治国」）判断学派与人物的对应，常与「社会大变革」的背景结合。"],["改革的评价","以商鞅变法为切口，要求「结合史实说明改革的作用与代价」，是有固定答题结构的常见大题。"]]},{"type":"note","title":"跨学科视角","text":"语文：甲骨文与汉字演变；道德与法治：规则、制度与社会秩序的形成。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 牧野之战：一天之内改写王朝","head":["时间","经过"],"rows":[["战前","周武王联合庸、蜀、羌等部族，率兵车三百乘、虎贲三千人东进"],["公元前 1046 年","双方在商都朝歌郊外牧野决战，商军中的奴隶阵前倒戈"],["当日","商军溃败，纣王自焚于鹿台，商朝灭亡"],["战后","周武王建立西周，定都镐京，大规模分封诸侯"]]},{"type":"note","title":"现场解说","text":"牧野之战是中国古代著名的以少胜多战例，「前徒倒戈」成为民心向背决定战争胜负的典型例证。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["大禹治水","传说禹治水十三年，三过家门而不入，采用疏导之法平息水患。","《史记·夏本纪》"],["助纣为虐","比喻帮助恶人做坏事。纣是商朝末代君主，以暴虐著称。","《史记·殷本纪》"],["姜太公钓鱼","传说姜尚在渭水垂钓以待文王，后辅佐周武王灭商。","《史记·齐太公世家》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"汤","v":"商朝建立者，任用伊尹，灭夏后建立商朝。 出处：《史记·殷本纪》"},{"k":"周武王","v":"姬发，西周建立者，牧野之战击败商纣王。 出处：《史记·周本纪》"}]},{"type":"list","title":"延伸阅读","items":["二里头遗址：河南偃师二里头遗址发现宫殿基址、青铜爵、绿松石龙形器，学界多认为其与夏朝晚期都城有关，是探索夏文化的重要遗址。 出处：中国社会科学院考古研究所《二里头》发掘报告","甲骨文印证商王世系：王国维依据殷墟甲骨卜辞作《殷卜辞中所见先公先王考》，证明《史记·殷本纪》所载商王世系基本可信，开创「二重证据法」。 出处：王国维《观堂集林》"]},{"type":"list","title":"本课拓展出处","items":["《史记·夏本纪》《史记·殷本纪》《史记·周本纪》","2024 部编版七上第 4 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】天子适诸侯曰巡狩……诸侯朝于天子曰述职。——《孟子》\n【材料二】（商鞅变法）有军功者，各以率受上爵……僇力本业，耕织致粟帛多者复其身。——《史记·商君列传》\n【材料三】及秦孝公用商君，坏井田，开阡陌，急耕战之赏……倾邻国而雄诸侯。——《汉书·食货志》","source":"材料研读 · 夏商周时期：早期国家与社会变革"}],"questions":[{"id":"h7a-u2-m1-q1","type":"short","stem":"（1）材料一反映的是西周的什么制度？受封者对周王承担哪些义务？（4 分）","answer":"分封制。义务：服从周王的调遣，向周王进献贡赋，平时镇守疆土、战时随从周王作战（「述职」「朝觐」）。","explain":"","tags":["分封制","历史解释"],"rubric":["答出分封制","答出服从调遣/随从作战","答出缴纳贡赋"]},{"id":"h7a-u2-q1","type":"choice","stem":"「大道之行也，天下为公，选贤与能……今大道既隐，天下为家。」「天下为家」开始于","answer":"B","explain":"启继承禹的王位，世袭制代替禅让制，「公天下」变为「家天下」。","options":["禹建立夏朝","启继承王位","汤灭夏建商","武王伐纣"],"tags":["世袭制","历史解释"]},{"id":"h7a-u2-q2","type":"choice","stem":"「封建亲戚，以藩屏周」反映的西周制度是","answer":"B","explain":"分封制把土地和人民分给宗亲、功臣，让他们建立诸侯国，起到拱卫王室的作用。","options":["禅让制","分封制","郡县制","世袭制"],"tags":["分封制","史料实证"]},{"id":"cat-7a-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 禹建立夏朝\n② 武王伐纣，牧野之战后建立西周\n③ 犬戎攻破镐京，西周灭亡","answer":"A","explain":"按时间顺序应为：①禹建立夏朝（约公元前 2070 年）→②武王伐纣，牧野之战后建立西周（公元前 1046 年）→③犬戎攻破镐京，西周灭亡（公元前 771 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-1-g2","type":"choice","stem":"下列关于「夏商西周王朝的更替」的表述，错误的是","answer":"A","explain":"把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」——制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。正确表述：分封制是西周的制度；夏朝是世袭制王朝。","options":["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","夏朝是我国历史上第一个王朝，世袭制代替禅让制，「公天下」变为「家天下」。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-1-g3","type":"choice","stem":"下列结论中，属于「夏商西周王朝的更替」的是","answer":"A","explain":"本课结论：分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","评价变法要一分为二：商鞅变法使秦国富强，但严刑峻法也激化了社会矛盾。","百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：河南偃师二里头遗址发现宫殿基址、青铜爵、绿松石龙形器，学界多认为其与夏朝晚期都城有关，是探索夏文化的重要遗址。（中国社会科学院考古研究所《二里头》发掘报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"夏商西周王朝的更替；夏朝是我国历史上第一个王朝，世袭制代替禅让制，「公天下」变为「家天下」。","explain":"材料出自中国社会科学院考古研究所《二里头》发掘报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-2-2","title":"第5课 动荡变化中的春秋时期","subtitle":"七年级上册 · 第二单元 夏商周时期：奴隶制王朝的更替和向封建社会的过渡","grade":"7a","tags":["七年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第二单元 夏商周时期：奴隶制王朝的更替和向封建社会的过渡"},{"k":"课时","v":"第5课 动荡变化中的春秋时期"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"公元前 770 年，周平王东迁洛邑，史称东周。王室衰微，诸侯不再定期朝觐，出现「礼崩乐坏」局面。齐、晋、楚、秦等大国相继争霸，齐桓公任用管仲改革，以「尊王攘夷」为号召，成为春秋时期第一位霸主。"},{"type":"note","title":"本课主线 · 因果链","text":"夏、商、西周确立了早期国家的制度（世袭、分封），春秋战国则因铁器牛耕带来的生产力飞跃，走向大变革：变法图强、百家争鸣，为秦的统一准备了条件。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["公元前 770—前 476 年","春秋时期","铁制农具与牛耕出现；王室衰微，诸侯争霸"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"百家争鸣：孔子（仁、为政以德、有教无…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"选择题","anchor":"start","size":3.5,"tone":"muted"},{"t":"text","x":18.5,"y":27.17,"text":"春秋五霸与战国七雄的格局；青铜器（后…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":41.33,"text":"生产力是变革的根本动力：铁制农具与牛…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"分封制的「双刃剑」：初期巩固统治，后…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"百家争鸣：孔子（仁、为政以德、有教无类）、老子（无为、辩证法）、墨子（兼爱非攻）、孟子（仁政）、韩非（以法治国、中央集权）。","explain":"答「社会大变革在思想上的反映」时要联系生产力：铁器牛耕 → 旧制度瓦解 → 各派提出治国方案。"},{"level":"选择题","text":"春秋五霸与战国七雄的格局；青铜器（后母戊鼎、四羊方尊）反映高超铸造技术。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。"],["认为商鞅变法只对秦国有利、没有阻力。","变法触动了旧贵族利益，遭到强烈反对，商鞅本人最终被处死。","材料题常给「商鞅被车裂」的材料，要求说明改革为何艰难。"]]},{"type":"table","title":"春秋战国思想与古希腊思想（「轴心时代」的中西思想比较）","head":["比较项","中国（孔子、老子、韩非）","古希腊（苏格拉底、柏拉图）"],"rows":[["时代","公元前 6—前 3 世纪","公元前 5—前 4 世纪"],["核心关切","如何治国、如何做人（伦理与政治）","什么是美德、如何认识真理"],["方法","游说诸侯、以德化民、以法治国","对话追问、逻辑论证"],["共同影响","都成为各自文明的思想源头","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度演变类材料题","给分封制与郡县制的材料，比较异同并说明「中央集权加强」这一趋势，落脚点通常在秦朝。"],["思想主张与人物配对","给出主张原文（「兼爱」「无为」「以法治国」）判断学派与人物的对应，常与「社会大变革」的背景结合。"],["改革的评价","以商鞅变法为切口，要求「结合史实说明改革的作用与代价」，是有固定答题结构的常见大题。"]]},{"type":"note","title":"跨学科视角","text":"语文：甲骨文与汉字演变；道德与法治：规则、制度与社会秩序的形成。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["退避三舍","晋文公重耳流亡楚国时承诺若两国交战将退避三舍（九十里），城濮之战中兑现承诺，比喻主动退让。","《左传·僖公二十三年、二十八年》"],["管鲍之交","管仲与鲍叔牙相知相惜，鲍叔牙力荐管仲为齐相，比喻深厚友谊。","《史记·管晏列传》"],["一箭之仇","齐桓公小白与公子纠争位时曾被管仲射中带钩，后不计前嫌任用管仲。","《史记·齐太公世家》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"齐桓公","v":"春秋首霸，任用管仲改革，葵丘会盟确立霸主地位。 出处：《史记·齐太公世家》"}]},{"type":"list","title":"延伸阅读","items":["管仲改革：管仲在齐国推行「相地而衰征」，按土地好坏分等征税；又设「轻重」之法调节物价，发展渔盐之利，使齐国国力大增。 出处：《国语·齐语》；《史记·管晏列传》","铁器与牛耕：春秋时期出现铁制农具和牛耕，生产力显著提高，井田制逐渐瓦解，为战国变法奠定物质基础。 出处：2024 部编版七上第 5 课"]},{"type":"list","title":"本课拓展出处","items":["《史记·齐太公世家》《史记·晋世家》","《左传》；2024 部编版七上第 5 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u2-q5","type":"choice","stem":"春秋战国时期出现「百家争鸣」局面的根本原因是","answer":"B","explain":"根本原因是生产力发展带来的社会大变革：经济基础变化引起上层建筑与思想的变动。其余选项是重要条件而非根本原因。","options":["各诸侯国竞相招揽人才","铁制农具和牛耕的推广，社会生产力提高","私学兴起，学术下移","周王室衰微，诸侯争霸"],"tags":["百家争鸣","唯物史观"]},{"id":"cat-7a-2-2-g2","type":"choice","stem":"下列关于「动荡变化中的春秋时期」的表述，错误的是","answer":"A","explain":"把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」——制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。正确表述：分封制是西周的制度；夏朝是世袭制王朝。","options":["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-2-g3","type":"choice","stem":"下列结论中，属于「动荡变化中的春秋时期」的是","answer":"A","explain":"本课结论：生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","评价变法要一分为二：商鞅变法使秦国富强，但严刑峻法也激化了社会矛盾。","百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：管仲在齐国推行「相地而衰征」，按土地好坏分等征税；又设「轻重」之法调节物价，发展渔盐之利，使齐国国力大增。（《国语·齐语》；《史记·管晏列传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"动荡变化中的春秋时期；百家争鸣：孔子（仁、为政以德、有教无类）、老子（无为、辩证法）、墨子（兼爱非攻）、孟子（仁政）、韩非（以法治国、中央集权）。","explain":"材料出自《国语·齐语》；《史记·管晏列传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7a-2-2-g5","type":"choice","stem":"「春秋时期」发生于","answer":"A","explain":"本课时间轴：春秋时期（公元前 770—前 476 年）。铁制农具与牛耕出现；王室衰微，诸侯争霸。其余三个时间是同一单元相邻课时的事件时间。","options":["公元前 770—前 476 年","约公元前 2070 年","公元前 1046 年","公元前 771 年"],"difficulty":1,"tags":["七年级上册","第二单元","本课练习"]}]},{"id":"cat-7a-2-3","title":"第6课 战国时期的社会变革","subtitle":"七年级上册 · 第二单元 夏商周时期：奴隶制王朝的更替和向封建社会的过渡","grade":"7a","tags":["七年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第二单元 夏商周时期：奴隶制王朝的更替和向封建社会的过渡"},{"k":"课时","v":"第6课 战国时期的社会变革"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"战国时期，三家分晋、田氏代齐，礼制进一步崩坏。各国为富国强兵纷纷变法：魏国李悝、楚国吴起、秦国商鞅。公元前 356 年起，商鞅在秦孝公支持下两次变法，使秦国成为最强盛的诸侯国。"},{"type":"note","title":"本课主线 · 因果链","text":"夏、商、西周确立了早期国家的制度（世袭、分封），春秋战国则因铁器牛耕带来的生产力飞跃，走向大变革：变法图强、百家争鸣，为秦的统一准备了条件。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["公元前 1046 年","武王伐纣，牧野之战后建立西周","实行分封制，形成「封建亲戚，以藩屏周」 · 重点"],["公元前 770—前 476 年","春秋时期","铁制农具与牛耕出现；王室衰微，诸侯争霸"],["公元前 475—前 221 年","战国时期","七雄并立；各国变法，商鞅变法最彻底 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 商鞅变法：一场改变秦国命运的制度改革","caption":"示意图：商鞅变法：一场改变秦国命运的制度改革，详见下方「历史现场」","view":"wide","alt":"示意图：商鞅变法：一场改变秦国命运的制度改革，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"公元前 356 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"第一次变法：编制户口、奖励耕织、奖励…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"公元前 350 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"第二次变法：废井田、开阡陌，迁都咸阳…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"变法期间","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"太子犯法，商鞅处罚其师傅公子虔、公孙…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"公元前 338 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"秦孝公去世，商鞅被车裂，但新法继续推…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"商鞅变法：奖励耕织、奖励军功、确立县制、废除井田制、统一度量衡。","explain":"变法中最能体现「社会转型」的是废除井田制（土地私有）与奖励军功（打击旧贵族），这两点最爱考。"},{"level":"重点","text":"百家争鸣：孔子（仁、为政以德、有教无类）、老子（无为、辩证法）、墨子（兼爱非攻）、孟子（仁政）、韩非（以法治国、中央集权）。","explain":"答「社会大变革在思想上的反映」时要联系生产力：铁器牛耕 → 旧制度瓦解 → 各派提出治国方案。"},{"level":"次重点","text":"都江堰（李冰，战国秦国）兼具防洪、灌溉、水运之利，使成都平原成为「天府之国」。","explain":""},{"level":"选择题","text":"春秋五霸与战国七雄的格局；青铜器（后母戊鼎、四羊方尊）反映高超铸造技术。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","评价变法要一分为二：商鞅变法使秦国富强，但严刑峻法也激化了社会矛盾。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为商鞅变法只对秦国有利、没有阻力。","变法触动了旧贵族利益，遭到强烈反对，商鞅本人最终被处死。","材料题常给「商鞅被车裂」的材料，要求说明改革为何艰难。"]]},{"type":"table","title":"春秋战国思想与古希腊思想（「轴心时代」的中西思想比较）","head":["比较项","中国（孔子、老子、韩非）","古希腊（苏格拉底、柏拉图）"],"rows":[["时代","公元前 6—前 3 世纪","公元前 5—前 4 世纪"],["核心关切","如何治国、如何做人（伦理与政治）","什么是美德、如何认识真理"],["方法","游说诸侯、以德化民、以法治国","对话追问、逻辑论证"],["共同影响","都成为各自文明的思想源头","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度演变类材料题","给分封制与郡县制的材料，比较异同并说明「中央集权加强」这一趋势，落脚点通常在秦朝。"],["思想主张与人物配对","给出主张原文（「兼爱」「无为」「以法治国」）判断学派与人物的对应，常与「社会大变革」的背景结合。"],["改革的评价","以商鞅变法为切口，要求「结合史实说明改革的作用与代价」，是有固定答题结构的常见大题。"]]},{"type":"note","title":"跨学科视角","text":"语文：甲骨文与汉字演变；道德与法治：规则、制度与社会秩序的形成。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 商鞅变法：一场改变秦国命运的制度改革","head":["时间","经过"],"rows":[["公元前 356 年","第一次变法：编制户口、奖励耕织、奖励军功、推行县制、什伍连坐"],["公元前 350 年","第二次变法：废井田、开阡陌，迁都咸阳，推行县制，统一度量衡"],["变法期间","太子犯法，商鞅处罚其师傅公子虔、公孙贾，新法得以严格执行"],["公元前 338 年","秦孝公去世，商鞅被车裂，但新法继续推行"]]},{"type":"note","title":"现场解说","text":"变法使秦国「民以殷盛，国以富强」，为日后统一六国奠定基础。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["徙木立信","商鞅在国都南门立木，宣布能搬走者赏十金，以取信于民，随即颁布新法。","《史记·商君列传》"],["图穷匕见","荆轲刺秦王，献燕国地图至尽头露出匕首，比喻事情发展到最后真相显露。","《战国策·燕策三》；《史记·刺客列传》"],["纸上谈兵","赵括熟读兵书却无实战经验，长平之战大败，比喻空谈理论。","《史记·廉颇蔺相如列传》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"商鞅","v":"卫国公孙鞅，战国政治家、改革家，秦国变法主持者。 出处：《史记·商君列传》"},{"k":"李冰","v":"战国水利专家，主持修建都江堰。 出处：《史记·河渠书》"}]},{"type":"list","title":"延伸阅读","items":["都江堰：公元前 256 年，秦蜀郡守李冰主持修建都江堰，由鱼嘴、飞沙堰、宝瓶口三大主体工程组成，兼具防洪、灌溉、航运功能，至今仍在发挥作用。 出处：《史记·河渠书》；都江堰水利工程管理局","商鞅的个人结局：秦孝公死后，商鞅被旧贵族诬陷谋反，车裂而死；但新法并未废止，继续在秦国推行。 出处：《史记·商君列传》"]},{"type":"list","title":"本课拓展出处","items":["《史记·商君列传》《史记·河渠书》","2024 部编版七上第 6 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】天子适诸侯曰巡狩……诸侯朝于天子曰述职。——《孟子》\n【材料二】（商鞅变法）有军功者，各以率受上爵……僇力本业，耕织致粟帛多者复其身。——《史记·商君列传》\n【材料三】及秦孝公用商君，坏井田，开阡陌，急耕战之赏……倾邻国而雄诸侯。——《汉书·食货志》","source":"材料研读 · 夏商周时期：早期国家与社会变革"}],"questions":[{"id":"h7a-u2-m1-q2","type":"short","stem":"（2）依据材料二、三，概括商鞅变法的两项措施，并说明变法为什么能使秦国「倾邻国而雄诸侯」。（6 分）","answer":"措施：①奖励军功，按军功授予爵位；②奖励耕织，生产粮食布帛多者可免除徭役；③废除井田制、开垦荒地。作用：奖励耕织使国家粮食充足、经济实力增强；奖励军功使军队战斗力提高；废井田、开阡陌承认土地私有，调动了生产积极性。因此秦国国力大增，在兼并战争中占据优势。","explain":"","tags":["商鞅变法","历史解释"],"rubric":["措施：奖励军功","措施：奖励耕织/废井田","作用：经济实力增强","作用：军队战斗力提高","作用：为统一奠定基础"]},{"id":"h7a-u2-q2","type":"choice","stem":"「封建亲戚，以藩屏周」反映的西周制度是","answer":"B","explain":"分封制把土地和人民分给宗亲、功臣，让他们建立诸侯国，起到拱卫王室的作用。","options":["禅让制","分封制","郡县制","世袭制"],"tags":["分封制","史料实证"]},{"id":"h7a-u2-q4","type":"choice","stem":"商鞅变法中最能体现「社会转型」的措施是","answer":"C","explain":"废除井田制、承认土地私有，标志着土地制度由奴隶制向封建制转变，最能体现社会转型。","options":["奖励耕织","确立县制","废除井田制，允许土地自由买卖","统一度量衡"],"tags":["商鞅变法","唯物史观"]},{"id":"h7a-u2-q5","type":"choice","stem":"春秋战国时期出现「百家争鸣」局面的根本原因是","answer":"B","explain":"根本原因是生产力发展带来的社会大变革：经济基础变化引起上层建筑与思想的变动。其余选项是重要条件而非根本原因。","options":["各诸侯国竞相招揽人才","铁制农具和牛耕的推广，社会生产力提高","私学兴起，学术下移","周王室衰微，诸侯争霸"],"tags":["百家争鸣","唯物史观"]},{"id":"cat-7a-2-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 武王伐纣，牧野之战后建立西周\n② 春秋时期\n③ 战国时期","answer":"A","explain":"按时间顺序应为：①武王伐纣，牧野之战后建立西周（公元前 1046 年）→②春秋时期（公元前 770—前 476 年）→③战国时期（公元前 475—前 221 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-3-g2","type":"choice","stem":"下列关于「战国时期的社会变革」的表述，错误的是","answer":"A","explain":"认为商鞅变法只对秦国有利、没有阻力——材料题常给「商鞅被车裂」的材料，要求说明改革为何艰难。正确表述：变法触动了旧贵族利益，遭到强烈反对，商鞅本人最终被处死。","options":["认为商鞅变法只对秦国有利、没有阻力。","变法触动了旧贵族利益，遭到强烈反对，商鞅本人最终被处死。","生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：公元前 256 年，秦蜀郡守李冰主持修建都江堰，由鱼嘴、飞沙堰、宝瓶口三大主体工程组成，兼具防洪、灌溉、航运功能，至今仍在发挥作用。（《史记·河渠书》；都江堰水利工程管理局）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"战国时期的社会变革；商鞅变法：奖励耕织、奖励军功、确立县制、废除井田制、统一度量衡。","explain":"材料出自《史记·河渠书》；都江堰水利工程管理局。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-2-4","title":"第7课 百家争鸣","subtitle":"七年级上册 · 第二单元 夏商周时期：奴隶制王朝的更替和向封建社会的过渡","grade":"7a","tags":["七年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第二单元 夏商周时期：奴隶制王朝的更替和向封建社会的过渡"},{"k":"课时","v":"第7课 百家争鸣"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"春秋战国时期社会剧烈变革，诸子百家围绕「如何治理国家」展开争鸣。孔子创立儒家，主张「仁」与「为政以德」，首创私学；老子创立道家，主张「无为而治」。战国时期，墨家、法家、兵家等学派进一步活跃。"},{"type":"note","title":"本课主线 · 因果链","text":"夏、商、西周确立了早期国家的制度（世袭、分封），春秋战国则因铁器牛耕带来的生产力飞跃，走向大变革：变法图强、百家争鸣，为秦的统一准备了条件。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["约公元前 2070 年","禹建立夏朝","我国历史上第一个奴隶制王朝；启继位后世袭制取代禅让制 · 重点"],["约公元前 1600 年","汤灭夏建商","盘庚迁殷后稳定；甲骨文与青铜器（后母戊鼎）闻名 · 重点"],["公元前 1046 年","武王伐纣，牧野之战后建立西周","实行分封制，形成「封建亲戚，以藩屏周」 · 重点"],["公元前 771 年","犬戎攻破镐京，西周灭亡","次年周平王东迁洛邑，东周开始 · 重点"],["公元前 770—前 476 年","春秋时期","铁制农具与牛耕出现；王室衰微，诸侯争霸"],["公元前 475—前 221 年","战国时期","七雄并立；各国变法，商鞅变法最彻底 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"约公元前 2070 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"禹建立夏朝","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"约公元前 1600 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"汤灭夏建商","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"公元前 1046 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"武王伐纣，牧野之战后建立西周","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"公元前 771 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"犬戎攻破镐京，西周灭亡","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"公元前 770—前 47…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"春秋时期","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"公元前 475—前 22…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"战国时期","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"百家争鸣：孔子（仁、为政以德、有教无类）、老子（无为、辩证法）、墨子（兼爱非攻）、孟子（仁政）、韩非（以法治国、中央集权）。","explain":"答「社会大变革在思想上的反映」时要联系生产力：铁器牛耕 → 旧制度瓦解 → 各派提出治国方案。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把孔子与老子的主张混为一谈。","孔子主张「仁」「为政以德」，重视教育与礼；老子主张「无为而治」，认为事物有对立面并可相互转化。","选择题常把「无为」写成孔子的主张。"]]},{"type":"table","title":"春秋战国思想与古希腊思想（「轴心时代」的中西思想比较）","head":["比较项","中国（孔子、老子、韩非）","古希腊（苏格拉底、柏拉图）"],"rows":[["时代","公元前 6—前 3 世纪","公元前 5—前 4 世纪"],["核心关切","如何治国、如何做人（伦理与政治）","什么是美德、如何认识真理"],["方法","游说诸侯、以德化民、以法治国","对话追问、逻辑论证"],["共同影响","都成为各自文明的思想源头","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度演变类材料题","给分封制与郡县制的材料，比较异同并说明「中央集权加强」这一趋势，落脚点通常在秦朝。"],["思想主张与人物配对","给出主张原文（「兼爱」「无为」「以法治国」）判断学派与人物的对应，常与「社会大变革」的背景结合。"],["改革的评价","以商鞅变法为切口，要求「结合史实说明改革的作用与代价」，是有固定答题结构的常见大题。"]]},{"type":"note","title":"跨学科视角","text":"语文：甲骨文与汉字演变；道德与法治：规则、制度与社会秩序的形成。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["因材施教","孔子根据学生个性与能力差异施以不同教育，出自《论语》所记孔子教学实践。","《论语·先进》；《二程遗书》概括"],["温故知新","温习旧知识而获得新理解，出自「温故而知新，可以为师矣」。","《论语·为政》"],["三人行必有我师","几个人同行，其中必有可学习之人，强调虚心求教。","《论语·述而》"],["守株待兔","韩非以宋人守树桩待兔的寓言，讽刺墨守成规、不知变通。","《韩非子·五蠹》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"孔子","v":"前 551—前 479，名丘，字仲尼，儒家学派创始人，教育家。 出处：《史记·孔子世家》"},{"k":"老子","v":"姓李名耳，道家学派创始人，著有《道德经》。 出处：《史记·老子韩非列传》"},{"k":"韩非","v":"战国法家集大成者，主张以法治国、中央集权。 出处：《史记·老子韩非列传》"}]},{"type":"list","title":"延伸阅读","items":["孔子周游列国：孔子 55 岁起率弟子周游卫、陈、蔡等国十四年，宣传政治主张，屡遭困厄，晚年返鲁整理六经、从事教育。 出处：《史记·孔子世家》","稷下学宫：齐国在临淄稷门附近设学宫，招揽天下贤士讲学论辩，孟子、荀子、邹衍等曾在此活动，是战国百家争鸣的重要舞台。 出处：《史记·孟子荀卿列传》"]},{"type":"list","title":"本课拓展出处","items":["《论语》《道德经》《史记·孔子世家》","2024 部编版七上第 7 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】天子适诸侯曰巡狩……诸侯朝于天子曰述职。——《孟子》\n【材料二】（商鞅变法）有军功者，各以率受上爵……僇力本业，耕织致粟帛多者复其身。——《史记·商君列传》\n【材料三】及秦孝公用商君，坏井田，开阡陌，急耕战之赏……倾邻国而雄诸侯。——《汉书·食货志》","source":"材料研读 · 夏商周时期：早期国家与社会变革"}],"questions":[{"id":"h7a-u2-q3","type":"choice","stem":"某学派主张「兼相爱，交相利」「非攻」，反对不义战争。该学派是","answer":"C","explain":"墨子的主张是「兼爱」「非攻」，代表下层劳动者利益。","options":["儒家","道家","墨家","法家"],"tags":["百家争鸣","历史解释"]},{"id":"h7a-u2-q5","type":"choice","stem":"春秋战国时期出现「百家争鸣」局面的根本原因是","answer":"B","explain":"根本原因是生产力发展带来的社会大变革：经济基础变化引起上层建筑与思想的变动。其余选项是重要条件而非根本原因。","options":["各诸侯国竞相招揽人才","铁制农具和牛耕的推广，社会生产力提高","私学兴起，学术下移","周王室衰微，诸侯争霸"],"tags":["百家争鸣","唯物史观"]},{"id":"cat-7a-2-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 禹建立夏朝\n② 汤灭夏建商\n③ 武王伐纣，牧野之战后建立西周\n④ 犬戎攻破镐京，西周灭亡","answer":"A","explain":"按时间顺序应为：①禹建立夏朝（约公元前 2070 年）→②汤灭夏建商（约公元前 1600 年）→③武王伐纣，牧野之战后建立西周（公元前 1046 年）→④犬戎攻破镐京，西周灭亡（公元前 771 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-4-g2","type":"choice","stem":"下列关于「百家争鸣」的表述，错误的是","answer":"A","explain":"把孔子与老子的主张混为一谈——选择题常把「无为」写成孔子的主张。正确表述：孔子主张「仁」「为政以德」，重视教育与礼；老子主张「无为而治」，认为事物有对立面并可相互转化。","options":["把孔子与老子的主张混为一谈。","孔子主张「仁」「为政以德」，重视教育与礼；老子主张「无为而治」，认为事物有对立面并可相互转化。","百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。","百家争鸣：孔子（仁、为政以德、有教无类）、老子（无为、辩证法）、墨子（兼爱非攻）、孟子（仁政）、韩非（以法治国、中央集权）。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-4-g3","type":"choice","stem":"下列结论中，属于「百家争鸣」的是","answer":"A","explain":"本课结论：百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","评价变法要一分为二：商鞅变法使秦国富强，但严刑峻法也激化了社会矛盾。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：孔子 55 岁起率弟子周游卫、陈、蔡等国十四年，宣传政治主张，屡遭困厄，晚年返鲁整理六经、从事教育。（《史记·孔子世家》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"百家争鸣；百家争鸣：孔子（仁、为政以德、有教无类）、老子（无为、辩证法）、墨子（兼爱非攻）、孟子（仁政）、韩非（以法治国、中央集权）。","explain":"材料出自《史记·孔子世家》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-2-5","title":"第8课 夏商周时期的科技与文化","subtitle":"七年级上册 · 第二单元 夏商周时期：奴隶制王朝的更替和向封建社会的过渡","grade":"7a","tags":["七年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第二单元 夏商周时期：奴隶制王朝的更替和向封建社会的过渡"},{"k":"课时","v":"第8课 夏商周时期的科技与文化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"夏商周时期，青铜铸造、甲骨文、天文历法等领域取得突出成就。商朝青铜器种类繁多、工艺精湛；甲骨文是我国已发现的年代最早、体系较为完整的文字；《诗经》保存了西周至春秋的诗歌。"},{"type":"note","title":"本课主线 · 因果链","text":"夏、商、西周确立了早期国家的制度（世袭、分封），春秋战国则因铁器牛耕带来的生产力飞跃，走向大变革：变法图强、百家争鸣，为秦的统一准备了条件。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约公元前 1600 年","汤灭夏建商","盘庚迁殷后稳定；甲骨文与青铜器（后母戊鼎）闻名 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"tall","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"次重点","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"甲骨文是我国已发现的年代最早、体系较…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"选择题","anchor":"start","size":3.5,"tone":"muted"},{"t":"text","x":18.5,"y":45,"text":"春秋五霸与战国七雄的格局；青铜器（后…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":73,"text":"生产力是变革的根本动力：铁制农具与牛…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":101,"text":"分封制的「双刃剑」：初期巩固统治，后…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":129,"text":"百家争鸣是中国古代第一次思想文化高峰…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"次重点","text":"甲骨文是我国已发现的年代最早、体系较为完整的文字，与今天的汉字有渊源关系。","explain":""},{"level":"选择题","text":"春秋五霸与战国七雄的格局；青铜器（后母戊鼎、四羊方尊）反映高超铸造技术。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。"],["认为商鞅变法只对秦国有利、没有阻力。","变法触动了旧贵族利益，遭到强烈反对，商鞅本人最终被处死。","材料题常给「商鞅被车裂」的材料，要求说明改革为何艰难。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度演变类材料题","给分封制与郡县制的材料，比较异同并说明「中央集权加强」这一趋势，落脚点通常在秦朝。"],["思想主张与人物配对","给出主张原文（「兼爱」「无为」「以法治国」）判断学派与人物的对应，常与「社会大变革」的背景结合。"],["改革的评价","以商鞅变法为切口，要求「结合史实说明改革的作用与代价」，是有固定答题结构的常见大题。"]]},{"type":"note","title":"跨学科视角","text":"语文：甲骨文与汉字演变；道德与法治：规则、制度与社会秩序的形成。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["路漫漫其修远兮","屈原《离骚》名句，表达不懈求索的精神。","屈原《离骚》"],["四羊方尊","商代晚期青铜酒器，1938 年出土于湖南宁乡，四角各铸一羊，现藏中国国家博物馆。","中国国家博物馆藏品说明"]]},{"type":"kv","title":"人物卡片","items":[{"k":"王懿荣","v":"清末学者，最早发现并鉴定甲骨文。 出处：《清史稿·王懿荣传》"},{"k":"屈原","v":"战国楚国诗人，创作《离骚》《九歌》等，开创楚辞体。 出处：《史记·屈原贾生列传》"}]},{"type":"list","title":"延伸阅读","items":["后母戊鼎：后母戊鼎（旧称司母戊鼎）1939 年出土于河南安阳武官村，重 832.84 千克，是目前已知中国古代最重的青铜器，现藏中国国家博物馆。 出处：中国国家博物馆藏品说明","甲骨文的发现：1899 年，王懿荣在中药「龙骨」上发现刻痕，认定为古文字，此后刘鹗、罗振玉、王国维等人相继研究，形成甲骨学。 出处：王宇信《甲骨学通论》"]},{"type":"list","title":"本课拓展出处","items":["《诗经》；《中国青铜器全集》","2024 部编版七上第 8 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u2-q1","type":"choice","stem":"「大道之行也，天下为公，选贤与能……今大道既隐，天下为家。」「天下为家」开始于","answer":"B","explain":"启继承禹的王位，世袭制代替禅让制，「公天下」变为「家天下」。","options":["禹建立夏朝","启继承王位","汤灭夏建商","武王伐纣"],"tags":["世袭制","历史解释"]},{"id":"h7a-u2-q2","type":"choice","stem":"「封建亲戚，以藩屏周」反映的西周制度是","answer":"B","explain":"分封制把土地和人民分给宗亲、功臣，让他们建立诸侯国，起到拱卫王室的作用。","options":["禅让制","分封制","郡县制","世袭制"],"tags":["分封制","史料实证"]},{"id":"h7a-u2-q3","type":"choice","stem":"某学派主张「兼相爱，交相利」「非攻」，反对不义战争。该学派是","answer":"C","explain":"墨子的主张是「兼爱」「非攻」，代表下层劳动者利益。","options":["儒家","道家","墨家","法家"],"tags":["百家争鸣","历史解释"]},{"id":"cat-7a-2-5-g2","type":"choice","stem":"下列关于「夏商周时期的科技与文化」的表述，错误的是","answer":"A","explain":"把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」——制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。正确表述：分封制是西周的制度；夏朝是世袭制王朝。","options":["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-5-g3","type":"choice","stem":"下列结论中，属于「夏商周时期的科技与文化」的是","answer":"A","explain":"本课结论：生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","评价变法要一分为二：商鞅变法使秦国富强，但严刑峻法也激化了社会矛盾。","百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-5-g4","type":"short","stem":"阅读材料，回答问题。\n材料：后母戊鼎（旧称司母戊鼎）1939 年出土于河南安阳武官村，重 832.84 千克，是目前已知中国古代最重的青铜器，现藏中国国家博物馆。（中国国家博物馆藏品说明）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"夏商周时期的科技与文化；甲骨文是我国已发现的年代最早、体系较为完整的文字，与今天的汉字有渊源关系。","explain":"材料出自中国国家博物馆藏品说明。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-3-1","title":"第9课 秦统一中国","subtitle":"七年级上册 · 第三单元 秦汉时期：统一多民族封建国家的建立和巩固","grade":"7a","tags":["七年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第三单元 秦汉时期：统一多民族封建国家的建立和巩固"},{"k":"课时","v":"第9课 秦统一中国"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"战国末年，秦国凭借商鞅变法积累的国力，自公元前 230 年起依次灭韩、赵、魏、楚、燕、齐。公元前 221 年，秦王嬴政完成统一，建立秦朝，定都咸阳，自称「始皇帝」，中国历史上第一个统一多民族封建国家由此诞生。"},{"type":"note","title":"本课主线 · 因果链","text":"秦朝首次建立统一多民族的中央集权国家并创立一整套制度，但因暴政速亡；汉朝承接秦制而「与民休息」，到汉武帝时在政治、经济、思想、军事上全面巩固大一统。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["公元前 221 年","秦灭六国，嬴政称「始皇帝」，定都咸阳","我国历史上第一个统一多民族的封建国家 · 重点"],["公元前 213—前 212 年","焚书坑儒","加强思想控制，摧残了文化"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 秦灭六国：十年统一战争","caption":"示意图：秦灭六国：十年统一战争，详见下方「历史现场」","view":"tall","alt":"示意图：秦灭六国：十年统一战争，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"公元前 230 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"秦灭韩，韩国最先灭亡","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"公元前 228 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"秦破赵都邯郸，赵王迁被俘","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"公元前 225 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"秦引黄河水灌大梁，魏国灭亡","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"公元前 223 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"秦将王翦率六十万大军灭楚","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"公元前 222 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"秦攻辽东，燕国灭亡","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"公元前 221 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"齐王建投降，秦完成统一，建立秦朝","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"秦朝巩固统一的措施：皇帝制、三公九卿、郡县制；统一文字（小篆）、货币（圆形方孔半两钱）、度量衡；修长城、开灵渠。","explain":"答题时按「政治—经济—文化—军事」分类罗列，每条都要写出**作用**。"},{"level":"重点","text":"汉武帝的大一统：颁「推恩令」削弱诸侯王；「罢黜百家，尊崇儒术」确立儒家学说的正统地位；盐铁官营、统一铸币；北击匈奴（卫青、霍去病）。","explain":"最常考「推恩令为什么高明」：不费一兵一卒就使诸侯国越分越小，加强了中央集权。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","它表面是「恩」，实质是削藩，材料题常问「高明之处」。"],["认为「罢黜百家，尊崇儒术」是秦始皇的措施。","这是汉武帝采纳董仲舒建议的措施；秦始皇是「焚书坑儒」。","两者都对思想加强控制，但朝代与手段不同。"]]},{"type":"table","title":"秦始皇与汉武帝：两次「大一统」的比较（跨条目对比（同一主题、不同手段））","head":["比较项","秦始皇","汉武帝"],"rows":[["政治","创皇帝制、三公九卿、郡县制","颁推恩令、设刺史，削弱诸侯"],["思想","焚书坑儒（高压）","罢黜百家、尊崇儒术（引导）"],["经济","统一货币、度量衡","盐铁官营、统一铸币"],["军事","北击匈奴、筑长城","派卫青霍去病北击匈奴，张骞通西域"],["结果","因暴政速亡","西汉进入鼎盛，大一统巩固"]]},{"type":"table","title":"秦汉与罗马：古代东西方两大帝国（中外对比（同一时期的大国治理））","head":["比较项","秦汉","罗马"],"rows":[["时间","公元前 221 年—公元 220 年","公元前 27 年—公元 476 年（帝国）"],["地方治理","郡县制，长官由中央任免","行省制，总督由元老院/皇帝任命"],["法律","秦律，以法家思想治国","《十二铜表法》到罗马法体系"],["共同点","都靠强大军力与交通网络维系庞大疆域","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度创新与影响","以郡县制、推恩令切入，要求说明「中央集权不断加强」的趋势，可与中国近代、世界史的中央与地方关系联动。"],["地图与路线识读","给出丝绸之路示意图，要求写出起点、经过地区与交流内容，考「时空观念」。"],["兴亡启示类","秦亡汉兴的材料对比几乎每年都有变式，落脚在「爱惜民力、以民为本」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：河西走廊与丝绸之路的路线选择；语文：《史记》叙事与人物刻画。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 秦灭六国：十年统一战争","head":["时间","经过"],"rows":[["公元前 230 年","秦灭韩，韩国最先灭亡"],["公元前 228 年","秦破赵都邯郸，赵王迁被俘"],["公元前 225 年","秦引黄河水灌大梁，魏国灭亡"],["公元前 223 年","秦将王翦率六十万大军灭楚"],["公元前 222 年","秦攻辽东，燕国灭亡"],["公元前 221 年","齐王建投降，秦完成统一，建立秦朝"]]},{"type":"note","title":"现场解说","text":"统一顺序为韩、赵、魏、楚、燕、齐，采取「远交近攻」策略，先弱后强、由近及远。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["焚书坑儒","秦始皇采纳李斯建议，焚毁民间收藏的《诗》《书》等典籍，坑杀方士儒生，加强思想控制。","《史记·秦始皇本纪》"],["指鹿为马","赵高在秦二世面前将鹿说成马以试探群臣，比喻颠倒黑白。","《史记·秦始皇本纪》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"秦始皇","v":"嬴政，秦朝建立者，中国历史上第一位皇帝。 出处：《史记·秦始皇本纪》"},{"k":"李斯","v":"秦朝丞相，主张郡县制、统一文字，参与焚书。 出处：《史记·李斯列传》"}]},{"type":"list","title":"延伸阅读","items":["统一措施：秦朝在中央设丞相、太尉、御史大夫，地方推行郡县制；统一文字为小篆、统一货币为圆形方孔半两钱、统一度量衡；修驰道、直道，开凿灵渠，连接湘江与漓江。 出处：《史记·秦始皇本纪》","秦陵兵马俑：1974 年陕西临潼农民打井时发现兵马俑，现已探明三个俑坑，出土陶俑陶马数千件，被誉为「世界第八大奇迹」。 出处：秦始皇兵马俑博物馆；《史记·秦始皇本纪》"]},{"type":"list","title":"本课拓展出处","items":["《史记·秦始皇本纪》","2024 部编版七上第 9 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】秦为乱政虐刑以残贼天下，数十年矣……百姓困穷，而吏弗恤。——《史记》\n【材料二】（汉初）民失作业，而大饥馑……上于是约法省禁，轻田租，什五而税一。——《汉书·食货志》\n【材料三】愿陛下令诸侯得推恩分子弟，以地侯之……于是藩国始分，而子弟毕侯矣。——《汉书·主父偃传》","source":"材料研读 · 秦汉时期：统一多民族封建国家的建立和巩固"}],"questions":[{"id":"h7a-u3-m1-q2","type":"short","stem":"（2）材料三中的建议被哪位皇帝采纳？该措施为什么能加强中央集权？（4 分）","answer":"汉武帝采纳主父偃的建议，颁布「推恩令」。原因：名义上是把恩惠推及诸侯子弟，实际上使诸侯国的封地不断分割、越分越小，无力对抗中央；同时又避免了直接削藩引发叛乱，中央集权因此大大加强。","explain":"","tags":["推恩令","中央集权"],"rubric":["答出汉武帝/推恩令","答出封地越分越小","答出削弱诸侯实力","答出加强中央集权"]},{"id":"h7a-u3-q1","type":"choice","stem":"秦朝在地方上推行的、对后世影响最深远的制度是","answer":"B","explain":"郡县制下郡县长官由皇帝直接任免、不世袭，开创了此后两千多年的中央集权地方行政制度。行省制是元朝，科举制是隋朝。","options":["分封制","郡县制","行省制","科举制"],"tags":["郡县制","制度创新"]},{"id":"cat-7a-3-1-g2","type":"choice","stem":"下列关于「秦统一中国」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","秦朝巩固统一的措施：皇帝制、三公九卿、郡县制；统一文字（小篆）、货币（圆形方孔半两钱）、度量衡；修长城、开灵渠。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-1-g3","type":"choice","stem":"下列结论中，属于「秦统一中国」的是","answer":"A","explain":"本课结论：秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：秦朝在中央设丞相、太尉、御史大夫，地方推行郡县制；统一文字为小篆、统一货币为圆形方孔半两钱、统一度量衡；修驰道、直道，开凿灵渠，连接湘江与漓江。（《史记·秦始皇本纪》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"秦统一中国；秦朝巩固统一的措施：皇帝制、三公九卿、郡县制；统一文字（小篆）、货币（圆形方孔半两钱）、度量衡；修长城、开灵渠。","explain":"材料出自《史记·秦始皇本纪》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-3-2","title":"第10课 秦末农民大起义","subtitle":"七年级上册 · 第三单元 秦汉时期：统一多民族封建国家的建立和巩固","grade":"7a","tags":["七年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第三单元 秦汉时期：统一多民族封建国家的建立和巩固"},{"k":"课时","v":"第10课 秦末农民大起义"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"秦朝赋税、徭役、兵役繁重，刑罚严酷，又大兴土木修阿房宫、骊山陵，民怨沸腾。公元前 209 年，陈胜、吴广率戍卒在大泽乡起义，喊出「王侯将相宁有种乎」，这是中国历史上第一次大规模的农民起义。"},{"type":"note","title":"本课主线 · 因果链","text":"秦朝首次建立统一多民族的中央集权国家并创立一整套制度，但因暴政速亡；汉朝承接秦制而「与民休息」，到汉武帝时在政治、经济、思想、军事上全面巩固大一统。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["公元前 209 年","陈胜、吴广在大泽乡起义","中国历史上第一次大规模的农民起义 · 重点"],["公元前 202 年","刘邦建立西汉，定都长安","吸取秦亡教训，推行休养生息政策 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 大泽乡起义：中国第一次农民大起义","caption":"示意图：大泽乡起义：中国第一次农民大起义，详见下方「历史现场」","view":"tall","alt":"示意图：大泽乡起义：中国第一次农民大起义，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"公元前 209 年七月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"陈胜、吴广等 900 名戍卒被征发前…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"起义爆发","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"按秦律失期当斩，陈胜吴广杀死押送军官…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"起义初期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"起义军攻占陈县，陈胜称「张楚王」，各…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"分兵西进","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"吴广攻荥阳，周文率军直逼咸阳，被秦将…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"公元前 208 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"陈胜退至下城父，被车夫庄贾杀害，起义…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"余波","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"项羽、刘邦等继续反秦，公元前 207…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"秦亡的原因与启示：赋税徭役沉重、刑法严苛、秦二世更加残暴 → 农民起义。启示：治国要爱惜民力。","explain":"「秦亡汉兴」的对比是必考逻辑：汉初休养生息正是吸取秦亡教训。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","它表面是「恩」，实质是削藩，材料题常问「高明之处」。"],["认为「罢黜百家，尊崇儒术」是秦始皇的措施。","这是汉武帝采纳董仲舒建议的措施；秦始皇是「焚书坑儒」。","两者都对思想加强控制，但朝代与手段不同。"]]},{"type":"table","title":"秦始皇与汉武帝：两次「大一统」的比较（跨条目对比（同一主题、不同手段））","head":["比较项","秦始皇","汉武帝"],"rows":[["政治","创皇帝制、三公九卿、郡县制","颁推恩令、设刺史，削弱诸侯"],["思想","焚书坑儒（高压）","罢黜百家、尊崇儒术（引导）"],["经济","统一货币、度量衡","盐铁官营、统一铸币"],["军事","北击匈奴、筑长城","派卫青霍去病北击匈奴，张骞通西域"],["结果","因暴政速亡","西汉进入鼎盛，大一统巩固"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度创新与影响","以郡县制、推恩令切入，要求说明「中央集权不断加强」的趋势，可与中国近代、世界史的中央与地方关系联动。"],["地图与路线识读","给出丝绸之路示意图，要求写出起点、经过地区与交流内容，考「时空观念」。"],["兴亡启示类","秦亡汉兴的材料对比几乎每年都有变式，落脚在「爱惜民力、以民为本」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：河西走廊与丝绸之路的路线选择；语文：《史记》叙事与人物刻画。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 大泽乡起义：中国第一次农民大起义","head":["时间","经过"],"rows":[["公元前 209 年七月","陈胜、吴广等 900 名戍卒被征发前往渔阳，行至蕲县大泽乡遇雨误期"],["起义爆发","按秦律失期当斩，陈胜吴广杀死押送军官，号召「王侯将相宁有种乎」"],["起义初期","起义军攻占陈县，陈胜称「张楚王」，各地纷纷响应，队伍迅速壮大"],["分兵西进","吴广攻荥阳，周文率军直逼咸阳，被秦将章邯击败"],["公元前 208 年","陈胜退至下城父，被车夫庄贾杀害，起义失败"],["余波","项羽、刘邦等继续反秦，公元前 207 年秦朝灭亡"]]},{"type":"note","title":"现场解说","text":"起义虽败，但沉重打击了秦朝统治，揭开反秦战争的序幕。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["揭竿而起","陈胜吴广起义时「斩木为兵，揭竿为旗」，后泛指发动起义。","《史记·陈涉世家》"],["王侯将相宁有种乎","王侯将相难道是天生的吗？表达对等级制度的反抗。","《史记·陈涉世家》"],["破釜沉舟","项羽在巨鹿之战中凿沉船只、砸破锅灶，以示决死一战，比喻下定决心。","《史记·项羽本纪》"],["四面楚歌","垓下之战中汉军唱楚歌瓦解楚军士气，比喻陷入孤立无援境地。","《史记·项羽本纪》"],["约法三章","刘邦入关中与百姓约定「杀人者死，伤人及盗抵罪」，比喻订立简明规矩。","《史记·高祖本纪》"],["鸿门宴","项羽设宴款待刘邦，范增欲杀之而未成，后指暗藏杀机的宴席。","《史记·项羽本纪》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"陈胜","v":"字涉，大泽乡起义领袖，建立「张楚」政权。 出处：《史记·陈涉世家》"},{"k":"吴广","v":"字叔，与陈胜共同发动大泽乡起义，后被部下杀害。 出处：《史记·陈涉世家》"},{"k":"项羽","v":"楚国贵族后裔，巨鹿之战大破秦军，后败于刘邦。 出处：《史记·项羽本纪》"}]},{"type":"list","title":"延伸阅读","items":["起义为什么失败：陈胜称王后逐渐脱离群众，用人不当，内部离心；起义军缺乏统一指挥和稳固根据地，终被秦军各个击破。陈胜于公元前 208 年被部下庄贾杀害。 出处：《史记·陈涉世家》","楚汉之争：秦亡后，项羽与刘邦争夺天下四年。公元前 202 年垓下之战，项羽兵败自刎乌江，刘邦建立西汉。 出处：《史记·项羽本纪》《史记·高祖本纪》"]},{"type":"list","title":"本课拓展出处","items":["《史记·陈涉世家》《史记·项羽本纪》《史记·高祖本纪》","2024 部编版七上第 10 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u3-q1","type":"choice","stem":"秦朝在地方上推行的、对后世影响最深远的制度是","answer":"B","explain":"郡县制下郡县长官由皇帝直接任免、不世袭，开创了此后两千多年的中央集权地方行政制度。行省制是元朝，科举制是隋朝。","options":["分封制","郡县制","行省制","科举制"],"tags":["郡县制","制度创新"]},{"id":"h7a-u3-q2","type":"choice","stem":"汉武帝采纳主父偃建议颁布「推恩令」，其高明之处在于","answer":"B","explain":"推恩令让诸侯王的子弟分封土地，封国越分越小，中央集权得到加强，且避免了激化矛盾。","options":["直接剥夺诸侯王的封地","使诸侯国越分越小，不费兵卒削弱了诸侯势力","以武力镇压诸侯叛乱","废除分封，全面推行郡县"],"tags":["推恩令","历史解释"]},{"id":"h7a-u3-q3","type":"choice","stem":"标志今新疆地区正式归属中央政权管辖的事件是","answer":"C","explain":"公元前 60 年西汉设置西域都护，标志西域正式归属中央政权管辖。","options":["张骞第一次出使西域","丝绸之路的开通","公元前 60 年西汉设置西域都护","班超经营西域"],"tags":["西域都护","时空观念"]},{"id":"cat-7a-3-2-g2","type":"choice","stem":"下列关于「秦末农民大起义」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","秦亡的原因与启示：赋税徭役沉重、刑法严苛、秦二世更加残暴 → 农民起义。启示：治国要爱惜民力。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-2-g3","type":"choice","stem":"下列结论中，属于「秦末农民大起义」的是","answer":"A","explain":"本课结论：「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：陈胜称王后逐渐脱离群众，用人不当，内部离心；起义军缺乏统一指挥和稳固根据地，终被秦军各个击破。陈胜于公元前 208 年被部下庄贾杀害。（《史记·陈涉世家》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"秦末农民大起义；秦亡的原因与启示：赋税徭役沉重、刑法严苛、秦二世更加残暴 → 农民起义。启示：治国要爱惜民力。","explain":"材料出自《史记·陈涉世家》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-3-3","title":"第11课 西汉建立和“文景之治”","subtitle":"七年级上册 · 第三单元 秦汉时期：统一多民族封建国家的建立和巩固","grade":"7a","tags":["七年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第三单元 秦汉时期：统一多民族封建国家的建立和巩固"},{"k":"课时","v":"第11课 西汉建立和“文景之治”"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"秦亡后四年楚汉相争，刘邦获胜，于公元前 202 年建立汉朝，定都长安，史称西汉。面对经济凋敝、人口锐减的局面，汉初统治者推行休养生息：减轻赋税徭役、释放奴婢、鼓励农耕。文帝、景帝时期社会安定，史称「文景之治」。"},{"type":"note","title":"本课主线 · 因果链","text":"秦朝首次建立统一多民族的中央集权国家并创立一整套制度，但因暴政速亡；汉朝承接秦制而「与民休息」，到汉武帝时在政治、经济、思想、军事上全面巩固大一统。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["公元前 202 年","刘邦建立西汉，定都长安","吸取秦亡教训，推行休养生息政策 · 重点"],["公元前 60 年","西汉设置西域都护","标志西域正式归属中央政权管辖 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"公元前 202 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"刘邦建立西汉，定都长安","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"公元前 60 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"西汉设置西域都护","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"秦亡的原因与启示：赋税徭役沉重、刑法严苛、秦二世更加残暴 → 农民起义。启示：治国要爱惜民力。","explain":"「秦亡汉兴」的对比是必考逻辑：汉初休养生息正是吸取秦亡教训。"},{"level":"选择题","text":"佛教在西汉末年传入中国；道教在东汉时期兴起。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为西域都护设置于东汉。","公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","时间点是最爱设的陷阱，要记「前 60 年、西汉」。"]]},{"type":"table","title":"秦始皇与汉武帝：两次「大一统」的比较（跨条目对比（同一主题、不同手段））","head":["比较项","秦始皇","汉武帝"],"rows":[["政治","创皇帝制、三公九卿、郡县制","颁推恩令、设刺史，削弱诸侯"],["思想","焚书坑儒（高压）","罢黜百家、尊崇儒术（引导）"],["经济","统一货币、度量衡","盐铁官营、统一铸币"],["军事","北击匈奴、筑长城","派卫青霍去病北击匈奴，张骞通西域"],["结果","因暴政速亡","西汉进入鼎盛，大一统巩固"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度创新与影响","以郡县制、推恩令切入，要求说明「中央集权不断加强」的趋势，可与中国近代、世界史的中央与地方关系联动。"],["地图与路线识读","给出丝绸之路示意图，要求写出起点、经过地区与交流内容，考「时空观念」。"],["兴亡启示类","秦亡汉兴的材料对比几乎每年都有变式，落脚在「爱惜民力、以民为本」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：河西走廊与丝绸之路的路线选择；语文：《史记》叙事与人物刻画。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["萧规曹随","曹参继萧何为相，完全遵循其既定法令，比喻沿袭前人成规。","《史记·曹相国世家》"],["文景之治","汉文帝、汉景帝时期政治清明、经济恢复、社会稳定的治世局面。","《汉书·景帝纪》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"汉文帝","v":"刘恒，推行休养生息，废除肉刑，开创文景之治。 出处：《史记·孝文本纪》"},{"k":"汉景帝","v":"刘启，平定七国之乱，延续与民休息政策。 出处：《史记·孝景本纪》"}]},{"type":"list","title":"延伸阅读","items":["轻徭薄赋：汉初田租由「十五税一」减至「三十税一」，文帝一度全免田租；徭役由每年一月减为三年一月。 出处：《汉书·食货志》","缇萦救父：齐太仓令淳于意获罪当受肉刑，其女缇萦上书愿代父受刑，汉文帝因此废除肉刑。 出处：《史记·扁鹊仓公列传》；《汉书·刑法志》"]},{"type":"list","title":"本课拓展出处","items":["《史记·孝文本纪》《汉书·食货志》","2024 部编版七上第 11 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u3-q3","type":"choice","stem":"标志今新疆地区正式归属中央政权管辖的事件是","answer":"C","explain":"公元前 60 年西汉设置西域都护，标志西域正式归属中央政权管辖。","options":["张骞第一次出使西域","丝绸之路的开通","公元前 60 年西汉设置西域都护","班超经营西域"],"tags":["西域都护","时空观念"]},{"id":"cat-7a-3-3-g2","type":"choice","stem":"下列关于「西汉建立和“文景之治”」的表述，错误的是","answer":"A","explain":"认为西域都护设置于东汉——时间点是最爱设的陷阱，要记「前 60 年、西汉」。正确表述：公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","options":["认为西域都护设置于东汉。","公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-3-g3","type":"choice","stem":"下列结论中，属于「西汉建立和“文景之治”」的是","answer":"A","explain":"本课结论：大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：汉初田租由「十五税一」减至「三十税一」，文帝一度全免田租；徭役由每年一月减为三年一月。（《汉书·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"西汉建立和“文景之治”；秦亡的原因与启示：赋税徭役沉重、刑法严苛、秦二世更加残暴 → 农民起义。启示：治国要爱惜民力。","explain":"材料出自《汉书·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7a-3-3-g5","type":"choice","stem":"「刘邦建立西汉，定都长安」发生于","answer":"A","explain":"本课时间轴：刘邦建立西汉，定都长安（公元前 202 年）。吸取秦亡教训，推行休养生息政策。其余三个时间是同一单元相邻课时的事件时间。","options":["公元前 202 年","公元前 221 年","公元前 213—前 212 年","公元前 209 年"],"difficulty":1,"tags":["七年级上册","第三单元","本课练习"]}]},{"id":"cat-7a-3-4","title":"第12课 大一统王朝的巩固","subtitle":"七年级上册 · 第三单元 秦汉时期：统一多民族封建国家的建立和巩固","grade":"7a","tags":["七年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第三单元 秦汉时期：统一多民族封建国家的建立和巩固"},{"k":"课时","v":"第12课 大一统王朝的巩固"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"汉初分封的诸侯王势力膨胀，威胁中央。汉武帝即位后，采纳主父偃建议颁布「推恩令」，使诸侯国越分越小；又采纳董仲舒建议「罢黜百家，尊崇儒术」，设太学；经济上盐铁官营、统一铸五铢钱；军事上派卫青、霍去病北击匈奴。"},{"type":"note","title":"本课主线 · 因果链","text":"秦朝首次建立统一多民族的中央集权国家并创立一整套制度，但因暴政速亡；汉朝承接秦制而「与民休息」，到汉武帝时在政治、经济、思想、军事上全面巩固大一统。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["公元前 2 世纪末","汉武帝在位（前 141—前 87）","推恩令、尊崇儒术、盐铁官营、北击匈奴、张骞通西域 · 重点"],["公元前 138 年、前 119 年","张骞两次出使西域","为丝绸之路的开通奠定基础 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 推恩令：不流血的削藩","caption":"示意图：推恩令：不流血的削藩，详见下方「历史现场」","view":"tall","alt":"示意图：推恩令：不流血的削藩，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"汉初","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"刘邦分封同姓王，诸侯国势力渐大，景帝…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"汉武帝初年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"诸侯王仍「连城数十，地方千里」，威胁…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"前 127 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"主父偃建议颁布推恩令，允许诸侯王分封…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"实施后","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"诸侯国被分割为众多小侯国，势力大为削…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"配套措施","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"汉武帝又设刺史监察地方，酎金夺爵，进…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"汉武帝的大一统：颁「推恩令」削弱诸侯王；「罢黜百家，尊崇儒术」确立儒家学说的正统地位；盐铁官营、统一铸币；北击匈奴（卫青、霍去病）。","explain":"最常考「推恩令为什么高明」：不费一兵一卒就使诸侯国越分越小，加强了中央集权。"},{"level":"重点","text":"丝绸之路：长安 → 河西走廊 → 西域 → 中亚 → 欧洲；汉武帝时开通，张骞两次出使西域是关键。","explain":"要会写作用：促进中西经济文化交流，是古代东西方往来的大动脉。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","它表面是「恩」，实质是削藩，材料题常问「高明之处」。"],["认为「罢黜百家，尊崇儒术」是秦始皇的措施。","这是汉武帝采纳董仲舒建议的措施；秦始皇是「焚书坑儒」。","两者都对思想加强控制，但朝代与手段不同。"]]},{"type":"table","title":"秦始皇与汉武帝：两次「大一统」的比较（跨条目对比（同一主题、不同手段））","head":["比较项","秦始皇","汉武帝"],"rows":[["政治","创皇帝制、三公九卿、郡县制","颁推恩令、设刺史，削弱诸侯"],["思想","焚书坑儒（高压）","罢黜百家、尊崇儒术（引导）"],["经济","统一货币、度量衡","盐铁官营、统一铸币"],["军事","北击匈奴、筑长城","派卫青霍去病北击匈奴，张骞通西域"],["结果","因暴政速亡","西汉进入鼎盛，大一统巩固"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度创新与影响","以郡县制、推恩令切入，要求说明「中央集权不断加强」的趋势，可与中国近代、世界史的中央与地方关系联动。"],["地图与路线识读","给出丝绸之路示意图，要求写出起点、经过地区与交流内容，考「时空观念」。"],["兴亡启示类","秦亡汉兴的材料对比几乎每年都有变式，落脚在「爱惜民力、以民为本」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：河西走廊与丝绸之路的路线选择；语文：《史记》叙事与人物刻画。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 推恩令：不流血的削藩","head":["时间","经过"],"rows":[["汉初","刘邦分封同姓王，诸侯国势力渐大，景帝时爆发七国之乱"],["汉武帝初年","诸侯王仍「连城数十，地方千里」，威胁中央"],["前 127 年","主父偃建议颁布推恩令，允许诸侯王分封子弟为侯"],["实施后","诸侯国被分割为众多小侯国，势力大为削弱"],["配套措施","汉武帝又设刺史监察地方，酎金夺爵，进一步打击诸侯王"]]},{"type":"note","title":"现场解说","text":"推恩令的高明之处在于「以恩之名行削之实」，使诸侯王难以公开反抗。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["罢黜百家，尊崇儒术","汉武帝采纳董仲舒建议，以儒家学说为治国正统，设太学教授五经。","《汉书·董仲舒传》"],["匈奴未灭，何以家为","霍去病的名言，表达以身许国的决心。","《史记·卫将军骠骑列传》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"汉武帝","v":"刘彻，前 141—前 87 在位，推行大一统措施，开疆拓土。 出处：《汉书·武帝纪》"},{"k":"主父偃","v":"汉武帝时大臣，提出推恩令。 出处：《史记·平津侯主父列传》"},{"k":"董仲舒","v":"西汉思想家，提出「罢黜百家，尊崇儒术」。 出处：《汉书·董仲舒传》"},{"k":"霍去病","v":"西汉名将，多次北击匈奴，封冠军侯。 出处：《史记·卫将军骠骑列传》"}]},{"type":"list","title":"延伸阅读","items":["推恩令怎么运作：规定诸侯王除嫡长子继承王位外，可将封地分给其他子弟为列侯，由皇帝制定封号。诸侯国越分越小，中央直辖郡县扩大，不费一兵一卒削弱了王国势力。 出处：《史记·平津侯主父列传》","张骞出使西域：公元前 138 年张骞奉命出使大月氏，途中被匈奴扣留十余年，历尽艰险返回，向汉武帝报告西域见闻，为丝绸之路开通奠定基础。 出处：《史记·大宛列传》"]},{"type":"list","title":"本课拓展出处","items":["《史记·孝武本纪》《汉书·董仲舒传》","2024 部编版七上第 12 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u3-q2","type":"choice","stem":"汉武帝采纳主父偃建议颁布「推恩令」，其高明之处在于","answer":"B","explain":"推恩令让诸侯王的子弟分封土地，封国越分越小，中央集权得到加强，且避免了激化矛盾。","options":["直接剥夺诸侯王的封地","使诸侯国越分越小，不费兵卒削弱了诸侯势力","以武力镇压诸侯叛乱","废除分封，全面推行郡县"],"tags":["推恩令","历史解释"]},{"id":"h7a-u3-q3","type":"choice","stem":"标志今新疆地区正式归属中央政权管辖的事件是","answer":"C","explain":"公元前 60 年西汉设置西域都护，标志西域正式归属中央政权管辖。","options":["张骞第一次出使西域","丝绸之路的开通","公元前 60 年西汉设置西域都护","班超经营西域"],"tags":["西域都护","时空观念"]},{"id":"cat-7a-3-4-g2","type":"choice","stem":"下列关于「大一统王朝的巩固」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","汉武帝的大一统：颁「推恩令」削弱诸侯王；「罢黜百家，尊崇儒术」确立儒家学说的正统地位；盐铁官营、统一铸币；北击匈奴（卫青、霍去病）。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-4-g3","type":"choice","stem":"下列结论中，属于「大一统王朝的巩固」的是","answer":"A","explain":"本课结论：大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：规定诸侯王除嫡长子继承王位外，可将封地分给其他子弟为列侯，由皇帝制定封号。诸侯国越分越小，中央直辖郡县扩大，不费一兵一卒削弱了王国势力。（《史记·平津侯主父列传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"大一统王朝的巩固；汉武帝的大一统：颁「推恩令」削弱诸侯王；「罢黜百家，尊崇儒术」确立儒家学说的正统地位；盐铁官营、统一铸币；北击匈奴（卫青、霍去病）。","explain":"材料出自《史记·平津侯主父列传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-3-5","title":"第13课 东汉的兴衰","subtitle":"七年级上册 · 第三单元 秦汉时期：统一多民族封建国家的建立和巩固","grade":"7a","tags":["七年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第三单元 秦汉时期：统一多民族封建国家的建立和巩固"},{"k":"课时","v":"第13课 东汉的兴衰"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"西汉末年政治腐败、土地兼并严重，王莽篡汉建立新朝，改革失败引发绿林、赤眉起义。公元 25 年，刘秀建立东汉，定都洛阳，史称光武中兴。东汉中后期外戚与宦官交替专权，政治黑暗。"},{"type":"note","title":"本课主线 · 因果链","text":"秦朝首次建立统一多民族的中央集权国家并创立一整套制度，但因暴政速亡；汉朝承接秦制而「与民休息」，到汉武帝时在政治、经济、思想、军事上全面巩固大一统。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["公元 25 年","刘秀建立东汉，定都洛阳","「光武中兴」 · 重点"],["公元 184 年","黄巾起义","沉重打击东汉统治，地方军阀割据形成"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 黄巾起义：一场有组织有准备的民变","caption":"示意图：黄巾起义：一场有组织有准备的民变，详见下方「历史现场」","view":"tall","alt":"示意图：黄巾起义：一场有组织有准备的民变，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"东汉后期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"外戚宦官交替专权，豪强兼并土地，灾荒…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"起义准备","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"张角创立太平道，十余年间徒众达数十万…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"184 年二月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"因弟子告密，起义提前发动，起义者头裹…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"起义高潮","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"黄巾军攻占郡县，焚烧官府，京师震动","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"镇压","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"东汉调集皇甫嵩、朱儁等率军镇压，曹操…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"结果","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"主力九月被镇压，余部坚持多年；地方军…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题（本课考点未单列，以下据本单元时间线整理）","items":[{"level":"重点","text":"刘秀建立东汉，定都洛阳：「光武中兴」","explain":""},{"level":"次重点","text":"黄巾起义：沉重打击东汉统治，地方军阀割据形成","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","它表面是「恩」，实质是削藩，材料题常问「高明之处」。"],["认为「罢黜百家，尊崇儒术」是秦始皇的措施。","这是汉武帝采纳董仲舒建议的措施；秦始皇是「焚书坑儒」。","两者都对思想加强控制，但朝代与手段不同。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度创新与影响","以郡县制、推恩令切入，要求说明「中央集权不断加强」的趋势，可与中国近代、世界史的中央与地方关系联动。"],["地图与路线识读","给出丝绸之路示意图，要求写出起点、经过地区与交流内容，考「时空观念」。"],["兴亡启示类","秦亡汉兴的材料对比几乎每年都有变式，落脚在「爱惜民力、以民为本」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：河西走廊与丝绸之路的路线选择；语文：《史记》叙事与人物刻画。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 黄巾起义：一场有组织有准备的民变","head":["时间","经过"],"rows":[["东汉后期","外戚宦官交替专权，豪强兼并土地，灾荒不断，民不聊生"],["起义准备","张角创立太平道，十余年间徒众达数十万，遍布青、徐、幽、冀等八州"],["184 年二月","因弟子告密，起义提前发动，起义者头裹黄巾为标志"],["起义高潮","黄巾军攻占郡县，焚烧官府，京师震动"],["镇压","东汉调集皇甫嵩、朱儁等率军镇压，曹操、刘备等也参与平乱"],["结果","主力九月被镇压，余部坚持多年；地方军阀借机坐大，东汉名存实亡"]]},{"type":"note","title":"现场解说","text":"黄巾起义是中国历史上第一次利用宗教组织发动的大规模农民起义。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["有志者事竟成","刘秀称赞耿弇「有志者事竟成也」，意为有志向的人终能成功。","《后汉书·耿弇传》"],["投笔从戎","班超弃文从军，出使西域，比喻弃文就武、报效国家。","《后汉书·班超传》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"刘秀","v":"汉光武帝，东汉建立者，开创光武中兴。 出处：《后汉书·光武帝纪》"},{"k":"张角","v":"太平道创始人，黄巾起义领袖。 出处：《后汉书·皇甫嵩传》"}]},{"type":"list","title":"延伸阅读","items":["光武中兴的措施：刘秀多次下诏释放奴婢，减轻赋税，精简机构，裁并四百余县，整顿吏治，使社会生产得到恢复。 出处：《后汉书·光武帝纪》","黄巾起义：184 年，张角以太平道组织群众，提出「苍天已死，黄天当立」，起义者头裹黄巾，席卷八州，虽被镇压，但东汉统治由此瓦解。 出处：《后汉书·皇甫嵩传》"]},{"type":"list","title":"本课拓展出处","items":["《后汉书·光武帝纪》《后汉书·皇甫嵩传》","2024 部编版七上第 13 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u3-q1","type":"choice","stem":"秦朝在地方上推行的、对后世影响最深远的制度是","answer":"B","explain":"郡县制下郡县长官由皇帝直接任免、不世袭，开创了此后两千多年的中央集权地方行政制度。行省制是元朝，科举制是隋朝。","options":["分封制","郡县制","行省制","科举制"],"tags":["郡县制","制度创新"]},{"id":"h7a-u3-q2","type":"choice","stem":"汉武帝采纳主父偃建议颁布「推恩令」，其高明之处在于","answer":"B","explain":"推恩令让诸侯王的子弟分封土地，封国越分越小，中央集权得到加强，且避免了激化矛盾。","options":["直接剥夺诸侯王的封地","使诸侯国越分越小，不费兵卒削弱了诸侯势力","以武力镇压诸侯叛乱","废除分封，全面推行郡县"],"tags":["推恩令","历史解释"]},{"id":"h7a-u3-q3","type":"choice","stem":"标志今新疆地区正式归属中央政权管辖的事件是","answer":"C","explain":"公元前 60 年西汉设置西域都护，标志西域正式归属中央政权管辖。","options":["张骞第一次出使西域","丝绸之路的开通","公元前 60 年西汉设置西域都护","班超经营西域"],"tags":["西域都护","时空观念"]},{"id":"cat-7a-3-5-g2","type":"choice","stem":"下列关于「东汉的兴衰」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-5-g3","type":"choice","stem":"下列结论中，属于「东汉的兴衰」的是","answer":"A","explain":"本课结论：秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-5-g4","type":"short","stem":"阅读材料，回答问题。\n材料：刘秀多次下诏释放奴婢，减轻赋税，精简机构，裁并四百余县，整顿吏治，使社会生产得到恢复。（《后汉书·光武帝纪》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"东汉的兴衰；刘秀建立东汉，定都洛阳：「光武中兴」","explain":"材料出自《后汉书·光武帝纪》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-3-6","title":"第14课 丝绸之路的开通与经营西域","subtitle":"七年级上册 · 第三单元 秦汉时期：统一多民族封建国家的建立和巩固","grade":"7a","tags":["七年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第三单元 秦汉时期：统一多民族封建国家的建立和巩固"},{"k":"课时","v":"第14课 丝绸之路的开通与经营西域"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"汉朝时期，中国与西域的联系逐步密切。公元前 138 年、前 119 年，张骞两次出使西域，开辟了从长安经河西走廊、西域通往中亚、西亚的陆上通道，后世称为「丝绸之路」。"},{"type":"note","title":"本课主线 · 因果链","text":"秦朝首次建立统一多民族的中央集权国家并创立一整套制度，但因暴政速亡；汉朝承接秦制而「与民休息」，到汉武帝时在政治、经济、思想、军事上全面巩固大一统。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["公元前 202 年","刘邦建立西汉，定都长安","吸取秦亡教训，推行休养生息政策 · 重点"],["公元前 2 世纪末","汉武帝在位（前 141—前 87）","推恩令、尊崇儒术、盐铁官营、北击匈奴、张骞通西域 · 重点"],["公元前 138 年、前 119 年","张骞两次出使西域","为丝绸之路的开通奠定基础 · 重点"],["公元前 60 年","西汉设置西域都护","标志西域正式归属中央政权管辖 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"公元前 202 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"刘邦建立西汉，定都长安","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"公元前 2 世纪末","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"汉武帝在位（前 141—前 87）","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"公元前 138 年、前 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"张骞两次出使西域","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"公元前 60 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"西汉设置西域都护","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"丝绸之路：长安 → 河西走廊 → 西域 → 中亚 → 欧洲；汉武帝时开通，张骞两次出使西域是关键。","explain":"要会写作用：促进中西经济文化交流，是古代东西方往来的大动脉。"},{"level":"次重点","text":"西域都护（公元前 60 年）的设置，标志着今新疆地区正式归属中央政权管辖。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为西域都护设置于东汉。","公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","时间点是最爱设的陷阱，要记「前 60 年、西汉」。"]]},{"type":"table","title":"秦始皇与汉武帝：两次「大一统」的比较（跨条目对比（同一主题、不同手段））","head":["比较项","秦始皇","汉武帝"],"rows":[["政治","创皇帝制、三公九卿、郡县制","颁推恩令、设刺史，削弱诸侯"],["思想","焚书坑儒（高压）","罢黜百家、尊崇儒术（引导）"],["经济","统一货币、度量衡","盐铁官营、统一铸币"],["军事","北击匈奴、筑长城","派卫青霍去病北击匈奴，张骞通西域"],["结果","因暴政速亡","西汉进入鼎盛，大一统巩固"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度创新与影响","以郡县制、推恩令切入，要求说明「中央集权不断加强」的趋势，可与中国近代、世界史的中央与地方关系联动。"],["地图与路线识读","给出丝绸之路示意图，要求写出起点、经过地区与交流内容，考「时空观念」。"],["兴亡启示类","秦亡汉兴的材料对比几乎每年都有变式，落脚在「爱惜民力、以民为本」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：河西走廊与丝绸之路的路线选择；语文：《史记》叙事与人物刻画。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["凿空","司马迁称张骞出使西域「凿空」，意为开通道路、首创其事。","《史记·大宛列传》"],["不入虎穴，焉得虎子","班超夜袭匈奴使者营地时所说，比喻不冒险就难以成功。","《后汉书·班超传》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"张骞","v":"西汉使者，两次出使西域，被誉为「丝绸之路的开拓者」。 出处：《史记·大宛列传》"},{"k":"班超","v":"东汉名将，经营西域三十余年，派甘英出使大秦。 出处：《后汉书·班超传》"}]},{"type":"list","title":"延伸阅读","items":["西域都护：公元前 60 年，西汉设置西域都护，管理西域事务，标志着西域正式归属中央政权管辖。 出处：《汉书·西域传》","甘英出使大秦：公元 97 年，班超派甘英出使大秦（罗马帝国），甘英到达波斯湾一带，因当地船夫劝阻而返回，是中国古代使者到达的最西地点之一。 出处：《后汉书·西域传》"]},{"type":"list","title":"本课拓展出处","items":["《史记·大宛列传》《汉书·西域传》《后汉书·班超传》","2024 部编版七上第 14 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u3-q3","type":"choice","stem":"标志今新疆地区正式归属中央政权管辖的事件是","answer":"C","explain":"公元前 60 年西汉设置西域都护，标志西域正式归属中央政权管辖。","options":["张骞第一次出使西域","丝绸之路的开通","公元前 60 年西汉设置西域都护","班超经营西域"],"tags":["西域都护","时空观念"]},{"id":"cat-7a-3-6-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 刘邦建立西汉，定都长安\n② 汉武帝在位（前 141—前 87）\n③ 张骞两次出使西域\n④ 西汉设置西域都护","answer":"A","explain":"按时间顺序应为：①刘邦建立西汉，定都长安（公元前 202 年）→②汉武帝在位（前 141—前 87）（公元前 2 世纪末）→③张骞两次出使西域（公元前 138 年、前 119 年）→④西汉设置西域都护（公元前 60 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-6-g2","type":"choice","stem":"下列关于「丝绸之路的开通与经营西域」的表述，错误的是","answer":"A","explain":"认为西域都护设置于东汉——时间点是最爱设的陷阱，要记「前 60 年、西汉」。正确表述：公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","options":["认为西域都护设置于东汉。","公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。","丝绸之路：长安 → 河西走廊 → 西域 → 中亚 → 欧洲；汉武帝时开通，张骞两次出使西域是关键。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-6-g3","type":"choice","stem":"下列结论中，属于「丝绸之路的开通与经营西域」的是","answer":"A","explain":"本课结论：丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-6-g4","type":"short","stem":"阅读材料，回答问题。\n材料：公元前 60 年，西汉设置西域都护，管理西域事务，标志着西域正式归属中央政权管辖。（《汉书·西域传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"丝绸之路的开通与经营西域；丝绸之路：长安 → 河西走廊 → 西域 → 中亚 → 欧洲；汉武帝时开通，张骞两次出使西域是关键。","explain":"材料出自《汉书·西域传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-3-7","title":"第15课 秦汉时期的科技与文化","subtitle":"七年级上册 · 第三单元 秦汉时期：统一多民族封建国家的建立和巩固","grade":"7a","tags":["七年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第三单元 秦汉时期：统一多民族封建国家的建立和巩固"},{"k":"课时","v":"第15课 秦汉时期的科技与文化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"秦汉时期，造纸术、医学、史学、宗教等领域成就斐然。西汉已有纸，105 年蔡伦改进造纸术，使纸张得以普及；张仲景著《伤寒杂病论》，华佗创麻沸散；司马迁著《史记》，开创纪传体通史体例。"},{"type":"note","title":"本课主线 · 因果链","text":"秦朝首次建立统一多民族的中央集权国家并创立一整套制度，但因暴政速亡；汉朝承接秦制而「与民休息」，到汉武帝时在政治、经济、思想、军事上全面巩固大一统。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["公元前 221 年","秦灭六国，嬴政称「始皇帝」，定都咸阳","我国历史上第一个统一多民族的封建国家 · 重点"],["公元前 213—前 212 年","焚书坑儒","加强思想控制，摧残了文化"],["公元前 209 年","陈胜、吴广在大泽乡起义","中国历史上第一次大规模的农民起义 · 重点"],["公元前 202 年","刘邦建立西汉，定都长安","吸取秦亡教训，推行休养生息政策 · 重点"],["公元前 2 世纪末","汉武帝在位（前 141—前 87）","推恩令、尊崇儒术、盐铁官营、北击匈奴、张骞通西域 · 重点"],["公元前 138 年、前 119 年","张骞两次出使西域","为丝绸之路的开通奠定基础 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"公元前 221 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"秦灭六国，嬴政称「始皇帝」，定都咸阳","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"公元前 213—前 21…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"焚书坑儒","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"公元前 209 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"陈胜、吴广在大泽乡起义","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"公元前 202 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"刘邦建立西汉，定都长安","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"公元前 2 世纪末","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"汉武帝在位（前 141—前 87）","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"公元前 138 年、前 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"张骞两次出使西域","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"次重点","text":"两汉科技文化：蔡伦改进造纸术、张仲景《伤寒杂病论》、华佗、司马迁《史记》（我国第一部纪传体通史）。","explain":""},{"level":"选择题","text":"佛教在西汉末年传入中国；道教在东汉时期兴起。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","它表面是「恩」，实质是削藩，材料题常问「高明之处」。"],["认为「罢黜百家，尊崇儒术」是秦始皇的措施。","这是汉武帝采纳董仲舒建议的措施；秦始皇是「焚书坑儒」。","两者都对思想加强控制，但朝代与手段不同。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度创新与影响","以郡县制、推恩令切入，要求说明「中央集权不断加强」的趋势，可与中国近代、世界史的中央与地方关系联动。"],["地图与路线识读","给出丝绸之路示意图，要求写出起点、经过地区与交流内容，考「时空观念」。"],["兴亡启示类","秦亡汉兴的材料对比几乎每年都有变式，落脚在「爱惜民力、以民为本」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：河西走廊与丝绸之路的路线选择；语文：《史记》叙事与人物刻画。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["人固有一死，或重于泰山，或轻于鸿毛","司马迁《报任安书》名句，表达忍辱负重完成《史记》的决心。","司马迁《报任安书》"],["医圣","张仲景著《伤寒杂病论》，奠定中医治疗学基础，被后世尊为「医圣」。","《后汉书·张仲景传》；2024 部编版七上第 15 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"蔡伦","v":"东汉宦官，改进造纸术，封龙亭侯。 出处：《后汉书·蔡伦传》"},{"k":"张仲景","v":"东汉医学家，著《伤寒杂病论》，被尊为医圣。 出处：《后汉书》相关记载"},{"k":"华佗","v":"东汉名医，创麻沸散、五禽戏。 出处：《三国志·魏书·方技传》"},{"k":"司马迁","v":"西汉史学家，著《史记》。 出处：《史记·太史公自序》"}]},{"type":"list","title":"延伸阅读","items":["蔡伦改进造纸术：蔡伦用树皮、麻头、破布、旧渔网等原料，经沤、煮、捣、抄等工序造纸，成本低、质量好，被称为「蔡侯纸」。 出处：《后汉书·蔡伦传》","《史记》的地位：《史记》记载从黄帝到汉武帝约三千年历史，共 130 篇，首创本纪、表、书、世家、列传五体，鲁迅誉为「史家之绝唱，无韵之离骚」。 出处：鲁迅《汉文学史纲要》"]},{"type":"list","title":"本课拓展出处","items":["《后汉书·蔡伦传》《史记·太史公自序》","2024 部编版七上第 15 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】秦为乱政虐刑以残贼天下，数十年矣……百姓困穷，而吏弗恤。——《史记》\n【材料二】（汉初）民失作业，而大饥馑……上于是约法省禁，轻田租，什五而税一。——《汉书·食货志》\n【材料三】愿陛下令诸侯得推恩分子弟，以地侯之……于是藩国始分，而子弟毕侯矣。——《汉书·主父偃传》","source":"材料研读 · 秦汉时期：统一多民族封建国家的建立和巩固"}],"questions":[{"id":"h7a-u3-q4","type":"choice","stem":"下列著作中，被称为我国第一部纪传体通史的是","answer":"B","explain":"《史记》由司马迁撰写，记述从黄帝到汉武帝时期的历史，是我国第一部纪传体通史。《资治通鉴》是编年体。","options":["《春秋》","《史记》","《汉书》","《资治通鉴》"],"tags":["司马迁","文化成就"]},{"id":"cat-7a-3-7-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 秦灭六国，嬴政称「始皇帝」，定都咸阳\n② 焚书坑儒\n③ 陈胜、吴广在大泽乡起义\n④ 刘邦建立西汉，定都长安","answer":"A","explain":"按时间顺序应为：①秦灭六国，嬴政称「始皇帝」，定都咸阳（公元前 221 年）→②焚书坑儒（公元前 213—前 212 年）→③陈胜、吴广在大泽乡起义（公元前 209 年）→④刘邦建立西汉，定都长安（公元前 202 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-7-g2","type":"choice","stem":"下列关于「秦汉时期的科技与文化」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-7-g3","type":"choice","stem":"下列结论中，属于「秦汉时期的科技与文化」的是","answer":"A","explain":"本课结论：秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-7-g4","type":"short","stem":"阅读材料，回答问题。\n材料：蔡伦用树皮、麻头、破布、旧渔网等原料，经沤、煮、捣、抄等工序造纸，成本低、质量好，被称为「蔡侯纸」。（《后汉书·蔡伦传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"秦汉时期的科技与文化；两汉科技文化：蔡伦改进造纸术、张仲景《伤寒杂病论》、华佗、司马迁《史记》（我国第一部纪传体通史）。","explain":"材料出自《后汉书·蔡伦传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-4-1","title":"第16课 三国鼎立","subtitle":"七年级上册 · 第四单元 三国两晋南北朝时期：政权分立与民族交融","grade":"7a","tags":["七年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第四单元 三国两晋南北朝时期：政权分立与民族交融"},{"k":"课时","v":"第16课 三国鼎立"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"东汉末年，军阀混战。200 年官渡之战，曹操以少胜多击败袁绍，统一北方。208 年赤壁之战，孙权、刘备联军以火攻击败曹操，奠定三国鼎立的基础。220 年曹丕称帝建魏，221 年刘备建蜀，229 年孙权称帝建吴。"},{"type":"note","title":"本课主线 · 因果链","text":"政权长期分立、战乱频繁，但北方民族大交融与江南地区的开发同时推进，为隋唐的重新统一与繁荣奠定了基础。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["200 年","官渡之战","曹操打败袁绍，为统一北方奠定基础 · 重点"],["208 年","赤壁之战","孙刘联军以少胜多，为三国鼎立局面形成奠定基础 · 重点"],["220 年","曹丕称帝建魏，定都洛阳","东汉灭亡；221 年刘备建汉（蜀），229 年孙权称帝建吴 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 赤壁之战：火烧连环船","caption":"示意图：赤壁之战：火烧连环船，详见下方「历史现场」","view":"tall","alt":"示意图：赤壁之战：火烧连环船，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"208 年秋","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"曹操率二十余万大军南下，刘琮投降，刘…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"战前","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"孙权命周瑜率三万精兵与刘备联军，双方…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"初战","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"曹军多北方人，不习水战，且军中疫病流…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"火攻","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"黄盖诈降，以十艘蒙冲斗舰载薪草膏油，…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"结果","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"曹军大败，曹操退回北方，孙刘联军获胜","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"三国鼎立：魏（220，曹丕，洛阳）、汉/蜀（221，刘备，成都）、吴（229，孙权，建业）；赤壁之战是局面形成的关键战役。","explain":"常考「三国鼎立是历史的进步还是倒退」：从分裂看是割据，从局部统一与恢复经济看是进步。"},{"level":"选择题","text":"官渡之战与赤壁之战都是以少胜多的战役，但官渡之战统一了北方，赤壁之战阻止了曹操统一南方。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","官渡之战与赤壁之战的结果、意义最容易被调换。"]]},{"type":"table","title":"官渡之战与赤壁之战（两次以少胜多的战役对比）","head":["比较项","官渡之战（200 年）","赤壁之战（208 年）"],"rows":[["交战双方","曹操 vs 袁绍","曹操 vs 孙刘联军"],["结果","曹操胜","曹操败"],["意义","为统一北方奠定基础","为三国鼎立局面形成奠定基础"],["共同启示","战争胜负不取决于兵力多少，而取决于战略战术与人心","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["战役与格局","给出战役示意图或兵力对比材料，要求判断战役并说明其对政治格局的影响，标准答法是「为……奠定基础」。"],["改革的评价与民族交融","以孝文帝改革为背景，要求「结合措施说明改革如何促进民族交融」，需逐条对应。"],["因果链条题","「人口南迁 → 江南开发 → 经济重心南移」这条链条常与唐宋经济重心南移合并成大题。"]]},{"type":"note","title":"跨学科视角","text":"地理：北方民族内迁与农牧交错带；语文：《木兰诗》中的南北与战争。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 赤壁之战：火烧连环船","head":["时间","经过"],"rows":[["208 年秋","曹操率二十余万大军南下，刘琮投降，刘备败走夏口"],["战前","孙权命周瑜率三万精兵与刘备联军，双方会于赤壁"],["初战","曹军多北方人，不习水战，且军中疫病流行，初战不利"],["火攻","黄盖诈降，以十艘蒙冲斗舰载薪草膏油，趁东南风纵火，曹军船阵连环延烧"],["结果","曹军大败，曹操退回北方，孙刘联军获胜"]]},{"type":"note","title":"现场解说","text":"赤壁之战是中国历史上著名的以弱胜强战役，奠定了三国鼎立的基础。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["挟天子以令诸侯","曹操将汉献帝迎至许昌，借皇帝名义发号施令。","《三国志·魏书·武帝纪》"],["三顾茅庐","刘备三次到隆中拜访诸葛亮，比喻诚心邀请贤才。","《三国志·蜀书·诸葛亮传》"],["草船借箭","小说《三国演义》情节，正史无载，比喻运用智谋借力成事。","罗贯中《三国演义》第四十六回"]]},{"type":"kv","title":"人物卡片","items":[{"k":"曹操","v":"字孟德，东汉末年政治家、军事家，统一北方。 出处：《三国志·魏书·武帝纪》"},{"k":"诸葛亮","v":"字孔明，蜀汉丞相，提出「隆中对」战略。 出处：《三国志·蜀书·诸葛亮传》"},{"k":"周瑜","v":"字公瑾，东吴名将，赤壁之战主要指挥者。 出处：《三国志·吴书·周瑜传》"}]},{"type":"list","title":"延伸阅读","items":["赤壁之战：曹操率军南下，孙权派周瑜、刘备派诸葛亮联合抗曹。联军利用曹军不习水战、疫病流行等弱点，以火攻大破曹军。 出处：《三国志·吴书·周瑜传》","史实与演义的区别：「草船借箭」「借东风」等情节出自小说《三国演义》，正史无载；「三顾茅庐」则见于《三国志·诸葛亮传》「凡三往，乃见」。 出处：《三国志·蜀书·诸葛亮传》；罗贯中《三国演义》"]},{"type":"list","title":"本课拓展出处","items":["《三国志·魏书·武帝纪》《三国志·蜀书·诸葛亮传》","2024 部编版七上第 16 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u4-q1","type":"choice","stem":"为三国鼎立局面形成奠定基础的战役是","answer":"B","explain":"208 年赤壁之战中孙刘联军打败曹操，为三国鼎立局面的形成奠定基础。官渡之战为曹操统一北方奠定基础。","options":["官渡之战","赤壁之战","淝水之战","巨鹿之战"],"tags":["赤壁之战","时空观念"]},{"id":"cat-7a-4-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 官渡之战\n② 赤壁之战\n③ 曹丕称帝建魏，定都洛阳","answer":"A","explain":"按时间顺序应为：①官渡之战（200 年）→②赤壁之战（208 年）→③曹丕称帝建魏，定都洛阳（220 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-1-g2","type":"choice","stem":"下列关于「三国鼎立」的表述，错误的是","answer":"A","explain":"认为赤壁之战使曹操统一了全国——官渡之战与赤壁之战的结果、意义最容易被调换。正确表述：赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","options":["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-1-g3","type":"choice","stem":"下列结论中，属于「三国鼎立」的是","answer":"A","explain":"本课结论：分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","文化成就与时代相关：战乱与民族交融时期，宗教艺术（石窟）与书法艺术特别兴盛。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：曹操率军南下，孙权派周瑜、刘备派诸葛亮联合抗曹。联军利用曹军不习水战、疫病流行等弱点，以火攻大破曹军。（《三国志·吴书·周瑜传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"三国鼎立；三国鼎立：魏（220，曹丕，洛阳）、汉/蜀（221，刘备，成都）、吴（229，孙权，建业）；赤壁之战是局面形成的关键战役。","explain":"材料出自《三国志·吴书·周瑜传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-4-2","title":"第17课 西晋的短暂统一和北方各族的内迁","subtitle":"七年级上册 · 第四单元 三国两晋南北朝时期：政权分立与民族交融","grade":"7a","tags":["七年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第四单元 三国两晋南北朝时期：政权分立与民族交融"},{"k":"课时","v":"第17课 西晋的短暂统一和北方各族的内迁"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"266 年司马炎建立西晋，280 年灭吴，短暂统一全国。西晋统治集团奢侈腐化，291—306 年爆发「八王之乱」，国力耗尽。与此同时，匈奴、鲜卑、羯、氐、羌等北方民族大量内迁，与汉族杂居。316 年西晋被内迁匈奴所灭。"},{"type":"note","title":"本课主线 · 因果链","text":"政权长期分立、战乱频繁，但北方民族大交融与江南地区的开发同时推进，为隋唐的重新统一与繁荣奠定了基础。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["280 年","西晋灭吴，统一全国","统一局面短暂 · 重点"],["316 年","内迁匈奴人灭西晋","317 年司马睿在建康建立东晋 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"280 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"西晋灭吴，统一全国","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"316 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"内迁匈奴人灭西晋","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"次重点","text":"民族交融的表现：内迁各族与汉族杂居、通婚、相互学习（生产、饮食、服饰、语言、习俗）。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","官渡之战与赤壁之战的结果、意义最容易被调换。"],["把北魏孝文帝改革只理解为「学习汉族文化」。","本质是顺应民族交融趋势、巩固统治的改革，客观上促进了民族交融与北方经济发展。","材料题要求归纳「改革与民族交融的关系」，只答「学汉文化」会丢分。"]]},{"type":"table","title":"魏晋南北朝与欧洲中世纪早期（中外对比：分裂动荡时期的共同特征）","head":["比较项","中国（220—589）","西欧（5—10 世纪）"],"rows":[["政治","政权分立、更替频繁","西罗马帝国灭亡后王国林立"],["民族关系","少数民族内迁，民族大交融","日耳曼诸族迁徙建国，与罗马因素融合"],["文化","佛教兴盛、石窟艺术、书法","基督教影响扩大"],["共同趋势","动荡中孕育新的统一与制度","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["战役与格局","给出战役示意图或兵力对比材料，要求判断战役并说明其对政治格局的影响，标准答法是「为……奠定基础」。"],["改革的评价与民族交融","以孝文帝改革为背景，要求「结合措施说明改革如何促进民族交融」，需逐条对应。"],["因果链条题","「人口南迁 → 江南开发 → 经济重心南移」这条链条常与唐宋经济重心南移合并成大题。"]]},{"type":"note","title":"跨学科视角","text":"地理：北方民族内迁与农牧交错带；语文：《木兰诗》中的南北与战争。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["洛阳纸贵","左思《三都赋》写成后，洛阳豪贵竞相传抄，纸价上涨，比喻作品风行一时。","《晋书·左思传》"],["八王之乱","西晋宗室八王争夺政权的混战，导致西晋衰亡。","《晋书·八王传》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"司马炎","v":"晋武帝，西晋建立者，280 年灭吴统一。 出处：《晋书·武帝纪》"},{"k":"左思","v":"西晋文学家，著《三都赋》。 出处：《晋书·左思传》"}]},{"type":"list","title":"延伸阅读","items":["八王之乱：西晋宗室诸王为争夺中央权力，先后有八位诸侯王卷入混战，历时十六年，中原人口大量死亡、南迁，形成第一次大规模南迁浪潮。 出处：《晋书·八王传》","内迁各族：东汉以来，匈奴、鲜卑、羯、氐、羌等族陆续内迁至黄河流域，西晋时内迁人口达数百万，与汉族杂居，受汉族地主压迫。 出处：《晋书·匈奴传》；2024 部编版七上第 17 课"]},{"type":"list","title":"本课拓展出处","items":["《晋书·武帝纪》《晋书·八王传》","2024 部编版七上第 17 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u4-q1","type":"choice","stem":"为三国鼎立局面形成奠定基础的战役是","answer":"B","explain":"208 年赤壁之战中孙刘联军打败曹操，为三国鼎立局面的形成奠定基础。官渡之战为曹操统一北方奠定基础。","options":["官渡之战","赤壁之战","淝水之战","巨鹿之战"],"tags":["赤壁之战","时空观念"]},{"id":"h7a-u4-q2","type":"choice","stem":"北魏孝文帝改革措施中，最能体现民族交融的是","answer":"B","explain":"语言、服饰、姓氏与婚姻的汉化直接促进了鲜卑族与汉族的交融；迁都洛阳是为改革创造条件。","options":["迁都洛阳","说汉语、穿汉服、改汉姓、与汉族通婚","奖励军功","实行均田制"],"tags":["孝文帝改革","民族交融"]},{"id":"h7a-u4-q3","type":"choice","stem":"魏晋南北朝时期江南地区得到开发的最主要原因是","answer":"B","explain":"北人南迁带来了劳动力与先进的生产技术，是江南开发最主要的原因，其余是重要条件。","options":["江南自然条件优越","北方人口大量南迁，带来劳动力和先进技术","南方统治者重视农业","南方战乱较少"],"tags":["江南开发","唯物史观"]},{"id":"cat-7a-4-2-g2","type":"choice","stem":"下列关于「西晋的短暂统一和北方各族的内迁」的表述，错误的是","answer":"A","explain":"认为赤壁之战使曹操统一了全国——官渡之战与赤壁之战的结果、意义最容易被调换。正确表述：赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","options":["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-2-g3","type":"choice","stem":"下列结论中，属于「西晋的短暂统一和北方各族的内迁」的是","answer":"A","explain":"本课结论：分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","文化成就与时代相关：战乱与民族交融时期，宗教艺术（石窟）与书法艺术特别兴盛。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：西晋宗室诸王为争夺中央权力，先后有八位诸侯王卷入混战，历时十六年，中原人口大量死亡、南迁，形成第一次大规模南迁浪潮。（《晋书·八王传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"西晋的短暂统一和北方各族的内迁；民族交融的表现：内迁各族与汉族杂居、通婚、相互学习（生产、饮食、服饰、语言、习俗）。","explain":"材料出自《晋书·八王传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-4-3","title":"第18课 东晋南朝政治和江南地区开发","subtitle":"七年级上册 · 第四单元 三国两晋南北朝时期：政权分立与民族交融","grade":"7a","tags":["七年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第四单元 三国两晋南北朝时期：政权分立与民族交融"},{"k":"课时","v":"第18课 东晋南朝政治和江南地区开发"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"317 年司马睿建立东晋，定都建康，形成「王与马，共天下」的门阀政治格局。北方人口大量南迁，带来劳动力、先进工具和技术，江南地区得到开发。383 年淝水之战，东晋以少胜多击败前秦。南朝宋、齐、梁、陈相继更替。"},{"type":"note","title":"本课主线 · 因果链","text":"政权长期分立、战乱频繁，但北方民族大交融与江南地区的开发同时推进，为隋唐的重新统一与繁荣奠定了基础。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["316 年","内迁匈奴人灭西晋","317 年司马睿在建康建立东晋 · 重点"],["383 年","淝水之战","东晋以少胜多击败前秦，北方重新陷入分裂 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"316 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"内迁匈奴人灭西晋","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"383 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"淝水之战","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"江南地区的开发：北方人口南迁带来劳动力与先进技术，加上江南自然条件优越、社会相对安定，为经济重心南移打下基础。","explain":"要分清「原因（人口南迁、技术、环境、安定）」与「表现（农业、手工业、商业）」两层。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为江南开发只是因为自然条件好。","主要原因是北方人口南迁带来劳动力与先进生产技术，自然条件与社会安定是重要条件。","「主要原因」与「条件」的区分是得分点。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["战役与格局","给出战役示意图或兵力对比材料，要求判断战役并说明其对政治格局的影响，标准答法是「为……奠定基础」。"],["改革的评价与民族交融","以孝文帝改革为背景，要求「结合措施说明改革如何促进民族交融」，需逐条对应。"],["因果链条题","「人口南迁 → 江南开发 → 经济重心南移」这条链条常与唐宋经济重心南移合并成大题。"]]},{"type":"note","title":"跨学科视角","text":"地理：北方民族内迁与农牧交错带；语文：《木兰诗》中的南北与战争。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["闻鸡起舞","祖逖与刘琨闻鸡鸣即起床练剑，比喻立志奋发。","《晋书·祖逖传》"],["东山再起","谢安隐居东山后复出，官至宰相，比喻失势后重新崛起。","《晋书·谢安传》"],["草木皆兵","淝水之战中苻坚登城远望，把草木都当成晋军，形容惊恐多疑。","《晋书·苻坚载记》"],["风声鹤唳","前秦败兵听到风声鹤叫都以为追兵，形容惊慌失措。","《晋书·谢玄传》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"祖逖","v":"东晋名将，率军北伐，闻鸡起舞故事的主角。 出处：《晋书·祖逖传》"},{"k":"谢安","v":"东晋政治家，淝水之战时任宰相，镇定指挥。 出处：《晋书·谢安传》"}]},{"type":"list","title":"延伸阅读","items":["江南开发的原因：北方人口南迁补充劳动力，带来先进农业生产工具和技术；江南雨量充沛、气候温暖、土地肥沃；南方战乱较少，社会相对安定。 出处：2024 部编版七上第 18 课","淝水之战：383 年，前秦苻坚率大军南下，东晋谢石、谢玄率八万北府兵迎战。前秦军阵脚大乱，自相践踏，大败而归。 出处：《晋书·谢玄传》；《资治通鉴》卷一〇五"]},{"type":"list","title":"本课拓展出处","items":["《晋书·谢安传》《宋书》","2024 部编版七上第 18 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】（孝文帝）诏不得以北俗之语言于朝廷，若有违者，免所居官。——《魏书》\n【材料二】（孝文帝）改拓跋氏为元氏……其余所改，不可胜纪。——《资治通鉴》\n【材料三】（江南）地广野丰，民勤本业，一岁或稔，则数郡忘饥。——《宋书》","source":"材料研读 · 三国两晋南北朝时期：政权分立与民族交融"}],"questions":[{"id":"h7a-u4-q1","type":"choice","stem":"为三国鼎立局面形成奠定基础的战役是","answer":"B","explain":"208 年赤壁之战中孙刘联军打败曹操，为三国鼎立局面的形成奠定基础。官渡之战为曹操统一北方奠定基础。","options":["官渡之战","赤壁之战","淝水之战","巨鹿之战"],"tags":["赤壁之战","时空观念"]},{"id":"h7a-u4-q3","type":"choice","stem":"魏晋南北朝时期江南地区得到开发的最主要原因是","answer":"B","explain":"北人南迁带来了劳动力与先进的生产技术，是江南开发最主要的原因，其余是重要条件。","options":["江南自然条件优越","北方人口大量南迁，带来劳动力和先进技术","南方统治者重视农业","南方战乱较少"],"tags":["江南开发","唯物史观"]},{"id":"h7a-u4-q4","type":"choice","stem":"把圆周率精确到小数点以后第七位数字的南朝科学家是","answer":"B","explain":"祖冲之在数学上把圆周率精确到小数点后第七位，领先世界近千年。","options":["贾思勰","祖冲之","郦道元","王羲之"],"tags":["科技文化","祖冲之"]},{"id":"cat-7a-4-3-g2","type":"choice","stem":"下列关于「东晋南朝政治和江南地区开发」的表述，错误的是","answer":"A","explain":"认为江南开发只是因为自然条件好——「主要原因」与「条件」的区分是得分点。正确表述：主要原因是北方人口南迁带来劳动力与先进生产技术，自然条件与社会安定是重要条件。","options":["认为江南开发只是因为自然条件好。","主要原因是北方人口南迁带来劳动力与先进生产技术，自然条件与社会安定是重要条件。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：北方人口南迁补充劳动力，带来先进农业生产工具和技术；江南雨量充沛、气候温暖、土地肥沃；南方战乱较少，社会相对安定。（2024 部编版七上第 18 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"东晋南朝政治和江南地区开发；江南地区的开发：北方人口南迁带来劳动力与先进技术，加上江南自然条件优越、社会相对安定，为经济重心南移打下基础。","explain":"材料出自2024 部编版七上第 18 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-4-4","title":"第19课 北朝政治和北方民族大交融","subtitle":"七年级上册 · 第四单元 三国两晋南北朝时期：政权分立与民族交融","grade":"7a","tags":["七年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第四单元 三国两晋南北朝时期：政权分立与民族交融"},{"k":"课时","v":"第19课 北朝政治和北方民族大交融"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"439 年北魏统一北方，结束了十六国混战。北魏孝文帝推行改革：迁都洛阳，改鲜卑姓为汉姓，说汉语，穿汉服，与汉族通婚，学习汉族礼法。改革促进了民族交融，也增强了北魏实力。"},{"type":"note","title":"本课主线 · 因果链","text":"政权长期分立、战乱频繁，但北方民族大交融与江南地区的开发同时推进，为隋唐的重新统一与繁荣奠定了基础。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["439 年","北魏统一北方","北方进入相对稳定的发展时期 · 重点"],["494 年前后","北魏孝文帝迁都洛阳并推行汉化改革","说汉语、穿汉服、改汉姓、通婚姻——民族交融的高峰 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 孝文帝改革：一场自上而下的汉化","caption":"示意图：孝文帝改革：一场自上而下的汉化，详见下方「历史现场」","view":"tall","alt":"示意图：孝文帝改革：一场自上而下的汉化，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"439 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"北魏统一北方，鲜卑族与汉族杂居，民族…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"490 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"孝文帝亲政，决心推行汉化改革","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"494 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"以「南伐」为名，迁都洛阳","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"迁都后","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"下令鲜卑人改穿汉服、说汉语，改鲜卑姓…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"鼓励通婚","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"孝文帝带头娶汉族士族女子，并令鲜卑贵…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"影响","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"促进北方民族交融，为隋唐统一多民族国…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"北魏孝文帝改革的措施与作用：迁都洛阳，说汉语、穿汉服、改汉姓、与汉族通婚；促进了民族交融，也增强了北魏的实力。","explain":"答题要点必须落到「民族交融」，这是本单元的核心概念。"},{"level":"次重点","text":"民族交融的表现：内迁各族与汉族杂居、通婚、相互学习（生产、饮食、服饰、语言、习俗）。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","文化成就与时代相关：战乱与民族交融时期，宗教艺术（石窟）与书法艺术特别兴盛。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把北魏孝文帝改革只理解为「学习汉族文化」。","本质是顺应民族交融趋势、巩固统治的改革，客观上促进了民族交融与北方经济发展。","材料题要求归纳「改革与民族交融的关系」，只答「学汉文化」会丢分。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["战役与格局","给出战役示意图或兵力对比材料，要求判断战役并说明其对政治格局的影响，标准答法是「为……奠定基础」。"],["改革的评价与民族交融","以孝文帝改革为背景，要求「结合措施说明改革如何促进民族交融」，需逐条对应。"],["因果链条题","「人口南迁 → 江南开发 → 经济重心南移」这条链条常与唐宋经济重心南移合并成大题。"]]},{"type":"note","title":"跨学科视角","text":"地理：北方民族内迁与农牧交错带；语文：《木兰诗》中的南北与战争。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 孝文帝改革：一场自上而下的汉化","head":["时间","经过"],"rows":[["439 年","北魏统一北方，鲜卑族与汉族杂居，民族交融趋势加强"],["490 年","孝文帝亲政，决心推行汉化改革"],["494 年","以「南伐」为名，迁都洛阳"],["迁都后","下令鲜卑人改穿汉服、说汉语，改鲜卑姓为汉姓（皇族拓跋改姓元）"],["鼓励通婚","孝文帝带头娶汉族士族女子，并令鲜卑贵族与汉族通婚"],["影响","促进北方民族交融，为隋唐统一多民族国家的发展奠定基础"]]},{"type":"note","title":"现场解说","text":"改革也带来一些副作用，如旧贵族不满、六镇地位下降，为后来北魏分裂埋下伏笔。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["胡服骑射","战国赵武灵王学习胡人服饰骑射以强兵，是古代学习少数民族文化的著名事例。","《史记·赵世家》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"北魏孝文帝","v":"拓跋宏（元宏），推行汉化改革，促进民族交融。 出处：《魏书·高祖纪》"}]},{"type":"list","title":"延伸阅读","items":["迁都洛阳：孝文帝为摆脱鲜卑旧贵族阻力、便于接受中原文化，于 494 年将都城从平城迁至洛阳。 出处：《魏书·高祖纪》","改革的代价：改革引发部分鲜卑贵族不满，太子元恂谋逃回平城被废；但改革顺应了民族交融的历史趋势。 出处：《魏书·高祖纪》；《资治通鉴》卷一四〇"]},{"type":"list","title":"本课拓展出处","items":["《魏书·高祖纪》；《资治通鉴》卷一三九—一四〇","2024 部编版七上第 19 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】（孝文帝）诏不得以北俗之语言于朝廷，若有违者，免所居官。——《魏书》\n【材料二】（孝文帝）改拓跋氏为元氏……其余所改，不可胜纪。——《资治通鉴》\n【材料三】（江南）地广野丰，民勤本业，一岁或稔，则数郡忘饥。——《宋书》","source":"材料研读 · 三国两晋南北朝时期：政权分立与民族交融"}],"questions":[{"id":"h7a-u4-m1-q1","type":"short","stem":"（1）材料一、二反映了孝文帝改革的哪些措施？这些措施起了什么作用？（5 分）","answer":"措施：规定在朝廷上必须说汉语（禁用鲜卑语）；改鲜卑姓为汉姓等。作用：促进了民族交融，也增强了北魏的实力，推动了北方经济文化的发展。","explain":"","tags":["孝文帝改革","民族交融"],"rubric":["答出说汉语","答出改汉姓","答出促进民族交融","答出增强国力"]},{"id":"h7a-u4-q2","type":"choice","stem":"北魏孝文帝改革措施中，最能体现民族交融的是","answer":"B","explain":"语言、服饰、姓氏与婚姻的汉化直接促进了鲜卑族与汉族的交融；迁都洛阳是为改革创造条件。","options":["迁都洛阳","说汉语、穿汉服、改汉姓、与汉族通婚","奖励军功","实行均田制"],"tags":["孝文帝改革","民族交融"]},{"id":"cat-7a-4-4-g2","type":"choice","stem":"下列关于「北朝政治和北方民族大交融」的表述，错误的是","answer":"A","explain":"把北魏孝文帝改革只理解为「学习汉族文化」——材料题要求归纳「改革与民族交融的关系」，只答「学汉文化」会丢分。正确表述：本质是顺应民族交融趋势、巩固统治的改革，客观上促进了民族交融与北方经济发展。","options":["把北魏孝文帝改革只理解为「学习汉族文化」。","本质是顺应民族交融趋势、巩固统治的改革，客观上促进了民族交融与北方经济发展。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：孝文帝为摆脱鲜卑旧贵族阻力、便于接受中原文化，于 494 年将都城从平城迁至洛阳。（《魏书·高祖纪》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"北朝政治和北方民族大交融；北魏孝文帝改革的措施与作用：迁都洛阳，说汉语、穿汉服、改汉姓、与汉族通婚；促进了民族交融，也增强了北魏的实力。","explain":"材料出自《魏书·高祖纪》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7a-4-4-g5","type":"choice","stem":"「北魏统一北方」发生于","answer":"A","explain":"本课时间轴：北魏统一北方（439 年）。北方进入相对稳定的发展时期。其余三个时间是同一单元相邻课时的事件时间。","options":["439 年","200 年","208 年","220 年"],"difficulty":1,"tags":["七年级上册","第四单元","本课练习"]}]},{"id":"cat-7a-4-5","title":"第20课 三国两晋南北朝时期的科技与文化","subtitle":"七年级上册 · 第四单元 三国两晋南北朝时期：政权分立与民族交融","grade":"7a","tags":["七年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第四单元 三国两晋南北朝时期：政权分立与民族交融"},{"k":"课时","v":"第20课 三国两晋南北朝时期的科技与文化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"三国两晋南北朝时期，虽然政局动荡，但科技文化仍有重要成就。贾思勰著《齐民要术》，是我国现存最早、最完整的农业科学著作；祖冲之把圆周率精确到小数点后第七位；王羲之的书法、顾恺之的绘画、云冈和龙门石窟的雕塑，都是这一时期的文化瑰宝。"},{"type":"note","title":"本课主线 · 因果链","text":"政权长期分立、战乱频繁，但北方民族大交融与江南地区的开发同时推进，为隋唐的重新统一与繁荣奠定了基础。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["200 年","官渡之战","曹操打败袁绍，为统一北方奠定基础 · 重点"],["208 年","赤壁之战","孙刘联军以少胜多，为三国鼎立局面形成奠定基础 · 重点"],["220 年","曹丕称帝建魏，定都洛阳","东汉灭亡；221 年刘备建汉（蜀），229 年孙权称帝建吴 · 重点"],["280 年","西晋灭吴，统一全国","统一局面短暂 · 重点"],["316 年","内迁匈奴人灭西晋","317 年司马睿在建康建立东晋 · 重点"],["383 年","淝水之战","东晋以少胜多击败前秦，北方重新陷入分裂 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"200 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"官渡之战","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"208 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"赤壁之战","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"220 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"曹丕称帝建魏，定都洛阳","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"280 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"西晋灭吴，统一全国","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"316 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"内迁匈奴人灭西晋","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"383 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"淝水之战","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"次重点","text":"科技文化：祖冲之把圆周率精确到小数点后第七位；贾思勰《齐民要术》；王羲之《兰亭集序》；云冈石窟、龙门石窟。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","官渡之战与赤壁之战的结果、意义最容易被调换。"],["把北魏孝文帝改革只理解为「学习汉族文化」。","本质是顺应民族交融趋势、巩固统治的改革，客观上促进了民族交融与北方经济发展。","材料题要求归纳「改革与民族交融的关系」，只答「学汉文化」会丢分。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["战役与格局","给出战役示意图或兵力对比材料，要求判断战役并说明其对政治格局的影响，标准答法是「为……奠定基础」。"],["改革的评价与民族交融","以孝文帝改革为背景，要求「结合措施说明改革如何促进民族交融」，需逐条对应。"],["因果链条题","「人口南迁 → 江南开发 → 经济重心南移」这条链条常与唐宋经济重心南移合并成大题。"]]},{"type":"note","title":"跨学科视角","text":"地理：北方民族内迁与农牧交错带；语文：《木兰诗》中的南北与战争。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["入木三分","传说王羲之写字笔力强劲，墨迹渗入木板三分，形容书法有力或见解深刻。","张怀瓘《书断》（唐）"],["画龙点睛","传说张僧繇画龙点睛后龙破壁飞去，比喻关键处一笔使整体生动。","张彦远《历代名画记》（唐）"]]},{"type":"kv","title":"人物卡片","items":[{"k":"贾思勰","v":"北魏农学家，著《齐民要术》。 出处：《齐民要术》序"},{"k":"祖冲之","v":"南朝科学家，精确计算圆周率，编制《大明历》。 出处：《南齐书·祖冲之传》"},{"k":"王羲之","v":"东晋书法家，著《兰亭集序》，被誉为「书圣」。 出处：《晋书·王羲之传》"}]},{"type":"list","title":"延伸阅读","items":["《齐民要术》：北魏贾思勰总结北方农业生产经验，系统记述作物栽培、耕作技术、家畜饲养、农产品加工等，强调「顺天时，量地利」。 出处：贾思勰《齐民要术》","祖冲之与圆周率：祖冲之把圆周率推算到 3.1415926 和 3.1415927 之间，领先世界近千年；他还编制《大明历》，改革闰法。 出处：《南齐书·祖冲之传》"]},{"type":"list","title":"本课拓展出处","items":["《齐民要术》序；《南齐书·祖冲之传》","2024 部编版七上第 20 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7a-u4-q4","type":"choice","stem":"把圆周率精确到小数点以后第七位数字的南朝科学家是","answer":"B","explain":"祖冲之在数学上把圆周率精确到小数点后第七位，领先世界近千年。","options":["贾思勰","祖冲之","郦道元","王羲之"],"tags":["科技文化","祖冲之"]},{"id":"cat-7a-4-5-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 官渡之战\n② 赤壁之战\n③ 曹丕称帝建魏，定都洛阳\n④ 西晋灭吴，统一全国","answer":"A","explain":"按时间顺序应为：①官渡之战（200 年）→②赤壁之战（208 年）→③曹丕称帝建魏，定都洛阳（220 年）→④西晋灭吴，统一全国（280 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-5-g2","type":"choice","stem":"下列关于「三国两晋南北朝时期的科技与文化」的表述，错误的是","answer":"A","explain":"认为赤壁之战使曹操统一了全国——官渡之战与赤壁之战的结果、意义最容易被调换。正确表述：赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","options":["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-5-g3","type":"choice","stem":"下列结论中，属于「三国两晋南北朝时期的科技与文化」的是","answer":"A","explain":"本课结论：分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","文化成就与时代相关：战乱与民族交融时期，宗教艺术（石窟）与书法艺术特别兴盛。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-5-g4","type":"short","stem":"阅读材料，回答问题。\n材料：北魏贾思勰总结北方农业生产经验，系统记述作物栽培、耕作技术、家畜饲养、农产品加工等，强调「顺天时，量地利」。（贾思勰《齐民要术》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"三国两晋南北朝时期的科技与文化；科技文化：祖冲之把圆周率精确到小数点后第七位；贾思勰《齐民要术》；王羲之《兰亭集序》；云冈石窟、龙门石窟。","explain":"材料出自贾思勰《齐民要术》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7a-4-6","title":"第21课 活动课 从考古发现看中华文明的起源","subtitle":"七年级上册 · 第四单元 三国两晋南北朝时期：政权分立与民族交融","grade":"7a","tags":["七年级上册","第四单元","活动课"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第四单元 三国两晋南北朝时期：政权分立与民族交融"},{"k":"课时","v":"第21课 活动课 从考古发现看中华文明的起源"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"本课是活动课，通过良渚、陶寺、二里头等考古发现，学习「以考古证据说话」的方法。考古发现是重建史前史的主要依据，玉器、城址、水利设施、祭祀遗迹等实物，能补充文献记载的空白。"},{"type":"note","title":"本课主线 · 因果链","text":"中华文明不是外来传入的：从元谋人、北京人到河姆渡、半坡，再到良渚、陶寺，中国境内的远古人类与史前文化一脉相承，约五千多年前已进入文明社会。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约 5300—4300 年前","良渚古城（浙江余杭）","有宫殿区、水利系统与大量随葬玉器——**中华五千年文明的实证** · 重点"],["约 4300—4000 年前","陶寺古城（山西襄汾）","黄河中游的早期国家，与良渚同为文明起源的重要证据 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"约 5300—4300 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"良渚古城（浙江余杭）","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"约 4300—4000 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"陶寺古城（山西襄汾）","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。","explain":"常以「遗址—时间—特征」配对或史料选择题出现。记住「元谋人最早、北京人用火、山顶洞人会人工取火」。"},{"level":"重点","text":"良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。","explain":"结论要会写：「中华文明具有五千多年的历史，且是**多元一体**、在本土独立起源的。」"},{"level":"重点","text":"炎帝、黄帝被尊为中华民族的人文初祖；尧舜禹时期的「禅让」是推举贤能。","explain":"华夏族的形成与「炎黄子孙」的说法都出自这里，材料题常与考古发现并置考查。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["考古发现是研究史前历史的**唯一可靠依据**；传说（炎黄、尧舜禹）需要考古材料印证，不能当作信史。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为北京人会人工取火。","北京人会使用天然火并保存火种；人工取火是山顶洞人。","这是最常见的混淆点，选项常把两者对调。"],["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","记「南稻北粟」，与「南干栏北半地穴」一起记。"]]},{"type":"table","title":"中国史前文明与世界早期文明（文明起源的共性与个性）","head":["比较项","中国（良渚、陶寺）","世界（古埃及、两河流域）"],"rows":[["起源时间","距今约 5000 多年","距今约 5000—5500 年"],["地理条件","黄河、长江两大河流域","尼罗河、两河流域"],["文明标志","宫殿、水利、玉器礼制","金字塔、楔形文字"],["共同规律","都诞生于大河流域，以农业为基础","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["遗址配对与图像识读","给出遗址出土的实物（骨耜、彩陶、玉琮）判断属于哪一文化，考「实物—文化—区域」的对应。"],["史料实证：传说与考古","给出传说记载与考古发现两组材料，要求说明二者的关系，落脚在「考古发现是更可靠的依据」。"],["年代尺与时序","把元谋人、北京人、河姆渡、良渚打乱排列，考查时间先后与「距今多少年」的换算。"]]},{"type":"note","title":"跨学科视角","text":"地理：长江流域与黄河流域的气候、地形差异，解释「南稻北粟」与干栏式、半地穴式建筑。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["二里头遗址与夏文化：二里头遗址发现中国最早的宫城、青铜礼器群和绿松石龙形器，其年代与夏朝晚期相当，是探索夏文化的关键遗址。 出处：中国社会科学院考古研究所《二里头》发掘报告","怎样读一件文物：观察文物要问：什么材质、什么工艺、在哪里出土、与什么共存、能说明当时怎样的生产生活。 出处：2024 部编版七上第 21 课「活动课」方法提示"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版七上第 21 课","《中华文明探源工程》成果"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】北京人遗址出土了大量打制石器、成堆的灰烬层，灰烬中有烧过的兽骨和树籽。\n【材料二】良渚古城遗址由宫殿区、内城、外城组成，外围发现由 11 条堤坝组成的水利系统；城内出土大量精致的玉琮、玉璧。\n【材料三】中华文明探源工程提出判断进入文明社会的中国方案：出现城市、出现阶级分化、出现王权与国家。","source":"材料研读 · 史前时期：原始社会与中华文明的起源"}],"questions":[{"id":"h7a-u1-m1-q2","type":"short","stem":"（2）依据材料二、三，说明良渚古城为什么被视为已进入文明社会的证据。（4 分）","answer":"良渚古城有宫殿区与内外城，说明已经出现城市；大型水利系统说明有组织大规模公共工程的能力和王权；随葬玉器的规格差异反映出阶级分化。以上都与材料三「城市、阶级分化、王权与国家」的判断标准相符。","explain":"","tags":["文明起源","史料实证"],"rubric":["指出城市/宫殿区","指出水利工程与组织能力","指出玉器反映阶级分化","对应文明判断标准"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"h7a-u1-q3","type":"choice","stem":"良渚古城与陶寺古城的考古发现，最主要的价值在于","answer":"B","explain":"两处古城都出现城市、阶级分化与王权，是中华文明五千多年历史的实证，也说明中华文明本土起源、多元一体。","options":["证明中华文明是由西方传入的","为中华文明五千多年历史提供实证","说明我国最早的文字出现在长江流域","证明夏朝是我国第一个王朝"],"tags":["文明起源","家国情怀"]},{"id":"cat-7a-4-6-g2","type":"choice","stem":"下列关于「活动课 从考古发现看中华文明的起…」的表述，错误的是","answer":"A","explain":"认为北京人会人工取火——这是最常见的混淆点，选项常把两者对调。正确表述：北京人会使用天然火并保存火种；人工取火是山顶洞人。","options":["认为北京人会人工取火。","北京人会使用天然火并保存火种；人工取火是山顶洞人。","考古发现是研究史前历史的**唯一可靠依据**；传说（炎黄、尧舜禹）需要考古材料印证，不能当作信史。","北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-6-g4","type":"short","stem":"阅读材料，回答问题。\n材料：二里头遗址发现中国最早的宫城、青铜礼器群和绿松石龙形器，其年代与夏朝晚期相当，是探索夏文化的关键遗址。（中国社会科学院考古研究所《二里头》发掘报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"活动课 从考古发现看中华文明的起源；北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。","explain":"材料出自中国社会科学院考古研究所《二里头》发掘报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-1-1","title":"第1课 隋朝统一与灭亡","subtitle":"七年级下册 · 第一单元 隋唐时期：繁荣与开放的时代","grade":"7b","tags":["七年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第一单元 隋唐时期：繁荣与开放的时代"},{"k":"课时","v":"第1课 隋朝统一与灭亡"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"581 年杨坚建立隋朝，589 年灭陈，结束南北朝分裂局面。隋炀帝即位后营建东都洛阳、开凿大运河、三征辽东，民力透支。605 年起开凿的大运河以洛阳为中心，北抵涿郡，南至余杭，全长 2000 多千米，是古代世界最长的运河。"},{"type":"note","title":"本课主线 · 因果链","text":"隋朝结束长期分裂，创立科举制、三省六部制并开凿大运河，为唐朝的繁荣奠定基础；唐朝前期政治清明、民族交融、对外开放，达到中国古代社会的鼎盛，而安史之乱使唐朝由盛转衰，藩镇割据最终演变成五代十国的分裂。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["581 年","杨坚夺取北周政权，建立隋朝，定都长安","他就是隋文帝；589 年隋灭陈，统一全国，结束了长期分裂的局面 · 重点"],["605 年起","隋炀帝下令开凿大运河","以洛阳为中心，北抵涿郡（今北京），南至余杭（今杭州），是古代世界上最长的运河 · 重点"],["隋炀帝时","设置进士科，科举制正式确立","隋文帝时已开始用分科考试的办法选拔官员，隋炀帝设进士科后才形成完整的科举制度 · 重点"],["618 年","隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","李渊即唐高祖；隋朝与秦朝一样二世而亡，教训都是「不恤民力」 · 重点"],["907 年","朱温建立后梁，唐朝灭亡，五代十国开始","五代十国是唐末以来藩镇割据局面的延续；统一始终是历史发展的必然趋势"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"581 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"杨坚夺取北周政权，建立隋朝，定都长安","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"605 年起","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"隋炀帝下令开凿大运河","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"隋炀帝时","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"设置进士科，科举制正式确立","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"618 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"隋炀帝被杀，隋朝灭亡；李渊建立唐朝，…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"907 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"朱温建立后梁，唐朝灭亡，五代十国开始","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"隋朝的制度创新与统一：结束分裂、实现统一，创立科举制与三省六部制，开凿大运河，为唐朝的繁荣奠定了基础。","explain":"「隋朝短暂却影响深远」是常考的判断。答题按「政治（三省六部、科举）、经济（大运河）、统一」三点罗列，并落到「为唐朝繁荣奠基」。"},{"level":"重点","text":"大运河：605 年起由隋炀帝下令开凿，以洛阳为中心，北抵涿郡、南至余杭；它加强了南北经济文化交流，有利于巩固国家统一。","explain":"最爱设的陷阱是「谁开的河」——开凿者是**隋炀帝**。评价要一分为二：便利南北交通、巩固统一，但征发民力过重也加重了百姓负担。"},{"level":"重点","text":"科举制：隋文帝时开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝进一步完善（唐太宗增加考试科目，武则天创立殿试和武举，唐玄宗把诗赋作为考试内容）。","explain":"意义必须会写：打破了门第限制、扩大了官吏选拔的范围，使有才学的人能够由此参政，加强了皇帝在选官和用人上的权力，促进了社会阶层的流动与文化教育的发展。"},{"level":"重点","text":"安史之乱（755—763）是唐朝由盛转衰的转折点：唐玄宗后期贪图享乐、任用奸臣，节度使权力膨胀，社会矛盾尖锐，最终酿成叛乱；此后中央权力衰微、藩镇割据。","explain":"注意与「唐朝灭亡」区分：安史之乱是**由盛转衰**的转折点，唐朝灭亡在 907 年。材料题还常问「北方人口南迁」，与后面经济重心南移衔接。"},{"level":"次重点","text":"五代十国（907—960）：北方相继出现五个朝代，南方先后存在十个政权；实质是唐末藩镇割据局面的延续，但统一趋势不断加强。","explain":""},{"level":"选择题","text":"隋朝速亡的原因：隋炀帝好大喜功，营建东都、三征辽东、开通运河都大量征发民力，徭役赋税沉重，激起农民起义。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。"],["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。"],["认为安史之乱直接导致唐朝灭亡。","安史之乱使唐朝由盛转衰，形成藩镇割据；唐朝灭亡是 907 年朱温建立后梁。","「转折点」与「终点」是两个概念，材料题问「由盛转衰的标志」时不要答成 907 年。"]]},{"type":"table","title":"科举制与九品中正制：选官标准的变化（跨册对比（七上·魏晋南北朝的选官制度 → 七下·隋唐的科举制））","head":["比较项","九品中正制（魏晋南北朝）","科举制（隋唐及以后）"],"rows":[["选官标准","主要看门第出身（「上品无寒门，下品无势族」）","考试取士，以才学为主要标准"],["选官权力","由中正官评定，为地方世族把持","由中央（皇帝）主持，选官用人权集中"],["社会影响","门阀士族垄断政权，阶层固化","寒门子弟可凭科第入仕，社会阶层流动"],["共同目的","都是为选拔官吏、维护统治","同左"]]},{"type":"table","title":"唐朝与同时期的世界（7—9 世纪）（中外对比：开放繁荣与相对封闭的不同走向）","head":["比较项","唐朝（中国）","西欧（法兰克王国等）"],"rows":[["政治","三省六部制、科举制，中央集权加强","封君封臣制度，王权软弱、地方割据"],["经济","农业生产发展，长安、洛阳、扬州等城市商业兴盛","以庄园经济为主，城市商业相对落后"],["对外交往","遣唐使、胡商云集，兼容并蓄","交往范围有限，受战乱与教会影响较大"],["文化","唐诗、雕版印刷术、火药","基督教文化，修道院保存古典典籍"],["共同点","都处于封建社会的发展时期","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["制度创新与人才选拔","近年中考常见","以科举制创立与完善的材料切入，要求说明「考试取士」打破门第限制、扩大统治基础，常与九品中正制或明清八股取士对比考查。"],["史料实证：隋唐的开放气象","","给出遣唐使、鉴真东渡、玄奘西行、唐蕃和亲等材料，要求提炼「对外开放、民族交融」的认识；答题必须**分类作答**（民族交往一类、中外交流一类）。"],["人物评价与辩证思维","","隋炀帝、唐玄宗（前期与后期）是评价题的常客，要求一分为二、史论结合，答「功过并存，以史实说明，不以成败论人」。"],["因果链条：治世与乱世","","「贞观之治—开元盛世—安史之乱」常连成一条因果链，考查「统治者政策与国家兴衰的关系」，落脚在「以民为本、爱惜民力」。"]]},{"type":"note","title":"跨学科视角","text":"地理：大运河与南北水运；语文：唐诗中的盛唐气象。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["罄竹难书","李密讨隋炀帝檄文称其罪「罄南山之竹，书罪无穷」，形容罪行多得写不完。","《旧唐书·李密传》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"隋文帝","v":"杨坚，581 年建隋，589 年统一全国，开创「开皇之治」。 出处：《隋书·高祖纪》"},{"k":"隋炀帝","v":"杨广，开凿大运河、设进士科，因暴政导致隋朝灭亡。 出处：《隋书·炀帝纪》"}]},{"type":"list","title":"延伸阅读","items":["大运河四段：永济渠（洛阳至涿郡）、通济渠（洛阳至淮水）、邗沟（淮水至江都入长江）、江南河（长江至余杭），沟通海河、黄河、淮河、长江、钱塘江五大水系。 出处：《隋书·食货志》","科举制的创立：隋文帝分科考试选拔官员，隋炀帝设进士科，标志科举制正式确立，此后沿用一千三百多年。 出处：《隋书·选举志》；2024 部编版七下第 1 课"]},{"type":"list","title":"本课拓展出处","items":["《隋书·炀帝纪》《隋书·食货志》","2024 部编版七下第 1 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】隋炀帝征发百余万民力开凿运河，自西苑引谷水、洛水注入黄河，又自板渚引黄河水沟通淮水，此后「天下利于转输」。——摘编自《隋书·食货志》\n【材料二】唐太宗尝谓侍臣曰：「为君之道，必须先存百姓。若损百姓以奉其身，犹割股以啖腹，腹饱而身毙。」——摘编自《贞观政要》\n【材料三】唐太宗见新科进士缀行而出，喜曰：「天下英雄入吾彀中矣！」——摘编自《唐摭言》","source":"材料研读 · 隋唐时期：繁荣与开放的时代"}],"questions":[{"id":"h7b-u1-q1","type":"choice","stem":"605 年起下令开凿大运河，以洛阳为中心、北抵涿郡、南至余杭的皇帝是","answer":"B","explain":"大运河由隋炀帝下令开凿（605 年起），以洛阳为中心，北抵涿郡，南至余杭，是古代世界上最长的运河。隋文帝的功绩是统一全国、创立三省六部制与分科考试选官。","options":["隋文帝","隋炀帝","唐高祖","唐玄宗"],"tags":["大运河","时空观念"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"h7b-u1-q6","type":"choice","stem":"关于五代十国，下列说法正确的是","answer":"A","explain":"五代十国是唐末藩镇割据局面的延续。北方政权更迭频繁、战乱不断；南方相对安定，经济得到发展；统一始终是历史发展的必然趋势。","options":["五代十国是唐末以来藩镇割据局面的延续","五代十国时期南方经济遭到严重破坏","五代十国都是由少数民族建立的政权","五代十国时期全国长期处于统一状态"],"tags":["五代十国","历史解释"]},{"id":"cat-7b-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杨坚夺取北周政权，建立隋朝，定都长安\n② 隋炀帝下令开凿大运河\n③ 设置进士科，科举制正式确立\n④ 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","answer":"A","explain":"按时间顺序应为：①杨坚夺取北周政权，建立隋朝，定都长安（581 年）→②隋炀帝下令开凿大运河（605 年起）→③设置进士科，科举制正式确立（隋炀帝时）→④隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g2","type":"choice","stem":"下列关于「隋朝统一与灭亡」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g3","type":"choice","stem":"下列结论中，属于「隋朝统一与灭亡」的是","answer":"A","explain":"本课结论：科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：永济渠（洛阳至涿郡）、通济渠（洛阳至淮水）、邗沟（淮水至江都入长江）、江南河（长江至余杭），沟通海河、黄河、淮河、长江、钱塘江五大水系。（《隋书·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋朝统一与灭亡；隋朝的制度创新与统一：结束分裂、实现统一，创立科举制与三省六部制，开凿大运河，为唐朝的繁荣奠定了基础。","explain":"材料出自《隋书·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-1-2","title":"第2课 唐朝建立与“贞观之治”","subtitle":"七年级下册 · 第一单元 隋唐时期：繁荣与开放的时代","grade":"7b","tags":["七年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第一单元 隋唐时期：繁荣与开放的时代"},{"k":"课时","v":"第2课 唐朝建立与“贞观之治”"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"618 年李渊建立唐朝，定都长安。626 年李世民经玄武门之变即位，次年改元贞观。唐太宗吸取隋亡教训，轻徭薄赋、虚心纳谏，任用房玄龄、杜如晦、魏征等，出现「贞观之治」。"},{"type":"note","title":"本课主线 · 因果链","text":"隋朝结束长期分裂，创立科举制、三省六部制并开凿大运河，为唐朝的繁荣奠定基础；唐朝前期政治清明、民族交融、对外开放，达到中国古代社会的鼎盛，而安史之乱使唐朝由盛转衰，藩镇割据最终演变成五代十国的分裂。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["618 年","隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","李渊即唐高祖；隋朝与秦朝一样二世而亡，教训都是「不恤民力」 · 重点"],["627—649 年","唐太宗统治时期，出现「贞观之治」","李世民吸取隋亡教训，减轻赋税徭役、虚心纳谏（魏征）、知人善任（房玄龄、杜如晦）"],["唐太宗时","玄奘西行天竺取经，后口述成《大唐西域记》","玄奘口述、弟子辩机笔录；该书是研究中外交流史的珍贵文献"],["641 年","唐太宗把文成公主嫁给吐蕃赞普松赞干布","唐蕃和亲促进了吐蕃经济与社会的发展；唐中宗时金城公主又入藏"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"618 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"隋炀帝被杀，隋朝灭亡；李渊建立唐朝，…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"627—649 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"唐太宗统治时期，出现「贞观之治」","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"唐太宗时","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"玄奘西行天竺取经，后口述成《大唐西域…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"641 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"唐太宗把文成公主嫁给吐蕃赞普松赞干布","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"科举制：隋文帝时开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝进一步完善（唐太宗增加考试科目，武则天创立殿试和武举，唐玄宗把诗赋作为考试内容）。","explain":"意义必须会写：打破了门第限制、扩大了官吏选拔的范围，使有才学的人能够由此参政，加强了皇帝在选官和用人上的权力，促进了社会阶层的流动与文化教育的发展。"},{"level":"重点","text":"「贞观之治」与「开元盛世」：唐太宗吸取隋亡教训，减轻赋税徭役、虚心纳谏、知人善任，出现贞观之治；唐玄宗前期任用贤能、整顿吏治、发展生产，唐朝进入鼎盛时期。","explain":"两个治世的比较、以及唐玄宗「前期治、后期乱」的对比，是「人物评价」类大题的现成素材。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["制度创新与人才选拔","近年中考常见","以科举制创立与完善的材料切入，要求说明「考试取士」打破门第限制、扩大统治基础，常与九品中正制或明清八股取士对比考查。"],["史料实证：隋唐的开放气象","","给出遣唐使、鉴真东渡、玄奘西行、唐蕃和亲等材料，要求提炼「对外开放、民族交融」的认识；答题必须**分类作答**（民族交往一类、中外交流一类）。"],["人物评价与辩证思维","","隋炀帝、唐玄宗（前期与后期）是评价题的常客，要求一分为二、史论结合，答「功过并存，以史实说明，不以成败论人」。"],["因果链条：治世与乱世","","「贞观之治—开元盛世—安史之乱」常连成一条因果链，考查「统治者政策与国家兴衰的关系」，落脚在「以民为本、爱惜民力」。"]]},{"type":"note","title":"跨学科视角","text":"地理：大运河与南北水运；语文：唐诗中的盛唐气象。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["兼听则明，偏信则暗","广泛听取意见才能明辨，只听一面之词就会糊涂。","《资治通鉴》卷一九二"],["水能载舟，亦能覆舟","唐太宗以水喻民、以舟喻君，强调民心向背决定政权安危。","《贞观政要·政体》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"唐太宗","v":"李世民，唐朝第二位皇帝，开创贞观之治。 出处：《旧唐书·太宗本纪》"},{"k":"魏征","v":"唐初名臣，以直言进谏著称。 出处：《旧唐书·魏征传》"}]},{"type":"list","title":"延伸阅读","items":["三省六部制：中书省起草诏令，门下省审议，尚书省执行，下设吏、户、礼、兵、刑、工六部，分工明确、相互牵制。 出处：《新唐书·百官志》","唐太宗的纳谏：魏征前后进谏二百余事，唐太宗称「以铜为镜，可以正衣冠；以古为镜，可以知兴替；以人为镜，可以明得失」。 出处：《旧唐书·魏征传》"]},{"type":"list","title":"本课拓展出处","items":["《旧唐书·太宗本纪》；《贞观政要》","2024 部编版七下第 2 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】隋炀帝征发百余万民力开凿运河，自西苑引谷水、洛水注入黄河，又自板渚引黄河水沟通淮水，此后「天下利于转输」。——摘编自《隋书·食货志》\n【材料二】唐太宗尝谓侍臣曰：「为君之道，必须先存百姓。若损百姓以奉其身，犹割股以啖腹，腹饱而身毙。」——摘编自《贞观政要》\n【材料三】唐太宗见新科进士缀行而出，喜曰：「天下英雄入吾彀中矣！」——摘编自《唐摭言》","source":"材料研读 · 隋唐时期：繁荣与开放的时代"}],"questions":[{"id":"h7b-u1-m1-q2","type":"short","stem":"（2）材料二、三分别反映了唐太宗怎样的治国做法？这些做法与「贞观之治」的出现有何关系？（5 分）","answer":"材料二反映唐太宗重视百姓、以民为本，注意减轻百姓负担（这是吸取隋亡教训的结果）；材料三反映他重视科举取士、笼络人才、扩大统治基础。关系：正因为唐太宗减轻赋税徭役、虚心纳谏、知人善任，并进一步完善三省六部制与科举制，才使政治比较清明、经济得到恢复和发展、社会秩序安定、国力增强，从而出现了「贞观之治」的局面。","explain":"","tags":["贞观之治","历史解释"],"rubric":["材料二：以民为本、重视百姓（减轻负担）","材料三：重视科举取士、重用人才","答出措施与治世之间的因果对应","答出贞观之治的表现（政治清明/经济发展/社会安定）"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"h7b-u1-q4","type":"choice","stem":"唐太宗说「舟所以比人君，水所以比黎庶，水能载舟，亦能覆舟」，这说明他","answer":"B","explain":"唐太宗从隋朝因暴政速亡的教训中认识到百姓的力量，因此减轻赋税徭役、推行有利于生产恢复的政策，这才有「贞观之治」。","options":["主张严刑峻法以驾驭臣下","注意吸取隋亡教训，爱惜民力","主张大力开疆拓土","主张抑制商业发展"],"tags":["贞观之治","家国情怀"]},{"id":"cat-7b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安\n② 唐太宗统治时期，出现「贞观之治」\n③ 玄奘西行天竺取经，后口述成《大唐西域记》\n④ 唐太宗把文成公主嫁给吐蕃赞普松赞干布","answer":"A","explain":"按时间顺序应为：①隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）→②唐太宗统治时期，出现「贞观之治」（627—649 年）→③玄奘西行天竺取经，后口述成《大唐西域记》（唐太宗时）→④唐太宗把文成公主嫁给吐蕃赞普松赞干布（641 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-2-g2","type":"choice","stem":"下列关于「唐朝建立与“贞观之治”」的表述，错误的是","answer":"A","explain":"把科举制的创立说成唐朝，或认为进士科是唐太宗设立的——「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。正确表述：科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","options":["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-2-g3","type":"choice","stem":"下列结论中，属于「唐朝建立与“贞观之治”」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：中书省起草诏令，门下省审议，尚书省执行，下设吏、户、礼、兵、刑、工六部，分工明确、相互牵制。（《新唐书·百官志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"唐朝建立与“贞观之治”；科举制：隋文帝时开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝进一步完善（唐太宗增加考试科目，武则天创立殿试和武举，唐玄宗把诗赋作为考试内容）。","explain":"材料出自《新唐书·百官志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-1-3","title":"第3课 “开元盛世”","subtitle":"七年级下册 · 第一单元 隋唐时期：繁荣与开放的时代","grade":"7b","tags":["七年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第一单元 隋唐时期：繁荣与开放的时代"},{"k":"课时","v":"第3课 “开元盛世”"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"唐玄宗前期，任用姚崇、宋璟为相，整顿吏治，裁减冗官，发展生产，唐朝进入鼎盛时期，史称「开元盛世」。杜甫《忆昔》追忆「忆昔开元全盛日，小邑犹藏万家室」。"},{"type":"note","title":"本课主线 · 因果链","text":"隋朝结束长期分裂，创立科举制、三省六部制并开凿大运河，为唐朝的繁荣奠定基础；唐朝前期政治清明、民族交融、对外开放，达到中国古代社会的鼎盛，而安史之乱使唐朝由盛转衰，藩镇割据最终演变成五代十国的分裂。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["713—741 年","唐玄宗统治前期，出现「开元盛世」","任用姚崇、宋璟等贤臣，整顿吏治、发展生产，唐朝进入鼎盛时期"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"tall","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":17,"text":"科举制：隋文帝时开始用分科考试选拔官…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":39.4,"text":"「贞观之治」与「开元盛世」：唐太宗吸…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":61.8,"text":"安史之乱（755—763）是唐朝由盛…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":84.2,"text":"隋唐时期的时代特征是**繁荣与开放*…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":106.6,"text":"科举制是隋唐最重要的制度创新：它以考…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":129,"text":"唐朝对外交往既有「走出去」（鉴真东渡…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"科举制：隋文帝时开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝进一步完善（唐太宗增加考试科目，武则天创立殿试和武举，唐玄宗把诗赋作为考试内容）。","explain":"意义必须会写：打破了门第限制、扩大了官吏选拔的范围，使有才学的人能够由此参政，加强了皇帝在选官和用人上的权力，促进了社会阶层的流动与文化教育的发展。"},{"level":"重点","text":"「贞观之治」与「开元盛世」：唐太宗吸取隋亡教训，减轻赋税徭役、虚心纳谏、知人善任，出现贞观之治；唐玄宗前期任用贤能、整顿吏治、发展生产，唐朝进入鼎盛时期。","explain":"两个治世的比较、以及唐玄宗「前期治、后期乱」的对比，是「人物评价」类大题的现成素材。"},{"level":"重点","text":"安史之乱（755—763）是唐朝由盛转衰的转折点：唐玄宗后期贪图享乐、任用奸臣，节度使权力膨胀，社会矛盾尖锐，最终酿成叛乱；此后中央权力衰微、藩镇割据。","explain":"注意与「唐朝灭亡」区分：安史之乱是**由盛转衰**的转折点，唐朝灭亡在 907 年。材料题还常问「北方人口南迁」，与后面经济重心南移衔接。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。"],["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["制度创新与人才选拔","近年中考常见","以科举制创立与完善的材料切入，要求说明「考试取士」打破门第限制、扩大统治基础，常与九品中正制或明清八股取士对比考查。"],["史料实证：隋唐的开放气象","","给出遣唐使、鉴真东渡、玄奘西行、唐蕃和亲等材料，要求提炼「对外开放、民族交融」的认识；答题必须**分类作答**（民族交往一类、中外交流一类）。"],["人物评价与辩证思维","","隋炀帝、唐玄宗（前期与后期）是评价题的常客，要求一分为二、史论结合，答「功过并存，以史实说明，不以成败论人」。"],["因果链条：治世与乱世","","「贞观之治—开元盛世—安史之乱」常连成一条因果链，考查「统治者政策与国家兴衰的关系」，落脚在「以民为本、爱惜民力」。"]]},{"type":"note","title":"跨学科视角","text":"地理：大运河与南北水运；语文：唐诗中的盛唐气象。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["口蜜腹剑","李林甫为相时表面和善、言辞甜蜜，背后却常陷害他人，形容阴险狡诈。","《资治通鉴》卷二一五"]]},{"type":"kv","title":"人物卡片","items":[{"k":"唐玄宗","v":"李隆基，前期开创开元盛世，后期怠政引发安史之乱。 出处：《旧唐书·玄宗本纪》"},{"k":"姚崇","v":"开元初名相，提出「十事要说」，辅佐玄宗改革。 出处：《旧唐书·姚崇传》"}]},{"type":"list","title":"延伸阅读","items":["开元通宝：唐高祖时始铸「开元通宝」，结束以重量命名钱币的传统，开创「通宝」钱制，影响后世千年。 出处：《旧唐书·食货志》","长安城：唐长安城面积约 84 平方千米，是当时世界上最大的城市之一，东西两市商业繁盛，居住着大量外国商人、留学生。 出处：2024 部编版七下第 3 课；《唐两京城坊考》"]},{"type":"list","title":"本课拓展出处","items":["《旧唐书·玄宗本纪》；杜甫《忆昔》","2024 部编版七下第 3 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u1-q1","type":"choice","stem":"605 年起下令开凿大运河，以洛阳为中心、北抵涿郡、南至余杭的皇帝是","answer":"B","explain":"大运河由隋炀帝下令开凿（605 年起），以洛阳为中心，北抵涿郡，南至余杭，是古代世界上最长的运河。隋文帝的功绩是统一全国、创立三省六部制与分科考试选官。","options":["隋文帝","隋炀帝","唐高祖","唐玄宗"],"tags":["大运河","时空观念"]},{"id":"cat-7b-1-3-g2","type":"choice","stem":"下列关于「“开元盛世”」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-3-g3","type":"choice","stem":"下列结论中，属于「“开元盛世”」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：唐高祖时始铸「开元通宝」，结束以重量命名钱币的传统，开创「通宝」钱制，影响后世千年。（《旧唐书·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"“开元盛世”；科举制：隋文帝时开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝进一步完善（唐太宗增加考试科目，武则天创立殿试和武举，唐玄宗把诗赋作为考试内容）。","explain":"材料出自《旧唐书·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-1-3-g5","type":"choice","stem":"「唐玄宗统治前期，出现「开元盛世」」发生于","answer":"A","explain":"本课时间轴：唐玄宗统治前期，出现「开元盛世」（713—741 年）。任用姚崇、宋璟等贤臣，整顿吏治、发展生产，唐朝进入鼎盛时期。其余三个时间是同一单元相邻课时的事件时间。","options":["713—741 年","581 年","605 年起","隋炀帝时"],"difficulty":1,"tags":["七年级下册","第一单元","本课练习"]}]},{"id":"cat-7b-1-4","title":"第4课 安史之乱与唐朝衰亡","subtitle":"七年级下册 · 第一单元 隋唐时期：繁荣与开放的时代","grade":"7b","tags":["七年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第一单元 隋唐时期：繁荣与开放的时代"},{"k":"课时","v":"第4课 安史之乱与唐朝衰亡"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"唐玄宗后期沉溺享乐，任用李林甫、杨国忠，节度使权力膨胀。755 年，安禄山、史思明以讨伐杨国忠为名起兵，安史之乱爆发，持续八年。战乱使北方经济遭到严重破坏，唐朝由盛转衰，此后形成藩镇割据局面。"},{"type":"note","title":"本课主线 · 因果链","text":"隋朝结束长期分裂，创立科举制、三省六部制并开凿大运河，为唐朝的繁荣奠定基础；唐朝前期政治清明、民族交融、对外开放，达到中国古代社会的鼎盛，而安史之乱使唐朝由盛转衰，藩镇割据最终演变成五代十国的分裂。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["755—763 年","安史之乱","安禄山、史思明发动；唐朝国势从此由盛转衰，形成藩镇割据的局面 · 重点"],["875—884 年","黄巢起义","给唐朝统治以致命打击"],["907 年","朱温建立后梁，唐朝灭亡，五代十国开始","五代十国是唐末以来藩镇割据局面的延续；统一始终是历史发展的必然趋势"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 安史之乱：八年战乱如何改变唐朝","caption":"示意图：安史之乱：八年战乱如何改变唐朝，详见下方「历史现场」","view":"tall","alt":"示意图：安史之乱：八年战乱如何改变唐朝，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"755 年十一月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"安禄山在范阳起兵，号称二十万，南下攻…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"755 年底","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"叛军攻陷洛阳，756 年正月安禄山称…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"756 年六月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"潼关失守，玄宗西逃，马嵬驿兵变","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"757 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"叛军内讧，安庆绪杀安禄山；唐军借回纥…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"759 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"史思明再叛，攻陷洛阳","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"763 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"史朝义自杀，安史之乱平定","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"安史之乱（755—763）是唐朝由盛转衰的转折点：唐玄宗后期贪图享乐、任用奸臣，节度使权力膨胀，社会矛盾尖锐，最终酿成叛乱；此后中央权力衰微、藩镇割据。","explain":"注意与「唐朝灭亡」区分：安史之乱是**由盛转衰**的转折点，唐朝灭亡在 907 年。材料题还常问「北方人口南迁」，与后面经济重心南移衔接。"},{"level":"次重点","text":"五代十国（907—960）：北方相继出现五个朝代，南方先后存在十个政权；实质是唐末藩镇割据局面的延续，但统一趋势不断加强。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为安史之乱直接导致唐朝灭亡。","安史之乱使唐朝由盛转衰，形成藩镇割据；唐朝灭亡是 907 年朱温建立后梁。","「转折点」与「终点」是两个概念，材料题问「由盛转衰的标志」时不要答成 907 年。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["制度创新与人才选拔","近年中考常见","以科举制创立与完善的材料切入，要求说明「考试取士」打破门第限制、扩大统治基础，常与九品中正制或明清八股取士对比考查。"],["史料实证：隋唐的开放气象","","给出遣唐使、鉴真东渡、玄奘西行、唐蕃和亲等材料，要求提炼「对外开放、民族交融」的认识；答题必须**分类作答**（民族交往一类、中外交流一类）。"],["人物评价与辩证思维","","隋炀帝、唐玄宗（前期与后期）是评价题的常客，要求一分为二、史论结合，答「功过并存，以史实说明，不以成败论人」。"],["因果链条：治世与乱世","","「贞观之治—开元盛世—安史之乱」常连成一条因果链，考查「统治者政策与国家兴衰的关系」，落脚在「以民为本、爱惜民力」。"]]},{"type":"note","title":"跨学科视角","text":"地理：大运河与南北水运；语文：唐诗中的盛唐气象。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 安史之乱：八年战乱如何改变唐朝","head":["时间","经过"],"rows":[["755 年十一月","安禄山在范阳起兵，号称二十万，南下攻唐"],["755 年底","叛军攻陷洛阳，756 年正月安禄山称帝，国号燕"],["756 年六月","潼关失守，玄宗西逃，马嵬驿兵变"],["757 年","叛军内讧，安庆绪杀安禄山；唐军借回纥兵收复长安、洛阳"],["759 年","史思明再叛，攻陷洛阳"],["763 年","史朝义自杀，安史之乱平定"]]},{"type":"note","title":"现场解说","text":"战乱导致人口锐减、北方经济凋敝，唐朝中央集权削弱，藩镇割据局面形成。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["渔阳鼙鼓","白居易《长恨歌》「渔阳鼙鼓动地来」，指安禄山起兵，后借指战乱。","白居易《长恨歌》"],["一骑红尘妃子笑","杜牧诗句，写唐玄宗为杨贵妃千里送荔枝，讽刺统治者骄奢。","杜牧《过华清宫》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"安禄山","v":"唐朝节度使，安史之乱发动者。 出处：《旧唐书·安禄山传》"},{"k":"郭子仪","v":"唐朝名将，平定安史之乱的主要将领。 出处：《旧唐书·郭子仪传》"}]},{"type":"list","title":"延伸阅读","items":["马嵬驿之变：756 年唐玄宗逃往蜀中，行至马嵬驿，禁军哗变，杀死杨国忠，逼玄宗缢死杨贵妃。 出处：《旧唐书·杨贵妃传》；《资治通鉴》卷二一八","黄巢起义与唐亡：875 年黄巢起义爆发，880 年攻入长安。907 年朱温废唐哀帝，建立后梁，唐朝灭亡，五代十国开始。 出处：《旧唐书·黄巢传》；《新五代史·梁本纪》"]},{"type":"list","title":"本课拓展出处","items":["《旧唐书·安禄山传》；《资治通鉴》卷二一七—二二二","2024 部编版七下第 4 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u1-q5","type":"choice","stem":"唐朝由盛转衰的转折点是","answer":"B","explain":"755—763 年的安史之乱使唐朝国势由盛转衰，此后中央权力衰微、藩镇割据。黄巢起义给唐朝统治以致命打击；907 年朱温建立后梁，唐朝灭亡。","options":["黄巢起义","安史之乱","藩镇割据","朱温建立后梁"],"tags":["安史之乱","历史解释"]},{"id":"h7b-u1-q6","type":"choice","stem":"关于五代十国，下列说法正确的是","answer":"A","explain":"五代十国是唐末藩镇割据局面的延续。北方政权更迭频繁、战乱不断；南方相对安定，经济得到发展；统一始终是历史发展的必然趋势。","options":["五代十国是唐末以来藩镇割据局面的延续","五代十国时期南方经济遭到严重破坏","五代十国都是由少数民族建立的政权","五代十国时期全国长期处于统一状态"],"tags":["五代十国","历史解释"]},{"id":"cat-7b-1-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 安史之乱\n② 黄巢起义\n③ 朱温建立后梁，唐朝灭亡，五代十国开始","answer":"A","explain":"按时间顺序应为：①安史之乱（755—763 年）→②黄巢起义（875—884 年）→③朱温建立后梁，唐朝灭亡，五代十国开始（907 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-4-g2","type":"choice","stem":"下列关于「安史之乱与唐朝衰亡」的表述，错误的是","answer":"A","explain":"认为安史之乱直接导致唐朝灭亡——「转折点」与「终点」是两个概念，材料题问「由盛转衰的标志」时不要答成 907 年。正确表述：安史之乱使唐朝由盛转衰，形成藩镇割据；唐朝灭亡是 907 年朱温建立后梁。","options":["认为安史之乱直接导致唐朝灭亡。","安史之乱使唐朝由盛转衰，形成藩镇割据；唐朝灭亡是 907 年朱温建立后梁。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","安史之乱（755—763）是唐朝由盛转衰的转折点：唐玄宗后期贪图享乐、任用奸臣，节度使权力膨胀，社会矛盾尖锐，最终酿成叛乱；此后中央权力衰微、藩镇割据。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-4-g3","type":"choice","stem":"下列结论中，属于「安史之乱与唐朝衰亡」的是","answer":"A","explain":"本课结论：安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：756 年唐玄宗逃往蜀中，行至马嵬驿，禁军哗变，杀死杨国忠，逼玄宗缢死杨贵妃。（《旧唐书·杨贵妃传》；《资治通鉴》卷二一八）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"安史之乱与唐朝衰亡；安史之乱（755—763）是唐朝由盛转衰的转折点：唐玄宗后期贪图享乐、任用奸臣，节度使权力膨胀，社会矛盾尖锐，最终酿成叛乱；此后中央权力衰微、藩镇割据。","explain":"材料出自《旧唐书·杨贵妃传》；《资治通鉴》卷二一八。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-1-5","title":"第5课 隋唐时期的民族交往与交融","subtitle":"七年级下册 · 第一单元 隋唐时期：繁荣与开放的时代","grade":"7b","tags":["七年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第一单元 隋唐时期：繁荣与开放的时代"},{"k":"课时","v":"第5课 隋唐时期的民族交往与交融"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"唐朝国力强盛，与周边民族交往密切。唐太宗被西北各族尊为「天可汗」；641 年文成公主入藏，与吐蕃赞普松赞干布联姻；唐朝设安西都护府、北庭都护府管理西域。"},{"type":"note","title":"本课主线 · 因果链","text":"隋朝结束长期分裂，创立科举制、三省六部制并开凿大运河，为唐朝的繁荣奠定基础；唐朝前期政治清明、民族交融、对外开放，达到中国古代社会的鼎盛，而安史之乱使唐朝由盛转衰，藩镇割据最终演变成五代十国的分裂。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["641 年","唐太宗把文成公主嫁给吐蕃赞普松赞干布","唐蕃和亲促进了吐蕃经济与社会的发展；唐中宗时金城公主又入藏"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"唐朝的民族交往：641 年文成公主入…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"隋唐时期的时代特征是**繁荣与开放*…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"唐朝的民族交往：641 年文成公主入藏与松赞干布和亲，唐中宗时金城公主入藏；唐蕃订立盟约、互通使节；唐朝还册封回纥、南诏等少数民族首领。","explain":"答题术语：唐朝实行**开明的民族政策**，和亲、册封、会盟多管齐下，促进了民族交融与边疆开发。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。"],["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["制度创新与人才选拔","近年中考常见","以科举制创立与完善的材料切入，要求说明「考试取士」打破门第限制、扩大统治基础，常与九品中正制或明清八股取士对比考查。"],["史料实证：隋唐的开放气象","","给出遣唐使、鉴真东渡、玄奘西行、唐蕃和亲等材料，要求提炼「对外开放、民族交融」的认识；答题必须**分类作答**（民族交往一类、中外交流一类）。"],["人物评价与辩证思维","","隋炀帝、唐玄宗（前期与后期）是评价题的常客，要求一分为二、史论结合，答「功过并存，以史实说明，不以成败论人」。"],["因果链条：治世与乱世","","「贞观之治—开元盛世—安史之乱」常连成一条因果链，考查「统治者政策与国家兴衰的关系」，落脚在「以民为本、爱惜民力」。"]]},{"type":"note","title":"跨学科视角","text":"地理：大运河与南北水运；语文：唐诗中的盛唐气象。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["天可汗","西北各族对唐太宗的尊称，表示拥戴其为共主。","《旧唐书·太宗本纪》"],["和同为一家","唐蕃会盟碑中的表述，形容唐与吐蕃的亲密关系。","《唐蕃会盟碑》碑文"]]},{"type":"kv","title":"人物卡片","items":[{"k":"松赞干布","v":"吐蕃赞普，统一青藏高原，迎娶文成公主。 出处：《旧唐书·吐蕃传》"},{"k":"文成公主","v":"唐宗室女，641 年入藏，促进唐蕃交流。 出处：《旧唐书·吐蕃传》"}]},{"type":"list","title":"延伸阅读","items":["文成公主入藏：641 年，唐太宗派文成公主入吐蕃，带去大量书籍、种子、工匠和技术，促进吐蕃经济文化发展。 出处：《旧唐书·吐蕃传》","唐蕃会盟碑：823 年，唐蕃会盟，立碑于拉萨大昭寺前，碑文称「舅甥二主，商议社稷如一」，至今保存。 出处：《唐蕃会盟碑》碑文；2024 部编版七下第 5 课"]},{"type":"list","title":"本课拓展出处","items":["《旧唐书·吐蕃传》；《资治通鉴》卷一九五","2024 部编版七下第 5 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u1-q1","type":"choice","stem":"605 年起下令开凿大运河，以洛阳为中心、北抵涿郡、南至余杭的皇帝是","answer":"B","explain":"大运河由隋炀帝下令开凿（605 年起），以洛阳为中心，北抵涿郡，南至余杭，是古代世界上最长的运河。隋文帝的功绩是统一全国、创立三省六部制与分科考试选官。","options":["隋文帝","隋炀帝","唐高祖","唐玄宗"],"tags":["大运河","时空观念"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"h7b-u1-q3","type":"choice","stem":"为中日文化交流作出突出贡献，六次东渡并在日本主持修建唐招提寺的僧人是","answer":"B","explain":"鉴真六次东渡日本，传授佛经、传播中华文化，主持修建唐招提寺。玄奘西行天竺取经并口述成《大唐西域记》；法显是东晋僧人。","options":["玄奘","鉴真","法显","一行"],"tags":["鉴真东渡","中外交流"]},{"id":"cat-7b-1-5-g2","type":"choice","stem":"下列关于「隋唐时期的民族交往与交融」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","唐朝的民族交往：641 年文成公主入藏与松赞干布和亲，唐中宗时金城公主入藏；唐蕃订立盟约、互通使节；唐朝还册封回纥、南诏等少数民族首领。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-5-g3","type":"choice","stem":"下列结论中，属于「隋唐时期的民族交往与交融」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-5-g4","type":"short","stem":"阅读材料，回答问题。\n材料：641 年，唐太宗派文成公主入吐蕃，带去大量书籍、种子、工匠和技术，促进吐蕃经济文化发展。（《旧唐书·吐蕃传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋唐时期的民族交往与交融；唐朝的民族交往：641 年文成公主入藏与松赞干布和亲，唐中宗时金城公主入藏；唐蕃订立盟约、互通使节；唐朝还册封回纥、南诏等少数民族首领。","explain":"材料出自《旧唐书·吐蕃传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-1-6","title":"第6课 隋唐时期的中外文化交流","subtitle":"七年级下册 · 第一单元 隋唐时期：繁荣与开放的时代","grade":"7b","tags":["七年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第一单元 隋唐时期：繁荣与开放的时代"},{"k":"课时","v":"第6课 隋唐时期的中外文化交流"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"唐朝实行开放的对外政策，与日本、新罗、天竺、大食等国交往频繁。日本先后派遣唐使十余次来华，学习唐朝制度文化；鉴真六次东渡日本传播佛法；玄奘西行天竺取经，著《大唐西域记》。"},{"type":"note","title":"本课主线 · 因果链","text":"隋朝结束长期分裂，创立科举制、三省六部制并开凿大运河，为唐朝的繁荣奠定基础；唐朝前期政治清明、民族交融、对外开放，达到中国古代社会的鼎盛，而安史之乱使唐朝由盛转衰，藩镇割据最终演变成五代十国的分裂。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["唐太宗时","玄奘西行天竺取经，后口述成《大唐西域记》","玄奘口述、弟子辩机笔录；该书是研究中外交流史的珍贵文献"],["753 年","鉴真第六次东渡成功，到达日本","鉴真在日本传授佛经、传播中华文化，主持修建唐招提寺"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 鉴真东渡：十二年六次渡海","caption":"示意图：鉴真东渡：十二年六次渡海，详见下方「历史现场」","view":"tall","alt":"示意图：鉴真东渡：十二年六次渡海，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"743 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"日本僧人荣睿、普照邀请鉴真东渡，首次…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"744 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"第二次被官府阻拦；此后第三、四次又因…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"748 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"第五次出海遇飓风，漂流至海南岛，荣睿…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"753 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"第六次东渡成功，抵达日本萨摩","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"754 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"到达奈良，受到日本朝野盛大欢迎，后主…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"唐朝的中外文化交流：日本先后派遣十几批遣唐使来华，鉴真六次东渡、在日本主持修建唐招提寺，玄奘西行天竺取经并写成《大唐西域记》，新罗也学习唐朝制度与文化。","explain":"要能分清「走出去」（鉴真东渡传播中华文化、玄奘西行取经）与「引进来」（遣唐使来华、吸收外来乐舞与物产），共同说明唐朝**实行开放的对外政策、兼容并蓄**。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把鉴真与玄奘的目的地写反。","鉴真东渡**日本**（传播佛法与中华文化，主持修建唐招提寺）；玄奘西行**天竺**（取经，口述成《大唐西域记》）。","一人去日本、一人去印度，选项常把地名对调。"]]},{"type":"table","title":"唐朝与同时期的世界（7—9 世纪）（中外对比：开放繁荣与相对封闭的不同走向）","head":["比较项","唐朝（中国）","西欧（法兰克王国等）"],"rows":[["政治","三省六部制、科举制，中央集权加强","封君封臣制度，王权软弱、地方割据"],["经济","农业生产发展，长安、洛阳、扬州等城市商业兴盛","以庄园经济为主，城市商业相对落后"],["对外交往","遣唐使、胡商云集，兼容并蓄","交往范围有限，受战乱与教会影响较大"],["文化","唐诗、雕版印刷术、火药","基督教文化，修道院保存古典典籍"],["共同点","都处于封建社会的发展时期","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["制度创新与人才选拔","近年中考常见","以科举制创立与完善的材料切入，要求说明「考试取士」打破门第限制、扩大统治基础，常与九品中正制或明清八股取士对比考查。"],["史料实证：隋唐的开放气象","","给出遣唐使、鉴真东渡、玄奘西行、唐蕃和亲等材料，要求提炼「对外开放、民族交融」的认识；答题必须**分类作答**（民族交往一类、中外交流一类）。"],["人物评价与辩证思维","","隋炀帝、唐玄宗（前期与后期）是评价题的常客，要求一分为二、史论结合，答「功过并存，以史实说明，不以成败论人」。"],["因果链条：治世与乱世","","「贞观之治—开元盛世—安史之乱」常连成一条因果链，考查「统治者政策与国家兴衰的关系」，落脚在「以民为本、爱惜民力」。"]]},{"type":"note","title":"跨学科视角","text":"地理：大运河与南北水运；语文：唐诗中的盛唐气象。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 鉴真东渡：十二年六次渡海","head":["时间","经过"],"rows":[["743 年","日本僧人荣睿、普照邀请鉴真东渡，首次出海遭风浪失败"],["744 年","第二次被官府阻拦；此后第三、四次又因风浪、告密失败"],["748 年","第五次出海遇飓风，漂流至海南岛，荣睿病逝，鉴真双目失明"],["753 年","第六次东渡成功，抵达日本萨摩"],["754 年","到达奈良，受到日本朝野盛大欢迎，后主持唐招提寺"]]},{"type":"note","title":"现场解说","text":"鉴真带去佛经、医药、建筑、雕塑等知识，对日本文化发展影响深远。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["六次东渡","鉴真六次东渡日本，五次失败仍不放弃，比喻坚韧不拔。","《唐大和上东征传》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"鉴真","v":"唐代高僧，六次东渡日本，传播佛教与唐文化。 出处：《唐大和上东征传》"},{"k":"玄奘","v":"唐代高僧，西行天竺取经，著《大唐西域记》。 出处：《大唐西域记》"}]},{"type":"list","title":"延伸阅读","items":["鉴真东渡：鉴真应日本僧人邀请东渡，前五次或遇风浪、或遭阻拦而失败，双目失明后仍坚持，753 年第六次成功抵达日本，主持修建唐招提寺。 出处：真人元开《唐大和上东征传》","玄奘西行：627 年玄奘从长安出发，历经艰险到达天竺，在那烂陀寺学习多年，645 年携大量佛经返回长安，主持译经。 出处：《大唐西域记》；《大慈恩寺三藏法师传》"]},{"type":"list","title":"本课拓展出处","items":["《大唐西域记》；真人元开《唐大和上东征传》","2024 部编版七下第 6 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u1-q3","type":"choice","stem":"为中日文化交流作出突出贡献，六次东渡并在日本主持修建唐招提寺的僧人是","answer":"B","explain":"鉴真六次东渡日本，传授佛经、传播中华文化，主持修建唐招提寺。玄奘西行天竺取经并口述成《大唐西域记》；法显是东晋僧人。","options":["玄奘","鉴真","法显","一行"],"tags":["鉴真东渡","中外交流"]},{"id":"cat-7b-1-6-g2","type":"choice","stem":"下列关于「隋唐时期的中外文化交流」的表述，错误的是","answer":"A","explain":"把鉴真与玄奘的目的地写反——一人去日本、一人去印度，选项常把地名对调。正确表述：鉴真东渡**日本**（传播佛法与中华文化，主持修建唐招提寺）；玄奘西行**天竺**（取经，口述成《大唐西域记》）。","options":["把鉴真与玄奘的目的地写反。","鉴真东渡**日本**（传播佛法与中华文化，主持修建唐招提寺）；玄奘西行**天竺**（取经，口述成《大唐西域记》）。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。","唐朝的中外文化交流：日本先后派遣十几批遣唐使来华，鉴真六次东渡、在日本主持修建唐招提寺，玄奘西行天竺取经并写成《大唐西域记》，新罗也学习唐朝制度与文化。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-6-g3","type":"choice","stem":"下列结论中，属于「隋唐时期的中外文化交流」的是","answer":"A","explain":"本课结论：唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-6-g4","type":"short","stem":"阅读材料，回答问题。\n材料：鉴真应日本僧人邀请东渡，前五次或遇风浪、或遭阻拦而失败，双目失明后仍坚持，753 年第六次成功抵达日本，主持修建唐招提寺。（真人元开《唐大和上东征传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋唐时期的中外文化交流；唐朝的中外文化交流：日本先后派遣十几批遣唐使来华，鉴真六次东渡、在日本主持修建唐招提寺，玄奘西行天竺取经并写成《大唐西域记》，新罗也学习唐朝制度与文化。","explain":"材料出自真人元开《唐大和上东征传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-1-6-g5","type":"choice","stem":"「玄奘西行天竺取经，后口述成《大唐西域记》」发生于","answer":"A","explain":"本课时间轴：玄奘西行天竺取经，后口述成《大唐西域记》（唐太宗时）。玄奘口述、弟子辩机笔录；该书是研究中外交流史的珍贵文献。其余三个时间是同一单元相邻课时的事件时间。","options":["唐太宗时","581 年","605 年起","隋炀帝时"],"difficulty":1,"tags":["七年级下册","第一单元","本课练习"]}]},{"id":"cat-7b-1-7","title":"第7课 隋唐时期的科技与文化","subtitle":"七年级下册 · 第一单元 隋唐时期：繁荣与开放的时代","grade":"7b","tags":["七年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第一单元 隋唐时期：繁荣与开放的时代"},{"k":"课时","v":"第7课 隋唐时期的科技与文化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"隋唐时期科技文化成就辉煌。雕版印刷术在唐代已经使用，现存最早标有年代的雕版印刷品是 868 年的《金刚经》；火药在唐末开始用于军事；唐诗是中国古典诗歌的高峰，李白、杜甫、白居易各具风格；书法有颜真卿、柳公权，绘画有阎立本、吴道子。"},{"type":"note","title":"本课主线 · 因果链","text":"隋朝结束长期分裂，创立科举制、三省六部制并开凿大运河，为唐朝的繁荣奠定基础；唐朝前期政治清明、民族交融、对外开放，达到中国古代社会的鼎盛，而安史之乱使唐朝由盛转衰，藩镇割据最终演变成五代十国的分裂。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["581 年","杨坚夺取北周政权，建立隋朝，定都长安","他就是隋文帝；589 年隋灭陈，统一全国，结束了长期分裂的局面 · 重点"],["605 年起","隋炀帝下令开凿大运河","以洛阳为中心，北抵涿郡（今北京），南至余杭（今杭州），是古代世界上最长的运河 · 重点"],["隋炀帝时","设置进士科，科举制正式确立","隋文帝时已开始用分科考试的办法选拔官员，隋炀帝设进士科后才形成完整的科举制度 · 重点"],["618 年","隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","李渊即唐高祖；隋朝与秦朝一样二世而亡，教训都是「不恤民力」 · 重点"],["627—649 年","唐太宗统治时期，出现「贞观之治」","李世民吸取隋亡教训，减轻赋税徭役、虚心纳谏（魏征）、知人善任（房玄龄、杜如晦）"],["唐太宗时","玄奘西行天竺取经，后口述成《大唐西域记》","玄奘口述、弟子辩机笔录；该书是研究中外交流史的珍贵文献"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"581 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"杨坚夺取北周政权，建立隋朝，定都长安","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"605 年起","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"隋炀帝下令开凿大运河","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"隋炀帝时","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"设置进士科，科举制正式确立","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"618 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"隋炀帝被杀，隋朝灭亡；李渊建立唐朝，…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"627—649 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"唐太宗统治时期，出现「贞观之治」","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"唐太宗时","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"玄奘西行天竺取经，后口述成《大唐西域…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"次重点","text":"隋唐科技文化：李春设计建造的赵州桥、隋唐时期的雕版印刷术、唐朝发明的火药；唐诗的黄金时代（李白、杜甫、白居易）。","explain":"与明清科技对比时常考「发明—外传—影响」这一条链。"},{"level":"次重点","text":"书法与绘画：颜真卿、柳公权的楷书，阎立本、吴道子的绘画，敦煌莫高窟的彩塑与壁画。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。"],["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。"]]},{"type":"table","title":"唐朝与同时期的世界（7—9 世纪）（中外对比：开放繁荣与相对封闭的不同走向）","head":["比较项","唐朝（中国）","西欧（法兰克王国等）"],"rows":[["政治","三省六部制、科举制，中央集权加强","封君封臣制度，王权软弱、地方割据"],["经济","农业生产发展，长安、洛阳、扬州等城市商业兴盛","以庄园经济为主，城市商业相对落后"],["对外交往","遣唐使、胡商云集，兼容并蓄","交往范围有限，受战乱与教会影响较大"],["文化","唐诗、雕版印刷术、火药","基督教文化，修道院保存古典典籍"],["共同点","都处于封建社会的发展时期","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["制度创新与人才选拔","近年中考常见","以科举制创立与完善的材料切入，要求说明「考试取士」打破门第限制、扩大统治基础，常与九品中正制或明清八股取士对比考查。"],["史料实证：隋唐的开放气象","","给出遣唐使、鉴真东渡、玄奘西行、唐蕃和亲等材料，要求提炼「对外开放、民族交融」的认识；答题必须**分类作答**（民族交往一类、中外交流一类）。"],["人物评价与辩证思维","","隋炀帝、唐玄宗（前期与后期）是评价题的常客，要求一分为二、史论结合，答「功过并存，以史实说明，不以成败论人」。"],["因果链条：治世与乱世","","「贞观之治—开元盛世—安史之乱」常连成一条因果链，考查「统治者政策与国家兴衰的关系」，落脚在「以民为本、爱惜民力」。"]]},{"type":"note","title":"跨学科视角","text":"地理：大运河与南北水运；语文：唐诗中的盛唐气象。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["诗仙、诗圣","李白诗风飘逸奔放，被称为诗仙；杜甫诗风沉郁顿挫、反映现实，被称为诗圣。","2024 部编版七下第 7 课；《唐才子传》"],["画圣","吴道子善画人物，笔法遒劲，被后世尊为画圣。","张彦远《历代名画记》"],["颜筋柳骨","颜真卿书法丰腴雄浑，柳公权书法骨力劲健，合称颜筋柳骨。","2024 部编版七下第 7 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"李白","v":"唐代诗人，代表作《将进酒》《蜀道难》，被誉为诗仙。 出处：《旧唐书·李白传》"},{"k":"杜甫","v":"唐代诗人，代表作「三吏」「三别」，被誉为诗圣。 出处：《旧唐书·杜甫传》"},{"k":"颜真卿","v":"唐代书法家，创颜体楷书，代表作《多宝塔碑》。 出处：《旧唐书·颜真卿传》"}]},{"type":"list","title":"延伸阅读","items":["敦煌莫高窟：莫高窟位于甘肃敦煌，现存洞窟 735 个，壁画 4.5 万平方米，彩塑 2400 余身，是世界上现存规模最大的佛教艺术宝库。 出处：敦煌研究院《敦煌莫高窟》","唐诗的数量：《全唐诗》收录诗歌约四万九千首，作者两千余人，反映唐代社会生活的各个方面。 出处：《全唐诗》"]},{"type":"list","title":"本课拓展出处","items":["《全唐诗》；《旧唐书·文苑传》","2024 部编版七下第 7 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u1-q1","type":"choice","stem":"605 年起下令开凿大运河，以洛阳为中心、北抵涿郡、南至余杭的皇帝是","answer":"B","explain":"大运河由隋炀帝下令开凿（605 年起），以洛阳为中心，北抵涿郡，南至余杭，是古代世界上最长的运河。隋文帝的功绩是统一全国、创立三省六部制与分科考试选官。","options":["隋文帝","隋炀帝","唐高祖","唐玄宗"],"tags":["大运河","时空观念"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"h7b-u1-q3","type":"choice","stem":"为中日文化交流作出突出贡献，六次东渡并在日本主持修建唐招提寺的僧人是","answer":"B","explain":"鉴真六次东渡日本，传授佛经、传播中华文化，主持修建唐招提寺。玄奘西行天竺取经并口述成《大唐西域记》；法显是东晋僧人。","options":["玄奘","鉴真","法显","一行"],"tags":["鉴真东渡","中外交流"]},{"id":"cat-7b-1-7-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杨坚夺取北周政权，建立隋朝，定都长安\n② 隋炀帝下令开凿大运河\n③ 设置进士科，科举制正式确立\n④ 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","answer":"A","explain":"按时间顺序应为：①杨坚夺取北周政权，建立隋朝，定都长安（581 年）→②隋炀帝下令开凿大运河（605 年起）→③设置进士科，科举制正式确立（隋炀帝时）→④隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-7-g2","type":"choice","stem":"下列关于「隋唐时期的科技与文化」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-7-g3","type":"choice","stem":"下列结论中，属于「隋唐时期的科技与文化」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-7-g4","type":"short","stem":"阅读材料，回答问题。\n材料：莫高窟位于甘肃敦煌，现存洞窟 735 个，壁画 4.5 万平方米，彩塑 2400 余身，是世界上现存规模最大的佛教艺术宝库。（敦煌研究院《敦煌莫高窟》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋唐时期的科技与文化；隋唐科技文化：李春设计建造的赵州桥、隋唐时期的雕版印刷术、唐朝发明的火药；唐诗的黄金时代（李白、杜甫、白居易）。","explain":"材料出自敦煌研究院《敦煌莫高窟》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-2-1","title":"第8课 北宋的政治","subtitle":"七年级下册 · 第二单元 辽宋夏金元时期：民族关系发展和社会变化","grade":"7b","tags":["七年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第二单元 辽宋夏金元时期：民族关系发展和社会变化"},{"k":"课时","v":"第8课 北宋的政治"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"960 年，后周大将赵匡胤在陈桥驿发动兵变，建立北宋，定都开封。他通过「杯酒释兵权」解除大将兵权，实行重文轻武政策，加强中央集权。1069 年宋神宗任用王安石变法，因阻力大而失败。"},{"type":"note","title":"本课主线 · 因果链","text":"北宋以「重文轻武」加强中央集权，与辽、西夏、金长期并立、和战交替；两宋时期经济重心南移完成，商品经济与海外贸易空前繁荣；蒙古崛起后元朝重建大一统，行省制与对西藏、台湾的管辖使统一多民族国家进一步发展，民族交融与宋元科技成就影响深远。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["960 年","赵匡胤建立北宋，定都东京（今河南开封）","赵匡胤即宋太祖；他「杯酒释兵权」，解除禁军将领的兵权，推行重文轻武政策 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"tall","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":17,"text":"北宋加强中央集权与「重文轻武」：宋太…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"次重点","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"王安石变法（1069 年）：推行募役…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":73,"text":"辽宋夏金元时期的时代特征是**民族关…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":101,"text":"经济重心南移的因果链：北方战乱与人口…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":129,"text":"元朝的行省制度是我国省级行政区划的开…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"北宋加强中央集权与「重文轻武」：宋太祖解除禁军将领兵权，分割宰相权力，派文臣担任地方长官并设通判加以牵制，同时大力发展科举、重用文臣。","explain":"评价要一分为二：积极方面防止了武将专权、有利于政权稳固和社会安定；消极方面造成官僚机构臃肿、军队战斗力削弱、财政负担沉重（冗官、冗兵、冗费）。"},{"level":"次重点","text":"王安石变法（1069 年）：推行募役法、方田均税法、保甲法、农田水利法等，收到一些成效，但因触犯大官僚、大地主的利益而失败。","explain":"常考「变法的目的（富国强兵）」「变法失败的原因（触犯大官僚大地主利益、用人不当）」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。"],["把「交子」说成唐朝或南宋出现。","交子出现于北宋前期的四川地区，是世界上最早的纸币。","时间（北宋前期）与地点（四川）都爱设陷阱，选项常用「南宋」「临安」来干扰。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["民族关系与政权并立","近年中考高频","以政权并立形势图或和战材料切入，要求说明「民族交融是历史发展的主流」，常与第三单元「统一多民族国家的巩固」合并成大题。"],["经济重心南移的因果分析","","给出「国家根本，仰给东南」一类材料，要求概括原因（北人南迁、南方安定、自然条件）与表现（农业、手工业、商业），并落到「社会安定是经济发展的前提」这一规律认识。"],["制度与边疆管辖","","行省制度、宣政院、澎湖巡检司是「西藏、台湾自古以来是中国领土」的核心史实论据，多见于选择题与材料题第一问，要求「措施—机构—作用」一一对应。"],["科技成就与世界影响","","以印刷术、指南针、火药的外传为切口，考查「中国古代科技对世界文明的影响」，答题须写出传入路线（经阿拉伯人西传）与对欧洲的具体作用。"]]},{"type":"note","title":"跨学科视角","text":"地理：经济重心南移与气候、水运；科学：指南针、活字印刷与火药。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["陈桥兵变","赵匡胤在陈桥驿被部下「黄袍加身」，建立北宋。","《宋史·太祖本纪》"],["杯酒释兵权","宋太祖设宴劝石守信等大将交出兵权，以和平方式加强中央集权。","《续资治通鉴长编》卷二"],["黄袍加身","部下把黄袍披在赵匡胤身上拥立为帝，后比喻被推举为首领。","《宋史·太祖本纪》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"宋太祖","v":"赵匡胤，北宋建立者，加强中央集权。 出处：《宋史·太祖本纪》"},{"k":"王安石","v":"北宋政治家、文学家，主持熙宁变法。 出处：《宋史·王安石传》"}]},{"type":"list","title":"延伸阅读","items":["重文轻武：北宋扩大科举取士，重用文臣掌兵权，地方设通判监督知州，设转运使收财权，形成「强干弱枝」格局。 出处：《宋史·职官志》","王安石变法：推行青苗法、募役法、方田均税法、农田水利法、保甲法等，目的是富国强兵，但因触动既得利益、执行偏差而失败。 出处：《宋史·王安石传》"]},{"type":"list","title":"本课拓展出处","items":["《宋史·太祖本纪》《宋史·王安石传》","2024 部编版七下第 8 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u2-q1","type":"choice","stem":"宋太祖「杯酒释兵权」，并推行重文轻武的政策，其主要目的是","answer":"B","explain":"宋太祖吸取唐末以来武将专权、藩镇割据的教训，通过解除禁军将领兵权、重用文臣等办法防止武将专权，加强中央集权。其结果是军队战斗力有所削弱、财政负担加重。","options":["提高军队的战斗力","防止武将专权，加强中央集权","减轻农民的赋税负担","增加国家的财政收入"],"tags":["重文轻武","中央集权"]},{"id":"cat-7b-2-1-g2","type":"choice","stem":"下列关于「北宋的政治」的表述，错误的是","answer":"A","explain":"认为经济重心南移完成于唐朝——「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。正确表述：经济重心南移**从唐朝中期开始，到南宋时最后完成**。","options":["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-1-g3","type":"choice","stem":"下列结论中，属于「北宋的政治」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：北宋扩大科举取士，重用文臣掌兵权，地方设通判监督知州，设转运使收财权，形成「强干弱枝」格局。（《宋史·职官志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"北宋的政治；北宋加强中央集权与「重文轻武」：宋太祖解除禁军将领兵权，分割宰相权力，派文臣担任地方长官并设通判加以牵制，同时大力发展科举、重用文臣。","explain":"材料出自《宋史·职官志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-2-1-g5","type":"choice","stem":"「赵匡胤建立北宋，定都东京（今河南开封）」发生于","answer":"A","explain":"本课时间轴：赵匡胤建立北宋，定都东京（今河南开封）（960 年）。赵匡胤即宋太祖；他「杯酒释兵权」，解除禁军将领的兵权，推行重文轻武政策。其余三个时间是同一单元相邻课时的事件时间。","options":["960 年","1005 年","1038 年","1115 年"],"difficulty":1,"tags":["七年级下册","第二单元","本课练习"]}]},{"id":"cat-7b-2-2","title":"第9课 辽、西夏与北宋并立","subtitle":"七年级下册 · 第二单元 辽宋夏金元时期：民族关系发展和社会变化","grade":"7b","tags":["七年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第二单元 辽宋夏金元时期：民族关系发展和社会变化"},{"k":"课时","v":"第9课 辽、西夏与北宋并立"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"916 年耶律阿保机建立契丹国（后改国号辽），1038 年党项首领元昊建立西夏。辽、西夏与北宋长期并立，时有战争。1005 年宋辽达成澶渊之盟，此后双方保持百余年和平。"},{"type":"note","title":"本课主线 · 因果链","text":"北宋以「重文轻武」加强中央集权，与辽、西夏、金长期并立、和战交替；两宋时期经济重心南移完成，商品经济与海外贸易空前繁荣；蒙古崛起后元朝重建大一统，行省制与对西藏、台湾的管辖使统一多民族国家进一步发展，民族交融与宋元科技成就影响深远。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1005 年","宋辽订立「澶渊之盟」","北宋每年给辽岁币，此后宋辽保持了长时间的和平局面，边境贸易（榷场）发展 · 重点"],["1038 年","党项族首领元昊称帝，建立西夏","西夏与北宋多次交战，后来议和并保持交往"],["1115 年","女真族首领完颜阿骨打建立金","1125 年金灭辽；1127 年金灭北宋，史称「靖康之变」"],["1206 年","铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗","蒙古先后灭西夏（1227 年）、灭金（1234 年），为元朝统一奠定基础"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1005 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"宋辽订立「澶渊之盟」","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"1038 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"党项族首领元昊称帝，建立西夏","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"1115 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"女真族首领完颜阿骨打建立金","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1206 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"铁木真统一蒙古草原，建立蒙古政权，被…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"辽、西夏、金与两宋的和战：1005 年宋辽订立澶渊之盟后长期和平；北宋与西夏议和；1141 年宋金议和，以淮河至大散关一线划界，南宋向金称臣、送岁币。","explain":"认识要写全两句话：和议对两宋而言带有屈辱性、加重了财政负担；但客观上使边境相对安定，促进了边境贸易与民族交融，**和平往来是民族关系的主流**。"},{"level":"重点","text":"宋元时期的民族交融：汉族与契丹、党项、女真、蒙古等族杂居、通婚，相互学习生产技术与生活习俗；元朝时逐渐形成一个新的民族——回族（回回）。","explain":"答题术语：民族交融是**双向**的（少数民族汉化与汉族吸收少数民族习俗并存），元朝的统一为大规模民族交融提供了条件。"},{"level":"次重点","text":"辽、西夏、金三个政权的建立民族与建立者：契丹族（耶律阿保机）建立辽，党项族（元昊）建立西夏，女真族（完颜阿骨打）建立金。","explain":"「民族—政权—建立者」的配对表是选择题常设的送分点，也常与「政权并立形势图」结合考查。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把「澶渊之盟」与「靖康之变」混为一谈。","澶渊之盟是 1005 年宋辽之间的议和；靖康之变是 1127 年金灭北宋。","一个发生在宋辽之间、一个发生在宋金之间，时间与对象都不能混。"]]},{"type":"table","title":"澶渊之盟与宋金议和（同一主题的横向比较（两宋与少数民族政权的和战））","head":["比较项","澶渊之盟（1005 年，宋辽）","宋金议和（1141 年）"],"rows":[["双方","北宋与辽","南宋与金"],["主要内容","北宋每年给辽岁币，双方约为兄弟之国","南宋向金称臣、送岁币，以淮河至大散关一线划界"],["影响","宋辽保持长时间和平，边境贸易发展","宋金对峙局面形成，南北交流与民族交融仍在继续"],["共同认识","和议带有屈辱性、加重财政负担，但客观上促进了和平交往与民族交融","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["民族关系与政权并立","近年中考高频","以政权并立形势图或和战材料切入，要求说明「民族交融是历史发展的主流」，常与第三单元「统一多民族国家的巩固」合并成大题。"],["经济重心南移的因果分析","","给出「国家根本，仰给东南」一类材料，要求概括原因（北人南迁、南方安定、自然条件）与表现（农业、手工业、商业），并落到「社会安定是经济发展的前提」这一规律认识。"],["制度与边疆管辖","","行省制度、宣政院、澎湖巡检司是「西藏、台湾自古以来是中国领土」的核心史实论据，多见于选择题与材料题第一问，要求「措施—机构—作用」一一对应。"],["科技成就与世界影响","","以印刷术、指南针、火药的外传为切口，考查「中国古代科技对世界文明的影响」，答题须写出传入路线（经阿拉伯人西传）与对欧洲的具体作用。"]]},{"type":"note","title":"跨学科视角","text":"地理：经济重心南移与气候、水运；科学：指南针、活字印刷与火药。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["澶渊之盟","宋辽和议，以岁币换取和平，是古代民族关系中以和谈解决冲突的案例。","《续资治通鉴长编》卷五十八"]]},{"type":"kv","title":"人物卡片","items":[{"k":"耶律阿保机","v":"契丹首领，916 年建立契丹国。 出处：《辽史·太祖本纪》"},{"k":"寇准","v":"北宋宰相，力主宋真宗亲征澶州。 出处：《宋史·寇准传》"}]},{"type":"list","title":"延伸阅读","items":["澶渊之盟：1004 年辽军南下，宋真宗在寇准力劝下亲征澶州。1005 年双方议和：宋每年给辽白银十万两、绢二十万匹，辽撤兵，双方约为兄弟之国。 出处：《续资治通鉴长编》卷五十八","榷场贸易：宋辽、宋夏在边境设榷场互市，北宋输出茶叶、瓷器、丝绸，换取马匹、皮毛、药材，经济联系加强。 出处：2024 部编版七下第 9 课"]},{"type":"list","title":"本课拓展出处","items":["《辽史》《宋史·真宗本纪》《续资治通鉴长编》","2024 部编版七下第 9 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u2-q2","type":"choice","stem":"宋辽之间保持长时间的和平局面，开始于","answer":"B","explain":"1005 年宋辽订立澶渊之盟，北宋每年给辽岁币，此后很长时间里宋辽保持了和平局面，边境贸易发展。","options":["北宋建立","澶渊之盟的订立","靖康之变","宋金议和"],"tags":["澶渊之盟","时空观念"]},{"id":"cat-7b-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 宋辽订立「澶渊之盟」\n② 党项族首领元昊称帝，建立西夏\n③ 女真族首领完颜阿骨打建立金\n④ 铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗","answer":"A","explain":"按时间顺序应为：①宋辽订立「澶渊之盟」（1005 年）→②党项族首领元昊称帝，建立西夏（1038 年）→③女真族首领完颜阿骨打建立金（1115 年）→④铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗（1206 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-2-g2","type":"choice","stem":"下列关于「辽、西夏与北宋并立」的表述，错误的是","answer":"A","explain":"把「澶渊之盟」与「靖康之变」混为一谈——一个发生在宋辽之间、一个发生在宋金之间，时间与对象都不能混。正确表述：澶渊之盟是 1005 年宋辽之间的议和；靖康之变是 1127 年金灭北宋。","options":["把「澶渊之盟」与「靖康之变」混为一谈。","澶渊之盟是 1005 年宋辽之间的议和；靖康之变是 1127 年金灭北宋。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-2-g3","type":"choice","stem":"下列结论中，属于「辽、西夏与北宋并立」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1004 年辽军南下，宋真宗在寇准力劝下亲征澶州。1005 年双方议和：宋每年给辽白银十万两、绢二十万匹，辽撤兵，双方约为兄弟之国。（《续资治通鉴长编》卷五十八）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"辽、西夏与北宋并立；辽、西夏、金与两宋的和战：1005 年宋辽订立澶渊之盟后长期和平；北宋与西夏议和；1141 年宋金议和，以淮河至大散关一线划界，南宋向金称臣、送岁币。","explain":"材料出自《续资治通鉴长编》卷五十八。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-2-3","title":"第10课 金与南宋对峙","subtitle":"七年级下册 · 第二单元 辽宋夏金元时期：民族关系发展和社会变化","grade":"7b","tags":["七年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第二单元 辽宋夏金元时期：民族关系发展和社会变化"},{"k":"课时","v":"第10课 金与南宋对峙"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1115 年，女真首领完颜阿骨打建立金朝。1127 年，金军攻破开封，掳走宋徽宗、宋钦宗，北宋灭亡，史称「靖康之变」。赵构在临安建立南宋。岳飞率「岳家军」抗金，1140 年在郾城大败金军，1142 年被以「莫须有」罪名杀害。"},{"type":"note","title":"本课主线 · 因果链","text":"北宋以「重文轻武」加强中央集权，与辽、西夏、金长期并立、和战交替；两宋时期经济重心南移完成，商品经济与海外贸易空前繁荣；蒙古崛起后元朝重建大一统，行省制与对西藏、台湾的管辖使统一多民族国家进一步发展，民族交融与宋元科技成就影响深远。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1115 年","女真族首领完颜阿骨打建立金","1125 年金灭辽；1127 年金灭北宋，史称「靖康之变」"],["1127 年","金灭北宋，赵构称帝建立南宋，后定都临安（今浙江杭州）","赵构即宋高宗；北宋灭亡与南宋建立发生在同一年 · 重点"],["1140—1141 年","岳飞率军抗金，取得郾城大捷；随后被害，宋金达成和议","1141 年宋金议和：南宋向金称臣、送岁币，以淮河至大散关一线划界，宋金对峙局面形成"],["1206 年","铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗","蒙古先后灭西夏（1227 年）、灭金（1234 年），为元朝统一奠定基础"],["1271 年","忽必烈改国号为元，次年定都大都；1279 年完成全国统一","1276 年元军攻占临安，南宋灭亡；元朝是蒙古族建立的全国性统一王朝 · 重点"],["南宋时","经济重心南移完成","谚语「苏湖熟，天下足」；南方成为全国最重要的粮仓与财赋来源地 · 重点"],["北宋前期","四川地区出现「交子」","这是世界上最早的纸币；南宋时纸币与铜钱并行流通"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1115 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"女真族首领完颜阿骨打建立金","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":29.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":32.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":29.67,"text":"1127 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":35.67,"text":"金灭北宋，赵构称帝建立南宋，后定都临…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":36.07,"x2":14,"y2":47.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":51.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":48.33,"text":"1140—1141 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":54.33,"text":"岳飞率军抗金，取得郾城大捷；随后被害…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":54.73,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1206 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"铁木真统一蒙古草原，建立蒙古政权，被…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":85.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":88.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":85.67,"text":"1271 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":91.67,"text":"忽必烈改国号为元，次年定都大都；12…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":92.07,"x2":14,"y2":103.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":107.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":104.33,"text":"南宋时","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":110.33,"text":"经济重心南移完成","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":110.73,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"北宋前期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"四川地区出现「交子」","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"辽、西夏、金与两宋的和战：1005 年宋辽订立澶渊之盟后长期和平；北宋与西夏议和；1141 年宋金议和，以淮河至大散关一线划界，南宋向金称臣、送岁币。","explain":"认识要写全两句话：和议对两宋而言带有屈辱性、加重了财政负担；但客观上使边境相对安定，促进了边境贸易与民族交融，**和平往来是民族关系的主流**。"},{"level":"重点","text":"经济重心南移的完成：从唐朝中期开始的经济重心南移，到南宋时最后完成。原因是北方战乱、人口南迁带来劳动力与先进技术，南方自然条件优越、社会相对安定，统治者重视生产。","explain":"表现要会举例：农业（「苏湖熟，天下足」、水稻产量居首、茶树与棉花种植推广）、手工业（景德镇瓷器、南方造船业）、商业与海外贸易。"},{"level":"次重点","text":"辽、西夏、金三个政权的建立民族与建立者：契丹族（耶律阿保机）建立辽，党项族（元昊）建立西夏，女真族（完颜阿骨打）建立金。","explain":"「民族—政权—建立者」的配对表是选择题常设的送分点，也常与「政权并立形势图」结合考查。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。"],["把「交子」说成唐朝或南宋出现。","交子出现于北宋前期的四川地区，是世界上最早的纸币。","时间（北宋前期）与地点（四川）都爱设陷阱，选项常用「南宋」「临安」来干扰。"],["把「澶渊之盟」与「靖康之变」混为一谈。","澶渊之盟是 1005 年宋辽之间的议和；靖康之变是 1127 年金灭北宋。","一个发生在宋辽之间、一个发生在宋金之间，时间与对象都不能混。"]]},{"type":"table","title":"澶渊之盟与宋金议和（同一主题的横向比较（两宋与少数民族政权的和战））","head":["比较项","澶渊之盟（1005 年，宋辽）","宋金议和（1141 年）"],"rows":[["双方","北宋与辽","南宋与金"],["主要内容","北宋每年给辽岁币，双方约为兄弟之国","南宋向金称臣、送岁币，以淮河至大散关一线划界"],["影响","宋辽保持长时间和平，边境贸易发展","宋金对峙局面形成，南北交流与民族交融仍在继续"],["共同认识","和议带有屈辱性、加重财政负担，但客观上促进了和平交往与民族交融","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["民族关系与政权并立","近年中考高频","以政权并立形势图或和战材料切入，要求说明「民族交融是历史发展的主流」，常与第三单元「统一多民族国家的巩固」合并成大题。"],["经济重心南移的因果分析","","给出「国家根本，仰给东南」一类材料，要求概括原因（北人南迁、南方安定、自然条件）与表现（农业、手工业、商业），并落到「社会安定是经济发展的前提」这一规律认识。"],["制度与边疆管辖","","行省制度、宣政院、澎湖巡检司是「西藏、台湾自古以来是中国领土」的核心史实论据，多见于选择题与材料题第一问，要求「措施—机构—作用」一一对应。"],["科技成就与世界影响","","以印刷术、指南针、火药的外传为切口，考查「中国古代科技对世界文明的影响」，答题须写出传入路线（经阿拉伯人西传）与对欧洲的具体作用。"]]},{"type":"note","title":"跨学科视角","text":"地理：经济重心南移与气候、水运；科学：指南针、活字印刷与火药。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["精忠报国","岳飞背部刺有「尽忠报国」四字（后世演为「精忠报国」），表示竭诚报效国家。","《宋史·岳飞传》"],["莫须有","秦桧诬陷岳飞谋反，韩世忠质问证据，秦桧答「其事体莫须有」，后指凭空捏造的罪名。","《宋史·岳飞传》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"岳飞","v":"南宋抗金名将，率岳家军屡败金军，后被冤杀。 出处：《宋史·岳飞传》"},{"k":"完颜阿骨打","v":"金朝建立者，1115 年称帝。 出处：《金史·太祖本纪》"}]},{"type":"list","title":"延伸阅读","items":["郾城大捷：1140 年，岳飞率岳家军在郾城大破金军精锐「拐子马」「铁浮图」，进军至朱仙镇，中原震动。 出处：《宋史·岳飞传》","宋金议和：1141 年宋金议和：南宋向金称臣，每年纳贡银二十五万两、绢二十五万匹，以淮水—大散关为界。 出处：《宋史·高宗本纪》"]},{"type":"list","title":"本课拓展出处","items":["《宋史·岳飞传》《金史·太祖本纪》","2024 部编版七下第 10 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u2-q2","type":"choice","stem":"宋辽之间保持长时间的和平局面，开始于","answer":"B","explain":"1005 年宋辽订立澶渊之盟，北宋每年给辽岁币，此后很长时间里宋辽保持了和平局面，边境贸易发展。","options":["北宋建立","澶渊之盟的订立","靖康之变","宋金议和"],"tags":["澶渊之盟","时空观念"]},{"id":"h7b-u2-q3","type":"choice","stem":"世界上最早的纸币「交子」出现的时间和地区是","answer":"A","explain":"北宋前期，四川地区出现「交子」，这是世界上最早的纸币，反映了宋代商品经济的繁荣。","options":["北宋前期的四川地区","唐朝中期的江南地区","南宋时期的临安","元朝的大都"],"tags":["交子","宋代经济"]},{"id":"h7b-u2-q5","type":"choice","stem":"我国经济重心南移最后完成于","answer":"C","explain":"经济重心南移从唐朝中期开始，到南宋时最后完成，南方成为全国的经济重心，出现「苏湖熟，天下足」的局面。","options":["唐朝中期","北宋","南宋","元朝"],"tags":["经济重心南移","时空观念"]},{"id":"cat-7b-2-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 女真族首领完颜阿骨打建立金\n② 金灭北宋，赵构称帝建立南宋，后定都临安（今浙江杭…\n③ 岳飞率军抗金，取得郾城大捷；随后被害，宋金达成和…\n④ 铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗","answer":"A","explain":"按时间顺序应为：①女真族首领完颜阿骨打建立金（1115 年）→②金灭北宋，赵构称帝建立南宋，后定都临安（今浙江杭州）（1127 年）→③岳飞率军抗金，取得郾城大捷；随后被害，宋金达成和议（1140—1141 年）→④铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗（1206 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-3-g2","type":"choice","stem":"下列关于「金与南宋对峙」的表述，错误的是","answer":"A","explain":"认为经济重心南移完成于唐朝——「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。正确表述：经济重心南移**从唐朝中期开始，到南宋时最后完成**。","options":["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-3-g3","type":"choice","stem":"下列结论中，属于「金与南宋对峙」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1140 年，岳飞率岳家军在郾城大破金军精锐「拐子马」「铁浮图」，进军至朱仙镇，中原震动。（《宋史·岳飞传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"金与南宋对峙；辽、西夏、金与两宋的和战：1005 年宋辽订立澶渊之盟后长期和平；北宋与西夏议和；1141 年宋金议和，以淮河至大散关一线划界，南宋向金称臣、送岁币。","explain":"材料出自《宋史·岳飞传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-2-4","title":"第11课 元朝的建立与统一","subtitle":"七年级下册 · 第二单元 辽宋夏金元时期：民族关系发展和社会变化","grade":"7b","tags":["七年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第二单元 辽宋夏金元时期：民族关系发展和社会变化"},{"k":"课时","v":"第11课 元朝的建立与统一"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1206 年，铁木真统一蒙古各部，被推举为大汗，尊称成吉思汗。1271 年忽必烈定国号「元」，1279 年灭南宋，完成全国统一。元朝疆域空前辽阔，创立行省制度，设澎湖巡检司管辖台湾，设宣政院管辖西藏。"},{"type":"note","title":"本课主线 · 因果链","text":"北宋以「重文轻武」加强中央集权，与辽、西夏、金长期并立、和战交替；两宋时期经济重心南移完成，商品经济与海外贸易空前繁荣；蒙古崛起后元朝重建大一统，行省制与对西藏、台湾的管辖使统一多民族国家进一步发展，民族交融与宋元科技成就影响深远。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1206 年","铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗","蒙古先后灭西夏（1227 年）、灭金（1234 年），为元朝统一奠定基础"],["1271 年","忽必烈改国号为元，次年定都大都；1279 年完成全国统一","1276 年元军攻占临安，南宋灭亡；元朝是蒙古族建立的全国性统一王朝 · 重点"],["元朝","在地方推行行省制度，设宣政院管辖西藏、澎湖巡检司管辖澎湖和琉球（今台湾）","行省制是我国省级行政区划的开端；西藏正式成为中央直接管辖下的一个行政区域"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1206 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"铁木真统一蒙古草原，建立蒙古政权，被…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1271 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"忽必烈改国号为元，次年定都大都；12…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"元朝","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"在地方推行行省制度，设宣政院管辖西藏…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"元朝的统一与制度：1271 年忽必烈改国号为元，1279 年完成统一；在地方推行行省制度（我国省级行政区划的开端）；设宣政院管辖西藏，设澎湖巡检司管辖澎湖和琉球。","explain":"这一条是「西藏、台湾自古以来就是中国领土」的**史实支撑**，材料题第一问常直接考「元朝用什么机构管辖西藏／台湾」。"},{"level":"重点","text":"宋元时期的民族交融：汉族与契丹、党项、女真、蒙古等族杂居、通婚，相互学习生产技术与生活习俗；元朝时逐渐形成一个新的民族——回族（回回）。","explain":"答题术语：民族交融是**双向**的（少数民族汉化与汉族吸收少数民族习俗并存），元朝的统一为大规模民族交融提供了条件。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为行省制度始于唐朝或宋朝。","行省制度开始于元朝，是我国省级行政区划的开端。","「郡县制（秦）—行省制（元）」是两条必须分清的行政制度线索。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["民族关系与政权并立","近年中考高频","以政权并立形势图或和战材料切入，要求说明「民族交融是历史发展的主流」，常与第三单元「统一多民族国家的巩固」合并成大题。"],["经济重心南移的因果分析","","给出「国家根本，仰给东南」一类材料，要求概括原因（北人南迁、南方安定、自然条件）与表现（农业、手工业、商业），并落到「社会安定是经济发展的前提」这一规律认识。"],["制度与边疆管辖","","行省制度、宣政院、澎湖巡检司是「西藏、台湾自古以来是中国领土」的核心史实论据，多见于选择题与材料题第一问，要求「措施—机构—作用」一一对应。"],["科技成就与世界影响","","以印刷术、指南针、火药的外传为切口，考查「中国古代科技对世界文明的影响」，答题须写出传入路线（经阿拉伯人西传）与对欧洲的具体作用。"]]},{"type":"note","title":"跨学科视角","text":"地理：经济重心南移与气候、水运；科学：指南针、活字印刷与火药。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["只识弯弓射大雕","毛泽东《沁园春·雪》评成吉思汗「一代天骄，成吉思汗，只识弯弓射大雕」，兼有肯定与惋惜。","毛泽东《沁园春·雪》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"成吉思汗","v":"铁木真，1206 年统一蒙古，建立蒙古政权。 出处：《元史·太祖本纪》"},{"k":"忽必烈","v":"元世祖，1271 年定国号元，1279 年统一全国。 出处：《元史·世祖本纪》"}]},{"type":"list","title":"延伸阅读","items":["行省制度：元朝在中央设中书省，地方设行中书省（行省），作为最高行政机构，行省制度对后世地方行政区划影响深远。 出处：《元史·百官志》","对边疆的管辖：元朝设澎湖巡检司管辖澎湖和琉球（今台湾），设宣政院管理西藏事务，西藏正式成为中央直接管辖的地方行政区域。 出处：《元史·百官志》；2024 部编版七下第 11 课"]},{"type":"list","title":"本课拓展出处","items":["《元史·太祖本纪》《元史·世祖本纪》","2024 部编版七下第 11 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u2-q3","type":"choice","stem":"世界上最早的纸币「交子」出现的时间和地区是","answer":"A","explain":"北宋前期，四川地区出现「交子」，这是世界上最早的纸币，反映了宋代商品经济的繁荣。","options":["北宋前期的四川地区","唐朝中期的江南地区","南宋时期的临安","元朝的大都"],"tags":["交子","宋代经济"]},{"id":"h7b-u2-q4","type":"choice","stem":"元朝设置的管理西藏地区事务的机构是","answer":"B","explain":"元朝设宣政院管理西藏，西藏正式成为中央直接管辖下的一个行政区域；澎湖巡检司管辖澎湖和琉球（今台湾）；中书省是中央机构，行中书省是地方机构。","options":["澎湖巡检司","宣政院","中书省","行中书省"],"tags":["宣政院","边疆管辖"]},{"id":"h7b-u2-q5","type":"choice","stem":"我国经济重心南移最后完成于","answer":"C","explain":"经济重心南移从唐朝中期开始，到南宋时最后完成，南方成为全国的经济重心，出现「苏湖熟，天下足」的局面。","options":["唐朝中期","北宋","南宋","元朝"],"tags":["经济重心南移","时空观念"]},{"id":"h7b-u2-q6","type":"choice","stem":"元朝在地方推行的行省制度，其重要意义在于","answer":"A","explain":"元朝疆域辽阔，行省制度既加强了中央对地方的管理，又是我国省级行政区划的开端。行省是地方机构，与中央的中书省并不互相取代。","options":["开创了我国省级行政区划的先河，加强了中央对地方的管理","取代了中央的中书省","使地方获得了完全的自治权","废除了秦朝以来的郡县制"],"tags":["行省制度","制度创新"]},{"id":"cat-7b-2-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗\n② 忽必烈改国号为元，次年定都大都；1279 年完成…\n③ 在地方推行行省制度，设宣政院管辖西藏、澎湖巡检司…","answer":"A","explain":"按时间顺序应为：①铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗（1206 年）→②忽必烈改国号为元，次年定都大都；1279 年完成全国统一（1271 年）→③在地方推行行省制度，设宣政院管辖西藏、澎湖巡检司管辖澎湖和琉球（今台湾）（元朝）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-4-g2","type":"choice","stem":"下列关于「元朝的建立与统一」的表述，错误的是","answer":"A","explain":"认为行省制度始于唐朝或宋朝——「郡县制（秦）—行省制（元）」是两条必须分清的行政制度线索。正确表述：行省制度开始于元朝，是我国省级行政区划的开端。","options":["认为行省制度始于唐朝或宋朝。","行省制度开始于元朝，是我国省级行政区划的开端。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。","元朝的统一与制度：1271 年忽必烈改国号为元，1279 年完成统一；在地方推行行省制度（我国省级行政区划的开端）；设宣政院管辖西藏，设澎湖巡检司管辖澎湖和琉球。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-4-g3","type":"choice","stem":"下列结论中，属于「元朝的建立与统一」的是","answer":"A","explain":"本课结论：元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：元朝在中央设中书省，地方设行中书省（行省），作为最高行政机构，行省制度对后世地方行政区划影响深远。（《元史·百官志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"元朝的建立与统一；元朝的统一与制度：1271 年忽必烈改国号为元，1279 年完成统一；在地方推行行省制度（我国省级行政区划的开端）；设宣政院管辖西藏，设澎湖巡检司管辖澎湖和琉球。","explain":"材料出自《元史·百官志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-2-5","title":"第12课 辽宋夏金元时期经济的繁荣","subtitle":"七年级下册 · 第二单元 辽宋夏金元时期：民族关系发展和社会变化","grade":"7b","tags":["七年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第二单元 辽宋夏金元时期：民族关系发展和社会变化"},{"k":"课时","v":"第12课 辽宋夏金元时期经济的繁荣"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"辽宋夏金元时期，南方经济持续发展，到南宋时经济重心南移完成。农业上推广占城稻、茶桑；手工业上景德镇成为瓷都，造船业发达；商业上出现世界最早的纸币「交子」，海外贸易兴盛，设市舶司管理。"},{"type":"note","title":"本课主线 · 因果链","text":"北宋以「重文轻武」加强中央集权，与辽、西夏、金长期并立、和战交替；两宋时期经济重心南移完成，商品经济与海外贸易空前繁荣；蒙古崛起后元朝重建大一统，行省制与对西藏、台湾的管辖使统一多民族国家进一步发展，民族交融与宋元科技成就影响深远。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1271 年","忽必烈改国号为元，次年定都大都；1279 年完成全国统一","1276 年元军攻占临安，南宋灭亡；元朝是蒙古族建立的全国性统一王朝 · 重点"],["南宋时","经济重心南移完成","谚语「苏湖熟，天下足」；南方成为全国最重要的粮仓与财赋来源地 · 重点"],["北宋前期","四川地区出现「交子」","这是世界上最早的纸币；南宋时纸币与铜钱并行流通"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1271 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"忽必烈改国号为元，次年定都大都；12…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"南宋时","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"经济重心南移完成","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"北宋前期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"四川地区出现「交子」","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"经济重心南移的完成：从唐朝中期开始的经济重心南移，到南宋时最后完成。原因是北方战乱、人口南迁带来劳动力与先进技术，南方自然条件优越、社会相对安定，统治者重视生产。","explain":"表现要会举例：农业（「苏湖熟，天下足」、水稻产量居首、茶树与棉花种植推广）、手工业（景德镇瓷器、南方造船业）、商业与海外贸易。"},{"level":"重点","text":"宋代商业与海外贸易：城市商业打破了「坊」「市」的界限，出现早市、夜市和乡村草市；北宋前期四川出现世界上最早的纸币「交子」；政府在广州、泉州等地设市舶司管理海外贸易。","explain":"「交子的时间与地点」（北宋前期、四川）与「市舶司的职能」是选择题高频点，常与唐朝长安的坊市制度对比。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。"],["把「交子」说成唐朝或南宋出现。","交子出现于北宋前期的四川地区，是世界上最早的纸币。","时间（北宋前期）与地点（四川）都爱设陷阱，选项常用「南宋」「临安」来干扰。"]]},{"type":"table","title":"宋朝城市与中世纪西欧城市（11—13 世纪）（中外对比：城市功能与市民阶层的不同走向）","head":["比较项","宋朝城市（东京、临安）","中世纪西欧城市"],"rows":[["城市功能","政治、经济、文化中心，坊市界限被打破，商业气息浓厚","多由工商业者聚集形成，规模较小"],["商业活动","早市、夜市、草市兴盛，出现纸币「交子」","以定期集市为主，货币经济发展较慢"],["市民文化","瓦子、勾栏、宋词、话本，市民生活丰富","市民争取城市自治，孕育了资产阶级的前身"],["共同点","都出现了商业繁荣与市民文化的发展","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["民族关系与政权并立","近年中考高频","以政权并立形势图或和战材料切入，要求说明「民族交融是历史发展的主流」，常与第三单元「统一多民族国家的巩固」合并成大题。"],["经济重心南移的因果分析","","给出「国家根本，仰给东南」一类材料，要求概括原因（北人南迁、南方安定、自然条件）与表现（农业、手工业、商业），并落到「社会安定是经济发展的前提」这一规律认识。"],["制度与边疆管辖","","行省制度、宣政院、澎湖巡检司是「西藏、台湾自古以来是中国领土」的核心史实论据，多见于选择题与材料题第一问，要求「措施—机构—作用」一一对应。"],["科技成就与世界影响","","以印刷术、指南针、火药的外传为切口，考查「中国古代科技对世界文明的影响」，答题须写出传入路线（经阿拉伯人西传）与对欧洲的具体作用。"]]},{"type":"note","title":"跨学科视角","text":"地理：经济重心南移与气候、水运；科学：指南针、活字印刷与火药。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["苏湖熟，天下足","南宋谚语，意为苏州、湖州丰收，天下粮食就充足，反映经济重心南移。","高斯得《耻堂存稿》卷五"]]},{"type":"list","title":"延伸阅读","items":["交子：北宋前期，四川地区出现「交子」，是世界上最早的纸币；南宋发行「会子」。 出处：《宋史·食货志》","市舶司：宋朝在广州、泉州、明州等地设市舶司管理海外贸易，征收关税，南宋外贸收入占财政重要比重。 出处：《宋史·职官志》"]},{"type":"list","title":"本课拓展出处","items":["《宋史·食货志》《元史·食货志》","2024 部编版七下第 12 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u2-q3","type":"choice","stem":"世界上最早的纸币「交子」出现的时间和地区是","answer":"A","explain":"北宋前期，四川地区出现「交子」，这是世界上最早的纸币，反映了宋代商品经济的繁荣。","options":["北宋前期的四川地区","唐朝中期的江南地区","南宋时期的临安","元朝的大都"],"tags":["交子","宋代经济"]},{"id":"h7b-u2-q5","type":"choice","stem":"我国经济重心南移最后完成于","answer":"C","explain":"经济重心南移从唐朝中期开始，到南宋时最后完成，南方成为全国的经济重心，出现「苏湖熟，天下足」的局面。","options":["唐朝中期","北宋","南宋","元朝"],"tags":["经济重心南移","时空观念"]},{"id":"cat-7b-2-5-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 忽必烈改国号为元，次年定都大都；1279 年完成…\n② 经济重心南移完成\n③ 四川地区出现「交子」","answer":"A","explain":"按时间顺序应为：①忽必烈改国号为元，次年定都大都；1279 年完成全国统一（1271 年）→②经济重心南移完成（南宋时）→③四川地区出现「交子」（北宋前期）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-5-g2","type":"choice","stem":"下列关于「辽宋夏金元时期经济的繁荣」的表述，错误的是","answer":"A","explain":"认为经济重心南移完成于唐朝——「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。正确表述：经济重心南移**从唐朝中期开始，到南宋时最后完成**。","options":["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-5-g3","type":"choice","stem":"下列结论中，属于「辽宋夏金元时期经济的繁荣」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-5-g4","type":"short","stem":"阅读材料，回答问题。\n材料：北宋前期，四川地区出现「交子」，是世界上最早的纸币；南宋发行「会子」。（《宋史·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"辽宋夏金元时期经济的繁荣；经济重心南移的完成：从唐朝中期开始的经济重心南移，到南宋时最后完成。原因是北方战乱、人口南迁带来劳动力与先进技术，南方自然条件优越、社会相对安定，统治者重视生产。","explain":"材料出自《宋史·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-2-6","title":"第13课 辽宋夏金元时期的对外交流","subtitle":"七年级下册 · 第二单元 辽宋夏金元时期：民族关系发展和社会变化","grade":"7b","tags":["七年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第二单元 辽宋夏金元时期：民族关系发展和社会变化"},{"k":"课时","v":"第13课 辽宋夏金元时期的对外交流"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"宋元时期，陆上丝绸之路和海上丝绸之路都很繁荣。元朝时泉州是当时世界最大的港口之一，马可·波罗来华，在《马可·波罗行纪》中记述了中国的富庶。"},{"type":"note","title":"本课主线 · 因果链","text":"北宋以「重文轻武」加强中央集权，与辽、西夏、金长期并立、和战交替；两宋时期经济重心南移完成，商品经济与海外贸易空前繁荣；蒙古崛起后元朝重建大一统，行省制与对西藏、台湾的管辖使统一多民族国家进一步发展，民族交融与宋元科技成就影响深远。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["960 年","赵匡胤建立北宋，定都东京（今河南开封）","赵匡胤即宋太祖；他「杯酒释兵权」，解除禁军将领的兵权，推行重文轻武政策 · 重点"],["1005 年","宋辽订立「澶渊之盟」","北宋每年给辽岁币，此后宋辽保持了长时间的和平局面，边境贸易（榷场）发展 · 重点"],["1038 年","党项族首领元昊称帝，建立西夏","西夏与北宋多次交战，后来议和并保持交往"],["1069 年","宋神宗任用王安石主持变法","推行募役法、方田均税法、保甲法、农田水利法等，目的是富国强兵"],["1115 年","女真族首领完颜阿骨打建立金","1125 年金灭辽；1127 年金灭北宋，史称「靖康之变」"],["1127 年","金灭北宋，赵构称帝建立南宋，后定都临安（今浙江杭州）","赵构即宋高宗；北宋灭亡与南宋建立发生在同一年 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"960 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"赵匡胤建立北宋，定都东京（今河南开封…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"1005 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"宋辽订立「澶渊之盟」","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1038 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"党项族首领元昊称帝，建立西夏","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"1069 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"宋神宗任用王安石主持变法","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"1115 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"女真族首领完颜阿骨打建立金","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1127 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"金灭北宋，赵构称帝建立南宋，后定都临…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"经济重心南移的完成：从唐朝中期开始的经济重心南移，到南宋时最后完成。原因是北方战乱、人口南迁带来劳动力与先进技术，南方自然条件优越、社会相对安定，统治者重视生产。","explain":"表现要会举例：农业（「苏湖熟，天下足」、水稻产量居首、茶树与棉花种植推广）、手工业（景德镇瓷器、南方造船业）、商业与海外贸易。"},{"level":"重点","text":"宋代商业与海外贸易：城市商业打破了「坊」「市」的界限，出现早市、夜市和乡村草市；北宋前期四川出现世界上最早的纸币「交子」；政府在广州、泉州等地设市舶司管理海外贸易。","explain":"「交子的时间与地点」（北宋前期、四川）与「市舶司的职能」是选择题高频点，常与唐朝长安的坊市制度对比。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。"],["把「交子」说成唐朝或南宋出现。","交子出现于北宋前期的四川地区，是世界上最早的纸币。","时间（北宋前期）与地点（四川）都爱设陷阱，选项常用「南宋」「临安」来干扰。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["民族关系与政权并立","近年中考高频","以政权并立形势图或和战材料切入，要求说明「民族交融是历史发展的主流」，常与第三单元「统一多民族国家的巩固」合并成大题。"],["经济重心南移的因果分析","","给出「国家根本，仰给东南」一类材料，要求概括原因（北人南迁、南方安定、自然条件）与表现（农业、手工业、商业），并落到「社会安定是经济发展的前提」这一规律认识。"],["制度与边疆管辖","","行省制度、宣政院、澎湖巡检司是「西藏、台湾自古以来是中国领土」的核心史实论据，多见于选择题与材料题第一问，要求「措施—机构—作用」一一对应。"],["科技成就与世界影响","","以印刷术、指南针、火药的外传为切口，考查「中国古代科技对世界文明的影响」，答题须写出传入路线（经阿拉伯人西传）与对欧洲的具体作用。"]]},{"type":"note","title":"跨学科视角","text":"地理：经济重心南移与气候、水运；科学：指南针、活字印刷与火药。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"马可·波罗","v":"意大利旅行家，元代来华，著《马可·波罗行纪》。 出处：《马可·波罗行纪》"}]},{"type":"list","title":"延伸阅读","items":["马可·波罗来华：意大利旅行家马可·波罗约 1275 年到达元朝大都，在中国游历十七年，回国后口述成《马可·波罗行纪》，激起欧洲人对东方的向往。 出处：《马可·波罗行纪》","泉州港：元朝泉州港「涨海声中万国商」，与埃及亚历山大港并称世界大港，遗址现存清净寺、伊斯兰教圣墓等。 出处：2024 部编版七下第 13 课；泉州海外交通史博物馆"]},{"type":"list","title":"本课拓展出处","items":["《马可·波罗行纪》；《元史》","2024 部编版七下第 13 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u2-q1","type":"choice","stem":"宋太祖「杯酒释兵权」，并推行重文轻武的政策，其主要目的是","answer":"B","explain":"宋太祖吸取唐末以来武将专权、藩镇割据的教训，通过解除禁军将领兵权、重用文臣等办法防止武将专权，加强中央集权。其结果是军队战斗力有所削弱、财政负担加重。","options":["提高军队的战斗力","防止武将专权，加强中央集权","减轻农民的赋税负担","增加国家的财政收入"],"tags":["重文轻武","中央集权"]},{"id":"h7b-u2-q2","type":"choice","stem":"宋辽之间保持长时间的和平局面，开始于","answer":"B","explain":"1005 年宋辽订立澶渊之盟，北宋每年给辽岁币，此后很长时间里宋辽保持了和平局面，边境贸易发展。","options":["北宋建立","澶渊之盟的订立","靖康之变","宋金议和"],"tags":["澶渊之盟","时空观念"]},{"id":"h7b-u2-q3","type":"choice","stem":"世界上最早的纸币「交子」出现的时间和地区是","answer":"A","explain":"北宋前期，四川地区出现「交子」，这是世界上最早的纸币，反映了宋代商品经济的繁荣。","options":["北宋前期的四川地区","唐朝中期的江南地区","南宋时期的临安","元朝的大都"],"tags":["交子","宋代经济"]},{"id":"cat-7b-2-6-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 赵匡胤建立北宋，定都东京（今河南开封）\n② 宋辽订立「澶渊之盟」\n③ 党项族首领元昊称帝，建立西夏\n④ 宋神宗任用王安石主持变法","answer":"A","explain":"按时间顺序应为：①赵匡胤建立北宋，定都东京（今河南开封）（960 年）→②宋辽订立「澶渊之盟」（1005 年）→③党项族首领元昊称帝，建立西夏（1038 年）→④宋神宗任用王安石主持变法（1069 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-6-g2","type":"choice","stem":"下列关于「辽宋夏金元时期的对外交流」的表述，错误的是","answer":"A","explain":"认为经济重心南移完成于唐朝——「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。正确表述：经济重心南移**从唐朝中期开始，到南宋时最后完成**。","options":["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-6-g3","type":"choice","stem":"下列结论中，属于「辽宋夏金元时期的对外交流」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-6-g4","type":"short","stem":"阅读材料，回答问题。\n材料：意大利旅行家马可·波罗约 1275 年到达元朝大都，在中国游历十七年，回国后口述成《马可·波罗行纪》，激起欧洲人对东方的向往。（《马可·波罗行纪》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"辽宋夏金元时期的对外交流；经济重心南移的完成：从唐朝中期开始的经济重心南移，到南宋时最后完成。原因是北方战乱、人口南迁带来劳动力与先进技术，南方自然条件优越、社会相对安定，统治者重视生产。","explain":"材料出自《马可·波罗行纪》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-2-7","title":"第14课 辽宋夏金元时期的科技与文化","subtitle":"七年级下册 · 第二单元 辽宋夏金元时期：民族关系发展和社会变化","grade":"7b","tags":["七年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第二单元 辽宋夏金元时期：民族关系发展和社会变化"},{"k":"课时","v":"第14课 辽宋夏金元时期的科技与文化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"宋元时期科技文化高度发达。北宋毕昇发明活字印刷术，指南针应用于航海，火药广泛用于军事；宋词、元曲兴盛；司马光编《资治通鉴》，是我国第一部编年体通史。"},{"type":"note","title":"本课主线 · 因果链","text":"北宋以「重文轻武」加强中央集权，与辽、西夏、金长期并立、和战交替；两宋时期经济重心南移完成，商品经济与海外贸易空前繁荣；蒙古崛起后元朝重建大一统，行省制与对西藏、台湾的管辖使统一多民族国家进一步发展，民族交融与宋元科技成就影响深远。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["960 年","赵匡胤建立北宋，定都东京（今河南开封）","赵匡胤即宋太祖；他「杯酒释兵权」，解除禁军将领的兵权，推行重文轻武政策 · 重点"],["1005 年","宋辽订立「澶渊之盟」","北宋每年给辽岁币，此后宋辽保持了长时间的和平局面，边境贸易（榷场）发展 · 重点"],["1038 年","党项族首领元昊称帝，建立西夏","西夏与北宋多次交战，后来议和并保持交往"],["1069 年","宋神宗任用王安石主持变法","推行募役法、方田均税法、保甲法、农田水利法等，目的是富国强兵"],["1115 年","女真族首领完颜阿骨打建立金","1125 年金灭辽；1127 年金灭北宋，史称「靖康之变」"],["1127 年","金灭北宋，赵构称帝建立南宋，后定都临安（今浙江杭州）","赵构即宋高宗；北宋灭亡与南宋建立发生在同一年 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"960 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"赵匡胤建立北宋，定都东京（今河南开封…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"1005 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"宋辽订立「澶渊之盟」","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1038 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"党项族首领元昊称帝，建立西夏","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"1069 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"宋神宗任用王安石主持变法","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"1115 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"女真族首领完颜阿骨打建立金","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1127 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"金灭北宋，赵构称帝建立南宋，后定都临…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"宋元科技成就：北宋匠人毕昇发明活字印刷术，指南针（罗盘）应用于航海，火药在宋元时期广泛用于军事；三大发明由阿拉伯人传入欧洲，推动了欧洲社会的变革。","explain":"「发明—应用—外传—影响」四步要写全：印刷术促进文化传播，指南针为地理大发现提供条件，火药推动欧洲火器发展与封建制度的崩溃。"},{"level":"次重点","text":"元代天文学家郭守敬编制《授时历》，主持全国范围的天文测量；宋代沈括的《梦溪笔谈》记载了活字印刷术。","explain":""},{"level":"次重点","text":"宋词与市民文化：苏轼、李清照、辛弃疾是宋词的代表人物；城市中出现了娱乐兼营商业的场所「瓦子」，里面有「勾栏」演出，市民文化生活丰富多彩。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。"],["把「交子」说成唐朝或南宋出现。","交子出现于北宋前期的四川地区，是世界上最早的纸币。","时间（北宋前期）与地点（四川）都爱设陷阱，选项常用「南宋」「临安」来干扰。"]]},{"type":"table","title":"宋朝城市与中世纪西欧城市（11—13 世纪）（中外对比：城市功能与市民阶层的不同走向）","head":["比较项","宋朝城市（东京、临安）","中世纪西欧城市"],"rows":[["城市功能","政治、经济、文化中心，坊市界限被打破，商业气息浓厚","多由工商业者聚集形成，规模较小"],["商业活动","早市、夜市、草市兴盛，出现纸币「交子」","以定期集市为主，货币经济发展较慢"],["市民文化","瓦子、勾栏、宋词、话本，市民生活丰富","市民争取城市自治，孕育了资产阶级的前身"],["共同点","都出现了商业繁荣与市民文化的发展","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["民族关系与政权并立","近年中考高频","以政权并立形势图或和战材料切入，要求说明「民族交融是历史发展的主流」，常与第三单元「统一多民族国家的巩固」合并成大题。"],["经济重心南移的因果分析","","给出「国家根本，仰给东南」一类材料，要求概括原因（北人南迁、南方安定、自然条件）与表现（农业、手工业、商业），并落到「社会安定是经济发展的前提」这一规律认识。"],["制度与边疆管辖","","行省制度、宣政院、澎湖巡检司是「西藏、台湾自古以来是中国领土」的核心史实论据，多见于选择题与材料题第一问，要求「措施—机构—作用」一一对应。"],["科技成就与世界影响","","以印刷术、指南针、火药的外传为切口，考查「中国古代科技对世界文明的影响」，答题须写出传入路线（经阿拉伯人西传）与对欧洲的具体作用。"]]},{"type":"note","title":"跨学科视角","text":"地理：经济重心南移与气候、水运；科学：指南针、活字印刷与火药。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"毕昇","v":"北宋发明家，发明活字印刷术。 出处：沈括《梦溪笔谈》卷十八"},{"k":"司马光","v":"北宋史学家，主编《资治通鉴》。 出处：《宋史·司马光传》"},{"k":"关汉卿","v":"元曲代表作家，著《窦娥冤》。 出处：《录鬼簿》"}]},{"type":"list","title":"延伸阅读","items":["活字印刷术：北宋庆历年间，毕昇用胶泥刻字，每字一印，火烧令坚，排版印刷，比雕版印刷更省时省料。沈括在《梦溪笔谈》中详细记录了这一工艺。 出处：沈括《梦溪笔谈》卷十八","《资治通鉴》：司马光主持编纂，记载从战国到五代共 1362 年历史，共 294 卷，宋神宗赐名「鉴于往事，有资于治道」。 出处：《宋史·司马光传》"]},{"type":"list","title":"本课拓展出处","items":["沈括《梦溪笔谈》；《宋史·司马光传》","2024 部编版七下第 14 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u2-q1","type":"choice","stem":"宋太祖「杯酒释兵权」，并推行重文轻武的政策，其主要目的是","answer":"B","explain":"宋太祖吸取唐末以来武将专权、藩镇割据的教训，通过解除禁军将领兵权、重用文臣等办法防止武将专权，加强中央集权。其结果是军队战斗力有所削弱、财政负担加重。","options":["提高军队的战斗力","防止武将专权，加强中央集权","减轻农民的赋税负担","增加国家的财政收入"],"tags":["重文轻武","中央集权"]},{"id":"h7b-u2-q2","type":"choice","stem":"宋辽之间保持长时间的和平局面，开始于","answer":"B","explain":"1005 年宋辽订立澶渊之盟，北宋每年给辽岁币，此后很长时间里宋辽保持了和平局面，边境贸易发展。","options":["北宋建立","澶渊之盟的订立","靖康之变","宋金议和"],"tags":["澶渊之盟","时空观念"]},{"id":"h7b-u2-q3","type":"choice","stem":"世界上最早的纸币「交子」出现的时间和地区是","answer":"A","explain":"北宋前期，四川地区出现「交子」，这是世界上最早的纸币，反映了宋代商品经济的繁荣。","options":["北宋前期的四川地区","唐朝中期的江南地区","南宋时期的临安","元朝的大都"],"tags":["交子","宋代经济"]},{"id":"cat-7b-2-7-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 赵匡胤建立北宋，定都东京（今河南开封）\n② 宋辽订立「澶渊之盟」\n③ 党项族首领元昊称帝，建立西夏\n④ 宋神宗任用王安石主持变法","answer":"A","explain":"按时间顺序应为：①赵匡胤建立北宋，定都东京（今河南开封）（960 年）→②宋辽订立「澶渊之盟」（1005 年）→③党项族首领元昊称帝，建立西夏（1038 年）→④宋神宗任用王安石主持变法（1069 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-7-g2","type":"choice","stem":"下列关于「辽宋夏金元时期的科技与文化」的表述，错误的是","answer":"A","explain":"认为经济重心南移完成于唐朝——「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。正确表述：经济重心南移**从唐朝中期开始，到南宋时最后完成**。","options":["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-7-g3","type":"choice","stem":"下列结论中，属于「辽宋夏金元时期的科技与文化」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-7-g4","type":"short","stem":"阅读材料，回答问题。\n材料：北宋庆历年间，毕昇用胶泥刻字，每字一印，火烧令坚，排版印刷，比雕版印刷更省时省料。沈括在《梦溪笔谈》中详细记录了这一工艺。（沈括《梦溪笔谈》卷十八）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"辽宋夏金元时期的科技与文化；宋元科技成就：北宋匠人毕昇发明活字印刷术，指南针（罗盘）应用于航海，火药在宋元时期广泛用于军事；三大发明由阿拉伯人传入欧洲，推动了欧洲社会的变革。","explain":"材料出自沈括《梦溪笔谈》卷十八。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-3-1","title":"第15课 明朝的统治","subtitle":"七年级下册 · 第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展","grade":"7b","tags":["七年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展"},{"k":"课时","v":"第15课 明朝的统治"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1368 年朱元璋建立明朝，定都应天府。明太祖废除丞相制度，权分六部，设锦衣卫；明成祖设东厂，特务机构强化。科举考试采用八股取士，束缚思想。"},{"type":"note","title":"本课主线 · 因果链","text":"明朝废除丞相、设三司与厂卫并以八股取士，把君主专制推向新的高度；明清两朝通过收复台湾、设置台湾府、册封达赖班禅并设驻藏大臣、平定准噶尔与大小和卓叛乱并设伊犁将军，巩固和发展了统一多民族国家；但对外由郑和下西洋、戚继光抗倭走向闭关锁国，只留广州一处通商并由十三行经营，使中国逐渐落后于世界潮流。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1368 年","朱元璋建立明朝，定都应天府（今江苏南京）","朱元璋即明太祖；同年明军攻占大都，元朝在全国的统治结束 · 重点"],["明太祖、明成祖时","强化皇权：中央废丞相、权分六部，地方废行省、设三司；设锦衣卫、东厂等特务机构","地方设布政使司、按察使司、都指挥使司，合称「三司」；同时实行八股取士"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1368 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"朱元璋建立明朝，定都应天府（今江苏南…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"明太祖、明成祖时","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"强化皇权：中央废丞相、权分六部，地方…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"明朝强化皇权：中央废除丞相和中书省，权力分给六部；地方废除行省，设立三司；设锦衣卫、东厂等特务机构；实行八股取士。","explain":"影响要一分为二：君主专制空前加强、有利于巩固统治；但官僚机构臃肿、思想被禁锢，社会逐渐失去活力。注意与元朝行省制、清朝总督巡抚的比较。"},{"level":"重点","text":"八股取士：考试题目必须来自「四书」「五经」，答卷必须写成八股文，不许考生自由发挥。","explain":"必答影响：束缚了人们的思想，不利于选贤任能，也阻碍了科学技术与文化的创新。与科举制「创立于隋、完善于唐、僵化于明清」连起来记。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。"],["把台湾府的设置时间说成 1662 年。","1662 年郑成功收复台湾；1684 年清朝设置台湾府，隶属福建省。","「收复」与「设府」的年份最容易混，而这两个年份都是高频考点，必须分别记牢。"]]},{"type":"table","title":"明朝与清朝强化君主专制的措施（跨条目对比（同一册内两个王朝的政治制度））","head":["比较项","明朝","清朝"],"rows":[["中央机构","废除丞相和中书省，权分六部","沿用内阁与六部，雍正帝时设军机处"],["地方制度","废除行省，设立三司","设总督、巡抚管理地方"],["监察与特务","设锦衣卫、东厂等特务机构","设厂卫，并大兴文字狱"],["思想控制","八股取士","八股取士，大兴文字狱"],["共同实质","都是为了加强君主专制、巩固统治","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["边疆管辖与统一多民族国家","近年中考高频","台湾、西藏、新疆三地的史实是「这些地区自古以来是中国领土」的核心论据，常以「措施—机构—作用」配对或材料题形式考查，务必按地区分条作答。"],["对外关系的变化","","从郑和下西洋、戚继光抗倭到闭关锁国、只留广州通商，要求概括「由开放走向封闭」的趋势及其后果，常与同期世界史的新航路开辟对比。"],["君主专制的强化及其评价","","以废丞相、设三司与厂卫、设军机处、八股取士、大兴文字狱的材料设问，要求说明「君主专制不断强化」并作出评价（积极：巩固统一与社会安定；消极：禁锢思想、阻碍社会进步）。"],["科技文化巨著","","《本草纲目》《天工开物》《农政全书》常以「著作—作者—领域」配对选择题出现，也常考「明清科技以总结为主、缺乏创新」这一特点。"]]},{"type":"note","title":"跨学科视角","text":"地理：明清疆域与边疆治理；语文：明清小说与四大名著。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["八股文","明清科举规定的程式化文体，束缚思想，后比喻空洞僵化的文章。","《明史·选举志》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"明太祖","v":"朱元璋，明朝建立者，废除丞相、加强皇权。 出处：《明史·太祖本纪》"}]},{"type":"list","title":"延伸阅读","items":["废除丞相：1380 年，明太祖借胡惟庸案废除中书省和丞相，由六部直接对皇帝负责，君主专制空前加强。 出处：《明史·太祖本纪》","八股取士：考试只能在四书五经中命题，答卷须用八股文，分破题、承题、起讲、入手、起股、中股、后股、束股八部分，不能自由发挥。 出处：《明史·选举志》"]},{"type":"list","title":"本课拓展出处","items":["《明史·太祖本纪》《明史·选举志》","2024 部编版七下第 15 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u3-q6","type":"choice","stem":"清朝雍正帝设立、使君主专制进一步强化的机构是","answer":"C","explain":"雍正帝时设立军机处，军机大臣只是跪受笔录、传达皇帝的旨意，君主专制进一步强化。锦衣卫、东厂是明朝的特务机构。","options":["中书省","内阁","军机处","锦衣卫"],"tags":["军机处","君主专制"]},{"id":"cat-7b-3-1-g2","type":"choice","stem":"下列关于「明朝的统治」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","明朝强化皇权：中央废除丞相和中书省，权力分给六部；地方废除行省，设立三司；设锦衣卫、东厂等特务机构；实行八股取士。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-1-g3","type":"choice","stem":"下列结论中，属于「明朝的统治」的是","answer":"A","explain":"本课结论：明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1380 年，明太祖借胡惟庸案废除中书省和丞相，由六部直接对皇帝负责，君主专制空前加强。（《明史·太祖本纪》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"明朝的统治；明朝强化皇权：中央废除丞相和中书省，权力分给六部；地方废除行省，设立三司；设锦衣卫、东厂等特务机构；实行八股取士。","explain":"材料出自《明史·太祖本纪》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-3-1-g5","type":"choice","stem":"「朱元璋建立明朝，定都应天府（今江苏南京）」发生于","answer":"A","explain":"本课时间轴：朱元璋建立明朝，定都应天府（今江苏南京）（1368 年）。朱元璋即明太祖；同年明军攻占大都，元朝在全国的统治结束。其余三个时间是同一单元相邻课时的事件时间。","options":["1368 年","16 世纪中期","1553 年","1616 年"],"difficulty":1,"tags":["七年级下册","第三单元","本课练习"]}]},{"id":"cat-7b-3-2","title":"第16课 明朝的对外关系","subtitle":"七年级下册 · 第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展","grade":"7b","tags":["七年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展"},{"k":"课时","v":"第16课 明朝的对外关系"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"明朝前期国力强盛，1405—1433 年郑和七次下西洋，最远到达非洲东海岸和红海沿岸。明朝中后期，倭寇侵扰东南沿海，戚继光率军抗倭。1553 年，葡萄牙人租占澳门。"},{"type":"note","title":"本课主线 · 因果链","text":"明朝废除丞相、设三司与厂卫并以八股取士，把君主专制推向新的高度；明清两朝通过收复台湾、设置台湾府、册封达赖班禅并设驻藏大臣、平定准噶尔与大小和卓叛乱并设伊犁将军，巩固和发展了统一多民族国家；但对外由郑和下西洋、戚继光抗倭走向闭关锁国，只留广州一处通商并由十三行经营，使中国逐渐落后于世界潮流。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["16 世纪中期","戚继光率「戚家军」抗倭，东南沿海的倭患基本平息","戚继光先后在台州、福建、广东大败倭寇，是我国历史上的民族英雄"],["1553 年","葡萄牙人攫取在澳门的居住权","这是明朝中后期来自海上的外来侵扰之一，说明中国已面临早期殖民者的威胁"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 郑和下西洋：七次远航","caption":"示意图：郑和下西洋：七次远航，详见下方「历史现场」","view":"wide","alt":"示意图：郑和下西洋：七次远航，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1405 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"郑和率船队从刘家港出发，经南海、印度…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"1407—1421 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"第二至第六次远航，到达爪哇、苏门答腊…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"1431 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"第七次远航，船队规模最大，分舟前往忽…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1433 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"郑和病逝于归途中，远航结束","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"郑和下西洋（1405—1433 年，共七次）：目的是提高明朝在国外的地位和威望、加强与海外各国的联系，最远到达非洲东海岸和红海沿岸。","explain":"意义与局限都要写：是世界航海史上的空前壮举，增进了中国与亚非国家的友好往来；但不计经济效益、给明朝造成巨大财政负担，因而未能持续。"},{"level":"次重点","text":"戚继光抗倭与葡萄牙人攫取澳门居住权：明朝中后期，东南沿海遭受倭寇侵扰，1553 年葡萄牙人攫取在澳门的居住权。","explain":"说明明朝已同时面临「海上倭患」与「西方殖民者东来」两种威胁，与清朝闭关锁国的背景相衔接。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。"]]},{"type":"table","title":"郑和下西洋与新航路开辟（中外对比：两种航海的动机与结果）","head":["比较项","郑和下西洋（1405—1433 年，中国）","新航路开辟（15 世纪末—16 世纪，欧洲）"],"rows":[["目的","宣扬国威，加强与海外各国的联系","寻找黄金与通往东方的新商路，开拓殖民地、掠夺财富"],["方式","和平友好交往，「厚往薄来」","伴随武力征服与殖民掠夺"],["规模与时间","船队规模大、时间早、次数多（七次）","船只少、时间晚"],["结果","不计经济效益，给明朝带来巨大财政负担，未能持续","为欧洲带来巨额财富，促进了资本主义的发展"],["共同影响","都加强了世界各地的联系，都是世界航海史上的壮举","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["边疆管辖与统一多民族国家","近年中考高频","台湾、西藏、新疆三地的史实是「这些地区自古以来是中国领土」的核心论据，常以「措施—机构—作用」配对或材料题形式考查，务必按地区分条作答。"],["对外关系的变化","","从郑和下西洋、戚继光抗倭到闭关锁国、只留广州通商，要求概括「由开放走向封闭」的趋势及其后果，常与同期世界史的新航路开辟对比。"],["君主专制的强化及其评价","","以废丞相、设三司与厂卫、设军机处、八股取士、大兴文字狱的材料设问，要求说明「君主专制不断强化」并作出评价（积极：巩固统一与社会安定；消极：禁锢思想、阻碍社会进步）。"],["科技文化巨著","","《本草纲目》《天工开物》《农政全书》常以「著作—作者—领域」配对选择题出现，也常考「明清科技以总结为主、缺乏创新」这一特点。"]]},{"type":"note","title":"跨学科视角","text":"地理：明清疆域与边疆治理；语文：明清小说与四大名著。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 郑和下西洋：七次远航","head":["时间","经过"],"rows":[["1405 年","郑和率船队从刘家港出发，经南海、印度洋到达古里等地"],["1407—1421 年","第二至第六次远航，到达爪哇、苏门答腊、锡兰、阿拉伯半岛、非洲东海岸"],["1431 年","第七次远航，船队规模最大，分舟前往忽鲁谟斯、天方等地"],["1433 年","郑和病逝于归途中，远航结束"]]},{"type":"note","title":"现场解说","text":"郑和下西洋以政治目的为主，「厚往薄来」，未带来持续经济利益，后因国力下降而停止。"},{"type":"kv","title":"人物卡片","items":[{"k":"郑和","v":"明代航海家，七次下西洋。 出处：《明史·郑和传》"},{"k":"戚继光","v":"明代抗倭名将，组建戚家军。 出处：《明史·戚继光传》"}]},{"type":"list","title":"延伸阅读","items":["郑和下西洋：郑和船队最多时有两百余艘船、两万七千余人，比欧洲航海家远航早半个多世纪，是中国古代规模最大的远洋航行。 出处：《明史·郑和传》","戚继光抗倭：戚继光组建「戚家军」，在台州九战九捷，后转战福建、广东，基本解除东南倭患。 出处：《明史·戚继光传》"]},{"type":"list","title":"本课拓展出处","items":["《明史·郑和传》《明史·戚继光传》","2024 部编版七下第 16 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u3-q2","type":"choice","stem":"郑和下西洋最远到达的地区是","answer":"B","explain":"1405—1433 年郑和七次下西洋，到达亚非三十多个国家和地区，最远到达非洲东海岸和红海沿岸，是世界航海史上的空前壮举。","options":["印度半岛南端","非洲东海岸和红海沿岸","波斯湾沿岸","美洲西海岸"],"tags":["郑和下西洋","时空观念"]},{"id":"cat-7b-3-2-g2","type":"choice","stem":"下列关于「明朝的对外关系」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-2-g3","type":"choice","stem":"下列结论中，属于「明朝的对外关系」的是","answer":"A","explain":"本课结论：对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。","明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：郑和船队最多时有两百余艘船、两万七千余人，比欧洲航海家远航早半个多世纪，是中国古代规模最大的远洋航行。（《明史·郑和传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"明朝的对外关系；郑和下西洋（1405—1433 年，共七次）：目的是提高明朝在国外的地位和威望、加强与海外各国的联系，最远到达非洲东海岸和红海沿岸。","explain":"材料出自《明史·郑和传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-3-2-g5","type":"choice","stem":"「戚继光率「戚家军」抗倭，东南沿海的倭患基本平息」发生于","answer":"A","explain":"本课时间轴：戚继光率「戚家军」抗倭，东南沿海的倭患基本平息（16 世纪中期）。戚继光先后在台州、福建、广东大败倭寇，是我国历史上的民族英雄。其余三个时间是同一单元相邻课时的事件时间。","options":["16 世纪中期","1368 年","明太祖、明成祖时","1616 年"],"difficulty":1,"tags":["七年级下册","第三单元","本课练习"]}]},{"id":"cat-7b-3-3","title":"第17课 明朝的灭亡和清朝的建立","subtitle":"七年级下册 · 第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展","grade":"7b","tags":["七年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展"},{"k":"课时","v":"第17课 明朝的灭亡和清朝的建立"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"明朝后期政治腐败，土地兼并严重，赋税沉重。1628 年陕西大旱，李自成参加起义，提出「均田免赋」，队伍壮大。1644 年李自成攻入北京，崇祯帝自缢，明朝灭亡。随后吴三桂引清军入关，清军击败李自成，建立全国统治。"},{"type":"note","title":"本课主线 · 因果链","text":"明朝废除丞相、设三司与厂卫并以八股取士，把君主专制推向新的高度；明清两朝通过收复台湾、设置台湾府、册封达赖班禅并设驻藏大臣、平定准噶尔与大小和卓叛乱并设伊犁将军，巩固和发展了统一多民族国家；但对外由郑和下西洋、戚继光抗倭走向闭关锁国，只留广州一处通商并由十三行经营，使中国逐渐落后于世界潮流。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1616 年","努尔哈赤统一女真各部，建立后金","1635 年皇太极改族名为满洲，1636 年改国号为清"],["1644 年","李自成攻入北京，明朝灭亡；清军入关，后迁都北京","清朝逐步确立起对全国的统治"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1616 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"努尔哈赤统一女真各部，建立后金","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1644 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"李自成攻入北京，明朝灭亡；清军入关，…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"次重点","text":"清朝的建立与君主专制的顶峰：1616 年努尔哈赤建立后金，1636 年皇太极改国号为清，1644 年清军入关；雍正帝时设立军机处，使君主专制进一步强化。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。"],["把台湾府的设置时间说成 1662 年。","1662 年郑成功收复台湾；1684 年清朝设置台湾府，隶属福建省。","「收复」与「设府」的年份最容易混，而这两个年份都是高频考点，必须分别记牢。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["边疆管辖与统一多民族国家","近年中考高频","台湾、西藏、新疆三地的史实是「这些地区自古以来是中国领土」的核心论据，常以「措施—机构—作用」配对或材料题形式考查，务必按地区分条作答。"],["对外关系的变化","","从郑和下西洋、戚继光抗倭到闭关锁国、只留广州通商，要求概括「由开放走向封闭」的趋势及其后果，常与同期世界史的新航路开辟对比。"],["君主专制的强化及其评价","","以废丞相、设三司与厂卫、设军机处、八股取士、大兴文字狱的材料设问，要求说明「君主专制不断强化」并作出评价（积极：巩固统一与社会安定；消极：禁锢思想、阻碍社会进步）。"],["科技文化巨著","","《本草纲目》《天工开物》《农政全书》常以「著作—作者—领域」配对选择题出现，也常考「明清科技以总结为主、缺乏创新」这一特点。"]]},{"type":"note","title":"跨学科视角","text":"地理：明清疆域与边疆治理；语文：明清小说与四大名著。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["冲冠一怒为红颜","吴伟业《圆圆曲》诗句，文学作品中把吴三桂引清军入关归因于陈圆圆被掳，属文学表现，非史实定论。","吴伟业《圆圆曲》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"李自成","v":"明末农民起义领袖，1644 年攻入北京，推翻明朝。 出处：《明史·李自成传》"},{"k":"努尔哈赤","v":"后金建立者，统一女真各部。 出处：《清史稿·太祖本纪》"},{"k":"皇太极","v":"努尔哈赤之子，改族名满洲、改国号清。 出处：《清史稿·太宗本纪》"}]},{"type":"list","title":"延伸阅读","items":["清朝的建立：1616 年努尔哈赤建立后金；1635 年皇太极改族名为满洲；1636 年改国号为清。 出处：《清史稿·太宗本纪》","山海关之战：1644 年，吴三桂联合清军在山海关击败李自成，清军随即入关，定都北京。 出处：《清史稿·世祖本纪》；《明史·李自成传》"]},{"type":"list","title":"本课拓展出处","items":["《明史·李自成传》《清史稿·太祖本纪》","2024 部编版七下第 17 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u3-q1","type":"choice","stem":"明朝废除丞相、撤销中书省，把权力分给六部，这一措施的主要作用是","answer":"A","explain":"废除丞相后，六部直接对皇帝负责，君主专制大大加强，但也使皇帝政务负担加重。","options":["加强了君主专制","削弱了皇权","提高了地方的自主权","形成了内阁制"],"tags":["明朝皇权强化","制度创新"]},{"id":"h7b-u3-q2","type":"choice","stem":"郑和下西洋最远到达的地区是","answer":"B","explain":"1405—1433 年郑和七次下西洋，到达亚非三十多个国家和地区，最远到达非洲东海岸和红海沿岸，是世界航海史上的空前壮举。","options":["印度半岛南端","非洲东海岸和红海沿岸","波斯湾沿岸","美洲西海岸"],"tags":["郑和下西洋","时空观念"]},{"id":"h7b-u3-q3","type":"choice","stem":"清朝设置台湾府，隶属福建省，此事发生在","answer":"C","explain":"1662 年郑成功从荷兰殖民者手中收复台湾；1684 年清朝设置台湾府，隶属福建省，加强了中央政府对台湾的管辖。","options":["1662 年","1683 年","1684 年","1689 年"],"tags":["台湾府","边疆管辖"]},{"id":"cat-7b-3-3-g2","type":"choice","stem":"下列关于「明朝的灭亡和清朝的建立」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-3-g3","type":"choice","stem":"下列结论中，属于「明朝的灭亡和清朝的建立」的是","answer":"A","explain":"本课结论：明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1616 年努尔哈赤建立后金；1635 年皇太极改族名为满洲；1636 年改国号为清。（《清史稿·太宗本纪》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"明朝的灭亡和清朝的建立；清朝的建立与君主专制的顶峰：1616 年努尔哈赤建立后金，1636 年皇太极改国号为清，1644 年清军入关；雍正帝时设立军机处，使君主专制进一步强化。","explain":"材料出自《清史稿·太宗本纪》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-3-4","title":"第18课 清朝的边疆治理","subtitle":"七年级下册 · 第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展","grade":"7b","tags":["七年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展"},{"k":"课时","v":"第18课 清朝的边疆治理"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"清朝前期通过军事与制度手段加强对边疆的管辖：1662 年郑成功收复台湾，1684 年设台湾府；1685、1686 年雅克萨之战后签订《尼布楚条约》；设驻藏大臣、伊犁将军；推行金瓶掣签和改土归流；平定准噶尔和大小和卓叛乱。"},{"type":"note","title":"本课主线 · 因果链","text":"明朝废除丞相、设三司与厂卫并以八股取士，把君主专制推向新的高度；明清两朝通过收复台湾、设置台湾府、册封达赖班禅并设驻藏大臣、平定准噶尔与大小和卓叛乱并设伊犁将军，巩固和发展了统一多民族国家；但对外由郑和下西洋、戚继光抗倭走向闭关锁国，只留广州一处通商并由十三行经营，使中国逐渐落后于世界潮流。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1662 年","郑成功从荷兰殖民者手中收复台湾","1661 年郑成功率军进军台湾，1662 年荷兰殖民者投降；郑成功是民族英雄"],["1684 年","清朝设置台湾府，隶属福建省","加强中央政府对台湾的管辖，巩固了祖国的东南海防 · 重点"],["1727 年","清朝设置驻藏大臣","驻藏大臣代表中央政府监督西藏地方事务，与达赖、班禅共同管理西藏 · 重点"],["乾隆年间","平定准噶尔部及大小和卓的叛乱，设置伊犁将军","1762 年设伊犁将军，管辖包括巴勒喀什池在内的整个新疆地区"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 郑成功收复台湾","caption":"示意图：郑成功收复台湾，详见下方「历史现场」","view":"tall","alt":"示意图：郑成功收复台湾，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1661 年三月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"郑成功率将士两万五千人、战船数百艘，…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"登陆","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"在鹿耳门登陆，切断荷兰殖民者与外界联…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1662 年二月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"荷兰总督揆一投降，郑成功收复台湾","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"收复后","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"郑成功在台湾设府县、开垦荒地、发展贸…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1684 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"清朝设台湾府，隶属福建省","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"对台湾的管辖：1662 年郑成功从荷兰殖民者手中收复台湾；1684 年清朝设置台湾府，隶属福建省。","explain":"两个年份必须分清——「1662 收复、1684 设府」。意义：维护了国家主权和领土完整，加强了中央政府对台湾的管辖。"},{"level":"重点","text":"对西藏的管辖：1653 年顺治帝册封「达赖喇嘛」，1713 年康熙帝册封「班禅额尔德尼」；1727 年清朝设置驻藏大臣，代表中央政府监督西藏地方事务，与达赖、班禅共同管理西藏。","explain":"答题要落到「中央政府对西藏的管辖不断加强、制度逐步完善」；册封与驻藏大臣都体现中央政府对西藏的主权管辖。"},{"level":"重点","text":"对新疆的管辖：乾隆年间平定准噶尔部及大小和卓的叛乱，设置伊犁将军，管辖包括巴勒喀什池在内的整个新疆地区。","explain":"「平定叛乱＋设置伊犁将军」是清朝巩固西北边疆的两步，不可只答其一。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把台湾府的设置时间说成 1662 年。","1662 年郑成功收复台湾；1684 年清朝设置台湾府，隶属福建省。","「收复」与「设府」的年份最容易混，而这两个年份都是高频考点，必须分别记牢。"],["认为驻藏大臣的地位高于达赖、班禅，或认为清朝废除了达赖、班禅的封号。","清朝册封达赖、班禅，1727 年又设驻藏大臣代表中央政府监督西藏地方事务，与达赖、班禅共同管理西藏。","材料题问「清朝怎样管辖西藏」，要把「册封」与「驻藏大臣」两条都答出来，并落到「中央管辖加强」。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["边疆管辖与统一多民族国家","近年中考高频","台湾、西藏、新疆三地的史实是「这些地区自古以来是中国领土」的核心论据，常以「措施—机构—作用」配对或材料题形式考查，务必按地区分条作答。"],["对外关系的变化","","从郑和下西洋、戚继光抗倭到闭关锁国、只留广州通商，要求概括「由开放走向封闭」的趋势及其后果，常与同期世界史的新航路开辟对比。"],["君主专制的强化及其评价","","以废丞相、设三司与厂卫、设军机处、八股取士、大兴文字狱的材料设问，要求说明「君主专制不断强化」并作出评价（积极：巩固统一与社会安定；消极：禁锢思想、阻碍社会进步）。"],["科技文化巨著","","《本草纲目》《天工开物》《农政全书》常以「著作—作者—领域」配对选择题出现，也常考「明清科技以总结为主、缺乏创新」这一特点。"]]},{"type":"note","title":"跨学科视角","text":"地理：明清疆域与边疆治理；语文：明清小说与四大名著。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 郑成功收复台湾","head":["时间","经过"],"rows":[["1661 年三月","郑成功率将士两万五千人、战船数百艘，从金门出发，经澎湖进攻台湾"],["登陆","在鹿耳门登陆，切断荷兰殖民者与外界联系，围攻赤嵌楼"],["1662 年二月","荷兰总督揆一投降，郑成功收复台湾"],["收复后","郑成功在台湾设府县、开垦荒地、发展贸易"],["1684 年","清朝设台湾府，隶属福建省"]]},{"type":"note","title":"现场解说","text":"郑成功收复台湾，驱逐了荷兰殖民者，维护了国家主权和领土完整。"},{"type":"kv","title":"人物卡片","items":[{"k":"郑成功","v":"民族英雄，1662 年收复台湾。 出处：《清史稿·郑成功传》"},{"k":"康熙帝","v":"清圣祖，平定三藩、统一台湾、抗击沙俄。 出处：《清史稿·圣祖本纪》"}]},{"type":"list","title":"延伸阅读","items":["郑成功收复台湾：1661 年郑成功率军渡海，围攻荷兰殖民者据点赤嵌楼和热兰遮城，1662 年荷兰总督揆一投降，台湾回归祖国。 出处：《清史稿·郑成功传》","《尼布楚条约》：1689 年中俄签订《尼布楚条约》，从法律上确认黑龙江和乌苏里江流域包括库页岛在内的广大地区属于中国。 出处：《尼布楚条约》原文"]},{"type":"list","title":"本课拓展出处","items":["《清史稿》；《尼布楚条约》原文","2024 部编版七下第 18 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】台湾者，中国之土地也，久为贵国所踞，今余既来索，则地当归我。——郑成功致荷兰殖民者书\n【材料二】雍正五年，设驻藏大臣，以监督西藏地方事务。乾隆年间，清军平定准噶尔部及大小和卓的叛乱，设置伊犁将军，管辖包括巴勒喀什池在内的整个新疆地区。——摘编自《清史稿》\n【材料三】天朝物产丰盈，无所不有，原不藉外夷货物以通有无。——乾隆帝致英王敕谕","source":"材料研读 · 明清时期：统一多民族国家的巩固与发展"}],"questions":[{"id":"h7b-u3-m1-q1","type":"short","stem":"（1）材料一中的「贵国」指哪一个国家？郑成功收复台湾有什么历史意义？（4 分）","answer":"指荷兰。意义：①结束了荷兰殖民者对台湾的殖民统治，使台湾重新回到祖国的怀抱；②维护了国家的主权和领土完整；③促进了台湾地区的开发；④郑成功因此成为我国历史上的民族英雄。","explain":"","tags":["郑成功收复台湾","家国情怀"],"rubric":["答出荷兰","答出结束殖民统治、台湾回归祖国","答出维护国家主权和领土完整","答出促进台湾开发（或郑成功的民族英雄地位）"]},{"id":"h7b-u3-q3","type":"choice","stem":"清朝设置台湾府，隶属福建省，此事发生在","answer":"C","explain":"1662 年郑成功从荷兰殖民者手中收复台湾；1684 年清朝设置台湾府，隶属福建省，加强了中央政府对台湾的管辖。","options":["1662 年","1683 年","1684 年","1689 年"],"tags":["台湾府","边疆管辖"]},{"id":"h7b-u3-q4","type":"choice","stem":"清朝设置驻藏大臣，代表中央政府监督西藏地方事务，其时间是","answer":"C","explain":"1727 年（雍正五年）清朝设置驻藏大臣，与达赖、班禅共同管理西藏。1653 年顺治帝册封「达赖喇嘛」，1713 年康熙帝册封「班禅额尔德尼」。","options":["1653 年","1713 年","1727 年","1762 年"],"tags":["驻藏大臣","边疆管辖"]},{"id":"cat-7b-3-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 郑成功从荷兰殖民者手中收复台湾\n② 清朝设置台湾府，隶属福建省\n③ 清朝设置驻藏大臣\n④ 平定准噶尔部及大小和卓的叛乱，设置伊犁将军","answer":"A","explain":"按时间顺序应为：①郑成功从荷兰殖民者手中收复台湾（1662 年）→②清朝设置台湾府，隶属福建省（1684 年）→③清朝设置驻藏大臣（1727 年）→④平定准噶尔部及大小和卓的叛乱，设置伊犁将军（乾隆年间）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-4-g2","type":"choice","stem":"下列关于「清朝的边疆治理」的表述，错误的是","answer":"A","explain":"把台湾府的设置时间说成 1662 年——「收复」与「设府」的年份最容易混，而这两个年份都是高频考点，必须分别记牢。正确表述：1662 年郑成功收复台湾；1684 年清朝设置台湾府，隶属福建省。","options":["把台湾府的设置时间说成 1662 年。","1662 年郑成功收复台湾；1684 年清朝设置台湾府，隶属福建省。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。","对台湾的管辖：1662 年郑成功从荷兰殖民者手中收复台湾；1684 年清朝设置台湾府，隶属福建省。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-4-g3","type":"choice","stem":"下列结论中，属于「清朝的边疆治理」的是","answer":"A","explain":"本课结论：统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1661 年郑成功率军渡海，围攻荷兰殖民者据点赤嵌楼和热兰遮城，1662 年荷兰总督揆一投降，台湾回归祖国。（《清史稿·郑成功传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"清朝的边疆治理；对台湾的管辖：1662 年郑成功从荷兰殖民者手中收复台湾；1684 年清朝设置台湾府，隶属福建省。","explain":"材料出自《清史稿·郑成功传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-3-5","title":"第19课 清朝君主专制的强化","subtitle":"七年级下册 · 第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展","grade":"7b","tags":["七年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展"},{"k":"课时","v":"第19课 清朝君主专制的强化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"清朝雍正时期设立军机处，军机大臣只是跪受笔录、传达旨意，君主专制达到顶峰。清朝大兴文字狱，禁锢思想。对外实行闭关锁国，1757 年后只留广州一处通商，由十三行经营。"},{"type":"note","title":"本课主线 · 因果链","text":"明朝废除丞相、设三司与厂卫并以八股取士，把君主专制推向新的高度；明清两朝通过收复台湾、设置台湾府、册封达赖班禅并设驻藏大臣、平定准噶尔与大小和卓叛乱并设伊犁将军，巩固和发展了统一多民族国家；但对外由郑和下西洋、戚继光抗倭走向闭关锁国，只留广州一处通商并由十三行经营，使中国逐渐落后于世界潮流。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1757 年","清朝下令只保留广州一处作为对外通商口岸","由广州十三行统一经营管理对外贸易，反映出闭关锁国的对外政策 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"tall","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":17,"text":"闭关锁国：清朝严格限制对外贸易，17…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"次重点","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"清朝的建立与君主专制的顶峰：1616…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"次重点","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"戚继光抗倭与葡萄牙人攫取澳门居住权：…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":101,"text":"明清时期君主专制空前强化：明朝废丞相…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":129,"text":"对外开放带来繁荣，闭关锁国导致落后：…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"闭关锁国：清朝严格限制对外贸易，1757 年下令只留广州一处作为对外通商口岸，由广州十三行统一经营管理对外贸易。","explain":"评价要全面：一定程度上抵御了西方殖民者的侵略、对西方殖民者的侵扰起过自卫作用；但限制了中外经济文化交流，使中国逐渐落后于世界潮流。注意「严格限制」不等于「完全禁绝」。"},{"level":"次重点","text":"清朝的建立与君主专制的顶峰：1616 年努尔哈赤建立后金，1636 年皇太极改国号为清，1644 年清军入关；雍正帝时设立军机处，使君主专制进一步强化。","explain":""},{"level":"次重点","text":"戚继光抗倭与葡萄牙人攫取澳门居住权：明朝中后期，东南沿海遭受倭寇侵扰，1553 年葡萄牙人攫取在澳门的居住权。","explain":"说明明朝已同时面临「海上倭患」与「西方殖民者东来」两种威胁，与清朝闭关锁国的背景相衔接。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把「闭关锁国」理解为完全禁止对外贸易。","闭关锁国是**严格限制**对外贸易，并非完全禁绝：1757 年后只留广州一处通商，由广州十三行统一经营管理。","「完全禁绝」是常见错误表述，一旦写进答案就会被判为史实错误。"]]},{"type":"table","title":"明朝与清朝强化君主专制的措施（跨条目对比（同一册内两个王朝的政治制度））","head":["比较项","明朝","清朝"],"rows":[["中央机构","废除丞相和中书省，权分六部","沿用内阁与六部，雍正帝时设军机处"],["地方制度","废除行省，设立三司","设总督、巡抚管理地方"],["监察与特务","设锦衣卫、东厂等特务机构","设厂卫，并大兴文字狱"],["思想控制","八股取士","八股取士，大兴文字狱"],["共同实质","都是为了加强君主专制、巩固统治","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["边疆管辖与统一多民族国家","近年中考高频","台湾、西藏、新疆三地的史实是「这些地区自古以来是中国领土」的核心论据，常以「措施—机构—作用」配对或材料题形式考查，务必按地区分条作答。"],["对外关系的变化","","从郑和下西洋、戚继光抗倭到闭关锁国、只留广州通商，要求概括「由开放走向封闭」的趋势及其后果，常与同期世界史的新航路开辟对比。"],["君主专制的强化及其评价","","以废丞相、设三司与厂卫、设军机处、八股取士、大兴文字狱的材料设问，要求说明「君主专制不断强化」并作出评价（积极：巩固统一与社会安定；消极：禁锢思想、阻碍社会进步）。"],["科技文化巨著","","《本草纲目》《天工开物》《农政全书》常以「著作—作者—领域」配对选择题出现，也常考「明清科技以总结为主、缺乏创新」这一特点。"]]},{"type":"note","title":"跨学科视角","text":"地理：明清疆域与边疆治理；语文：明清小说与四大名著。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["文字狱","清朝统治者从文人著作中摘取字句罗织罪名，制造冤狱，以压制反清思想。","《清史稿·刑法志》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"雍正帝","v":"清世宗，设军机处，强化君主专制。 出处：《清史稿·世宗本纪》"}]},{"type":"list","title":"延伸阅读","items":["军机处：1729 年因西北用兵设军机处，后成为常设机构。军机大臣无固定编制，每日入值，承旨拟旨，权力完全依附皇帝。 出处：《清史稿·职官志》","闭关锁国：清朝严格限制对外贸易，1757 年下令只开广州一处，由特许的十三行商人经营，阻碍了中国与世界的交流。 出处：《清史稿·食货志》"]},{"type":"list","title":"本课拓展出处","items":["《清史稿·世宗本纪》《清史稿·食货志》","2024 部编版七下第 19 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u3-q5","type":"choice","stem":"清朝实行闭关锁国政策时，只保留哪一处作为对外通商口岸","answer":"C","explain":"1757 年清朝下令只留广州一处作为对外通商口岸，并由广州十三行统一经营管理对外贸易，这就是闭关锁国政策的表现。","options":["泉州","宁波","广州","上海"],"tags":["闭关锁国","对外关系"]},{"id":"h7b-u3-q6","type":"choice","stem":"清朝雍正帝设立、使君主专制进一步强化的机构是","answer":"C","explain":"雍正帝时设立军机处，军机大臣只是跪受笔录、传达皇帝的旨意，君主专制进一步强化。锦衣卫、东厂是明朝的特务机构。","options":["中书省","内阁","军机处","锦衣卫"],"tags":["军机处","君主专制"]},{"id":"cat-7b-3-5-g2","type":"choice","stem":"下列关于「清朝君主专制的强化」的表述，错误的是","answer":"A","explain":"把「闭关锁国」理解为完全禁止对外贸易——「完全禁绝」是常见错误表述，一旦写进答案就会被判为史实错误。正确表述：闭关锁国是**严格限制**对外贸易，并非完全禁绝：1757 年后只留广州一处通商，由广州十三行统一经营管理。","options":["把「闭关锁国」理解为完全禁止对外贸易。","闭关锁国是**严格限制**对外贸易，并非完全禁绝：1757 年后只留广州一处通商，由广州十三行统一经营管理。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-5-g3","type":"choice","stem":"下列结论中，属于「清朝君主专制的强化」的是","answer":"A","explain":"本课结论：明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-5-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1729 年因西北用兵设军机处，后成为常设机构。军机大臣无固定编制，每日入值，承旨拟旨，权力完全依附皇帝。（《清史稿·职官志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"清朝君主专制的强化；闭关锁国：清朝严格限制对外贸易，1757 年下令只留广州一处作为对外通商口岸，由广州十三行统一经营管理对外贸易。","explain":"材料出自《清史稿·职官志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-3-6","title":"第20课 明清时期社会经济的发展","subtitle":"七年级下册 · 第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展","grade":"7b","tags":["七年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展"},{"k":"课时","v":"第20课 明清时期社会经济的发展"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"明清时期社会经济继续发展。明朝引进玉米、甘薯、马铃薯等高产作物，清朝人口突破三亿。手工业出现规模较大的作坊，苏州丝织业出现「机户出资，机工出力」的雇佣关系，被称为资本主义萌芽。"},{"type":"note","title":"本课主线 · 因果链","text":"明朝废除丞相、设三司与厂卫并以八股取士，把君主专制推向新的高度；明清两朝通过收复台湾、设置台湾府、册封达赖班禅并设驻藏大臣、平定准噶尔与大小和卓叛乱并设伊犁将军，巩固和发展了统一多民族国家；但对外由郑和下西洋、戚继光抗倭走向闭关锁国，只留广州一处通商并由十三行经营，使中国逐渐落后于世界潮流。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["1368 年","朱元璋建立明朝，定都应天府（今江苏南京）","朱元璋即明太祖；同年明军攻占大都，元朝在全国的统治结束 · 重点"],["明太祖、明成祖时","强化皇权：中央废丞相、权分六部，地方废行省、设三司；设锦衣卫、东厂等特务机构","地方设布政使司、按察使司、都指挥使司，合称「三司」；同时实行八股取士"],["1405—1433 年","明成祖派郑和七次下西洋","最远到达非洲东海岸和红海沿岸，是世界航海史上的空前壮举 · 重点"],["16 世纪中期","戚继光率「戚家军」抗倭，东南沿海的倭患基本平息","戚继光先后在台州、福建、广东大败倭寇，是我国历史上的民族英雄"],["1553 年","葡萄牙人攫取在澳门的居住权","这是明朝中后期来自海上的外来侵扰之一，说明中国已面临早期殖民者的威胁"],["1616 年","努尔哈赤统一女真各部，建立后金","1635 年皇太极改族名为满洲，1636 年改国号为清"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1368 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"朱元璋建立明朝，定都应天府（今江苏南…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"明太祖、明成祖时","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"强化皇权：中央废丞相、权分六部，地方…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1405—1433 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"明成祖派郑和七次下西洋","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"16 世纪中期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"戚继光率「戚家军」抗倭，东南沿海的倭…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"1553 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"葡萄牙人攫取在澳门的居住权","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1616 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"努尔哈赤统一女真各部，建立后金","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"明清科技巨著：明代李时珍的《本草纲目》是药物学巨著；宋应星的《天工开物》总结了农业和手工业生产技术，被誉为「中国 17 世纪的工艺百科全书」；明末徐光启的《农政全书》是重要的农学著作。","explain":"常考「著作—作者—朝代—领域」的配对；还要能说出明清科技的特点是**以总结传统经验为主**，缺乏近代实验科学的创新。"},{"level":"选择题","text":"明清经济的发展：明代引进并推广玉米、甘薯等高产作物，清代人口增长较快；商帮活跃，以晋商、徽商最为著名。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。"],["把台湾府的设置时间说成 1662 年。","1662 年郑成功收复台湾；1684 年清朝设置台湾府，隶属福建省。","「收复」与「设府」的年份最容易混，而这两个年份都是高频考点，必须分别记牢。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["边疆管辖与统一多民族国家","近年中考高频","台湾、西藏、新疆三地的史实是「这些地区自古以来是中国领土」的核心论据，常以「措施—机构—作用」配对或材料题形式考查，务必按地区分条作答。"],["对外关系的变化","","从郑和下西洋、戚继光抗倭到闭关锁国、只留广州通商，要求概括「由开放走向封闭」的趋势及其后果，常与同期世界史的新航路开辟对比。"],["君主专制的强化及其评价","","以废丞相、设三司与厂卫、设军机处、八股取士、大兴文字狱的材料设问，要求说明「君主专制不断强化」并作出评价（积极：巩固统一与社会安定；消极：禁锢思想、阻碍社会进步）。"],["科技文化巨著","","《本草纲目》《天工开物》《农政全书》常以「著作—作者—领域」配对选择题出现，也常考「明清科技以总结为主、缺乏创新」这一特点。"]]},{"type":"note","title":"跨学科视角","text":"地理：明清疆域与边疆治理；语文：明清小说与四大名著。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["高产作物的引进：明朝中后期，玉米、甘薯、马铃薯等原产美洲的作物传入中国，适应山地贫瘠土地，促进人口增长。 出处：2024 部编版七下第 20 课；《农政全书》","晋商与徽商：明清时期形成地域性商人群体，晋商经营票号、盐业，徽商经营盐、茶、木材，足迹遍及全国。 出处：张海鹏、张海瀛《中国十大商帮》"]},{"type":"list","title":"本课拓展出处","items":["《明史·食货志》《清史稿·食货志》","2024 部编版七下第 20 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u3-q7","type":"choice","stem":"下列关于《天工开物》的说法，正确的是","answer":"A","explain":"《天工开物》由明代宋应星撰写，被誉为「中国 17 世纪的工艺百科全书」。李时珍的著作是《本草纲目》，徐光启的著作是《农政全书》，曹雪芹的作品是《红楼梦》。","options":["是明代宋应星所著，总结了农业和手工业生产技术","是明代李时珍所著的药物学巨著","是明末徐光启所著的农学著作","是清代曹雪芹创作的长篇小说"],"tags":["明清科技","文化成就"]},{"id":"cat-7b-3-6-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 朱元璋建立明朝，定都应天府（今江苏南京）\n② 强化皇权：中央废丞相、权分六部，地方废行省、设三…\n③ 明成祖派郑和七次下西洋\n④ 戚继光率「戚家军」抗倭，东南沿海的倭患基本平息","answer":"A","explain":"按时间顺序应为：①朱元璋建立明朝，定都应天府（今江苏南京）（1368 年）→②强化皇权：中央废丞相、权分六部，地方废行省、设三司；设锦衣卫、东厂等特务机构（明太祖、明成祖时）→③明成祖派郑和七次下西洋（1405—1433 年）→④戚继光率「戚家军」抗倭，东南沿海的倭患基本平息（16 世纪中期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-6-g2","type":"choice","stem":"下列关于「明清时期社会经济的发展」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。","明清科技巨著：明代李时珍的《本草纲目》是药物学巨著；宋应星的《天工开物》总结了农业和手工业生产技术，被誉为「中国 17 世纪的工艺百科全书」；明末徐光启的《农政全书》是重要的农学著作。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-6-g3","type":"choice","stem":"下列结论中，属于「明清时期社会经济的发展」的是","answer":"A","explain":"本课结论：明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-6-g4","type":"short","stem":"阅读材料，回答问题。\n材料：明朝中后期，玉米、甘薯、马铃薯等原产美洲的作物传入中国，适应山地贫瘠土地，促进人口增长。（2024 部编版七下第 20 课；《农政全书》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"明清时期社会经济的发展；明清科技巨著：明代李时珍的《本草纲目》是药物学巨著；宋应星的《天工开物》总结了农业和手工业生产技术，被誉为「中国 17 世纪的工艺百科全书」；明末徐光启的《农政全书》是重要的农学著作。","explain":"材料出自2024 部编版七下第 20 课；《农政全书》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-3-7","title":"第21课 明清时期的科技与文化","subtitle":"七年级下册 · 第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展","grade":"7b","tags":["七年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展"},{"k":"课时","v":"第21课 明清时期的科技与文化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"明清时期传统科技进入总结阶段：李时珍《本草纲目》、宋应星《天工开物》、徐光启《农政全书》分别是医药学、工艺技术、农学的总结性著作。文学上《红楼梦》达到古典小说高峰，京剧在清代形成。"},{"type":"note","title":"本课主线 · 因果链","text":"明朝废除丞相、设三司与厂卫并以八股取士，把君主专制推向新的高度；明清两朝通过收复台湾、设置台湾府、册封达赖班禅并设驻藏大臣、平定准噶尔与大小和卓叛乱并设伊犁将军，巩固和发展了统一多民族国家；但对外由郑和下西洋、戚继光抗倭走向闭关锁国，只留广州一处通商并由十三行经营，使中国逐渐落后于世界潮流。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["1368 年","朱元璋建立明朝，定都应天府（今江苏南京）","朱元璋即明太祖；同年明军攻占大都，元朝在全国的统治结束 · 重点"],["明太祖、明成祖时","强化皇权：中央废丞相、权分六部，地方废行省、设三司；设锦衣卫、东厂等特务机构","地方设布政使司、按察使司、都指挥使司，合称「三司」；同时实行八股取士"],["1405—1433 年","明成祖派郑和七次下西洋","最远到达非洲东海岸和红海沿岸，是世界航海史上的空前壮举 · 重点"],["16 世纪中期","戚继光率「戚家军」抗倭，东南沿海的倭患基本平息","戚继光先后在台州、福建、广东大败倭寇，是我国历史上的民族英雄"],["1553 年","葡萄牙人攫取在澳门的居住权","这是明朝中后期来自海上的外来侵扰之一，说明中国已面临早期殖民者的威胁"],["1616 年","努尔哈赤统一女真各部，建立后金","1635 年皇太极改族名为满洲，1636 年改国号为清"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1368 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"朱元璋建立明朝，定都应天府（今江苏南…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"明太祖、明成祖时","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"强化皇权：中央废丞相、权分六部，地方…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1405—1433 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"明成祖派郑和七次下西洋","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"16 世纪中期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"戚继光率「戚家军」抗倭，东南沿海的倭…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"1553 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"葡萄牙人攫取在澳门的居住权","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1616 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"努尔哈赤统一女真各部，建立后金","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"明清科技巨著：明代李时珍的《本草纲目》是药物学巨著；宋应星的《天工开物》总结了农业和手工业生产技术，被誉为「中国 17 世纪的工艺百科全书」；明末徐光启的《农政全书》是重要的农学著作。","explain":"常考「著作—作者—朝代—领域」的配对；还要能说出明清科技的特点是**以总结传统经验为主**，缺乏近代实验科学的创新。"},{"level":"次重点","text":"明清小说与戏曲：明代《三国演义》《水浒传》《西游记》，清代曹雪芹的《红楼梦》；清代京剧形成并逐渐流行。","explain":"常考「四大名著」的成书朝代与作者，注意《红楼梦》是清代作品。"},{"level":"选择题","text":"明代长城与北京城：明长城东起鸭绿江、西至嘉峪关；北京城由宫城、皇城、内城和外城组成，宫城即紫禁城。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。"],["把台湾府的设置时间说成 1662 年。","1662 年郑成功收复台湾；1684 年清朝设置台湾府，隶属福建省。","「收复」与「设府」的年份最容易混，而这两个年份都是高频考点，必须分别记牢。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["边疆管辖与统一多民族国家","近年中考高频","台湾、西藏、新疆三地的史实是「这些地区自古以来是中国领土」的核心论据，常以「措施—机构—作用」配对或材料题形式考查，务必按地区分条作答。"],["对外关系的变化","","从郑和下西洋、戚继光抗倭到闭关锁国、只留广州通商，要求概括「由开放走向封闭」的趋势及其后果，常与同期世界史的新航路开辟对比。"],["君主专制的强化及其评价","","以废丞相、设三司与厂卫、设军机处、八股取士、大兴文字狱的材料设问，要求说明「君主专制不断强化」并作出评价（积极：巩固统一与社会安定；消极：禁锢思想、阻碍社会进步）。"],["科技文化巨著","","《本草纲目》《天工开物》《农政全书》常以「著作—作者—领域」配对选择题出现，也常考「明清科技以总结为主、缺乏创新」这一特点。"]]},{"type":"note","title":"跨学科视角","text":"地理：明清疆域与边疆治理；语文：明清小说与四大名著。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"李时珍","v":"明代医药学家，著《本草纲目》。 出处：《明史·方伎传》"},{"k":"宋应星","v":"明代科学家，著《天工开物》。 出处：《天工开物》"},{"k":"曹雪芹","v":"清代小说家，著《红楼梦》。 出处：《红楼梦》"}]},{"type":"list","title":"延伸阅读","items":["《天工开物》：宋应星系统记录农业和手工业的生产技术，包括谷物加工、纺织、制盐、造纸、冶铸、陶瓷等，被誉为「中国 17 世纪的工艺百科全书」。 出处：宋应星《天工开物》","京剧的形成：1790 年徽班进京为乾隆祝寿，此后徽调与汉调、昆曲、秦腔等融合，形成京剧。 出处：2024 部编版七下第 21 课；《中国戏曲志》"]},{"type":"list","title":"本课拓展出处","items":["《本草纲目》序；《天工开物》；《红楼梦》","2024 部编版七下第 21 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u3-q7","type":"choice","stem":"下列关于《天工开物》的说法，正确的是","answer":"A","explain":"《天工开物》由明代宋应星撰写，被誉为「中国 17 世纪的工艺百科全书」。李时珍的著作是《本草纲目》，徐光启的著作是《农政全书》，曹雪芹的作品是《红楼梦》。","options":["是明代宋应星所著，总结了农业和手工业生产技术","是明代李时珍所著的药物学巨著","是明末徐光启所著的农学著作","是清代曹雪芹创作的长篇小说"],"tags":["明清科技","文化成就"]},{"id":"cat-7b-3-7-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 朱元璋建立明朝，定都应天府（今江苏南京）\n② 强化皇权：中央废丞相、权分六部，地方废行省、设三…\n③ 明成祖派郑和七次下西洋\n④ 戚继光率「戚家军」抗倭，东南沿海的倭患基本平息","answer":"A","explain":"按时间顺序应为：①朱元璋建立明朝，定都应天府（今江苏南京）（1368 年）→②强化皇权：中央废丞相、权分六部，地方废行省、设三司；设锦衣卫、东厂等特务机构（明太祖、明成祖时）→③明成祖派郑和七次下西洋（1405—1433 年）→④戚继光率「戚家军」抗倭，东南沿海的倭患基本平息（16 世纪中期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-7-g2","type":"choice","stem":"下列关于「明清时期的科技与文化」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。","明清科技巨著：明代李时珍的《本草纲目》是药物学巨著；宋应星的《天工开物》总结了农业和手工业生产技术，被誉为「中国 17 世纪的工艺百科全书」；明末徐光启的《农政全书》是重要的农学著作。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-7-g3","type":"choice","stem":"下列结论中，属于「明清时期的科技与文化」的是","answer":"A","explain":"本课结论：明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-7-g4","type":"short","stem":"阅读材料，回答问题。\n材料：宋应星系统记录农业和手工业的生产技术，包括谷物加工、纺织、制盐、造纸、冶铸、陶瓷等，被誉为「中国 17 世纪的工艺百科全书」。（宋应星《天工开物》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"明清时期的科技与文化；明清科技巨著：明代李时珍的《本草纲目》是药物学巨著；宋应星的《天工开物》总结了农业和手工业生产技术，被誉为「中国 17 世纪的工艺百科全书」；明末徐光启的《农政全书》是重要的农学著作。","explain":"材料出自宋应星《天工开物》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-7b-3-8","title":"第22课 活动课 我国传统节日的起源与传承","subtitle":"七年级下册 · 第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展","grade":"7b","tags":["七年级下册","第三单元","活动课"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展"},{"k":"课时","v":"第22课 活动课 我国传统节日的起源与传承"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"本课是活动课，梳理春节、清明节、端午节、中秋节等传统节日的起源与习俗。传统节日多与农耕节令、祖先祭祀和历史人物纪念有关，是中华优秀传统文化的重要载体。"},{"type":"note","title":"本课主线 · 因果链","text":"明朝废除丞相、设三司与厂卫并以八股取士，把君主专制推向新的高度；明清两朝通过收复台湾、设置台湾府、册封达赖班禅并设驻藏大臣、平定准噶尔与大小和卓叛乱并设伊犁将军，巩固和发展了统一多民族国家；但对外由郑和下西洋、戚继光抗倭走向闭关锁国，只留广州一处通商并由十三行经营，使中国逐渐落后于世界潮流。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["1368 年","朱元璋建立明朝，定都应天府（今江苏南京）","朱元璋即明太祖；同年明军攻占大都，元朝在全国的统治结束 · 重点"],["明太祖、明成祖时","强化皇权：中央废丞相、权分六部，地方废行省、设三司；设锦衣卫、东厂等特务机构","地方设布政使司、按察使司、都指挥使司，合称「三司」；同时实行八股取士"],["1405—1433 年","明成祖派郑和七次下西洋","最远到达非洲东海岸和红海沿岸，是世界航海史上的空前壮举 · 重点"],["16 世纪中期","戚继光率「戚家军」抗倭，东南沿海的倭患基本平息","戚继光先后在台州、福建、广东大败倭寇，是我国历史上的民族英雄"],["1553 年","葡萄牙人攫取在澳门的居住权","这是明朝中后期来自海上的外来侵扰之一，说明中国已面临早期殖民者的威胁"],["1616 年","努尔哈赤统一女真各部，建立后金","1635 年皇太极改族名为满洲，1636 年改国号为清"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1368 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"朱元璋建立明朝，定都应天府（今江苏南…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"明太祖、明成祖时","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"强化皇权：中央废丞相、权分六部，地方…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1405—1433 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"明成祖派郑和七次下西洋","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"16 世纪中期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"戚继光率「戚家军」抗倭，东南沿海的倭…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"1553 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"葡萄牙人攫取在澳门的居住权","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1616 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"努尔哈赤统一女真各部，建立后金","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题（本课单独考点较少，以下取本单元整体内容）","items":[{"level":"重点","text":"明朝强化皇权：中央废除丞相和中书省，权力分给六部；地方废除行省，设立三司；设锦衣卫、东厂等特务机构；实行八股取士。","explain":"影响要一分为二：君主专制空前加强、有利于巩固统治；但官僚机构臃肿、思想被禁锢，社会逐渐失去活力。注意与元朝行省制、清朝总督巡抚的比较。"},{"level":"重点","text":"八股取士：考试题目必须来自「四书」「五经」，答卷必须写成八股文，不许考生自由发挥。","explain":"必答影响：束缚了人们的思想，不利于选贤任能，也阻碍了科学技术与文化的创新。与科举制「创立于隋、完善于唐、僵化于明清」连起来记。"},{"level":"重点","text":"郑和下西洋（1405—1433 年，共七次）：目的是提高明朝在国外的地位和威望、加强与海外各国的联系，最远到达非洲东海岸和红海沿岸。","explain":"意义与局限都要写：是世界航海史上的空前壮举，增进了中国与亚非国家的友好往来；但不计经济效益、给明朝造成巨大财政负担，因而未能持续。"},{"level":"重点","text":"对台湾的管辖：1662 年郑成功从荷兰殖民者手中收复台湾；1684 年清朝设置台湾府，隶属福建省。","explain":"两个年份必须分清——「1662 收复、1684 设府」。意义：维护了国家主权和领土完整，加强了中央政府对台湾的管辖。"},{"level":"重点","text":"对西藏的管辖：1653 年顺治帝册封「达赖喇嘛」，1713 年康熙帝册封「班禅额尔德尼」；1727 年清朝设置驻藏大臣，代表中央政府监督西藏地方事务，与达赖、班禅共同管理西藏。","explain":"答题要落到「中央政府对西藏的管辖不断加强、制度逐步完善」；册封与驻藏大臣都体现中央政府对西藏的主权管辖。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。"],["把台湾府的设置时间说成 1662 年。","1662 年郑成功收复台湾；1684 年清朝设置台湾府，隶属福建省。","「收复」与「设府」的年份最容易混，而这两个年份都是高频考点，必须分别记牢。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","考情","说明"],"rows":[["边疆管辖与统一多民族国家","近年中考高频","台湾、西藏、新疆三地的史实是「这些地区自古以来是中国领土」的核心论据，常以「措施—机构—作用」配对或材料题形式考查，务必按地区分条作答。"],["对外关系的变化","","从郑和下西洋、戚继光抗倭到闭关锁国、只留广州通商，要求概括「由开放走向封闭」的趋势及其后果，常与同期世界史的新航路开辟对比。"],["君主专制的强化及其评价","","以废丞相、设三司与厂卫、设军机处、八股取士、大兴文字狱的材料设问，要求说明「君主专制不断强化」并作出评价（积极：巩固统一与社会安定；消极：禁锢思想、阻碍社会进步）。"],["科技文化巨著","","《本草纲目》《天工开物》《农政全书》常以「著作—作者—领域」配对选择题出现，也常考「明清科技以总结为主、缺乏创新」这一特点。"]]},{"type":"note","title":"跨学科视角","text":"地理：明清疆域与边疆治理；语文：明清小说与四大名著。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["端午与屈原：端午节有赛龙舟、吃粽子、挂艾草等习俗，民间传说与纪念屈原有关，南朝宗懔《荆楚岁时记》已有五月五日竞渡的记载。 出处：宗懔《荆楚岁时记》","中秋赏月：中秋节在宋代成为重要节日，孟元老《东京梦华录》记载北宋开封中秋之夜「贵家结饰台榭，民间争占酒楼玩月」。 出处：孟元老《东京梦华录》卷八"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版七下第 22 课","《荆楚岁时记》；《东京梦华录》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 统一多民族国家与民族交融","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-07"},{"t":"跨章节专题 · 经济重心南移与中外经济交流","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-08"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h7b-u3-q1","type":"choice","stem":"明朝废除丞相、撤销中书省，把权力分给六部，这一措施的主要作用是","answer":"A","explain":"废除丞相后，六部直接对皇帝负责，君主专制大大加强，但也使皇帝政务负担加重。","options":["加强了君主专制","削弱了皇权","提高了地方的自主权","形成了内阁制"],"tags":["明朝皇权强化","制度创新"]},{"id":"h7b-u3-q2","type":"choice","stem":"郑和下西洋最远到达的地区是","answer":"B","explain":"1405—1433 年郑和七次下西洋，到达亚非三十多个国家和地区，最远到达非洲东海岸和红海沿岸，是世界航海史上的空前壮举。","options":["印度半岛南端","非洲东海岸和红海沿岸","波斯湾沿岸","美洲西海岸"],"tags":["郑和下西洋","时空观念"]},{"id":"h7b-u3-q3","type":"choice","stem":"清朝设置台湾府，隶属福建省，此事发生在","answer":"C","explain":"1662 年郑成功从荷兰殖民者手中收复台湾；1684 年清朝设置台湾府，隶属福建省，加强了中央政府对台湾的管辖。","options":["1662 年","1683 年","1684 年","1689 年"],"tags":["台湾府","边疆管辖"]},{"id":"cat-7b-3-8-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 朱元璋建立明朝，定都应天府（今江苏南京）\n② 强化皇权：中央废丞相、权分六部，地方废行省、设三…\n③ 明成祖派郑和七次下西洋\n④ 戚继光率「戚家军」抗倭，东南沿海的倭患基本平息","answer":"A","explain":"按时间顺序应为：①朱元璋建立明朝，定都应天府（今江苏南京）（1368 年）→②强化皇权：中央废丞相、权分六部，地方废行省、设三司；设锦衣卫、东厂等特务机构（明太祖、明成祖时）→③明成祖派郑和七次下西洋（1405—1433 年）→④戚继光率「戚家军」抗倭，东南沿海的倭患基本平息（16 世纪中期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-8-g2","type":"choice","stem":"下列关于「活动课 我国传统节日的起源与传承」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-8-g3","type":"choice","stem":"下列结论中，属于「活动课 我国传统节日的起源与传承」的是","answer":"A","explain":"本课结论：明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-8-g4","type":"short","stem":"阅读材料，回答问题。\n材料：端午节有赛龙舟、吃粽子、挂艾草等习俗，民间传说与纪念屈原有关，南朝宗懔《荆楚岁时记》已有五月五日竞渡的记载。（宗懔《荆楚岁时记》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"活动课 我国传统节日的起源与传承；明朝强化皇权：中央废除丞相和中书省，权力分给六部；地方废除行省，设立三司；设锦衣卫、东厂等特务机构；实行八股取士。","explain":"材料出自宗懔《荆楚岁时记》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-1-1","title":"第1课 鸦片战争","subtitle":"八年级上册 · 第一单元 中国开始沦为半殖民地半封建社会","grade":"8a","tags":["八年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第一单元 中国开始沦为半殖民地半封建社会"},{"k":"课时","v":"第1课 鸦片战争"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"19 世纪上半期，英国完成工业革命，急需原料和市场，向中国大量走私鸦片。鸦片输入导致白银外流、财政危机和国民体质下降。1839 年 6 月，林则徐在虎门海滩当众销毁鸦片，英国以此为借口发动战争。"},{"type":"note","title":"本课主线 · 因果链","text":"英国为打开中国市场发动鸦片战争，中国战败签订《南京条约》，领土、关税、司法等主权开始被破坏，社会性质由封建社会开始沦为半殖民地半封建社会；第二次鸦片战争使这一程度进一步加深，而农民阶级的太平天国运动虽沉重打击了中外反动势力，却因阶级局限最终失败。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1839 年 6 月","林则徐在广东虎门销烟","销毁鸦片 110 多万千克，是中国人民禁烟斗争的伟大胜利，显示中华民族反抗侵略的决心"],["1840 年 6 月—1842 年 8 月","鸦片战争","英国为打开中国市场而发动的侵略战争，中国战败 · 重点"],["1842 年 8 月","中英《南京条约》签订","中国近代第一个不平等条约：割香港岛、赔款 2100 万银元、开五口通商、协定关税 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 虎门销烟：23 天销毁两百多万斤鸦片","caption":"示意图：虎门销烟：23 天销毁两百多万斤鸦片，详见下方「历史现场」","view":"tall","alt":"示意图：虎门销烟：23 天销毁两百多万斤鸦片，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1838 年底","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"林则徐受命为钦差大臣，赴广东查禁鸦片","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"1839 年 3 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"林则徐到达广州，责令外商限期交出鸦片…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1839 年 6 月 3…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"虎门销烟开始，在海滩开池浸化鸦片","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"1839 年 6 月 2…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"销烟结束，共销毁鸦片 19187 箱…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1840 年 6 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"英国舰队封锁珠江口，鸦片战争爆发","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战争的借口（直接原因）。","explain":"常考「如果没有林则徐禁烟，鸦片战争还会爆发吗」：会。因为战争的根源是资本主义扩张的需要，禁烟只是导火线。"},{"level":"重点","text":"《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、上海五处为通商口岸；英商进出口货物应纳税款须经双方协议（协定关税）。","explain":"答题要按「割地—赔款—通商—关税」四点默写。其中协定关税破坏了中国关税自主权，是列强经济侵略的关键条款，最爱考。"},{"level":"重点","text":"鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。","explain":"「开始沦为」四个字是踩分点。领土完整和主权遭到破坏（半殖民地），封建经济逐步解体、被卷入资本主义世界市场（半封建）。"},{"level":"选择题","text":"关天培、陈化成等爱国将领在鸦片战争中英勇殉国；林则徐是伟大的民族英雄，也是「开眼看世界」的第一人。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。","列强侵华的核心目的是把中国变成其商品市场和原料产地；《南京条约》中的**协定关税**破坏中国关税自主权，便利了列强的经济侵略。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。"],["认为鸦片战争是由林则徐虎门销烟引起的。","虎门销烟只是英国发动战争的借口（直接原因），根本原因是英国要打开中国市场。","材料题常设「有人说没有林则徐禁烟就不会有鸦片战争，你同意吗」，必须答根本原因与直接原因两层。"],["把「中国近代史的开端」与「中国近代化的开端」混为一谈。","鸦片战争是中国近代史的开端；洋务运动是中国近代化的开端。","两字之差，指向完全不同的事件，选择题常把两个结论对调。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["条约内容与影响的对应","给出条约条款原文，要求判断条约名称并说明「破坏了中国哪一方面的主权」，落脚在「半殖民地化程度如何变化」的时间线上。"],["史料实证：从鸦片输入到销烟","常用林则徐奏折、「银荒兵弱」等材料组合，要求说明禁烟的原因与虎门销烟的意义，注意区分「直接原因／根本原因」。"],["农民运动的评价","以太平天国为切口，考查「为什么农民阶级不能领导中国革命取得胜利」，答法固定：阶级局限性 + 提不出科学纲领 + 缺乏先进阶级领导。"]]},{"type":"note","title":"跨学科视角","text":"地理：沿海口岸与鸦片贸易路线；道德与法治：国家主权与民族尊严。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 虎门销烟：23 天销毁两百多万斤鸦片","head":["时间","经过"],"rows":[["1838 年底","林则徐受命为钦差大臣，赴广东查禁鸦片"],["1839 年 3 月","林则徐到达广州，责令外商限期交出鸦片，并出具永不夹带鸦片的具结"],["1839 年 6 月 3 日","虎门销烟开始，在海滩开池浸化鸦片"],["1839 年 6 月 25 日","销烟结束，共销毁鸦片 19187 箱又 2119 袋，约 237 万余斤"],["1840 年 6 月","英国舰队封锁珠江口，鸦片战争爆发"]]},{"type":"note","title":"现场解说","text":"虎门销烟维护了中华民族的尊严，也成为英国发动侵略战争的借口。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["虎门销烟","1839 年林则徐在虎门销毁鸦片的壮举，是中国禁烟运动的重大胜利。","《清史稿·林则徐传》"],["开眼看世界","林则徐组织翻译西方书报，编《四洲志》，被后人称为近代中国「开眼看世界第一人」。","《清史稿·林则徐传》；2024 部编版八上第 1 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"林则徐","v":"清朝大臣，领导虎门销烟，主张学习西方。 出处：《清史稿·林则徐传》"},{"k":"道光帝","v":"清宣宗，派林则徐禁烟，战败后签订《南京条约》。 出处：《清史稿·宣宗本纪》"}]},{"type":"list","title":"延伸阅读","items":["虎门销烟的方法：在林则徐主持下，于海滩挖池，先注海水，再投入鸦片，撒入生石灰搅拌，鸦片随潮水冲入大海。历时 23 天，销毁鸦片 110 多万千克。 出处：《清史稿·林则徐传》；2024 部编版八上第 1 课","《南京条约》主要内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、上海五处通商口岸；英商进出口货物应纳税款须与英国商定。 出处：《南京条约》原文"]},{"type":"list","title":"本课拓展出处","items":["《清史稿·林则徐传》；《南京条约》原文","2024 部编版八上第 1 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】若犹泄泄视之，是使数十年后，中原几无可以御敌之兵，且无可以充饷之银。——林则徐上道光帝奏折\n【材料二】一八四二年八月，中英《南京条约》规定：割香港岛给英国；赔款二千一百万银元；开放广州、厦门、福州、宁波、上海五处为通商口岸；英商进出口货物应纳税款，必须经过双方协议。——据《筹办夷务始末》整理\n【材料三】鸦片战争以后，中国形式上仍是独立国家，但领土完整和主权遭到破坏，自给自足的封建经济逐步解体，中国经济被卷入资本主义世界市场。","source":"材料研读 · 中国开始沦为半殖民地半封建社会"}],"questions":[{"id":"h8a-u1-m1-q1","type":"short","stem":"（1）依据材料一，说明林则徐主张禁烟的原因；结合所学指出虎门销烟的意义。（4 分）","answer":"原因：鸦片大量输入使中国白银外流、财政困难（「无可以充饷之银」），并严重摧残吸食者的体质，军队战斗力削弱（「无可以御敌之兵」），危及清朝统治。意义：虎门销烟是中国人民禁烟斗争的伟大胜利，显示了中华民族反抗外来侵略的坚强意志，林则徐是当之无愧的民族英雄。","explain":"","tags":["虎门销烟","史料实证"],"rubric":["答出白银外流、财政困难","答出兵弱、摧残体质","答出禁烟斗争的伟大胜利","答出反抗侵略的坚强意志/民族英雄"]},{"id":"h8a-u1-m1-q2","type":"short","stem":"（2）依据材料二，指出《南京条约》中破坏中国关税自主权的条款，并结合材料三说明鸦片战争对中国社会性质的影响。（6 分）","answer":"条款：英商进出口货物应纳税款必须经过双方协议（协定关税）。影响：中国的领土完整和主权遭到破坏，开始沦为半殖民地；封建经济逐步解体，被卷入资本主义世界市场，开始沦为半封建。总之，鸦片战争后中国开始沦为半殖民地半封建社会，鸦片战争成为中国近代史的开端。","explain":"","tags":["南京条约","半殖民地半封建社会"],"rubric":["答出协定关税","答出领土、主权遭到破坏","答出封建经济开始解体","答出开始沦为半殖民地半封建社会","答出是中国近代史的开端"]},{"id":"h8a-u1-q1","type":"choice","stem":"英国发动鸦片战争的根本原因是","answer":"B","explain":"鸦片战争是英国资本主义发展的必然结果：工业革命后英国急需商品市场和原料产地。虎门销烟只是英国发动战争的借口，即直接原因。","options":["林则徐在虎门销烟","英国为打开中国市场、推销工业品并掠夺原料","清政府闭关自守、禁止通商","中英两国贸易长期不平衡"],"tags":["鸦片战争","历史解释"]},{"id":"h8a-u1-q2","type":"choice","stem":"《南京条约》的各项内容中，最能反映英国打开中国市场、便利经济侵略意图的是","answer":"C","explain":"五口通商打开了中国大门，协定关税破坏了中国关税自主权，使列强可以低价倾销商品、掠夺原料，最能体现其经济侵略意图。割地赔款是政治与财政层面的侵害。","options":["割香港岛给英国","赔款 2100 万银元","开放五处通商口岸并协定关税","英军占领广州"],"tags":["南京条约","史料实证"]},{"id":"cat-8a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 林则徐在广东虎门销烟\n② 鸦片战争\n③ 中英《南京条约》签订","answer":"A","explain":"按时间顺序应为：①林则徐在广东虎门销烟（1839 年 6 月）→②鸦片战争（1840 年 6 月—1842 年 8 月）→③中英《南京条约》签订（1842 年 8 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-1-g2","type":"choice","stem":"下列关于「鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。","列强侵华的核心目的是把中国变成其商品市场和原料产地；《南京条约》中的**协定关税**破坏中国关税自主权，便利了列强的经济侵略。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：在林则徐主持下，于海滩挖池，先注海水，再投入鸦片，撒入生石灰搅拌，鸦片随潮水冲入大海。历时 23 天，销毁鸦片 110 多万千克。（《清史稿·林则徐传》；2024 部编版八上第 1 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"鸦片战争；鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战争的借口（直接原因）。","explain":"材料出自《清史稿·林则徐传》；2024 部编版八上第 1 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-1-2","title":"第2课 第二次鸦片战争","subtitle":"八年级上册 · 第一单元 中国开始沦为半殖民地半封建社会","grade":"8a","tags":["八年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第一单元 中国开始沦为半殖民地半封建社会"},{"k":"课时","v":"第2课 第二次鸦片战争"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"鸦片战争后，英法等国不满足既得利益，以「修约」为名再次发动战争。1856—1860 年，英法联军攻占广州、天津、北京，火烧圆明园。清政府被迫签订《天津条约》《北京条约》，中国半殖民地化程度进一步加深。"},{"type":"note","title":"本课主线 · 因果链","text":"英国为打开中国市场发动鸦片战争，中国战败签订《南京条约》，领土、关税、司法等主权开始被破坏，社会性质由封建社会开始沦为半殖民地半封建社会；第二次鸦片战争使这一程度进一步加深，而农民阶级的太平天国运动虽沉重打击了中外反动势力，却因阶级局限最终失败。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1856 年 10 月—1860 年 10 月","第二次鸦片战争","英法联军发动，是鸦片战争的继续和扩大；1858 年《天津条约》 · 重点"],["1860 年 10 月","英法联军火烧圆明园，签订《北京条约》","割九龙司地方一区给英国、增开天津为商埠、赔款增加 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1856 年 10 月—…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"第二次鸦片战争","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1860 年 10 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"英法联军火烧圆明园，签订《北京条约》","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联军 1860 年所为。","explain":"「继续」指目的相同，「扩大」指侵略范围扩大（从东南沿海到北方沿海、从五口到十一口）与侵略方式扩大（由商品输出走向更多特权）。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。","列强侵华的核心目的是把中国变成其商品市场和原料产地；《南京条约》中的**协定关税**破坏中国关税自主权，便利了列强的经济侵略。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。"]]},{"type":"table","title":"鸦片战争与第二次鸦片战争（两次侵略战争：继续与扩大）","head":["比较项","鸦片战争（1840—1842）","第二次鸦片战争（1856—1860）"],"rows":[["发动者","英国","英法联军（美、俄帮凶）"],["根本目的","打开中国市场，掠夺原料","进一步打开中国市场，扩大侵略权益"],["主要条约","《南京条约》（1842）","《天津条约》（1858）、《北京条约》（1860）"],["侵略范围","东南沿海五口","从东南沿海扩展到北方沿海，增开天津等商埠"],["对中国的影响","开始沦为半殖民地半封建社会","半殖民地化程度进一步加深"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["条约内容与影响的对应","给出条约条款原文，要求判断条约名称并说明「破坏了中国哪一方面的主权」，落脚在「半殖民地化程度如何变化」的时间线上。"],["史料实证：从鸦片输入到销烟","常用林则徐奏折、「银荒兵弱」等材料组合，要求说明禁烟的原因与虎门销烟的意义，注意区分「直接原因／根本原因」。"],["农民运动的评价","以太平天国为切口，考查「为什么农民阶级不能领导中国革命取得胜利」，答法固定：阶级局限性 + 提不出科学纲领 + 缺乏先进阶级领导。"]]},{"type":"note","title":"跨学科视角","text":"地理：沿海口岸与鸦片贸易路线；道德与法治：国家主权与民族尊严。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["火烧圆明园","1860 年英法联军焚毁圆明园，是中国近代史上的文化浩劫。","《清史稿·文宗本纪》"]]},{"type":"list","title":"延伸阅读","items":["火烧圆明园：1860 年 10 月，英法联军闯入圆明园，掠夺文物珍宝，并纵火焚烧，大火三日不熄。 出处：《清史稿·文宗本纪》；2024 部编版八上第 2 课","沙俄趁火打劫：第二次鸦片战争期间及以后，沙俄通过《瑷珲条约》《北京条约》等不平等条约，割占中国东北和西北领土 150 多万平方千米。 出处：《清史稿》；2024 部编版八上第 2 课"]},{"type":"list","title":"本课拓展出处","items":["《清史稿·文宗本纪》；《天津条约》《北京条约》原文","2024 部编版八上第 2 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8a-u1-q3","type":"choice","stem":"1860 年焚毁圆明园的侵略者是","answer":"B","explain":"第二次鸦片战争中，1860 年 10 月英法联军攻入北京，抢劫并焚毁了圆明园。八国联军侵华是 1900 年的事。","options":["英国军队","英法联军","八国联军","日本军队"],"tags":["第二次鸦片战争","时空观念"]},{"id":"cat-8a-1-2-g2","type":"choice","stem":"下列关于「第二次鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1860 年 10 月，英法联军闯入圆明园，掠夺文物珍宝，并纵火焚烧，大火三日不熄。（《清史稿·文宗本纪》；2024 部编版八上第 2 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"第二次鸦片战争；第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联军 1860 年所为。","explain":"材料出自《清史稿·文宗本纪》；2024 部编版八上第 2 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-1-2-g5","type":"choice","stem":"「第二次鸦片战争」发生于","answer":"A","explain":"本课时间轴：第二次鸦片战争（1856 年 10 月—1860 年 10 月）。英法联军发动，是鸦片战争的继续和扩大；1858 年《天津条约》。其余三个时间是同一单元相邻课时的事件时间。","options":["1856 年 10 月—1860 年 10 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-2-g6","type":"choice","stem":"下列考点中，属于「第二次鸦片战争」的是","answer":"A","explain":"本课考点（重点）：第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联军 1860 年所为。其余三项是同一单元相邻课时的考点。","options":["第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]}]},{"id":"cat-8a-1-3","title":"第3课 太平天国运动","subtitle":"八年级上册 · 第一单元 中国开始沦为半殖民地半封建社会","grade":"8a","tags":["八年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第一单元 中国开始沦为半殖民地半封建社会"},{"k":"课时","v":"第3课 太平天国运动"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"鸦片战争后，清政府赔款、增税，阶级矛盾激化。洪秀全创立拜上帝会，1851 年在广西桂平金田村起义，建号太平天国。1853 年攻占南京，定为天京，颁布《天朝田亩制度》。1864 年天京陷落，运动失败。"},{"type":"note","title":"本课主线 · 因果链","text":"英国为打开中国市场发动鸦片战争，中国战败签订《南京条约》，领土、关税、司法等主权开始被破坏，社会性质由封建社会开始沦为半殖民地半封建社会；第二次鸦片战争使这一程度进一步加深，而农民阶级的太平天国运动虽沉重打击了中外反动势力，却因阶级局限最终失败。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1851 年 1 月","洪秀全在广西桂平金田村起义，建号太平天国","1853 年攻占南京改名天京并定都，与清朝对峙 · 重点"],["1864 年","天京陷落，太平天国运动失败","此前 1856 年天京事变已使其由盛转衰"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 太平天国：从金田到天京","caption":"示意图：太平天国：从金田到天京，详见下方「历史现场」","view":"tall","alt":"示意图：太平天国：从金田到天京，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1843 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"洪秀全创立拜上帝会，在广西传教组织群…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":29.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":32.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":29.67,"text":"1851 年 1 月 1…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":35.67,"text":"金田起义爆发，建号太平天国，洪秀全称…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":36.07,"x2":14,"y2":47.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":51.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":48.33,"text":"1852 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":54.33,"text":"太平军北上，攻占永安，突围后进入湖南…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":54.73,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1853 年 3 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"攻占南京，改名天京，定为都城","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":85.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":88.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":85.67,"text":"1853—1856 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":91.67,"text":"北伐、西征，达到军事全盛","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":92.07,"x2":14,"y2":103.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":107.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":104.33,"text":"1856 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":110.33,"text":"天京事变，领导集团自相残杀，由盛转衰","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":110.73,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1864 年 7 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"湘军攻陷天京，太平天国运动失败","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1856，由盛转衰）—天京陷落（1864）；它沉重打击了清朝统治和外国侵略势力，但农民阶级不能领导中国革命取得胜利。","explain":"失败的根本原因是农民阶级的局限性：提不出科学的革命纲领，《天朝田亩制度》的绝对平均主义无法实现。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。","列强侵华的核心目的是把中国变成其商品市场和原料产地；《南京条约》中的**协定关税**破坏中国关税自主权，便利了列强的经济侵略。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。"],["认为鸦片战争是由林则徐虎门销烟引起的。","虎门销烟只是英国发动战争的借口（直接原因），根本原因是英国要打开中国市场。","材料题常设「有人说没有林则徐禁烟就不会有鸦片战争，你同意吗」，必须答根本原因与直接原因两层。"]]},{"type":"table","title":"太平天国运动与以往农民战争（中国农民战争的最高峰与新特点）","head":["比较项","以往农民战争（如明末李自成起义）","太平天国运动"],"rows":[["时代背景","封建社会的阶级矛盾","半殖民地半封建社会，肩负反侵略与反封建双重任务"],["斗争对象","封建王朝","清朝统治与外国侵略势力"],["纲领文件","「均田免赋」等口号","《天朝田亩制度》《资政新篇》"],["失败原因","流寇主义、缺乏巩固根据地","农民阶级局限性与中外反动势力联合镇压"],["共同点","都因阶级局限而失败，都沉重打击了封建统治","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["条约内容与影响的对应","给出条约条款原文，要求判断条约名称并说明「破坏了中国哪一方面的主权」，落脚在「半殖民地化程度如何变化」的时间线上。"],["史料实证：从鸦片输入到销烟","常用林则徐奏折、「银荒兵弱」等材料组合，要求说明禁烟的原因与虎门销烟的意义，注意区分「直接原因／根本原因」。"],["农民运动的评价","以太平天国为切口，考查「为什么农民阶级不能领导中国革命取得胜利」，答法固定：阶级局限性 + 提不出科学纲领 + 缺乏先进阶级领导。"]]},{"type":"note","title":"跨学科视角","text":"地理：沿海口岸与鸦片贸易路线；道德与法治：国家主权与民族尊严。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 太平天国：从金田到天京","head":["时间","经过"],"rows":[["1843 年","洪秀全创立拜上帝会，在广西传教组织群众"],["1851 年 1 月 11 日","金田起义爆发，建号太平天国，洪秀全称天王"],["1852 年","太平军北上，攻占永安，突围后进入湖南、湖北"],["1853 年 3 月","攻占南京，改名天京，定为都城"],["1853—1856 年","北伐、西征，达到军事全盛"],["1856 年","天京事变，领导集团自相残杀，由盛转衰"],["1864 年 7 月","湘军攻陷天京，太平天国运动失败"]]},{"type":"note","title":"现场解说","text":"太平天国运动是中国近代规模最大的农民战争，沉重打击了清朝统治和外国侵略势力。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["金田起义","1851 年洪秀全在广西桂平金田村发动起义，标志太平天国运动开始。","《清史稿·洪秀全传》"],["天京事变","1856 年太平天国领导集团内讧，杨秀清、韦昌辉被杀，石达开出走，运动由盛转衰。","《清史稿·洪秀全传》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"洪秀全","v":"太平天国领袖，创立拜上帝会。 出处：《清史稿·洪秀全传》"},{"k":"洪仁玕","v":"太平天国后期领导人，著《资政新篇》。 出处：《资政新篇》"}]},{"type":"list","title":"延伸阅读","items":["《天朝田亩制度》：主张按人口平均分配土地，「凡天下田，天下人同耕」，具有强烈的反封建色彩，但绝对平均主义无法实现。 出处：《天朝田亩制度》原文","《资政新篇》：洪仁玕提出学习西方，发展工商业、兴办学校、修建铁路，是近代中国最早提出的发展资本主义的方案，但未能实施。 出处：《资政新篇》原文"]},{"type":"list","title":"本课拓展出处","items":["《清史稿·洪秀全传》；《天朝田亩制度》《资政新篇》原文","2024 部编版八上第 3 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8a-u1-q4","type":"choice","stem":"太平天国运动中，标志其由盛转衰的事件是","answer":"C","explain":"1856 年的天京事变是太平天国领导集团内讧，使其由盛转衰；1864 年天京陷落标志运动失败。","options":["金田起义","定都天京","天京事变","天京陷落"],"tags":["太平天国运动","时空观念"]},{"id":"cat-8a-1-3-g2","type":"choice","stem":"下列关于「太平天国运动」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：主张按人口平均分配土地，「凡天下田，天下人同耕」，具有强烈的反封建色彩，但绝对平均主义无法实现。（《天朝田亩制度》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"太平天国运动；太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1856，由盛转衰）—天京陷落（1864）；它沉重打击了清朝统治和外国侵略势力，但农民阶级不能领导中国革命取得胜利。","explain":"材料出自《天朝田亩制度》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-1-3-g5","type":"choice","stem":"「洪秀全在广西桂平金田村起义，建号太平天国」发生于","answer":"A","explain":"本课时间轴：洪秀全在广西桂平金田村起义，建号太平天国（1851 年 1 月）。1853 年攻占南京改名天京并定都，与清朝对峙。其余三个时间是同一单元相邻课时的事件时间。","options":["1851 年 1 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g6","type":"choice","stem":"下列考点中，属于「太平天国运动」的是","answer":"A","explain":"本课考点（重点）：太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1856，由盛转衰）—天京陷落（1864）；它沉重打击了清朝统治和外国侵略势力，但农民阶级不能领导中国革命取得胜利。其余三项是同一单元相邻课时的考点。","options":["太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]}]},{"id":"cat-8a-2-1","title":"第4课 洋务运动和边疆危机","subtitle":"八年级上册 · 第二单元 早期现代化的初步探索和民族危机加剧","grade":"8a","tags":["八年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第二单元 早期现代化的初步探索和民族危机加剧"},{"k":"课时","v":"第4课 洋务运动和边疆危机"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"第二次鸦片战争后，清政府内忧外患，洋务派主张学习西方技术「自强」「求富」。19 世纪 60—90 年代，洋务运动创办军事工业和民用工业、建立新式海军、兴办新式学堂。与此同时，西北、东南边疆危机加剧。"},{"type":"note","title":"本课主线 · 因果链","text":"面对内忧外患，地主阶级洋务派以「自强」「求富」开启器物层面的近代化探索，甲午战败宣告其破产；资产阶级维新派进而尝试制度改良，戊戌变法又遭扼杀；与此同时列强侵略步步升级，从《马关条约》的资本输出到《辛丑条约》，中国完全陷入半殖民地半封建社会的深渊。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["19 世纪 60—90 年代中期","洋务运动","「自强」「求富」；创办军事工业与民用企业，筹建新式海陆军，是中国近代化的开端 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"洋务运动：以「自强」「求富」为口号，…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":34.25,"text":"洋务运动的评价：是中国近代化的开端，…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"近代化探索由表及里：洋务运动学**技…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"洋务运动：以「自强」「求富」为口号，创办安庆内军械所、江南机器制造总局、福州船政局等军事工业和轮船招商局、开平煤矿、汉阳铁厂、湖北织布局等民用企业，筹建北洋舰队等新式海陆军。","explain":"代表人物：中央奕䜣，地方曾国藩、李鸿章、左宗棠、张之洞。答「性质」：地主阶级的自救运动。"},{"level":"重点","text":"洋务运动的评价：是中国近代化的开端，引进了西方先进技术，客观上促进了中国民族资本主义的产生，对外国资本的入侵起到一定抵制作用；但只学习技术、不改变封建制度，最终破产。","explain":"「破产」的标志是甲午战争中北洋舰队全军覆没。答题务必写出「只学技术不改制度」这一根本局限。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为洋务运动是中国近代史的开端。","中国近代史的开端是鸦片战争；洋务运动是中国**近代化**的开端。","「近代史」讲社会性质变化，「近代化」讲向工业化、民主化迈进，两个概念必须分清。"],["认为北洋舰队是在黄海海战中全军覆没的。","黄海海战只是重创北洋舰队；1895 年初的威海卫战役中北洋舰队全军覆没，标志洋务运动的破产。","两场海战的结果最易互换，记「黄海海战失致远，威海卫之战全军覆没」。"]]},{"type":"table","title":"洋务运动与戊戌变法：近代化探索的两条道路（器物层面与制度层面的探索（同一阶级内部的两种主张与两个阶级的选择））","head":["比较项","洋务运动（19 世纪 60—90 年代）","戊戌变法（1898 年）"],"rows":[["领导力量","地主阶级洋务派（奕䜣、李鸿章、张之洞）","资产阶级维新派（康有为、梁启超、严复）"],["学习层面","西方先进技术（器物）","君主立宪的政治制度（制度）"],["口号/目标","「自强」「求富」，维护清朝统治","变法图强、救亡图存，发展资本主义"],["结果","甲午战败，北洋舰队全军覆没，运动破产","慈禧太后发动政变，变法失败，戊戌六君子遇害"],["失败原因","只学技术不改制度，封建制度腐朽","维新派力量弱小，依靠无实权的皇帝"],["共同启示","在半殖民地半封建社会的中国，这两个阶级都无法使中国走上富强道路","同左"]]},{"type":"table","title":"中国近代化探索与日本明治维新（中外对比：同样是「学习西方」，结果为何不同）","head":["比较项","中国（洋务运动／戊戌变法）","日本（明治维新，1868 年起）"],"rows":[["学习重点","前期只学技术，后期才触及制度且未成功","政治、经济、军事、教育全面改革，确立君主立宪"],["领导力量","地主阶级洋务派、力量弱小的维新派","倒幕派武士集团，掌握实权"],["阻碍力量","腐朽的封建制度与顽固派","通过倒幕战争推翻了幕府统治"],["结果","没有摆脱半殖民地命运","走上资本主义道路，逐渐成为亚洲强国"],["启示","改革必须触及旧制度、必须具备强有力的领导与广泛支持","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["近代化探索的「层次递进」","把洋务运动、戊戌变法、辛亥革命、新文化运动串成一张表，要求说明「学习西方的内容由浅入深」，答法是「技术→制度→思想文化」。"],["条约与侵略阶段","给出条约条款，问「反映列强侵略方式发生了什么变化」，标准答法是「由商品输出为主转向资本输出为主」。"],["改革的评价与教训","以戊戌变法为切口考「改革为什么失败、给我们什么启示」，踩分点是阶级力量对比与「改良道路行不通」。"]]},{"type":"note","title":"跨学科视角","text":"语文：近代报刊与变法言论；道德与法治：改革与制度变革。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["自强、求富","洋务运动前后期口号，前期以「自强」办军事工业，后期以「求富」办民用工业。","2024 部编版八上第 4 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"李鸿章","v":"洋务派代表人物，创办江南制造总局、轮船招商局等。 出处：《清史稿·李鸿章传》"},{"k":"左宗棠","v":"洋务派代表，收复新疆。 出处：《清史稿·左宗棠传》"}]},{"type":"list","title":"延伸阅读","items":["主要洋务企业：军事工业有安庆内军械所、江南机器制造总局、福州船政局；民用工业有轮船招商局、开平煤矿、汉阳铁厂、湖北织布局。 出处：2024 部编版八上第 4 课","左宗棠收复新疆：1876 年左宗棠率军西征，采取「先北后南、缓进急战」方针，1878 年收复新疆大部分地区，1884 年清政府在新疆建立行省。 出处：《清史稿·左宗棠传》"]},{"type":"list","title":"本课拓展出处","items":["《清史稿·李鸿章传》；《李文忠公全书》","2024 部编版八上第 4 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 近代化探索的四步走（附中外对比：明治维新）","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-02"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】中国文武制度，事事远出西人之上，独火器万不能及。——李鸿章《李文忠公全书》\n【材料二】法者天下之公器也，变者天下之公理也。——梁启超《变法通议》\n【材料三】《马关条约》规定：中国割辽东半岛、台湾全岛及所有附属各岛屿、澎湖列岛给日本；赔款白银二亿两；开放沙市、重庆、苏州、杭州为商埠；允许日本在中国通商口岸开设工厂。","source":"材料研读 · 近代化的早期探索与民族危机的加剧"}],"questions":[{"id":"h8a-u2-m1-q1","type":"short","stem":"（1）材料一反映了洋务派的什么主张？依据材料一、二说明这一主张在甲午战后为什么被国人普遍质疑。（6 分）","answer":"主张：认为中国的政治制度和文教制度远胜西方，只是在武器技术上不如人，因此主张「师夷长技」，只学习西方先进技术而不改变封建制度。被质疑的原因：甲午中日战争中国战败、北洋舰队全军覆没，说明单靠引进洋枪洋炮、创办近代军事工业，并不能挽救民族危亡；而材料二梁启超主张「变者天下之公理也」，认为必须变革制度。可见洋务运动「只学技术、不改制度」的道路走不通，必须进行制度变革。","explain":"","tags":["洋务运动","历史解释"],"rubric":["答出「只学技术」的主张","答出甲午战败、北洋舰队覆没","答出洋务运动破产","答出必须变革制度"]},{"id":"h8a-u2-q1","type":"choice","stem":"洋务运动「只学习西方技术而不改变封建制度」，导致其最终破产。标志其破产的事件是","answer":"B","explain":"1895 年初威海卫战役中北洋舰队全军覆没，甲午战争中国战败，宣告了洋务运动的破产，也说明单靠引进技术不能救中国。","options":["太平天国运动失败","甲午中日战争中国战败、北洋舰队全军覆没","《辛丑条约》的签订","戊戌变法失败"],"tags":["洋务运动","历史解释"]},{"id":"h8a-u2-q3","type":"choice","stem":"「法者天下之公器也，变者天下之公理也」的提出者，也是戊戌变法主要领导人之一的是","answer":"B","explain":"此语出自梁启超《变法通议》。梁启超与康有为是维新变法的主要领导人，严复译述《天演论》宣传进化论，李鸿章是洋务派代表。","options":["李鸿章","梁启超","严复","孙中山"],"tags":["戊戌变法","历史解释"]},{"id":"cat-8a-2-1-g2","type":"choice","stem":"下列关于「洋务运动和边疆危机」的表述，错误的是","answer":"A","explain":"认为洋务运动是中国近代史的开端——「近代史」讲社会性质变化，「近代化」讲向工业化、民主化迈进，两个概念必须分清。正确表述：中国近代史的开端是鸦片战争；洋务运动是中国**近代化**的开端。","options":["认为洋务运动是中国近代史的开端。","中国近代史的开端是鸦片战争；洋务运动是中国**近代化**的开端。","近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","洋务运动：以「自强」「求富」为口号，创办安庆内军械所、江南机器制造总局、福州船政局等军事工业和轮船招商局、开平煤矿、汉阳铁厂、湖北织布局等民用企业，筹建北洋舰队等新式海陆军。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-1-g3","type":"choice","stem":"下列结论中，属于「洋务运动和边疆危机」的是","answer":"A","explain":"本课结论：近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","《马关条约》允许日本在通商口岸开设工厂，标志列强对华侵略**由以商品输出为主转向以资本输出为主**，中国的民族危机空前严重。","改革要顺应历史潮流并依靠可靠的力量：戊戌变法失败说明**资产阶级改良道路在中国行不通**，这为后来辛亥革命用暴力推翻清政府提供了历史教训。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：军事工业有安庆内军械所、江南机器制造总局、福州船政局；民用工业有轮船招商局、开平煤矿、汉阳铁厂、湖北织布局。（2024 部编版八上第 4 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"洋务运动和边疆危机；洋务运动：以「自强」「求富」为口号，创办安庆内军械所、江南机器制造总局、福州船政局等军事工业和轮船招商局、开平煤矿、汉阳铁厂、湖北织布局等民用企业，筹建北洋舰队等新式海陆军。","explain":"材料出自2024 部编版八上第 4 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-2-2","title":"第5课 甲午中日战争与列强瓜分中国狂潮","subtitle":"八年级上册 · 第二单元 早期现代化的初步探索和民族危机加剧","grade":"8a","tags":["八年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第二单元 早期现代化的初步探索和民族危机加剧"},{"k":"课时","v":"第5课 甲午中日战争与列强瓜分中国狂潮"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1894 年，日本发动侵华战争。9 月黄海海战中，致远舰管带邓世昌壮烈殉国。1895 年，清政府战败，签订《马关条约》，割让台湾、澎湖列岛，赔款二亿两白银。此后列强掀起瓜分中国的狂潮。"},{"type":"note","title":"本课主线 · 因果链","text":"面对内忧外患，地主阶级洋务派以「自强」「求富」开启器物层面的近代化探索，甲午战败宣告其破产；资产阶级维新派进而尝试制度改良，戊戌变法又遭扼杀；与此同时列强侵略步步升级，从《马关条约》的资本输出到《辛丑条约》，中国完全陷入半殖民地半封建社会的深渊。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1894 年 7 月—1895 年 4 月","甲午中日战争","1894 年 9 月黄海海战中邓世昌壮烈殉国；1895 年初威海卫战役北洋舰队全军覆没 · 重点"],["1895 年 4 月","《马关条约》签订","割辽东半岛、台湾全岛及所有附属各岛屿、澎湖列岛；赔款 2 亿两白银；开沙市、重庆、苏州、杭州为商埠；允许日本在通商口岸开设工厂 · 重点"],["1895 年","康有为、梁启超等发起公车上书","因《马关条约》签订而起，揭开了维新变法运动的序幕"],["1901 年","《辛丑条约》签订","赔款 4.5 亿两白银、划定使馆界、拆毁大沽炮台、清政府保证严禁人民参加反帝活动——中国完全陷入半殖民地半封建社会的深渊 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1894 年 7 月—1…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"甲午中日战争","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"1895 年 4 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"《马关条约》签订","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"1895 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"康有为、梁启超等发起公车上书","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1901 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"《辛丑条约》签订","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"洋务运动的评价：是中国近代化的开端，引进了西方先进技术，客观上促进了中国民族资本主义的产生，对外国资本的入侵起到一定抵制作用；但只学习技术、不改变封建制度，最终破产。","explain":"「破产」的标志是甲午战争中北洋舰队全军覆没。答题务必写出「只学技术不改制度」这一根本局限。"},{"level":"重点","text":"《马关条约》的内容与影响：割辽东半岛、台湾全岛及所有附属各岛屿、澎湖列岛；赔款 2 亿两白银；开放沙市、重庆、苏州、杭州为商埠；允许日本在通商口岸开设工厂。它使中国半殖民地化程度大大加深，列强掀起瓜分中国的狂潮。","explain":"「允许日本在通商口岸开设工厂」是重点中的重点：标志列强侵华由以商品输出为主转向以资本输出为主。"},{"level":"重点","text":"《辛丑条约》的内容与影响：清政府赔款白银 4.5 亿两，分 39 年还清，本息共约 9.8 亿两；清政府保证严禁人民参加各种形式的反帝活动；拆毁大沽炮台，允许外国军队驻扎从北京到山海关铁路沿线要地；划定北京东交民巷为使馆界，允许各国派兵驻守，不准中国人居住；改总理衙门为外务部，班列六部之前。","explain":"核心记忆点：赔款最多、禁止人民反帝、驻兵权、使馆界。影响：中国完全陷入半殖民地半封建社会的深渊，清政府成为「洋人的朝廷」。"},{"level":"选择题","text":"黄海海战中邓世昌率致远舰冲锋殉国；威海卫战役中北洋舰队全军覆没，丁汝昌自杀殉国。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","《马关条约》允许日本在通商口岸开设工厂，标志列强对华侵略**由以商品输出为主转向以资本输出为主**，中国的民族危机空前严重。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为北洋舰队是在黄海海战中全军覆没的。","黄海海战只是重创北洋舰队；1895 年初的威海卫战役中北洋舰队全军覆没，标志洋务运动的破产。","两场海战的结果最易互换，记「黄海海战失致远，威海卫之战全军覆没」。"],["把「允许日本在通商口岸开设工厂」记成《南京条约》或《辛丑条约》的内容。","它出自 1895 年《马关条约》，是列强侵华由商品输出为主转向资本输出为主的标志。","这是条约内容与「侵略阶段变化」结合最紧的一条，材料题常据此问「侵略方式发生了什么变化」。"]]},{"type":"table","title":"洋务运动与戊戌变法：近代化探索的两条道路（器物层面与制度层面的探索（同一阶级内部的两种主张与两个阶级的选择））","head":["比较项","洋务运动（19 世纪 60—90 年代）","戊戌变法（1898 年）"],"rows":[["领导力量","地主阶级洋务派（奕䜣、李鸿章、张之洞）","资产阶级维新派（康有为、梁启超、严复）"],["学习层面","西方先进技术（器物）","君主立宪的政治制度（制度）"],["口号/目标","「自强」「求富」，维护清朝统治","变法图强、救亡图存，发展资本主义"],["结果","甲午战败，北洋舰队全军覆没，运动破产","慈禧太后发动政变，变法失败，戊戌六君子遇害"],["失败原因","只学技术不改制度，封建制度腐朽","维新派力量弱小，依靠无实权的皇帝"],["共同启示","在半殖民地半封建社会的中国，这两个阶级都无法使中国走上富强道路","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["近代化探索的「层次递进」","把洋务运动、戊戌变法、辛亥革命、新文化运动串成一张表，要求说明「学习西方的内容由浅入深」，答法是「技术→制度→思想文化」。"],["条约与侵略阶段","给出条约条款，问「反映列强侵略方式发生了什么变化」，标准答法是「由商品输出为主转向资本输出为主」。"],["改革的评价与教训","以戊戌变法为切口考「改革为什么失败、给我们什么启示」，踩分点是阶级力量对比与「改良道路行不通」。"]]},{"type":"note","title":"跨学科视角","text":"语文：近代报刊与变法言论；道德与法治：改革与制度变革。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["此日漫挥天下泪，有公足壮海军威","光绪帝为邓世昌所撰挽联，高度评价其殉国壮举。","2024 部编版八上第 5 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"邓世昌","v":"北洋舰队致远舰管带，黄海海战中壮烈殉国。 出处：《清史稿·邓世昌传》"}]},{"type":"list","title":"延伸阅读","items":["黄海海战：1894 年 9 月 17 日，北洋舰队与日本联合舰队在黄海大东沟激战五小时，致远舰弹尽，邓世昌下令撞向日舰吉野，中鱼雷沉没，全舰官兵壮烈殉国。 出处：《清史稿·邓世昌传》","《马关条约》的影响：割地、赔款、开埠、允许日本在通商口岸开设工厂，大大加深了中国的半殖民地化程度，刺激了列强瓜分中国的野心。 出处：《马关条约》原文；2024 部编版八上第 5 课"]},{"type":"list","title":"本课拓展出处","items":["《清史稿·邓世昌传》；《马关条约》原文","2024 部编版八上第 5 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 近代化探索的四步走（附中外对比：明治维新）","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-02"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】中国文武制度，事事远出西人之上，独火器万不能及。——李鸿章《李文忠公全书》\n【材料二】法者天下之公器也，变者天下之公理也。——梁启超《变法通议》\n【材料三】《马关条约》规定：中国割辽东半岛、台湾全岛及所有附属各岛屿、澎湖列岛给日本；赔款白银二亿两；开放沙市、重庆、苏州、杭州为商埠；允许日本在中国通商口岸开设工厂。","source":"材料研读 · 近代化的早期探索与民族危机的加剧"}],"questions":[{"id":"h8a-u2-m1-q1","type":"short","stem":"（1）材料一反映了洋务派的什么主张？依据材料一、二说明这一主张在甲午战后为什么被国人普遍质疑。（6 分）","answer":"主张：认为中国的政治制度和文教制度远胜西方，只是在武器技术上不如人，因此主张「师夷长技」，只学习西方先进技术而不改变封建制度。被质疑的原因：甲午中日战争中国战败、北洋舰队全军覆没，说明单靠引进洋枪洋炮、创办近代军事工业，并不能挽救民族危亡；而材料二梁启超主张「变者天下之公理也」，认为必须变革制度。可见洋务运动「只学技术、不改制度」的道路走不通，必须进行制度变革。","explain":"","tags":["洋务运动","历史解释"],"rubric":["答出「只学技术」的主张","答出甲午战败、北洋舰队覆没","答出洋务运动破产","答出必须变革制度"]},{"id":"h8a-u2-m1-q2","type":"short","stem":"（2）依据材料三并结合所学，说明「允许日本在中国通商口岸开设工厂」这一条款反映了列强侵华方式的什么变化，并指出《马关条约》对中国的影响。（6 分）","answer":"变化：反映列强侵华由以商品输出为主转向以资本输出为主。此前列强主要通过倾销商品、掠夺原料牟利，此后纷纷在中国开设工厂、修筑铁路、开采矿山、开设银行，直接利用中国的原料和廉价劳动力。影响：《马关条约》使中国的领土和主权进一步遭到破坏，半殖民地化程度大大加深；列强掀起瓜分中国的狂潮，民族危机空前严重；同时也刺激了中国人民的救亡图存运动。","explain":"","tags":["马关条约","资本输出"],"rubric":["答出由商品输出为主转向资本输出为主","答出开设工厂/修路开矿等具体表现","答出半殖民地化程度大大加深","答出瓜分中国狂潮/民族危机加深"]},{"id":"h8a-u2-q1","type":"choice","stem":"洋务运动「只学习西方技术而不改变封建制度」，导致其最终破产。标志其破产的事件是","answer":"B","explain":"1895 年初威海卫战役中北洋舰队全军覆没，甲午战争中国战败，宣告了洋务运动的破产，也说明单靠引进技术不能救中国。","options":["太平天国运动失败","甲午中日战争中国战败、北洋舰队全军覆没","《辛丑条约》的签订","戊戌变法失败"],"tags":["洋务运动","历史解释"]},{"id":"h8a-u2-q2","type":"choice","stem":"标志列强对华经济侵略由以商品输出为主转向以资本输出为主的不平等条约条款是","answer":"B","explain":"允许在通商口岸开设工厂，意味着列强可以直接利用中国的原料和劳动力进行生产，是资本输出的典型方式，故《马关条约》是这一转变的标志。","options":["《南京条约》中的协定关税","《马关条约》中允许日本在通商口岸开设工厂","《辛丑条约》中的巨额赔款","《北京条约》中的增开天津为商埠"],"tags":["马关条约","资本输出"]},{"id":"h8a-u2-q4","type":"choice","stem":"《辛丑条约》中，最能说明清政府已成为「洋人的朝廷」的条款是","answer":"C","explain":"「保证严禁人民参加反帝活动」意味着清政府由中国的政权机构变成列强镇压中国人民的工具，故称「洋人的朝廷」，标志中国完全陷入半殖民地半封建社会的深渊。","options":["赔款白银 4.5 亿两","划定北京东交民巷为使馆界","清政府保证严禁人民参加各种形式的反帝活动","拆毁大沽炮台"],"tags":["辛丑条约","历史解释"]},{"id":"cat-8a-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 甲午中日战争\n② 《马关条约》签订\n③ 康有为、梁启超等发起公车上书\n④ 《辛丑条约》签订","answer":"A","explain":"按时间顺序应为：①甲午中日战争（1894 年 7 月—1895 年 4 月）→②《马关条约》签订（1895 年 4 月）→③康有为、梁启超等发起公车上书（1895 年）→④《辛丑条约》签订（1901 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-2-g2","type":"choice","stem":"下列关于「甲午中日战争与列强瓜分中国狂潮」的表述，错误的是","answer":"A","explain":"认为北洋舰队是在黄海海战中全军覆没的——两场海战的结果最易互换，记「黄海海战失致远，威海卫之战全军覆没」。正确表述：黄海海战只是重创北洋舰队；1895 年初的威海卫战役中北洋舰队全军覆没，标志洋务运动的破产。","options":["认为北洋舰队是在黄海海战中全军覆没的。","黄海海战只是重创北洋舰队；1895 年初的威海卫战役中北洋舰队全军覆没，标志洋务运动的破产。","甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","《马关条约》允许日本在通商口岸开设工厂，标志列强对华侵略**由以商品输出为主转向以资本输出为主**，中国的民族危机空前严重。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-2-g3","type":"choice","stem":"下列结论中，属于「甲午中日战争与列强瓜分中国狂潮」的是","answer":"A","explain":"本课结论：甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","改革要顺应历史潮流并依靠可靠的力量：戊戌变法失败说明**资产阶级改良道路在中国行不通**，这为后来辛亥革命用暴力推翻清政府提供了历史教训。","《辛丑条约》使中国**完全陷入半殖民地半封建社会的深渊**，清政府完全成为帝国主义统治中国的工具，中国人民必须推翻清政府的反动统治才能救亡图存。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1894 年 9 月 17 日，北洋舰队与日本联合舰队在黄海大东沟激战五小时，致远舰弹尽，邓世昌下令撞向日舰吉野，中鱼雷沉没，全舰官兵壮烈殉国。（《清史稿·邓世昌传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"甲午中日战争与列强瓜分中国狂潮；洋务运动的评价：是中国近代化的开端，引进了西方先进技术，客观上促进了中国民族资本主义的产生，对外国资本的入侵起到一定抵制作用；但只学习技术、不改变封建制度，最终破产。","explain":"材料出自《清史稿·邓世昌传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-2-3","title":"第6课 戊戌变法","subtitle":"八年级上册 · 第二单元 早期现代化的初步探索和民族危机加剧","grade":"8a","tags":["八年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第二单元 早期现代化的初步探索和民族危机加剧"},{"k":"课时","v":"第6课 戊戌变法"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"《马关条约》签订后，民族危机空前严重。1895 年康有为、梁启超发动「公车上书」，请求变法。1898 年 6 月 11 日，光绪帝颁布「明定国是」诏书，推行变法，历时 103 天，因慈禧太后发动政变而失败。"},{"type":"note","title":"本课主线 · 因果链","text":"面对内忧外患，地主阶级洋务派以「自强」「求富」开启器物层面的近代化探索，甲午战败宣告其破产；资产阶级维新派进而尝试制度改良，戊戌变法又遭扼杀；与此同时列强侵略步步升级，从《马关条约》的资本输出到《辛丑条约》，中国完全陷入半殖民地半封建社会的深渊。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1895 年","康有为、梁启超等发起公车上书","因《马关条约》签订而起，揭开了维新变法运动的序幕"],["1898 年 6—9 月","百日维新（戊戌变法）","6 月 11 日光绪帝颁布「明定国是」诏书，9 月 21 日慈禧太后发动政变，变法失败，谭嗣同等戊戌六君子遇害 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1895 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"康有为、梁启超等发起公车上书","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1898 年 6—9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"百日维新（戊戌变法）","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"戊戌变法：公车上书揭开序幕，百日维新推行政治、经济、军事、文教方面的改革；它是中国政治近代化的开端，在思想文化方面产生了广泛而持久的影响。","explain":"失败原因：以慈禧太后为首的顽固派势力强大，维新派力量弱小、把希望寄托在没有实权的皇帝身上。教训：资产阶级改良道路在半殖民地半封建社会的中国行不通。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","改革要顺应历史潮流并依靠可靠的力量：戊戌变法失败说明**资产阶级改良道路在中国行不通**，这为后来辛亥革命用暴力推翻清政府提供了历史教训。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把公车上书与百日维新混为一谈。","公车上书（1895 年）揭开了维新变法运动的序幕；百日维新（1898 年 6—9 月）是变法的实际推行阶段。","时间与性质不同，问「变法开始的标志」要答百日维新，问「序幕」才答公车上书。"]]},{"type":"table","title":"洋务运动与戊戌变法：近代化探索的两条道路（器物层面与制度层面的探索（同一阶级内部的两种主张与两个阶级的选择））","head":["比较项","洋务运动（19 世纪 60—90 年代）","戊戌变法（1898 年）"],"rows":[["领导力量","地主阶级洋务派（奕䜣、李鸿章、张之洞）","资产阶级维新派（康有为、梁启超、严复）"],["学习层面","西方先进技术（器物）","君主立宪的政治制度（制度）"],["口号/目标","「自强」「求富」，维护清朝统治","变法图强、救亡图存，发展资本主义"],["结果","甲午战败，北洋舰队全军覆没，运动破产","慈禧太后发动政变，变法失败，戊戌六君子遇害"],["失败原因","只学技术不改制度，封建制度腐朽","维新派力量弱小，依靠无实权的皇帝"],["共同启示","在半殖民地半封建社会的中国，这两个阶级都无法使中国走上富强道路","同左"]]},{"type":"table","title":"中国近代化探索与日本明治维新（中外对比：同样是「学习西方」，结果为何不同）","head":["比较项","中国（洋务运动／戊戌变法）","日本（明治维新，1868 年起）"],"rows":[["学习重点","前期只学技术，后期才触及制度且未成功","政治、经济、军事、教育全面改革，确立君主立宪"],["领导力量","地主阶级洋务派、力量弱小的维新派","倒幕派武士集团，掌握实权"],["阻碍力量","腐朽的封建制度与顽固派","通过倒幕战争推翻了幕府统治"],["结果","没有摆脱半殖民地命运","走上资本主义道路，逐渐成为亚洲强国"],["启示","改革必须触及旧制度、必须具备强有力的领导与广泛支持","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["近代化探索的「层次递进」","把洋务运动、戊戌变法、辛亥革命、新文化运动串成一张表，要求说明「学习西方的内容由浅入深」，答法是「技术→制度→思想文化」。"],["条约与侵略阶段","给出条约条款，问「反映列强侵略方式发生了什么变化」，标准答法是「由商品输出为主转向资本输出为主」。"],["改革的评价与教训","以戊戌变法为切口考「改革为什么失败、给我们什么启示」，踩分点是阶级力量对比与「改良道路行不通」。"]]},{"type":"note","title":"跨学科视角","text":"语文：近代报刊与变法言论；道德与法治：改革与制度变革。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["公车上书","1895 年康有为、梁启超联合各省举人上书光绪帝，反对签订《马关条约》，请求变法。","梁启超《戊戌政变记》"],["我自横刀向天笑，去留肝胆两昆仑","谭嗣同狱中题壁诗句，表达为变法献身的决心。","谭嗣同《狱中题壁》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"康有为","v":"维新派领袖，发起公车上书，主持变法。 出处：梁启超《戊戌政变记》"},{"k":"梁启超","v":"维新派思想家，著《变法通议》。 出处：梁启超《戊戌政变记》"},{"k":"谭嗣同","v":"戊戌六君子之一，变法失败后拒绝出逃，慷慨就义。 出处：《清史稿·德宗本纪》；谭嗣同《狱中题壁》"}]},{"type":"list","title":"延伸阅读","items":["百日维新的内容：政治上裁撤冗官、允许官民上书言事；经济上鼓励私人兴办工矿企业；文化上废八股、办新式学堂；军事上训练新式军队。 出处：梁启超《戊戌政变记》","戊戌六君子：慈禧发动政变后，谭嗣同、林旭、杨锐、杨深秀、刘光第、康广仁被杀害，史称「戊戌六君子」。 出处：梁启超《戊戌政变记》；《清史稿·德宗本纪》"]},{"type":"list","title":"本课拓展出处","items":["梁启超《戊戌政变记》；《清史稿·德宗本纪》","2024 部编版八上第 6 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 近代化探索的四步走（附中外对比：明治维新）","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-02"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】中国文武制度，事事远出西人之上，独火器万不能及。——李鸿章《李文忠公全书》\n【材料二】法者天下之公器也，变者天下之公理也。——梁启超《变法通议》\n【材料三】《马关条约》规定：中国割辽东半岛、台湾全岛及所有附属各岛屿、澎湖列岛给日本；赔款白银二亿两；开放沙市、重庆、苏州、杭州为商埠；允许日本在中国通商口岸开设工厂。","source":"材料研读 · 近代化的早期探索与民族危机的加剧"}],"questions":[{"id":"h8a-u2-q1","type":"choice","stem":"洋务运动「只学习西方技术而不改变封建制度」，导致其最终破产。标志其破产的事件是","answer":"B","explain":"1895 年初威海卫战役中北洋舰队全军覆没，甲午战争中国战败，宣告了洋务运动的破产，也说明单靠引进技术不能救中国。","options":["太平天国运动失败","甲午中日战争中国战败、北洋舰队全军覆没","《辛丑条约》的签订","戊戌变法失败"],"tags":["洋务运动","历史解释"]},{"id":"h8a-u2-q3","type":"choice","stem":"「法者天下之公器也，变者天下之公理也」的提出者，也是戊戌变法主要领导人之一的是","answer":"B","explain":"此语出自梁启超《变法通议》。梁启超与康有为是维新变法的主要领导人，严复译述《天演论》宣传进化论，李鸿章是洋务派代表。","options":["李鸿章","梁启超","严复","孙中山"],"tags":["戊戌变法","历史解释"]},{"id":"cat-8a-2-3-g2","type":"choice","stem":"下列关于「戊戌变法」的表述，错误的是","answer":"A","explain":"把公车上书与百日维新混为一谈——时间与性质不同，问「变法开始的标志」要答百日维新，问「序幕」才答公车上书。正确表述：公车上书（1895 年）揭开了维新变法运动的序幕；百日维新（1898 年 6—9 月）是变法的实际推行阶段。","options":["把公车上书与百日维新混为一谈。","公车上书（1895 年）揭开了维新变法运动的序幕；百日维新（1898 年 6—9 月）是变法的实际推行阶段。","近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","改革要顺应历史潮流并依靠可靠的力量：戊戌变法失败说明**资产阶级改良道路在中国行不通**，这为后来辛亥革命用暴力推翻清政府提供了历史教训。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-3-g3","type":"choice","stem":"下列结论中，属于「戊戌变法」的是","answer":"A","explain":"本课结论：近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","《马关条约》允许日本在通商口岸开设工厂，标志列强对华侵略**由以商品输出为主转向以资本输出为主**，中国的民族危机空前严重。","《辛丑条约》使中国**完全陷入半殖民地半封建社会的深渊**，清政府完全成为帝国主义统治中国的工具，中国人民必须推翻清政府的反动统治才能救亡图存。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：政治上裁撤冗官、允许官民上书言事；经济上鼓励私人兴办工矿企业；文化上废八股、办新式学堂；军事上训练新式军队。（梁启超《戊戌政变记》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"戊戌变法；戊戌变法：公车上书揭开序幕，百日维新推行政治、经济、军事、文教方面的改革；它是中国政治近代化的开端，在思想文化方面产生了广泛而持久的影响。","explain":"材料出自梁启超《戊戌政变记》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-2-4","title":"第7课 义和团运动和八国联军侵华","subtitle":"八年级上册 · 第二单元 早期现代化的初步探索和民族危机加剧","grade":"8a","tags":["八年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第二单元 早期现代化的初步探索和民族危机加剧"},{"k":"课时","v":"第7课 义和团运动和八国联军侵华"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"19 世纪末，反洋教斗争高涨，义和团在山东、直隶兴起，提出「扶清灭洋」。1900 年，英、美、法、德、俄、日、意、奥八国联军侵华，攻占北京。1901 年清政府被迫签订《辛丑条约》，中国完全陷入半殖民地半封建社会的深渊。"},{"type":"note","title":"本课主线 · 因果链","text":"面对内忧外患，地主阶级洋务派以「自强」「求富」开启器物层面的近代化探索，甲午战败宣告其破产；资产阶级维新派进而尝试制度改良，戊戌变法又遭扼杀；与此同时列强侵略步步升级，从《马关条约》的资本输出到《辛丑条约》，中国完全陷入半殖民地半封建社会的深渊。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1899—1900 年","义和团运动","以「扶清灭洋」为口号，抗击八国联军，具有强烈的反帝爱国精神，也有盲目排外的局限"],["1900 年","八国联军侵华","攻占北京，清政府被迫于 1901 年签订《辛丑条约》"],["1901 年","《辛丑条约》签订","赔款 4.5 亿两白银、划定使馆界、拆毁大沽炮台、清政府保证严禁人民参加反帝活动——中国完全陷入半殖民地半封建社会的深渊 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1899—1900 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"义和团运动","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1900 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"八国联军侵华","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1901 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"《辛丑条约》签订","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"《辛丑条约》的内容与影响：清政府赔款白银 4.5 亿两，分 39 年还清，本息共约 9.8 亿两；清政府保证严禁人民参加各种形式的反帝活动；拆毁大沽炮台，允许外国军队驻扎从北京到山海关铁路沿线要地；划定北京东交民巷为使馆界，允许各国派兵驻守，不准中国人居住；改总理衙门为外务部，班列六部之前。","explain":"核心记忆点：赔款最多、禁止人民反帝、驻兵权、使馆界。影响：中国完全陷入半殖民地半封建社会的深渊，清政府成为「洋人的朝廷」。"},{"level":"次重点","text":"义和团运动的口号「扶清灭洋」：具有强烈的反帝爱国精神，能广泛动员群众；但「扶清」放松了对清政府的警惕，「灭洋」带有盲目排外的落后性。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["《辛丑条约》使中国**完全陷入半殖民地半封建社会的深渊**，清政府完全成为帝国主义统治中国的工具，中国人民必须推翻清政府的反动统治才能救亡图存。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把「允许日本在通商口岸开设工厂」记成《南京条约》或《辛丑条约》的内容。","它出自 1895 年《马关条约》，是列强侵华由商品输出为主转向资本输出为主的标志。","这是条约内容与「侵略阶段变化」结合最紧的一条，材料题常据此问「侵略方式发生了什么变化」。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["近代化探索的「层次递进」","把洋务运动、戊戌变法、辛亥革命、新文化运动串成一张表，要求说明「学习西方的内容由浅入深」，答法是「技术→制度→思想文化」。"],["条约与侵略阶段","给出条约条款，问「反映列强侵略方式发生了什么变化」，标准答法是「由商品输出为主转向资本输出为主」。"],["改革的评价与教训","以戊戌变法为切口考「改革为什么失败、给我们什么启示」，踩分点是阶级力量对比与「改良道路行不通」。"]]},{"type":"note","title":"跨学科视角","text":"语文：近代报刊与变法言论；道德与法治：改革与制度变革。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["扶清灭洋","义和团口号，既反映反帝愿望，也带有对清政府认识不清的局限。","2024 部编版八上第 7 课"]]},{"type":"list","title":"延伸阅读","items":["《辛丑条约》主要内容：赔款白银 4.5 亿两，分 39 年还清，本息共约 9.8 亿两；划定北京东交民巷为使馆界，允许各国驻兵；拆毁大沽炮台，允许列强在从北京到山海关铁路沿线驻兵；严禁人民参加反帝活动。 出处：《辛丑条约》原文","义和团的两面性：义和团具有强烈的反帝爱国精神，但也带有盲目排外色彩，如拆毁铁路、电线，攻击教民，反映农民阶级的局限性。 出处：2024 部编版八上第 7 课"]},{"type":"list","title":"本课拓展出处","items":["《清史稿·德宗本纪》；《辛丑条约》原文","2024 部编版八上第 7 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 近代化探索的四步走（附中外对比：明治维新）","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-02"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8a-u2-q1","type":"choice","stem":"洋务运动「只学习西方技术而不改变封建制度」，导致其最终破产。标志其破产的事件是","answer":"B","explain":"1895 年初威海卫战役中北洋舰队全军覆没，甲午战争中国战败，宣告了洋务运动的破产，也说明单靠引进技术不能救中国。","options":["太平天国运动失败","甲午中日战争中国战败、北洋舰队全军覆没","《辛丑条约》的签订","戊戌变法失败"],"tags":["洋务运动","历史解释"]},{"id":"h8a-u2-q2","type":"choice","stem":"标志列强对华经济侵略由以商品输出为主转向以资本输出为主的不平等条约条款是","answer":"B","explain":"允许在通商口岸开设工厂，意味着列强可以直接利用中国的原料和劳动力进行生产，是资本输出的典型方式，故《马关条约》是这一转变的标志。","options":["《南京条约》中的协定关税","《马关条约》中允许日本在通商口岸开设工厂","《辛丑条约》中的巨额赔款","《北京条约》中的增开天津为商埠"],"tags":["马关条约","资本输出"]},{"id":"h8a-u2-q4","type":"choice","stem":"《辛丑条约》中，最能说明清政府已成为「洋人的朝廷」的条款是","answer":"C","explain":"「保证严禁人民参加反帝活动」意味着清政府由中国的政权机构变成列强镇压中国人民的工具，故称「洋人的朝廷」，标志中国完全陷入半殖民地半封建社会的深渊。","options":["赔款白银 4.5 亿两","划定北京东交民巷为使馆界","清政府保证严禁人民参加各种形式的反帝活动","拆毁大沽炮台"],"tags":["辛丑条约","历史解释"]},{"id":"h8a-u2-q5","type":"choice","stem":"义和团运动提出「扶清灭洋」的口号，对这一口号的正确评价是","answer":"B","explain":"「灭洋」反映了反对帝国主义侵略的强烈愿望，能够广泛动员群众；「扶清」放松了对清政府的警惕，「灭洋」又带有笼统排外的落后性。义和团始终是农民自发的反帝斗争组织。","options":["完全正确，体现了坚定的反帝立场","具有强烈的反帝爱国精神，但也带有盲目排外的落后性","是错误的，因为义和团反对一切外来事物","说明义和团已成为资产阶级革命团体"],"tags":["义和团运动","唯物史观"]},{"id":"cat-8a-2-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 义和团运动\n② 八国联军侵华\n③ 《辛丑条约》签订","answer":"A","explain":"按时间顺序应为：①义和团运动（1899—1900 年）→②八国联军侵华（1900 年）→③《辛丑条约》签订（1901 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-4-g2","type":"choice","stem":"下列关于「义和团运动和八国联军侵华」的表述，错误的是","answer":"A","explain":"把「允许日本在通商口岸开设工厂」记成《南京条约》或《辛丑条约》的内容——这是条约内容与「侵略阶段变化」结合最紧的一条，材料题常据此问「侵略方式发生了什么变化」。正确表述：它出自 1895 年《马关条约》，是列强侵华由商品输出为主转向资本输出为主的标志。","options":["把「允许日本在通商口岸开设工厂」记成《南京条约》或《辛丑条约》的内容。","它出自 1895 年《马关条约》，是列强侵华由商品输出为主转向资本输出为主的标志。","《辛丑条约》使中国**完全陷入半殖民地半封建社会的深渊**，清政府完全成为帝国主义统治中国的工具，中国人民必须推翻清政府的反动统治才能救亡图存。","《辛丑条约》的内容与影响：清政府赔款白银 4.5 亿两，分 39 年还清，本息共约 9.8 亿两；清政府保证严禁人民参加各种形式的反帝活动；拆毁大沽炮台，允许外国军队驻扎从北京到山海关铁路沿线要地；划定北京东交民巷为使馆界，允许各国派兵驻守，不准中国人居住；改总理衙门为外务部，班列六部之前。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-4-g3","type":"choice","stem":"下列结论中，属于「义和团运动和八国联军侵华」的是","answer":"A","explain":"本课结论：《辛丑条约》使中国**完全陷入半殖民地半封建社会的深渊**，清政府完全成为帝国主义统治中国的工具，中国人民必须推翻清政府的反动统治才能救亡图存。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["《辛丑条约》使中国**完全陷入半殖民地半封建社会的深渊**，清政府完全成为帝国主义统治中国的工具，中国人民必须推翻清政府的反动统治才能救亡图存。","近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","《马关条约》允许日本在通商口岸开设工厂，标志列强对华侵略**由以商品输出为主转向以资本输出为主**，中国的民族危机空前严重。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：赔款白银 4.5 亿两，分 39 年还清，本息共约 9.8 亿两；划定北京东交民巷为使馆界，允许各国驻兵；拆毁大沽炮台，允许列强在从北京到山海关铁路沿线驻兵；严禁人民参加反帝活动。（《辛丑条约》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"义和团运动和八国联军侵华；《辛丑条约》的内容与影响：清政府赔款白银 4.5 亿两，分 39 年还清，本息共约 9.8 亿两；清政府保证严禁人民参加各种形式的反帝活动；拆毁大沽炮台，允许外国军队驻扎从北京到山海关铁路沿线要地；划定北京东交民巷为使馆界，允许各国派兵驻守，不准中国人居住；改总理衙门为外务部，班列六部之前。","explain":"材料出自《辛丑条约》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-3-1","title":"第8课 中国同盟会","subtitle":"八年级上册 · 第三单元 资产阶级民主革命与中华民国的建立","grade":"8a","tags":["八年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第三单元 资产阶级民主革命与中华民国的建立"},{"k":"课时","v":"第8课 中国同盟会"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"甲午战后，孙中山弃医从政，1894 年在檀香山创立兴中会，提出「振兴中华」。1905 年，中国同盟会在东京成立，孙中山被推举为总理，提出「驱除鞑虏，恢复中华，创立民国，平均地权」的纲领，后阐发为三民主义。"},{"type":"note","title":"本课主线 · 因果链","text":"孙中山创立同盟会、提出三民主义，资产阶级革命派用武装起义推翻了清朝统治，结束了两千多年的君主专制制度，建立中华民国并颁布《中华民国临时约法》；但革命果实被袁世凯窃取，复辟与军阀割据使民主共和名存实亡，反帝反封建的任务并未完成。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1894 年","孙中山在檀香山成立兴中会","中国第一个资产阶级革命团体"],["1905 年 8 月","中国同盟会在日本东京成立","第一个全国规模的资产阶级革命政党；纲领为「驱除鞑虏，恢复中华，创立民国，平均地权」；机关报《民报》 · 重点"],["1911 年 4 月","黄花岗起义","黄兴等在广州领导，起义失败但革命党人的英勇激励了全国志士"],["1911 年 10 月 10 日","武昌起义","辛亥革命爆发，各省纷纷响应，清朝统治迅速崩溃 · 重点"],["1912 年 1 月 1 日","中华民国临时政府在南京成立","孙中山就任临时大总统，以 1912 年为民国元年 · 重点"],["1913—1916 年","二次革命、袁世凯复辟帝制与护国战争","1913 年二次革命失败；1915 年袁世凯复辟帝制，蔡锷等发动护国战争；1916 年袁世凯死去，此后军阀割据"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1894 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"孙中山在檀香山成立兴中会","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"1905 年 8 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"中国同盟会在日本东京成立","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1911 年 4 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"黄花岗起义","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"1911 年 10 月 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"武昌起义","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"1912 年 1 月 1…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"中华民国临时政府在南京成立","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1913—1916 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"二次革命、袁世凯复辟帝制与护国战争","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"三民主义：孙中山把同盟会纲领阐发为民族、民权、民生三大主义，成为辛亥革命的指导思想。其中民权主义即「创立民国」，是核心。","explain":"局限：没有明确提出反对帝国主义的要求，也没有彻底的土地革命纲领，因此不能彻底完成反帝反封建的任务。这一点常考。"},{"level":"重点","text":"辛亥革命的历史意义：推翻了清王朝的反动统治，宣告了中国两千多年君主专制制度的终结；建立了中华民国，颁布《中华民国临时约法》；开创了完全意义上的近代民族民主革命，极大推动了中华民族的思想解放，使民主共和观念深入人心。","explain":"答「终结」时要写「君主专制制度（封建帝制）」，不能写成「封建制度」，更不能写成「半殖民地半封建社会」。"},{"level":"重点","text":"辛亥革命的局限性：没有改变中国半殖民地半封建社会的性质，没有完成反帝反封建的革命任务，革命果实被袁世凯窃取。","explain":"根本原因是资产阶级革命派的软弱性和妥协性：不敢充分发动群众、不敢彻底反帝。"},{"level":"重点","text":"袁世凯复辟与军阀割据：袁世凯窃取革命果实后镇压二次革命、接受日本「二十一条」、复辟帝制，激起护国战争；1916 年袁世凯死去，中国陷入军阀割据混战局面。","explain":"这段史实说明「民主共和之路充满曲折」：辛亥革命后仍需继续反对专制、争取民主。"},{"level":"次重点","text":"同盟会成立后，革命党人发动了萍浏醴起义、安庆起义、绍兴起义（秋瑾）、黄花岗起义等一系列武装起义，为武昌起义的成功准备了条件。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。","评价辛亥革命要一分为二：**成功在于推翻帝制、建立民国**；**失败在于没有改变半殖民地半封建的社会性质，没有完成反帝反封建任务**。","资产阶级革命派**不敢充分发动和依靠人民群众，也不敢明确提出反帝要求**，这是辛亥革命失败的根本原因，也是后来中国革命必须由无产阶级领导的深刻教训。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为辛亥革命推翻了封建制度。","辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","「封建制度」包含经济、政治、思想等多方面，辛亥革命没有改变封建土地制度与社会性质，写错就丢掉关键分。"],["把兴中会与同盟会混为一谈。","兴中会（1894 年，檀香山）是中国第一个资产阶级革命团体；同盟会（1905 年，东京）是第一个全国规模的资产阶级革命政党。","「团体」与「政党」的区别对应不同的历史地位，是常见设题点。"]]},{"type":"table","title":"戊戌变法与辛亥革命：改良与革命的两条道路（中国近代史上两条救国道路的比较（同一目标、不同手段））","head":["比较项","戊戌变法（1898）","辛亥革命（1911）"],"rows":[["领导阶级","资产阶级维新派","资产阶级革命派"],["政治目标","君主立宪（保留皇帝）","民主共和（推翻帝制）"],["手段","自上而下的改良，依靠光绪帝","自下而上的暴力革命，发动武装起义"],["结果","百日而败，六君子遇害","推翻清朝、建立中华民国，但果实被袁世凯窃取"],["共同局限","资产阶级力量弱小，未充分发动群众，没有提出彻底的反帝反封建纲领","同左"],["共同教训","资产阶级的改良与革命都不能改变中国半殖民地半封建社会的性质","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["历史意义与局限的「两面作答」","问「如何评价辛亥革命」，必须同时写出功绩与局限，只答一面得分不超过一半。"],["法律文本类史料分析","给出《中华民国临时约法》条文，要求说明它体现了什么原则、制定目的是什么，落脚在「防止专制、维护共和」。"],["时序与年代换算","用民国纪年、年代尺或「距今年数」等设问考查 1911、1912 两个关键年份及事件顺序。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：共和、法治与公民权利；语文：《与妻书》等革命文本。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["振兴中华","孙中山在兴中会章程中提出「振兴中华」，成为近代中国奋斗的重要口号。","《孙中山全集》第一卷"]]},{"type":"kv","title":"人物卡片","items":[{"k":"孙中山","v":"中国民主革命的先行者，创立兴中会、同盟会，领导辛亥革命。 出处：《孙中山全集》"},{"k":"黄兴","v":"同盟会重要领导人，与孙中山并称「孙黄」。 出处：《黄兴集》"}]},{"type":"list","title":"延伸阅读","items":["同盟会的成立：1905 年 8 月 20 日，兴中会、华兴会、光复会等团体在日本东京联合成立中国同盟会，是第一个全国规模的资产阶级革命政党。 出处：《孙中山全集》第一卷","三民主义：孙中山把同盟会纲领阐发为民族、民权、民生三大主义，成为辛亥革命的指导思想。 出处：《孙中山全集》第一卷"]},{"type":"list","title":"本课拓展出处","items":["《孙中山全集》；《革命方略》","2024 部编版八上第 8 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 近代化探索的四步走（附中外对比：明治维新）","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-02"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】余维欧美之进化，凡以三大主义：曰民族，曰民权，曰民生。——孙中山《〈民报〉发刊词》（1905 年）\n【材料二】中华民国之主权属于国民全体。中华民国人民一律平等，无种族、阶级、宗教之区别。……国务员辅佐临时大总统，负其责任。——《中华民国临时约法》（1912 年）\n【材料三】1915 年，袁世凯为称帝接受日本「二十一条」的大部分要求，年底宣布恢复帝制，改中华民国为中华帝国；蔡锷等人在云南宣布独立，发动护国战争。","source":"材料研读 · 资产阶级民主革命与中华民国的建立"}],"questions":[{"id":"h8a-u3-m1-q1","type":"short","stem":"（1）依据材料一，写出孙中山阐发的三大主义，并指出这一思想体系的局限性。（4 分）","answer":"三大主义：民族主义、民权主义、民生主义（合称三民主义）。局限性：没有明确提出反对帝国主义的要求，也没有彻底的土地革命纲领，不能彻底解决农民的土地问题，因而无法完成反帝反封建的革命任务。","explain":"","tags":["三民主义","历史解释"],"rubric":["答出民族、民权、民生三大主义","答出没有明确提出反帝要求","答出没有彻底的土地纲领","答出无法完成反帝反封建任务"]},{"id":"h8a-u3-m1-q2","type":"short","stem":"（2）依据材料二说明《中华民国临时约法》体现的原则，并结合材料三谈谈你对辛亥革命结果的认识。（6 分）","answer":"原则：主权在民（中华民国的主权属于国民全体）；法律面前人人平等；三权分立与责任内阁制（国务员负其责任，用以限制总统权力）。认识：袁世凯窃取革命果实、复辟帝制，说明辛亥革命虽然推翻了清朝统治、结束了君主专制制度、建立了中华民国，但没有改变中国半殖民地半封建社会的性质，没有完成反帝反封建的任务；军阀割据混战也说明民主共和的实现需要强大的社会力量支撑，资产阶级革命派不能领导中国革命走向彻底胜利。","explain":"","tags":["临时约法","辛亥革命的评价"],"rubric":["答出主权在民","答出平等/分权与责任内阁","答出革命果实被袁世凯窃取","答出没有改变社会性质、没有完成反帝反封建任务","答出资产阶级革命派的局限"]},{"id":"h8a-u3-q1","type":"choice","stem":"孙中山提出的三民主义中，对应同盟会纲领「创立民国」的是","answer":"B","explain":"民族主义对应「驱除鞑虏，恢复中华」，民权主义对应「创立民国」，民生主义对应「平均地权」。民权主义是三民主义的核心。","options":["民族主义","民权主义","民生主义","民主主义"],"tags":["三民主义","历史解释"]},{"id":"h8a-u3-q2","type":"choice","stem":"辛亥革命爆发的标志性事件是","answer":"B","explain":"1911 年 10 月 10 日武昌起义爆发，各省纷纷响应，清朝统治迅速崩溃。因 1911 年为农历辛亥年，故称辛亥革命。","options":["黄花岗起义","武昌起义","中华民国成立","《中华民国临时约法》颁布"],"tags":["武昌起义","时空观念"]},{"id":"h8a-u3-q4","type":"choice","stem":"下列关于辛亥革命的说法，正确的是","answer":"C","explain":"辛亥革命的最大功绩是推翻清朝统治、结束君主专制制度、建立中华民国、使民主共和观念深入人心；但它没有改变社会性质，没有完成反帝反封建任务，革命果实被袁世凯窃取。","options":["它改变了中国半殖民地半封建社会的性质","它完成了反帝反封建的革命任务","它推翻了清王朝，结束了中国两千多年的君主专制制度","它建立了亚洲第一个资产阶级共和国并长期巩固下来"],"tags":["辛亥革命的评价","唯物史观"]},{"id":"cat-8a-3-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 孙中山在檀香山成立兴中会\n② 中国同盟会在日本东京成立\n③ 黄花岗起义\n④ 武昌起义","answer":"A","explain":"按时间顺序应为：①孙中山在檀香山成立兴中会（1894 年）→②中国同盟会在日本东京成立（1905 年 8 月）→③黄花岗起义（1911 年 4 月）→④武昌起义（1911 年 10 月 10 日）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"cat-8a-3-1-g2","type":"choice","stem":"下列关于「中国同盟会」的表述，错误的是","answer":"A","explain":"认为辛亥革命推翻了封建制度——「封建制度」包含经济、政治、思想等多方面，辛亥革命没有改变封建土地制度与社会性质，写错就丢掉关键分。正确表述：辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","options":["认为辛亥革命推翻了封建制度。","辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。","评价辛亥革命要一分为二：**成功在于推翻帝制、建立民国**；**失败在于没有改变半殖民地半封建的社会性质，没有完成反帝反封建任务**。"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"cat-8a-3-1-g3","type":"choice","stem":"下列结论中，属于「中国同盟会」的是","answer":"A","explain":"本课结论：辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。","评价辛亥革命要一分为二：**成功在于推翻帝制、建立民国**；**失败在于没有改变半殖民地半封建的社会性质，没有完成反帝反封建任务**。","《中华民国临时约法》体现了**主权在民、三权分立、法律面前人人平等**的资产阶级民主原则，是中国政治民主化的重要成果。","资产阶级革命派**不敢充分发动和依靠人民群众，也不敢明确提出反帝要求**，这是辛亥革命失败的根本原因，也是后来中国革命必须由无产阶级领导的深刻教训。"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"cat-8a-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1905 年 8 月 20 日，兴中会、华兴会、光复会等团体在日本东京联合成立中国同盟会，是第一个全国规模的资产阶级革命政党。（《孙中山全集》第一卷）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中国同盟会；三民主义：孙中山把同盟会纲领阐发为民族、民权、民生三大主义，成为辛亥革命的指导思想。其中民权主义即「创立民国」，是核心。","explain":"材料出自《孙中山全集》第一卷。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-3-2","title":"第9课 辛亥革命","subtitle":"八年级上册 · 第三单元 资产阶级民主革命与中华民国的建立","grade":"8a","tags":["八年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第三单元 资产阶级民主革命与中华民国的建立"},{"k":"课时","v":"第9课 辛亥革命"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1911 年，清政府出卖铁路修筑权，激起保路运动。10 月 10 日，武昌新军起义，占领武汉三镇。各省纷纷响应，清朝统治土崩瓦解。1912 年 1 月 1 日，中华民国临时政府在南京成立，孙中山任临时大总统。"},{"type":"note","title":"本课主线 · 因果链","text":"孙中山创立同盟会、提出三民主义，资产阶级革命派用武装起义推翻了清朝统治，结束了两千多年的君主专制制度，建立中华民国并颁布《中华民国临时约法》；但革命果实被袁世凯窃取，复辟与军阀割据使民主共和名存实亡，反帝反封建的任务并未完成。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1911 年 10 月 10 日","武昌起义","辛亥革命爆发，各省纷纷响应，清朝统治迅速崩溃 · 重点"],["1912 年 1 月 1 日","中华民国临时政府在南京成立","孙中山就任临时大总统，以 1912 年为民国元年 · 重点"],["1912 年 3 月 11 日","《中华民国临时约法》颁布","中国历史上第一部具有资产阶级共和国宪法性质的重要文件 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 武昌起义：一夜之间的枪声","caption":"示意图：武昌起义：一夜之间的枪声，详见下方「历史现场」","view":"tall","alt":"示意图：武昌起义：一夜之间的枪声，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1911 年 9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"四川保路运动爆发，清政府调湖北新军入…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"10 月 9 日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"起义计划泄露，革命党人彭楚藩、刘复基…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"10 月 10 日晚","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"武昌新军工程第八营首先发难，攻占楚望…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"10 月 11 日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"起义军占领武昌全城，成立湖北军政府，…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"此后","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"各省纷纷响应，两个月内十几个省宣布独…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1912 年 1 月 1…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"中华民国临时政府在南京成立","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"三民主义：孙中山把同盟会纲领阐发为民族、民权、民生三大主义，成为辛亥革命的指导思想。其中民权主义即「创立民国」，是核心。","explain":"局限：没有明确提出反对帝国主义的要求，也没有彻底的土地革命纲领，因此不能彻底完成反帝反封建的任务。这一点常考。"},{"level":"重点","text":"辛亥革命的历史意义：推翻了清王朝的反动统治，宣告了中国两千多年君主专制制度的终结；建立了中华民国，颁布《中华民国临时约法》；开创了完全意义上的近代民族民主革命，极大推动了中华民族的思想解放，使民主共和观念深入人心。","explain":"答「终结」时要写「君主专制制度（封建帝制）」，不能写成「封建制度」，更不能写成「半殖民地半封建社会」。"},{"level":"重点","text":"辛亥革命的局限性：没有改变中国半殖民地半封建社会的性质，没有完成反帝反封建的革命任务，革命果实被袁世凯窃取。","explain":"根本原因是资产阶级革命派的软弱性和妥协性：不敢充分发动群众、不敢彻底反帝。"},{"level":"重点","text":"《中华民国临时约法》：规定中华民国的主权属于全体国民；国民一律平等，享有各项自由与权利；参议院行使立法权、法院行使司法权、临时大总统与国务员行使行政权（三权分立），并实行责任内阁制。","explain":"它的直接目的是限制袁世凯的权力、维护共和制度；性质是「中国历史上第一部具有资产阶级共和国宪法性质的重要文件」。"},{"level":"重点","text":"袁世凯复辟与军阀割据：袁世凯窃取革命果实后镇压二次革命、接受日本「二十一条」、复辟帝制，激起护国战争；1916 年袁世凯死去，中国陷入军阀割据混战局面。","explain":"这段史实说明「民主共和之路充满曲折」：辛亥革命后仍需继续反对专制、争取民主。"},{"level":"次重点","text":"同盟会成立后，革命党人发动了萍浏醴起义、安庆起义、绍兴起义（秋瑾）、黄花岗起义等一系列武装起义，为武昌起义的成功准备了条件。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。","评价辛亥革命要一分为二：**成功在于推翻帝制、建立民国**；**失败在于没有改变半殖民地半封建的社会性质，没有完成反帝反封建任务**。","《中华民国临时约法》体现了**主权在民、三权分立、法律面前人人平等**的资产阶级民主原则，是中国政治民主化的重要成果。","资产阶级革命派**不敢充分发动和依靠人民群众，也不敢明确提出反帝要求**，这是辛亥革命失败的根本原因，也是后来中国革命必须由无产阶级领导的深刻教训。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为辛亥革命推翻了封建制度。","辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","「封建制度」包含经济、政治、思想等多方面，辛亥革命没有改变封建土地制度与社会性质，写错就丢掉关键分。"],["把中华民国成立与清帝退位的先后顺序记反。","1912 年 1 月 1 日中华民国临时政府成立；1912 年 2 月 12 日宣统帝退位，清朝覆灭。","时序类选择题与年代尺题常用这两个时间点设陷阱，记「先建民国，后清帝退位」。"],["认为《中华民国临时约法》是中国第一部宪法。","它是中国历史上第一部**具有资产阶级共和国宪法性质**的重要文件，不能等同于新中国 1954 年宪法。","「宪法性质」与「宪法」的表述差别是细节分点，材料题按原文表述作答最稳妥。"]]},{"type":"table","title":"戊戌变法与辛亥革命：改良与革命的两条道路（中国近代史上两条救国道路的比较（同一目标、不同手段））","head":["比较项","戊戌变法（1898）","辛亥革命（1911）"],"rows":[["领导阶级","资产阶级维新派","资产阶级革命派"],["政治目标","君主立宪（保留皇帝）","民主共和（推翻帝制）"],["手段","自上而下的改良，依靠光绪帝","自下而上的暴力革命，发动武装起义"],["结果","百日而败，六君子遇害","推翻清朝、建立中华民国，但果实被袁世凯窃取"],["共同局限","资产阶级力量弱小，未充分发动群众，没有提出彻底的反帝反封建纲领","同左"],["共同教训","资产阶级的改良与革命都不能改变中国半殖民地半封建社会的性质","同左"]]},{"type":"table","title":"《中华民国临时约法》与美国 1787 年宪法（中外对比：资产阶级民主原则的体现）","head":["比较项","《中华民国临时约法》（1912）","美国 1787 年宪法"],"rows":[["权力来源","主权属于全体国民","主权属于人民（「我们人民」）"],["权力结构","参议院立法、总统与国务员行政、法院司法，实行责任内阁制","国会立法、总统行政、法院司法，三权分立与制衡"],["制定背景","为限制袁世凯权力、维护共和制度","独立战争后加强中央权力、巩固邦联"],["历史地位","中国第一部具有资产阶级共和国宪法性质的文件","世界上第一部比较完整的资产阶级成文宪法"],["共同点","都确认主权在民、分权制衡、法律面前人人平等","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["历史意义与局限的「两面作答」","问「如何评价辛亥革命」，必须同时写出功绩与局限，只答一面得分不超过一半。"],["法律文本类史料分析","给出《中华民国临时约法》条文，要求说明它体现了什么原则、制定目的是什么，落脚在「防止专制、维护共和」。"],["时序与年代换算","用民国纪年、年代尺或「距今年数」等设问考查 1911、1912 两个关键年份及事件顺序。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：共和、法治与公民权利；语文：《与妻书》等革命文本。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 武昌起义：一夜之间的枪声","head":["时间","经过"],"rows":[["1911 年 9 月","四川保路运动爆发，清政府调湖北新军入川镇压，武汉兵力空虚"],["10 月 9 日","起义计划泄露，革命党人彭楚藩、刘复基、杨洪胜被捕遇害"],["10 月 10 日晚","武昌新军工程第八营首先发难，攻占楚望台军械库"],["10 月 11 日","起义军占领武昌全城，成立湖北军政府，推黎元洪为都督"],["此后","各省纷纷响应，两个月内十几个省宣布独立"],["1912 年 1 月 1 日","中华民国临时政府在南京成立"]]},{"type":"note","title":"现场解说","text":"武昌起义是辛亥革命的首义，拉开了推翻清朝统治的序幕。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["辛亥革命","1911 年爆发的资产阶级民主革命，推翻清朝统治，结束两千多年君主专制制度。","2024 部编版八上第 9 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"孙中山","v":"中华民国临时大总统，领导辛亥革命。 出处：《孙中山全集》"},{"k":"黎元洪","v":"武昌起义后被推为湖北军政府都督。 出处：《辛亥革命史》"}]},{"type":"list","title":"延伸阅读","items":["《中华民国临时约法》：1912 年 3 月颁布，规定中华民国主权属于国民全体，实行三权分立，是中国历史上第一部具有资产阶级共和国宪法性质的重要文件。 出处：《中华民国临时约法》原文","辛亥革命的局限：革命没有改变中国半殖民地半封建的社会性质，没有完成反帝反封建的任务，袁世凯窃取革命果实。 出处：2024 部编版八上第 9 课"]},{"type":"list","title":"本课拓展出处","items":["《孙中山全集》；《中华民国临时约法》原文","2024 部编版八上第 9 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 近代化探索的四步走（附中外对比：明治维新）","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-02"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】余维欧美之进化，凡以三大主义：曰民族，曰民权，曰民生。——孙中山《〈民报〉发刊词》（1905 年）\n【材料二】中华民国之主权属于国民全体。中华民国人民一律平等，无种族、阶级、宗教之区别。……国务员辅佐临时大总统，负其责任。——《中华民国临时约法》（1912 年）\n【材料三】1915 年，袁世凯为称帝接受日本「二十一条」的大部分要求，年底宣布恢复帝制，改中华民国为中华帝国；蔡锷等人在云南宣布独立，发动护国战争。","source":"材料研读 · 资产阶级民主革命与中华民国的建立"}],"questions":[{"id":"h8a-u3-m1-q2","type":"short","stem":"（2）依据材料二说明《中华民国临时约法》体现的原则，并结合材料三谈谈你对辛亥革命结果的认识。（6 分）","answer":"原则：主权在民（中华民国的主权属于国民全体）；法律面前人人平等；三权分立与责任内阁制（国务员负其责任，用以限制总统权力）。认识：袁世凯窃取革命果实、复辟帝制，说明辛亥革命虽然推翻了清朝统治、结束了君主专制制度、建立了中华民国，但没有改变中国半殖民地半封建社会的性质，没有完成反帝反封建的任务；军阀割据混战也说明民主共和的实现需要强大的社会力量支撑，资产阶级革命派不能领导中国革命走向彻底胜利。","explain":"","tags":["临时约法","辛亥革命的评价"],"rubric":["答出主权在民","答出平等/分权与责任内阁","答出革命果实被袁世凯窃取","答出没有改变社会性质、没有完成反帝反封建任务","答出资产阶级革命派的局限"]},{"id":"h8a-u3-q2","type":"choice","stem":"辛亥革命爆发的标志性事件是","answer":"B","explain":"1911 年 10 月 10 日武昌起义爆发，各省纷纷响应，清朝统治迅速崩溃。因 1911 年为农历辛亥年，故称辛亥革命。","options":["黄花岗起义","武昌起义","中华民国成立","《中华民国临时约法》颁布"],"tags":["武昌起义","时空观念"]},{"id":"h8a-u3-q3","type":"choice","stem":"《中华民国临时约法》的性质是","answer":"B","explain":"《中华民国临时约法》由南京临时政府颁布，确认主权在民、三权分立，是中国历史上第一部具有资产阶级共和国宪法性质的重要文件。","options":["中国第一部社会主义类型的宪法","中国历史上第一部具有资产阶级共和国宪法性质的重要文件","清政府颁布的君主立宪文件","北洋政府制定的军事法令"],"tags":["临时约法","史料实证"]},{"id":"h8a-u3-q4","type":"choice","stem":"下列关于辛亥革命的说法，正确的是","answer":"C","explain":"辛亥革命的最大功绩是推翻清朝统治、结束君主专制制度、建立中华民国、使民主共和观念深入人心；但它没有改变社会性质，没有完成反帝反封建任务，革命果实被袁世凯窃取。","options":["它改变了中国半殖民地半封建社会的性质","它完成了反帝反封建的革命任务","它推翻了清王朝，结束了中国两千多年的君主专制制度","它建立了亚洲第一个资产阶级共和国并长期巩固下来"],"tags":["辛亥革命的评价","唯物史观"]},{"id":"cat-8a-3-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 武昌起义\n② 中华民国临时政府在南京成立\n③ 《中华民国临时约法》颁布","answer":"A","explain":"按时间顺序应为：①武昌起义（1911 年 10 月 10 日）→②中华民国临时政府在南京成立（1912 年 1 月 1 日）→③《中华民国临时约法》颁布（1912 年 3 月 11 日）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"cat-8a-3-2-g2","type":"choice","stem":"下列关于「辛亥革命」的表述，错误的是","answer":"A","explain":"认为辛亥革命推翻了封建制度——「封建制度」包含经济、政治、思想等多方面，辛亥革命没有改变封建土地制度与社会性质，写错就丢掉关键分。正确表述：辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","options":["认为辛亥革命推翻了封建制度。","辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。","评价辛亥革命要一分为二：**成功在于推翻帝制、建立民国**；**失败在于没有改变半殖民地半封建的社会性质，没有完成反帝反封建任务**。"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"cat-8a-3-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1912 年 3 月颁布，规定中华民国主权属于国民全体，实行三权分立，是中国历史上第一部具有资产阶级共和国宪法性质的重要文件。（《中华民国临时约法》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"辛亥革命；三民主义：孙中山把同盟会纲领阐发为民族、民权、民生三大主义，成为辛亥革命的指导思想。其中民权主义即「创立民国」，是核心。","explain":"材料出自《中华民国临时约法》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-3-3","title":"第10课 帝制复辟与军阀割据","subtitle":"八年级上册 · 第三单元 资产阶级民主革命与中华民国的建立","grade":"8a","tags":["八年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第三单元 资产阶级民主革命与中华民国的建立"},{"k":"课时","v":"第10课 帝制复辟与军阀割据"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"辛亥革命后，袁世凯就任临时大总统，1913 年派人刺杀宋教仁，镇压国民党。1915 年袁世凯复辟帝制，改国号「中华帝国」。蔡锷、李烈钧、唐继尧等发动护国战争，袁世凯被迫取消帝制。袁世凯死后，中国陷入军阀割据混战。"},{"type":"note","title":"本课主线 · 因果链","text":"孙中山创立同盟会、提出三民主义，资产阶级革命派用武装起义推翻了清朝统治，结束了两千多年的君主专制制度，建立中华民国并颁布《中华民国临时约法》；但革命果实被袁世凯窃取，复辟与军阀割据使民主共和名存实亡，反帝反封建的任务并未完成。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1913—1916 年","二次革命、袁世凯复辟帝制与护国战争","1913 年二次革命失败；1915 年袁世凯复辟帝制，蔡锷等发动护国战争；1916 年袁世凯死去，此后军阀割据"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"辛亥革命的局限性：没有改变中国半殖民…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":27.17,"text":"《中华民国临时约法》：规定中华民国的…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":41.33,"text":"袁世凯复辟与军阀割据：袁世凯窃取革命…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"袁世凯复辟与军阀割据说明：**任何违…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"辛亥革命的局限性：没有改变中国半殖民地半封建社会的性质，没有完成反帝反封建的革命任务，革命果实被袁世凯窃取。","explain":"根本原因是资产阶级革命派的软弱性和妥协性：不敢充分发动群众、不敢彻底反帝。"},{"level":"重点","text":"《中华民国临时约法》：规定中华民国的主权属于全体国民；国民一律平等，享有各项自由与权利；参议院行使立法权、法院行使司法权、临时大总统与国务员行使行政权（三权分立），并实行责任内阁制。","explain":"它的直接目的是限制袁世凯的权力、维护共和制度；性质是「中国历史上第一部具有资产阶级共和国宪法性质的重要文件」。"},{"level":"重点","text":"袁世凯复辟与军阀割据：袁世凯窃取革命果实后镇压二次革命、接受日本「二十一条」、复辟帝制，激起护国战争；1916 年袁世凯死去，中国陷入军阀割据混战局面。","explain":"这段史实说明「民主共和之路充满曲折」：辛亥革命后仍需继续反对专制、争取民主。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["袁世凯复辟与军阀割据说明：**任何违背民主共和潮流的倒行逆施都必然失败**，但民主政治的实现需要强大的社会力量作支撑。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为辛亥革命推翻了封建制度。","辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","「封建制度」包含经济、政治、思想等多方面，辛亥革命没有改变封建土地制度与社会性质，写错就丢掉关键分。"],["把兴中会与同盟会混为一谈。","兴中会（1894 年，檀香山）是中国第一个资产阶级革命团体；同盟会（1905 年，东京）是第一个全国规模的资产阶级革命政党。","「团体」与「政党」的区别对应不同的历史地位，是常见设题点。"]]},{"type":"table","title":"戊戌变法与辛亥革命：改良与革命的两条道路（中国近代史上两条救国道路的比较（同一目标、不同手段））","head":["比较项","戊戌变法（1898）","辛亥革命（1911）"],"rows":[["领导阶级","资产阶级维新派","资产阶级革命派"],["政治目标","君主立宪（保留皇帝）","民主共和（推翻帝制）"],["手段","自上而下的改良，依靠光绪帝","自下而上的暴力革命，发动武装起义"],["结果","百日而败，六君子遇害","推翻清朝、建立中华民国，但果实被袁世凯窃取"],["共同局限","资产阶级力量弱小，未充分发动群众，没有提出彻底的反帝反封建纲领","同左"],["共同教训","资产阶级的改良与革命都不能改变中国半殖民地半封建社会的性质","同左"]]},{"type":"table","title":"《中华民国临时约法》与美国 1787 年宪法（中外对比：资产阶级民主原则的体现）","head":["比较项","《中华民国临时约法》（1912）","美国 1787 年宪法"],"rows":[["权力来源","主权属于全体国民","主权属于人民（「我们人民」）"],["权力结构","参议院立法、总统与国务员行政、法院司法，实行责任内阁制","国会立法、总统行政、法院司法，三权分立与制衡"],["制定背景","为限制袁世凯权力、维护共和制度","独立战争后加强中央权力、巩固邦联"],["历史地位","中国第一部具有资产阶级共和国宪法性质的文件","世界上第一部比较完整的资产阶级成文宪法"],["共同点","都确认主权在民、分权制衡、法律面前人人平等","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["历史意义与局限的「两面作答」","问「如何评价辛亥革命」，必须同时写出功绩与局限，只答一面得分不超过一半。"],["法律文本类史料分析","给出《中华民国临时约法》条文，要求说明它体现了什么原则、制定目的是什么，落脚在「防止专制、维护共和」。"],["时序与年代换算","用民国纪年、年代尺或「距今年数」等设问考查 1911、1912 两个关键年份及事件顺序。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：共和、法治与公民权利；语文：《与妻书》等革命文本。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["洪宪帝制","袁世凯 1916 年改元「洪宪」，复辟帝制，仅 83 天即告失败。","《北洋军阀史》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"袁世凯","v":"北洋军阀首领，窃取辛亥革命果实，复辟帝制失败。 出处：《北洋军阀史》"},{"k":"宋教仁","v":"国民党代理理事长，主张责任内阁制，1913 年遇刺。 出处：《宋教仁集》"}]},{"type":"list","title":"延伸阅读","items":["宋教仁案：1913 年 3 月，国民党代理理事长宋教仁在上海遇刺身亡，舆论普遍认为是袁世凯主谋，引发「二次革命」。 出处：《北洋军阀史》","军阀割据：袁世凯死后，北洋军阀分裂为直系、皖系、奉系等，各派依仗帝国主义支持争夺地盘，连年混战，民不聊生。 出处：2024 部编版八上第 10 课"]},{"type":"list","title":"本课拓展出处","items":["《北洋军阀史》；《护国运动》相关档案","2024 部编版八上第 10 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 近代化探索的四步走（附中外对比：明治维新）","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-02"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】余维欧美之进化，凡以三大主义：曰民族，曰民权，曰民生。——孙中山《〈民报〉发刊词》（1905 年）\n【材料二】中华民国之主权属于国民全体。中华民国人民一律平等，无种族、阶级、宗教之区别。……国务员辅佐临时大总统，负其责任。——《中华民国临时约法》（1912 年）\n【材料三】1915 年，袁世凯为称帝接受日本「二十一条」的大部分要求，年底宣布恢复帝制，改中华民国为中华帝国；蔡锷等人在云南宣布独立，发动护国战争。","source":"材料研读 · 资产阶级民主革命与中华民国的建立"}],"questions":[{"id":"h8a-u3-q5","type":"choice","stem":"1916 年袁世凯死去后，中国出现的政治局面是","answer":"B","explain":"袁世凯死后，北洋军阀分裂为直系、皖系、奉系等派系，中国陷入军阀割据混战的局面，人民生活痛苦，民主共和名存实亡。","options":["南北对峙、国共对立","军阀割据混战","列强共同支配下的「以华治华」","君主立宪制的确立"],"tags":["军阀割据","时空观念"]},{"id":"cat-8a-3-3-g2","type":"choice","stem":"下列关于「帝制复辟与军阀割据」的表述，错误的是","answer":"A","explain":"认为辛亥革命推翻了封建制度——「封建制度」包含经济、政治、思想等多方面，辛亥革命没有改变封建土地制度与社会性质，写错就丢掉关键分。正确表述：辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","options":["认为辛亥革命推翻了封建制度。","辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","袁世凯复辟与军阀割据说明：**任何违背民主共和潮流的倒行逆施都必然失败**，但民主政治的实现需要强大的社会力量作支撑。","辛亥革命的局限性：没有改变中国半殖民地半封建社会的性质，没有完成反帝反封建的革命任务，革命果实被袁世凯窃取。"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"cat-8a-3-3-g3","type":"choice","stem":"下列结论中，属于「帝制复辟与军阀割据」的是","answer":"A","explain":"本课结论：袁世凯复辟与军阀割据说明：**任何违背民主共和潮流的倒行逆施都必然失败**，但民主政治的实现需要强大的社会力量作支撑。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["袁世凯复辟与军阀割据说明：**任何违背民主共和潮流的倒行逆施都必然失败**，但民主政治的实现需要强大的社会力量作支撑。","辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。","评价辛亥革命要一分为二：**成功在于推翻帝制、建立民国**；**失败在于没有改变半殖民地半封建的社会性质，没有完成反帝反封建任务**。","资产阶级革命派**不敢充分发动和依靠人民群众，也不敢明确提出反帝要求**，这是辛亥革命失败的根本原因，也是后来中国革命必须由无产阶级领导的深刻教训。"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"cat-8a-3-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1913 年 3 月，国民党代理理事长宋教仁在上海遇刺身亡，舆论普遍认为是袁世凯主谋，引发「二次革命」。（《北洋军阀史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"帝制复辟与军阀割据；辛亥革命的局限性：没有改变中国半殖民地半封建社会的性质，没有完成反帝反封建的革命任务，革命果实被袁世凯窃取。","explain":"材料出自《北洋军阀史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-3-3-g5","type":"choice","stem":"「二次革命、袁世凯复辟帝制与护国战争」发生于","answer":"A","explain":"本课时间轴：二次革命、袁世凯复辟帝制与护国战争（1913—1916 年）。1913 年二次革命失败；1915 年袁世凯复辟帝制，蔡锷等发动护国战争；1916 年袁世凯死去，此后军阀割据。其余三个时间是同一单元相邻课时的事件时间。","options":["1913—1916 年","1894 年","1905 年 8 月","1911 年 4 月"],"difficulty":1,"tags":["八年级上册","第三单元","本课练习"]}]},{"id":"cat-8a-4-1","title":"第11课 五四运动","subtitle":"八年级上册 · 第四单元 新民主主义革命的兴起","grade":"8a","tags":["八年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第四单元 新民主主义革命的兴起"},{"k":"课时","v":"第11课 五四运动"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1915 年陈独秀创办《青年杂志》，新文化运动兴起，提倡民主与科学，反对旧道德旧文化。1919 年巴黎和会决定将德国在山东的权益转让给日本，中国外交失败，激起五四运动。"},{"type":"note","title":"本课主线 · 因果链","text":"辛亥革命后先进知识分子认识到必须改造国民思想，于是掀起新文化运动；巴黎和会外交失败引发五四运动，工人阶级登上政治舞台，中国新民主主义革命由此开端；马克思主义与工人运动相结合，1921 年中国共产党成立，中国革命的面貌焕然一新。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1915 年","陈独秀在上海创办《青年杂志》（后改名《新青年》）","新文化运动开始的标志；高举民主与科学两面大旗 · 重点"],["1918 年","李大钊发表《庶民的胜利》《布尔什维主义的胜利》","在中国最早宣传马克思主义"],["1919 年 5 月 4 日","五四运动爆发","导火线是巴黎和会上中国外交的失败；口号「外争主权，内除国贼」 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 五四运动：从学生游行到全国响应","caption":"示意图：五四运动：从学生游行到全国响应，详见下方「历史现场」","view":"tall","alt":"示意图：五四运动：从学生游行到全国响应，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1919 年 1 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"巴黎和会开幕，中国代表提出废除不平等…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"4 月底","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"和会决定将德国在山东权益转让日本，中…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"5 月 4 日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"北京三千余名学生游行示威，火烧赵家楼…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"6 月 5 日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"上海工人罢工、商人罢市，运动扩展到全…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"6 月 10 日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"北洋政府被迫释放被捕学生，罢免曹汝霖…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"6 月 28 日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"中国代表拒绝在《凡尔赛条约》上签字","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"新文化运动：以《新青年》为主要阵地，代表人物有陈独秀、胡适、李大钊、鲁迅；提倡民主与科学，抨击旧道德和旧文化，提倡白话文。","explain":"口号是「民主」（德先生）与「科学」（赛先生），性质是思想解放运动，为马克思主义在中国的传播创造了条件。"},{"level":"重点","text":"五四运动：导火线是巴黎和会上中国外交的失败；口号是「外争主权，内除国贼」（最能体现其反帝反封建性质）；它是一场彻底反帝反封建的伟大爱国革命运动，是中国新民主主义革命的开端。","explain":"「彻底」指不妥协地反对帝国主义和封建主义；「新民主主义」的关键是工人阶级登上政治舞台并发挥主力作用。"},{"level":"重点","text":"五四精神：以爱国、进步、民主、科学为主要内容，核心是爱国主义精神。","explain":"材料题常要求「谈谈青年学生应怎样继承五四精神」，答法：把个人理想与国家命运结合，努力学习、勇于担当。"},{"level":"次重点","text":"新文化运动的局限：对东西方文化的看法带有绝对肯定或绝对否定的偏向，但它的主流是传播民主与科学、解放思想。","explain":""},{"level":"选择题","text":"鲁迅的白话小说《狂人日记》深刻揭露了封建礼教和封建制度的吃人本质；五四运动中北京学生的示威游行得到全国各界的声援。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["新文化运动是**中国近代史上一次伟大的思想解放运动**：它动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放，为马克思主义在中国的传播创造了条件。","五四运动是**中国新民主主义革命的开端**：工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质，促进了马克思主义与中国工人运动的结合。","近代中国的思想解放层层深入：从学习西方技术（洋务运动）到学习制度（戊戌变法、辛亥革命）再到学习思想文化（新文化运动），最后选择了马克思主义。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把五四运动的导火线说成「二十一条」的签订。","导火线是 1919 年巴黎和会上中国外交的失败（列强将德国在山东的特权转让给日本）；「二十一条」是 1915 年日本提出、袁世凯接受的事件。","两件事都与日本侵略山东有关，但时间与性质不同，属高频陷阱。"],["把新民主主义革命的开端记为中国共产党成立。","新民主主义革命的开端是五四运动（1919 年）；中国共产党的成立使中国革命的面貌焕然一新。","两个结论都对，但对应不同事件，必须按设问区分。"],["认为新文化运动始于五四运动。","新文化运动始于 1915 年陈独秀创办《青年杂志》；五四运动后，新文化运动发展为以传播马克思主义为主流的思想运动。","教材的表述是「五四运动后新文化运动有了新的发展」，不能把开始时间后移。"]]},{"type":"table","title":"旧民主主义革命与新民主主义革命（中国近代革命的两个阶段（以 1919 年五四运动为分界））","head":["比较项","旧民主主义革命（1840—1919）","新民主主义革命（1919—1949）"],"rows":[["领导阶级","农民阶级、资产阶级","无产阶级（中国共产党）"],["指导思想","平均主义、三民主义等","马克思主义"],["革命目标","建立资产阶级共和国、走资本主义道路","建立人民民主专政的国家，走社会主义道路"],["群众基础","未能充分发动群众","广泛发动工农群众，建立革命统一战线"],["结果","没有改变半殖民地半封建社会性质","取得反帝反封建斗争的伟大胜利，1949 年建立新中国"],["相同点","都是反帝反封建的民主革命，都以改变中国社会性质为目标","同左"]]},{"type":"table","title":"新文化运动与法国启蒙运动（中外对比：思想解放运动的社会作用）","head":["比较项","新文化运动（1915 年起）","法国启蒙运动（18 世纪）"],"rows":[["核心主张","民主与科学，反对旧道德旧文化","理性、自由、平等、天赋人权，反对专制与教会"],["主要阵地","《新青年》杂志与北京大学","《百科全书》与沙龙、报刊"],["直接作用","解放思想，为五四运动与马克思主义传播创造条件","为法国大革命做了思想动员"],["共同规律","思想解放是社会变革的先导","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["口号与性质的对应","给出「外争主权，内除国贼」「民主与科学」等口号，要求判断运动名称、性质与历史地位，落脚在「开端」「思想解放」这类结论上。"],["革命阶段划分","以 1919 年为界比较新旧民主主义革命，考查领导阶级、指导思想与前途的不同，是中考高频的综合比较题。"],["历史事件的原因分析","以「为什么中国共产党能诞生」设问，要求从思想、阶级、组织三方面作答，是固定结构的原因类材料题。"]]},{"type":"note","title":"跨学科视角","text":"语文：五四新文学；道德与法治：爱国主义与青年责任。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 五四运动：从学生游行到全国响应","head":["时间","经过"],"rows":[["1919 年 1 月","巴黎和会开幕，中国代表提出废除不平等条约、收回山东权益等要求"],["4 月底","和会决定将德国在山东权益转让日本，中国外交失败消息传回国内"],["5 月 4 日","北京三千余名学生游行示威，火烧赵家楼，遭军警镇压"],["6 月 5 日","上海工人罢工、商人罢市，运动扩展到全国 20 多个省"],["6 月 10 日","北洋政府被迫释放被捕学生，罢免曹汝霖、章宗祥、陆宗舆"],["6 月 28 日","中国代表拒绝在《凡尔赛条约》上签字"]]},{"type":"note","title":"现场解说","text":"五四运动是中国旧民主主义革命走向新民主主义革命的转折点。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["外争主权，内除国贼","五四运动口号，要求收回山东主权、惩办卖国贼。","彭明《五四运动史》"],["德先生与赛先生","新文化运动对民主（Democracy）与科学（Science）的称呼。","陈独秀《新青年》罪案之答辩书"]]},{"type":"kv","title":"人物卡片","items":[{"k":"陈独秀","v":"新文化运动代表人物，创办《青年杂志》，中国共产党主要创始人之一。 出处：《新青年》"},{"k":"李大钊","v":"中国最早传播马克思主义者之一，著《我的马克思主义观》。 出处：《李大钊选集》"}]},{"type":"list","title":"延伸阅读","items":["新文化运动：陈独秀、李大钊、胡适、鲁迅等以《新青年》为阵地，提倡民主与科学，提倡白话文，反对文言文，推动思想解放。 出处：《新青年》；2024 部编版八上第 11 课","五四运动两个阶段：5 月 4 日至 6 月初，以学生为主，中心在北京；6 月 5 日后，上海工人罢工、商人罢市，运动中心转移到上海，工人阶级成为主力。 出处：彭明《五四运动史》"]},{"type":"list","title":"本课拓展出处","items":["《五四运动史》（彭明）；《新青年》","2024 部编版八上第 11 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】我们现在认定只有这两位先生，可以救治中国政治上、道德上、学术上、思想上一切的黑暗。——陈独秀《本志罪案之答辩书》（1919 年，《新青年》第六卷第一号）\n【材料二】中国的土地可以征服而不可以断送！中国的人民可以杀戮而不可以低头！——北京学生界宣言（1919 年 5 月）\n【材料三】中共一大通过的纲领确定：党的名称为中国共产党，党的奋斗目标是推翻资产阶级政权，建立无产阶级专政，消灭阶级差别，实现共产主义。","source":"材料研读 · 新民主主义革命的开始"}],"questions":[{"id":"h8a-u4-m1-q1","type":"short","stem":"（1）材料一中的「两位先生」指什么？依据材料一并结合所学，说明新文化运动的作用。（5 分）","answer":"「两位先生」指民主与科学。作用：新文化运动动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放；它提倡白话文，推动了文学革命与文化普及；为马克思主义在中国的传播和五四运动的爆发创造了条件。总起来说，它是一次伟大的思想解放运动。","explain":"","tags":["新文化运动","史料实证"],"rubric":["答出民主与科学","答出动摇封建道德礼教/解放思想","答出为马克思主义传播创造条件","答出是伟大的思想解放运动"]},{"id":"h8a-u4-m1-q2","type":"short","stem":"（2）材料二体现了五四运动的什么精神？结合材料三说明中国共产党成立后中国革命为什么「面貌焕然一新」。（6 分）","answer":"精神：材料二表现出誓死捍卫国家主权、不向侵略者低头的爱国主义精神，即五四精神，其核心是爱国主义（还包括进步、民主、科学）。「焕然一新」的原因：中国共产党以马克思主义为指导思想，有了科学理论的指导；中共一大确定了推翻资产阶级政权、实现共产主义的奋斗目标，中共二大又第一次明确提出彻底的反帝反封建的民主革命纲领，使中国革命有了明确方向；中国共产党代表工人阶级和广大人民利益，能够深入发动群众，从而开辟了与以往一切政治力量都不相同的革命道路。","explain":"","tags":["五四运动","中共成立"],"rubric":["答出爱国主义/五四精神","答出以马克思主义为指导","答出提出彻底的反帝反封建纲领","答出代表人民利益、发动群众","答出中国革命有了坚强领导核心"]},{"id":"h8a-u4-q1","type":"choice","stem":"新文化运动开始的标志是","answer":"B","explain":"1915 年陈独秀在上海创办《青年杂志》（自第二卷起改名《新青年》），标志新文化运动开始。《天演论》是维新变法的思想武器。","options":["严复译述《天演论》","陈独秀在上海创办《青年杂志》","五四运动爆发","中共一大召开"],"tags":["新文化运动","时空观念"]},{"id":"h8a-u4-q2","type":"choice","stem":"五四运动爆发的导火线是","answer":"B","explain":"1919 年巴黎和会拒绝中国正当要求，竟将德国在山东的特权转让给日本，消息传回国内直接引发五四运动。","options":["日本提出「二十一条」","巴黎和会上中国外交的失败","北洋政府镇压学生游行","中国共产党号召反帝反封建"],"tags":["五四运动","历史解释"]},{"id":"h8a-u4-q3","type":"choice","stem":"五四运动被称为中国新民主主义革命的开端，主要因为它","answer":"C","explain":"判断革命阶段的关键是领导阶级与指导思想。五四运动中工人阶级成为主力，运动具有彻底反帝反封建的性质，因此成为新民主主义革命的开端。","options":["取得了彻底胜利","由学生首先发起","工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质","建立了中国共产党"],"tags":["五四运动","唯物史观"]},{"id":"cat-8a-4-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 陈独秀在上海创办《青年杂志》（后改名《新青年》）\n② 李大钊发表《庶民的胜利》《布尔什维主义的胜利》\n③ 五四运动爆发","answer":"A","explain":"按时间顺序应为：①陈独秀在上海创办《青年杂志》（后改名《新青年》）（1915 年）→②李大钊发表《庶民的胜利》《布尔什维主义的胜利》（1918 年）→③五四运动爆发（1919 年 5 月 4 日）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"cat-8a-4-1-g2","type":"choice","stem":"下列关于「五四运动」的表述，错误的是","answer":"A","explain":"把五四运动的导火线说成「二十一条」的签订——两件事都与日本侵略山东有关，但时间与性质不同，属高频陷阱。正确表述：导火线是 1919 年巴黎和会上中国外交的失败（列强将德国在山东的特权转让给日本）；「二十一条」是 1915 年日本提出、袁世凯接受的事件。","options":["把五四运动的导火线说成「二十一条」的签订。","导火线是 1919 年巴黎和会上中国外交的失败（列强将德国在山东的特权转让给日本）；「二十一条」是 1915 年日本提出、袁世凯接受的事件。","新文化运动是**中国近代史上一次伟大的思想解放运动**：它动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放，为马克思主义在中国的传播创造了条件。","五四运动是**中国新民主主义革命的开端**：工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质，促进了马克思主义与中国工人运动的结合。"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"cat-8a-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：陈独秀、李大钊、胡适、鲁迅等以《新青年》为阵地，提倡民主与科学，提倡白话文，反对文言文，推动思想解放。（《新青年》；2024 部编版八上第 11 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"五四运动；新文化运动：以《新青年》为主要阵地，代表人物有陈独秀、胡适、李大钊、鲁迅；提倡民主与科学，抨击旧道德和旧文化，提倡白话文。","explain":"材料出自《新青年》；2024 部编版八上第 11 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-4-2","title":"第12课 中国共产党诞生","subtitle":"八年级上册 · 第四单元 新民主主义革命的兴起","grade":"8a","tags":["八年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第四单元 新民主主义革命的兴起"},{"k":"课时","v":"第12课 中国共产党诞生"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"五四运动后，马克思主义在中国广泛传播，工人运动发展，各地共产党早期组织相继建立。1921 年 7 月，中国共产党第一次全国代表大会在上海召开，后转移到浙江嘉兴南湖游船上继续举行，宣告中国共产党诞生。"},{"type":"note","title":"本课主线 · 因果链","text":"辛亥革命后先进知识分子认识到必须改造国民思想，于是掀起新文化运动；巴黎和会外交失败引发五四运动，工人阶级登上政治舞台，中国新民主主义革命由此开端；马克思主义与工人运动相结合，1921 年中国共产党成立，中国革命的面貌焕然一新。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1918 年","李大钊发表《庶民的胜利》《布尔什维主义的胜利》","在中国最早宣传马克思主义"],["1921 年 7 月","中共一大在上海召开，后转到浙江嘉兴南湖游船","中国共产党成立，中国革命的面貌从此焕然一新 · 重点"],["1923 年","京汉铁路工人大罢工","中国共产党认识到必须团结更多革命力量，推动了国共合作的实现"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 中共一大：开天辟地的大事变","caption":"示意图：中共一大：开天辟地的大事变，详见下方「历史现场」","view":"tall","alt":"示意图：中共一大：开天辟地的大事变，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1921 年 7 月 2…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"中共一大在上海法租界望志路 106 …","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"会议期间","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"遭法租界巡捕搜查，会议被迫中断","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"8 月初","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"代表转移到浙江嘉兴南湖游船上继续开会","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"会议决定","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"通过党的第一个纲领，确定党的名称、奋…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"意义","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"中国共产党诞生，中国革命的面貌焕然一…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"新文化运动：以《新青年》为主要阵地，代表人物有陈独秀、胡适、李大钊、鲁迅；提倡民主与科学，抨击旧道德和旧文化，提倡白话文。","explain":"口号是「民主」（德先生）与「科学」（赛先生），性质是思想解放运动，为马克思主义在中国的传播创造了条件。"},{"level":"重点","text":"中国共产党成立的条件与意义：马克思主义的传播（思想基础）、工人阶级队伍的壮大与工人运动的发展（阶级基础）、各地共产党早期组织的建立（组织基础）；中共一大通过党的第一个纲领，确定党的名称为中国共产党，选举陈独秀为中央局书记。","explain":"意义：中国共产党的成立是开天辟地的大事，自从有了中国共产党，中国革命的面貌就焕然一新了。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["新文化运动是**中国近代史上一次伟大的思想解放运动**：它动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放，为马克思主义在中国的传播创造了条件。","五四运动是**中国新民主主义革命的开端**：工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质，促进了马克思主义与中国工人运动的结合。","**自从有了中国共产党，中国革命的面貌就焕然一新了**：中国共产党以马克思主义为指导，第一次明确提出彻底的反帝反封建纲领，使中国革命有了坚强的领导核心。","近代中国的思想解放层层深入：从学习西方技术（洋务运动）到学习制度（戊戌变法、辛亥革命）再到学习思想文化（新文化运动），最后选择了马克思主义。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把新民主主义革命的开端记为中国共产党成立。","新民主主义革命的开端是五四运动（1919 年）；中国共产党的成立使中国革命的面貌焕然一新。","两个结论都对，但对应不同事件，必须按设问区分。"],["认为新文化运动始于五四运动。","新文化运动始于 1915 年陈独秀创办《青年杂志》；五四运动后，新文化运动发展为以传播马克思主义为主流的思想运动。","教材的表述是「五四运动后新文化运动有了新的发展」，不能把开始时间后移。"],["把最早宣传马克思主义的人记成陈独秀。","在中国最早宣传马克思主义的是李大钊（《庶民的胜利》《布尔什维主义的胜利》）；陈独秀是《新青年》的创办者和新文化运动的代表人物。","人物与贡献的配对是选择题常用考法，注意「最先」「最早」这类限定词。"]]},{"type":"table","title":"旧民主主义革命与新民主主义革命（中国近代革命的两个阶段（以 1919 年五四运动为分界））","head":["比较项","旧民主主义革命（1840—1919）","新民主主义革命（1919—1949）"],"rows":[["领导阶级","农民阶级、资产阶级","无产阶级（中国共产党）"],["指导思想","平均主义、三民主义等","马克思主义"],["革命目标","建立资产阶级共和国、走资本主义道路","建立人民民主专政的国家，走社会主义道路"],["群众基础","未能充分发动群众","广泛发动工农群众，建立革命统一战线"],["结果","没有改变半殖民地半封建社会性质","取得反帝反封建斗争的伟大胜利，1949 年建立新中国"],["相同点","都是反帝反封建的民主革命，都以改变中国社会性质为目标","同左"]]},{"type":"table","title":"新文化运动与法国启蒙运动（中外对比：思想解放运动的社会作用）","head":["比较项","新文化运动（1915 年起）","法国启蒙运动（18 世纪）"],"rows":[["核心主张","民主与科学，反对旧道德旧文化","理性、自由、平等、天赋人权，反对专制与教会"],["主要阵地","《新青年》杂志与北京大学","《百科全书》与沙龙、报刊"],["直接作用","解放思想，为五四运动与马克思主义传播创造条件","为法国大革命做了思想动员"],["共同规律","思想解放是社会变革的先导","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["口号与性质的对应","给出「外争主权，内除国贼」「民主与科学」等口号，要求判断运动名称、性质与历史地位，落脚在「开端」「思想解放」这类结论上。"],["革命阶段划分","以 1919 年为界比较新旧民主主义革命，考查领导阶级、指导思想与前途的不同，是中考高频的综合比较题。"],["历史事件的原因分析","以「为什么中国共产党能诞生」设问，要求从思想、阶级、组织三方面作答，是固定结构的原因类材料题。"]]},{"type":"note","title":"跨学科视角","text":"语文：五四新文学；道德与法治：爱国主义与青年责任。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 中共一大：开天辟地的大事变","head":["时间","经过"],"rows":[["1921 年 7 月 23 日","中共一大在上海法租界望志路 106 号开幕，共 13 名代表出席"],["会议期间","遭法租界巡捕搜查，会议被迫中断"],["8 月初","代表转移到浙江嘉兴南湖游船上继续开会"],["会议决定","通过党的第一个纲领，确定党的名称、奋斗目标，选举陈独秀为中央局书记"],["意义","中国共产党诞生，中国革命的面貌焕然一新"]]},{"type":"note","title":"现场解说","text":"中国共产党的成立，是近代中国历史发展的必然结果。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["红船精神","中共一大在嘉兴南湖游船上闭幕，后以「红船」象征开天辟地、敢为人先的革命精神。","习近平《弘扬「红船精神」 走在时代前列》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"陈独秀","v":"中共一大选出的中央局书记。 出处：《中国共产党简史》"},{"k":"李大钊","v":"中国共产主义运动的先驱。 出处：《中国共产党简史》"}]},{"type":"list","title":"延伸阅读","items":["中共一大：出席大会的有毛泽东、董必武、李达等 13 名代表，代表全国 50 多名党员。大会确定党的名称为「中国共产党」，奋斗目标是推翻资产阶级政权、建立无产阶级专政、实现共产主义。 出处：《中国共产党简史》","中共二大：1922 年在上海召开，第一次提出彻底的反帝反封建的民主革命纲领。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《一大回忆录》","2024 部编版八上第 12 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】我们现在认定只有这两位先生，可以救治中国政治上、道德上、学术上、思想上一切的黑暗。——陈独秀《本志罪案之答辩书》（1919 年，《新青年》第六卷第一号）\n【材料二】中国的土地可以征服而不可以断送！中国的人民可以杀戮而不可以低头！——北京学生界宣言（1919 年 5 月）\n【材料三】中共一大通过的纲领确定：党的名称为中国共产党，党的奋斗目标是推翻资产阶级政权，建立无产阶级专政，消灭阶级差别，实现共产主义。","source":"材料研读 · 新民主主义革命的开始"}],"questions":[{"id":"h8a-u4-m1-q2","type":"short","stem":"（2）材料二体现了五四运动的什么精神？结合材料三说明中国共产党成立后中国革命为什么「面貌焕然一新」。（6 分）","answer":"精神：材料二表现出誓死捍卫国家主权、不向侵略者低头的爱国主义精神，即五四精神，其核心是爱国主义（还包括进步、民主、科学）。「焕然一新」的原因：中国共产党以马克思主义为指导思想，有了科学理论的指导；中共一大确定了推翻资产阶级政权、实现共产主义的奋斗目标，中共二大又第一次明确提出彻底的反帝反封建的民主革命纲领，使中国革命有了明确方向；中国共产党代表工人阶级和广大人民利益，能够深入发动群众，从而开辟了与以往一切政治力量都不相同的革命道路。","explain":"","tags":["五四运动","中共成立"],"rubric":["答出爱国主义/五四精神","答出以马克思主义为指导","答出提出彻底的反帝反封建纲领","答出代表人民利益、发动群众","答出中国革命有了坚强领导核心"]},{"id":"h8a-u4-q1","type":"choice","stem":"新文化运动开始的标志是","answer":"B","explain":"1915 年陈独秀在上海创办《青年杂志》（自第二卷起改名《新青年》），标志新文化运动开始。《天演论》是维新变法的思想武器。","options":["严复译述《天演论》","陈独秀在上海创办《青年杂志》","五四运动爆发","中共一大召开"],"tags":["新文化运动","时空观念"]},{"id":"h8a-u4-q2","type":"choice","stem":"五四运动爆发的导火线是","answer":"B","explain":"1919 年巴黎和会拒绝中国正当要求，竟将德国在山东的特权转让给日本，消息传回国内直接引发五四运动。","options":["日本提出「二十一条」","巴黎和会上中国外交的失败","北洋政府镇压学生游行","中国共产党号召反帝反封建"],"tags":["五四运动","历史解释"]},{"id":"h8a-u4-q3","type":"choice","stem":"五四运动被称为中国新民主主义革命的开端，主要因为它","answer":"C","explain":"判断革命阶段的关键是领导阶级与指导思想。五四运动中工人阶级成为主力，运动具有彻底反帝反封建的性质，因此成为新民主主义革命的开端。","options":["取得了彻底胜利","由学生首先发起","工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质","建立了中国共产党"],"tags":["五四运动","唯物史观"]},{"id":"h8a-u4-q4","type":"choice","stem":"中共一大确定党的奋斗目标是","answer":"B","explain":"中共一大通过党的第一个纲领，确定党的名称为中国共产党，奋斗目标是推翻资产阶级政权，建立无产阶级专政，实现共产主义。A 项是中共二大提出的民主革命纲领的内容。","options":["打倒军阀、推翻国际帝国主义的压迫","推翻资产阶级政权，建立无产阶级专政，实现共产主义","联俄、联共、扶助农工","建立抗日民族统一战线"],"tags":["中共一大","历史解释"]},{"id":"h8a-u4-q5","type":"choice","stem":"第一次明确提出彻底的反帝反封建民主革命纲领的会议是","answer":"B","explain":"1922 年中共二大重申最高纲领，并第一次明确提出彻底的反帝反封建的民主革命纲领，为中国革命指明了方向。","options":["中共一大","中共二大","国民党一大","中共七大"],"tags":["中共二大","历史解释"]},{"id":"cat-8a-4-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 李大钊发表《庶民的胜利》《布尔什维主义的胜利》\n② 中共一大在上海召开，后转到浙江嘉兴南湖游船\n③ 京汉铁路工人大罢工","answer":"A","explain":"按时间顺序应为：①李大钊发表《庶民的胜利》《布尔什维主义的胜利》（1918 年）→②中共一大在上海召开，后转到浙江嘉兴南湖游船（1921 年 7 月）→③京汉铁路工人大罢工（1923 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"cat-8a-4-2-g2","type":"choice","stem":"下列关于「中国共产党诞生」的表述，错误的是","answer":"A","explain":"把新民主主义革命的开端记为中国共产党成立——两个结论都对，但对应不同事件，必须按设问区分。正确表述：新民主主义革命的开端是五四运动（1919 年）；中国共产党的成立使中国革命的面貌焕然一新。","options":["把新民主主义革命的开端记为中国共产党成立。","新民主主义革命的开端是五四运动（1919 年）；中国共产党的成立使中国革命的面貌焕然一新。","新文化运动是**中国近代史上一次伟大的思想解放运动**：它动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放，为马克思主义在中国的传播创造了条件。","五四运动是**中国新民主主义革命的开端**：工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质，促进了马克思主义与中国工人运动的结合。"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"cat-8a-4-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：出席大会的有毛泽东、董必武、李达等 13 名代表，代表全国 50 多名党员。大会确定党的名称为「中国共产党」，奋斗目标是推翻资产阶级政权、建立无产阶级专政、实现共产主义。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中国共产党诞生；新文化运动：以《新青年》为主要阵地，代表人物有陈独秀、胡适、李大钊、鲁迅；提倡民主与科学，抨击旧道德和旧文化，提倡白话文。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-5-1","title":"第13课 国共合作与北伐战争","subtitle":"八年级上册 · 第五单元 从国共合作到农村革命根据地的建立","grade":"8a","tags":["八年级上册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第五单元 从国共合作到农村革命根据地的建立"},{"k":"课时","v":"第13课 国共合作与北伐战争"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1924 年，国民党一大在广州召开，标志国共第一次合作正式建立。同年创办黄埔军校，培养军事政治人才。1926 年国民革命军誓师北伐，打击吴佩孚、孙传芳、张作霖。1927 年蒋介石发动四一二反革命政变，国共合作破裂。"},{"type":"note","title":"本课主线 · 因果链","text":"国共第一次合作推动了国民革命与北伐战争的胜利进军，但国民党右派叛变革命使合作破裂；中国共产党发动南昌起义、秋收起义，创建井冈山革命根据地，开辟了农村包围城市、武装夺取政权的正确道路；第五次反「围剿」失败迫使红军长征，遵义会议在生死关头挽救了党和红军，长征的胜利使中国革命转危为安。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1924 年 1 月","国民党一大在广州召开","把旧三民主义发展为新三民主义，确立联俄、联共、扶助农工三大政策，标志国共第一次合作正式建立 · 重点"],["1924 年 5 月","黄埔军校在广州创办","孙中山任总理、蒋介石任校长、周恩来任政治部主任，为国民革命培养了大批军事政治人才"],["1926 年","国民革命军出师北伐","目标是吴佩孚、孙传芳、张作霖；到 1927 年基本推翻北洋军阀统治 · 重点"],["1927 年 4 月","四一二反革命政变，南京国民政府成立","蒋介石叛变革命，7 月汪精卫在武汉「分共」，国民革命失败；1928 年底东北易帜，南京国民政府在名义上统一全国"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1924 年 1 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"国民党一大在广州召开","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"1924 年 5 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"黄埔军校在广州创办","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"1926 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"国民革命军出师北伐","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1927 年 4 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"四一二反革命政变，南京国民政府成立","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"第一次国共合作的成果：创办黄埔军校，培养革命军事政治人才；推动北伐战争胜利进军，基本推翻了北洋军阀的统治。","explain":"北伐战争胜利进军的原因：国共合作、作战方针正确、将士英勇作战、工农群众的支持。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为北伐战争胜利了，国民革命就成功了。","北伐战争取得了胜利进军、基本推翻北洋军阀统治；但 1927 年蒋介石、汪精卫相继叛变革命，国民革命最终失败。","「北伐胜利」与「国民革命失败」两句话都对，指向不同层面，材料题常要求分别说明。"],["认为黄埔军校是中国共产党创办的。","黄埔军校是国共合作后由孙中山在广州创办的，蒋介石任校长、周恩来任政治部主任，是第一次国共合作的成果。","把国共共同创办的成果说成中共一家，是常见事实性错误。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["「转折点」类结论考查","常考遵义会议、长征胜利、南昌起义等事件的历史地位，答法固定：会议是「生死攸关的转折点」「走向成熟的标志」，起义是「第一枪」「建军节的由来」。"],["道路选择的因果分析","给出城市起义受挫与农村根据地发展的材料，要求说明「为什么中国革命必须走农村包围城市的道路」，需结合国情作答。"],["诗词与史料中的长征","以《七律·长征》或回忆录为材料，考查长征的艰难历程、胜利原因与长征精神，注意答题要「史实＋精神」两层。"]]},{"type":"note","title":"跨学科视角","text":"地理：井冈山、长征路线的地形；语文：毛泽东诗词中的革命情怀。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["联俄、联共、扶助农工","孙中山在国民党一大上确立的三大政策。","《孙中山全集》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"孙中山","v":"国民党总理，推动国共合作。 出处：《孙中山全集》"},{"k":"周恩来","v":"黄埔军校政治部主任，中共重要领导人。 出处：《周恩来传》"}]},{"type":"list","title":"延伸阅读","items":["黄埔军校：1924 年 5 月创办，全称「中国国民党陆军军官学校」，孙中山任总理，蒋介石任校长，周恩来任政治部主任。 出处：《黄埔军校史料》","北伐战争：1926 年 7 月誓师，以叶挺独立团为先锋，不到半年从珠江流域打到长江流域，基本消灭吴佩孚、孙传芳主力。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《黄埔军校史料》","2024 部编版八上第 13 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8a-u5-q1","type":"choice","stem":"标志国共第一次合作正式建立的事件是","answer":"B","explain":"1924 年 1 月国民党一大召开，把旧三民主义发展为新三民主义，确立联俄、联共、扶助农工三大政策，标志国共第一次合作正式建立。黄埔军校创办是合作的成果。","options":["中共三大的召开","国民党一大在广州召开","黄埔军校创办","北伐战争开始"],"tags":["国共合作","时空观念"]},{"id":"h8a-u5-q3","type":"choice","stem":"1927 年秋收起义受挫后，毛泽东率部队向井冈山进军，其深远意义在于","answer":"B","explain":"秋收起义受挫后转向农村，创建井冈山革命根据地，开辟了农村包围城市、武装夺取政权的道路，这是马克思主义与中国国情相结合的正确道路。","options":["完成了北伐战争的任务","开创了农村包围城市、武装夺取政权的革命道路","促成了国共第二次合作","建立了中华苏维埃共和国"],"tags":["井冈山道路","历史解释"]},{"id":"cat-8a-5-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 国民党一大在广州召开\n② 黄埔军校在广州创办\n③ 国民革命军出师北伐\n④ 四一二反革命政变，南京国民政府成立","answer":"A","explain":"按时间顺序应为：①国民党一大在广州召开（1924 年 1 月）→②黄埔军校在广州创办（1924 年 5 月）→③国民革命军出师北伐（1926 年）→④四一二反革命政变，南京国民政府成立（1927 年 4 月）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-1-g2","type":"choice","stem":"下列关于「国共合作与北伐战争」的表述，错误的是","answer":"A","explain":"认为北伐战争胜利了，国民革命就成功了——「北伐胜利」与「国民革命失败」两句话都对，指向不同层面，材料题常要求分别说明。正确表述：北伐战争取得了胜利进军、基本推翻北洋军阀统治；但 1927 年蒋介石、汪精卫相继叛变革命，国民革命最终失败。","options":["认为北伐战争胜利了，国民革命就成功了。","北伐战争取得了胜利进军、基本推翻北洋军阀统治；但 1927 年蒋介石、汪精卫相继叛变革命，国民革命最终失败。","**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。","第一次国共合作的成果：创办黄埔军校，培养革命军事政治人才；推动北伐战争胜利进军，基本推翻了北洋军阀的统治。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-1-g3","type":"choice","stem":"下列结论中，属于「国共合作与北伐战争」的是","answer":"A","explain":"本课结论：**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。","**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。","**遵义会议是党的历史上生死攸关的转折点**：它在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党从幼年走向成熟的标志。","**长征胜利使中国革命转危为安**：它保存了革命的基干力量，播下了革命种子，为开创抗日战争的新局面奠定了基础。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1924 年 5 月创办，全称「中国国民党陆军军官学校」，孙中山任总理，蒋介石任校长，周恩来任政治部主任。（《黄埔军校史料》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"国共合作与北伐战争；第一次国共合作的成果：创办黄埔军校，培养革命军事政治人才；推动北伐战争胜利进军，基本推翻了北洋军阀的统治。","explain":"材料出自《黄埔军校史料》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-5-2","title":"第14课 毛泽东开辟井冈山道路","subtitle":"八年级上册 · 第五单元 从国共合作到农村革命根据地的建立","grade":"8a","tags":["八年级上册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第五单元 从国共合作到农村革命根据地的建立"},{"k":"课时","v":"第14课 毛泽东开辟井冈山道路"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1927 年大革命失败后，中国共产党开始独立领导武装斗争。8 月 1 日南昌起义打响武装反抗国民党反动派第一枪；8 月 7 日八七会议确定土地革命和武装反抗的总方针；毛泽东领导秋收起义，转向农村，创建井冈山革命根据地。"},{"type":"note","title":"本课主线 · 因果链","text":"国共第一次合作推动了国民革命与北伐战争的胜利进军，但国民党右派叛变革命使合作破裂；中国共产党发动南昌起义、秋收起义，创建井冈山革命根据地，开辟了农村包围城市、武装夺取政权的正确道路；第五次反「围剿」失败迫使红军长征，遵义会议在生死关头挽救了党和红军，长征的胜利使中国革命转危为安。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1927 年 8 月 1 日","南昌起义","打响武装反抗国民党反动统治的第一枪，是中国共产党创建人民军队的开始 · 重点"],["1927 年 8—9 月","八七会议与秋收起义","八七会议确定土地革命和武装反抗国民党反动统治的总方针；秋收起义受挫后毛泽东率部队向井冈山进军"],["1928 年 4 月","井冈山会师，成立中国工农红军第四军","朱德任军长、毛泽东任党代表；井冈山是中国第一个农村革命根据地 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 南昌起义：打响第一枪","caption":"示意图：南昌起义：打响第一枪，详见下方「历史现场」","view":"tall","alt":"示意图：南昌起义：打响第一枪，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1927 年 7 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"大革命失败，中共中央决定在南昌发动武…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"8 月 1 日凌晨","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"周恩来、贺龙、叶挺、朱德、刘伯承率两…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"起义当天","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"经过数小时激战，占领南昌城","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"起义后","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"因敌强我弱，起义军南下广东，部分由朱…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1928 年 4 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"朱德、陈毅率部到达井冈山，与毛泽东部…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"南昌起义的意义：打响武装反抗国民党反动统治的第一枪，是中国共产党独立领导武装斗争、创建人民军队的开始，8 月 1 日由此成为建军节。","explain":"八七会议上毛泽东提出「政权是由枪杆子中取得的」，为革命指明了方向。"},{"level":"重点","text":"井冈山道路：秋收起义受挫后，毛泽东率部队向井冈山进军，创建中国第一个农村革命根据地；1928 年井冈山会师成立红四军。这条「农村包围城市、武装夺取政权」的道路，是中国革命从挫折走向胜利的正确道路。","explain":"为什么走这条路：中国是半殖民地半封建社会，敌人力量集中在城市，农村敌人力量薄弱、群众基础好，因此必须把工作重心放在农村。"},{"level":"次重点","text":"南昌起义与秋收起义的教训：城市武装起义屡遭挫折，说明照搬俄国十月革命的城市中心道路在中国行不通，必须结合中国国情。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把井冈山革命根据地与井冈山会师的时间、意义混在一起。","1927 年 10 月毛泽东创建井冈山革命根据地（第一个农村革命根据地）；1928 年 4 月井冈山会师成立红四军。","「创建根据地」与「会师建军队」是两件事，时序题常设陷阱。"]]},{"type":"table","title":"俄国十月革命道路与井冈山道路（两条革命道路：城市中心与农村包围城市）","head":["比较项","俄国十月革命道路","井冈山道路（中国）"],"rows":[["起点与重心","以中心城市起义为起点（彼得格勒）","以农村革命根据地为依托，向农村进军"],["基本方式","城市工人武装起义夺取政权","农村包围城市、武装夺取政权"],["适用国情","资本主义国家，工人阶级力量集中、城市是统治中心","半殖民地半封建社会，敌人力量集中在城市，农村基础薄弱"],["结果","建立了世界上第一个社会主义国家","开辟了中国革命的正确道路，为革命胜利奠定基础"],["共同启示","革命道路必须与本国的具体国情相结合，不能照搬照抄","同左"]]},{"type":"table","title":"南昌起义与秋收起义（两次武装起义的对比：从城市到农村的转变）","head":["比较项","南昌起义（1927 年 8 月 1 日）","秋收起义（1927 年 9 月）"],"rows":[["领导人","周恩来、贺龙、叶挺、朱德、刘伯承","毛泽东"],["进攻方向","攻占南昌等城市","进攻长沙受挫后转向井冈山"],["主要意义","打响武装反抗国民党反动统治的第一枪，创建人民军队的开始","创建中国第一个农村革命根据地，开辟井冈山道路"],["共同教训","城市中心道路在中国行不通，必须把革命重心转向农村","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["「转折点」类结论考查","常考遵义会议、长征胜利、南昌起义等事件的历史地位，答法固定：会议是「生死攸关的转折点」「走向成熟的标志」，起义是「第一枪」「建军节的由来」。"],["道路选择的因果分析","给出城市起义受挫与农村根据地发展的材料，要求说明「为什么中国革命必须走农村包围城市的道路」，需结合国情作答。"],["诗词与史料中的长征","以《七律·长征》或回忆录为材料，考查长征的艰难历程、胜利原因与长征精神，注意答题要「史实＋精神」两层。"]]},{"type":"note","title":"跨学科视角","text":"地理：井冈山、长征路线的地形；语文：毛泽东诗词中的革命情怀。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 南昌起义：打响第一枪","head":["时间","经过"],"rows":[["1927 年 7 月","大革命失败，中共中央决定在南昌发动武装起义"],["8 月 1 日凌晨","周恩来、贺龙、叶挺、朱德、刘伯承率两万余人在南昌起义"],["起义当天","经过数小时激战，占领南昌城"],["起义后","因敌强我弱，起义军南下广东，部分由朱德、陈毅率领转战湘南"],["1928 年 4 月","朱德、陈毅率部到达井冈山，与毛泽东部会师"]]},{"type":"note","title":"现场解说","text":"南昌起义是中国共产党独立领导武装斗争、创建人民军队的开始。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["星星之火，可以燎原","毛泽东 1930 年给林彪的信，比喻革命力量虽小但终将发展壮大。","《毛泽东选集》第一卷"]]},{"type":"kv","title":"人物卡片","items":[{"k":"毛泽东","v":"领导秋收起义，创建井冈山革命根据地。 出处：《毛泽东选集》"},{"k":"朱德","v":"南昌起义领导人之一，后与毛泽东井冈山会师。 出处：《朱德选集》"},{"k":"周恩来","v":"南昌起义前敌委员会书记。 出处：《周恩来传》"}]},{"type":"list","title":"延伸阅读","items":["井冈山会师：1928 年 4 月，朱德、陈毅率南昌起义余部与毛泽东领导的工农革命军在井冈山会师，合编为工农红军第四军。 出处：《中国共产党简史》","工农武装割据：毛泽东提出「农村包围城市、武装夺取政权」的道路，把武装斗争、土地革命、根据地建设结合起来。 出处：《毛泽东选集》第一卷"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《毛泽东选集》第一卷","2024 部编版八上第 14 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】边界红旗子始终不倒，不但表示了共产党的力量，而且表示了统治阶级的破产，在全国政治上有重大的意义。——毛泽东《井冈山的斗争》（1928 年）\n【材料二】红军不怕远征难，万水千山只等闲。五岭逶迤腾细浪，乌蒙磅礴走泥丸。金沙水拍云崖暖，大渡桥横铁索寒。更喜岷山千里雪，三军过后尽开颜。——毛泽东《七律·长征》（1935 年 10 月）\n【材料三】遵义会议集中全力解决了当时具有决定意义的军事和组织问题……开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位。","source":"材料研读 · 从国共合作到国共对立"}],"questions":[{"id":"h8a-u5-q2","type":"choice","stem":"南昌起义最重要的历史意义是","answer":"B","explain":"1927 年 8 月 1 日南昌起义打响武装反抗国民党反动统治的第一枪，是中国共产党独立领导武装斗争、创建人民军队的开始，故 8 月 1 日为建军节。","options":["建立了第一个农村革命根据地","打响武装反抗国民党反动统治的第一枪，是中国共产党创建人民军队的开始","开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位","使中国革命转危为安"],"tags":["南昌起义","历史解释"]},{"id":"h8a-u5-q3","type":"choice","stem":"1927 年秋收起义受挫后，毛泽东率部队向井冈山进军，其深远意义在于","answer":"B","explain":"秋收起义受挫后转向农村，创建井冈山革命根据地，开辟了农村包围城市、武装夺取政权的道路，这是马克思主义与中国国情相结合的正确道路。","options":["完成了北伐战争的任务","开创了农村包围城市、武装夺取政权的革命道路","促成了国共第二次合作","建立了中华苏维埃共和国"],"tags":["井冈山道路","历史解释"]},{"id":"cat-8a-5-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 南昌起义\n② 八七会议与秋收起义\n③ 井冈山会师，成立中国工农红军第四军","answer":"A","explain":"按时间顺序应为：①南昌起义（1927 年 8 月 1 日）→②八七会议与秋收起义（1927 年 8—9 月）→③井冈山会师，成立中国工农红军第四军（1928 年 4 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-2-g2","type":"choice","stem":"下列关于「毛泽东开辟井冈山道路」的表述，错误的是","answer":"A","explain":"把井冈山革命根据地与井冈山会师的时间、意义混在一起——「创建根据地」与「会师建军队」是两件事，时序题常设陷阱。正确表述：1927 年 10 月毛泽东创建井冈山革命根据地（第一个农村革命根据地）；1928 年 4 月井冈山会师成立红四军。","options":["把井冈山革命根据地与井冈山会师的时间、意义混在一起。","1927 年 10 月毛泽东创建井冈山革命根据地（第一个农村革命根据地）；1928 年 4 月井冈山会师成立红四军。","**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。","南昌起义的意义：打响武装反抗国民党反动统治的第一枪，是中国共产党独立领导武装斗争、创建人民军队的开始，8 月 1 日由此成为建军节。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-2-g3","type":"choice","stem":"下列结论中，属于「毛泽东开辟井冈山道路」的是","answer":"A","explain":"本课结论：**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。","**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。","**遵义会议是党的历史上生死攸关的转折点**：它在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党从幼年走向成熟的标志。","**长征胜利使中国革命转危为安**：它保存了革命的基干力量，播下了革命种子，为开创抗日战争的新局面奠定了基础。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1928 年 4 月，朱德、陈毅率南昌起义余部与毛泽东领导的工农革命军在井冈山会师，合编为工农红军第四军。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"毛泽东开辟井冈山道路；南昌起义的意义：打响武装反抗国民党反动统治的第一枪，是中国共产党独立领导武装斗争、创建人民军队的开始，8 月 1 日由此成为建军节。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-5-3","title":"第15课 中国工农红军长征与遵义会议","subtitle":"八年级上册 · 第五单元 从国共合作到农村革命根据地的建立","grade":"8a","tags":["八年级上册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第五单元 从国共合作到农村革命根据地的建立"},{"k":"课时","v":"第15课 中国工农红军长征与遵义会议"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1933 年第五次反「围剿」失败，红军被迫实行战略转移。1934 年 10 月开始长征，1935 年 1 月遵义会议纠正「左」倾错误，确立以毛泽东为代表的正确领导。红军四渡赤水、巧渡金沙江、强渡大渡河、飞夺泸定桥、爬雪山过草地，1936 年 10 月在甘肃会宁会师。"},{"type":"note","title":"本课主线 · 因果链","text":"国共第一次合作推动了国民革命与北伐战争的胜利进军，但国民党右派叛变革命使合作破裂；中国共产党发动南昌起义、秋收起义，创建井冈山革命根据地，开辟了农村包围城市、武装夺取政权的正确道路；第五次反「围剿」失败迫使红军长征，遵义会议在生死关头挽救了党和红军，长征的胜利使中国革命转危为安。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1928 年 4 月","井冈山会师，成立中国工农红军第四军","朱德任军长、毛泽东任党代表；井冈山是中国第一个农村革命根据地 · 重点"],["1934 年 10 月—1936 年 10 月","红军长征","1935 年 1 月遵义会议；1935 年 10 月中央红军到达陕北吴起镇；1936 年 10 月红军三大主力在甘肃会宁会师，长征胜利结束 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 长征路线：二万五千里","caption":"示意图：长征路线：二万五千里，详见下方「历史现场」","view":"tall","alt":"示意图：长征路线：二万五千里，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1934 年 10 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"中央红军从江西瑞金等地出发，开始长征","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":29.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":32.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":29.67,"text":"1935 年 1 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":35.67,"text":"遵义会议召开，确立毛泽东的领导地位","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":36.07,"x2":14,"y2":47.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":51.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":48.33,"text":"1935 年 1—3 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":54.33,"text":"四渡赤水，摆脱国民党军围追堵截","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":54.73,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1935 年 5 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"巧渡金沙江，强渡大渡河，飞夺泸定桥","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":85.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":88.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":85.67,"text":"1935 年 6—8 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":91.67,"text":"翻越夹金山等雪山，穿越茫茫草地","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":92.07,"x2":14,"y2":103.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":107.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":104.33,"text":"1935 年 10 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":110.33,"text":"中央红军到达陕北吴起镇","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":110.73,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1936 年 10 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"红一、二、四方面军在甘肃会宁会师，长…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"遵义会议（1935 年 1 月）：集中解决了军事和组织问题，开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位，是党的历史上生死攸关的转折点，是中国共产党从幼年走向成熟的标志。","explain":"「生死攸关的转折点」「从幼年走向成熟」是必须写出的固定术语。"},{"level":"重点","text":"长征胜利的意义：粉碎了国民党反动派消灭红军的企图，使中国革命转危为安；保存了党和红军的基干力量；播下了革命种子，铸就了伟大的长征精神。","explain":"长征精神：不怕牺牲、艰苦奋斗、坚定理想、团结互助。材料题常要求结合《七律·长征》等材料谈体会。"},{"level":"次重点","text":"1931 年冬，中华苏维埃共和国临时中央政府在江西瑞金成立，毛泽东任主席；红军力量壮大后，蒋介石连续发动「围剿」。","explain":""},{"level":"选择题","text":"红军长征的路线：中央革命根据地 → 突破湘江 → 遵义 → 四渡赤水 → 巧渡金沙江 → 强渡大渡河、飞夺泸定桥 → 爬雪山、过草地 → 陕北吴起镇 → 甘肃会宁会师。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["**遵义会议是党的历史上生死攸关的转折点**：它在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党从幼年走向成熟的标志。","**长征胜利使中国革命转危为安**：它保存了革命的基干力量，播下了革命种子，为开创抗日战争的新局面奠定了基础。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把长征结束的时间记成 1935 年。","1935 年 10 月中央红军到达陕北吴起镇；1936 年 10 月红军三大主力在甘肃会宁会师，长征胜利结束。","两个时间点分别对应「中央红军到达陕北」与「长征胜利结束」，注意题目问的是哪一个。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["「转折点」类结论考查","常考遵义会议、长征胜利、南昌起义等事件的历史地位，答法固定：会议是「生死攸关的转折点」「走向成熟的标志」，起义是「第一枪」「建军节的由来」。"],["道路选择的因果分析","给出城市起义受挫与农村根据地发展的材料，要求说明「为什么中国革命必须走农村包围城市的道路」，需结合国情作答。"],["诗词与史料中的长征","以《七律·长征》或回忆录为材料，考查长征的艰难历程、胜利原因与长征精神，注意答题要「史实＋精神」两层。"]]},{"type":"note","title":"跨学科视角","text":"地理：井冈山、长征路线的地形；语文：毛泽东诗词中的革命情怀。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 长征路线：二万五千里","head":["时间","经过"],"rows":[["1934 年 10 月","中央红军从江西瑞金等地出发，开始长征"],["1935 年 1 月","遵义会议召开，确立毛泽东的领导地位"],["1935 年 1—3 月","四渡赤水，摆脱国民党军围追堵截"],["1935 年 5 月","巧渡金沙江，强渡大渡河，飞夺泸定桥"],["1935 年 6—8 月","翻越夹金山等雪山，穿越茫茫草地"],["1935 年 10 月","中央红军到达陕北吴起镇"],["1936 年 10 月","红一、二、四方面军在甘肃会宁会师，长征胜利结束"]]},{"type":"note","title":"现场解说","text":"长征保存了党和红军的基干力量，播下革命种子，铸就长征精神。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["万水千山只等闲","毛泽东《七律·长征》诗句，表现红军不畏艰险的英雄气概。","毛泽东《七律·长征》"],["半条被子","长征途中三名女红军借宿湖南汝城徐解秀家，临走时把仅有的一床被子剪下一半留给老乡，体现军民鱼水情。","纪念红军长征胜利 80 周年相关报道"]]},{"type":"kv","title":"人物卡片","items":[{"k":"毛泽东","v":"遵义会议后确立在党中央和红军的领导地位。 出处：《毛泽东选集》"},{"k":"周恩来","v":"长征中协助毛泽东指挥军事。 出处：《周恩来传》"}]},{"type":"list","title":"延伸阅读","items":["遵义会议：1935 年 1 月，中共中央在遵义召开政治局扩大会议，集中解决军事和组织问题，确立了毛泽东在党中央和红军的领导地位，是党的历史上生死攸关的转折点。 出处：《中国共产党简史》","长征的里程：中央红军长征历时一年，纵横十余省，行程约二万五千里，翻越 18 座大山，跨过 24 条大河。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《毛泽东选集》第一卷","2024 部编版八上第 15 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】边界红旗子始终不倒，不但表示了共产党的力量，而且表示了统治阶级的破产，在全国政治上有重大的意义。——毛泽东《井冈山的斗争》（1928 年）\n【材料二】红军不怕远征难，万水千山只等闲。五岭逶迤腾细浪，乌蒙磅礴走泥丸。金沙水拍云崖暖，大渡桥横铁索寒。更喜岷山千里雪，三军过后尽开颜。——毛泽东《七律·长征》（1935 年 10 月）\n【材料三】遵义会议集中全力解决了当时具有决定意义的军事和组织问题……开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位。","source":"材料研读 · 从国共合作到国共对立"}],"questions":[{"id":"h8a-u5-m1-q2","type":"short","stem":"（2）材料二反映了怎样的革命精神？依据材料三说明遵义会议的历史地位。（5 分）","answer":"革命精神：《七律·长征》表现出红军不怕艰难险阻、革命乐观主义和坚定理想信念的精神，即长征精神——把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念；不怕牺牲、艰苦奋斗、团结互助。历史地位：遵义会议开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位，是党的历史上生死攸关的转折点，是中国共产党从幼年走向成熟的标志，为长征的胜利和中国革命的发展奠定了基础。","explain":"","tags":["长征","遵义会议"],"rubric":["答出不怕牺牲、艰苦奋斗的乐观精神","答出坚定的理想信念/长征精神","答出确立正确路线的领导地位","答出「生死攸关的转折点」","答出从幼年走向成熟的标志"]},{"id":"h8a-u5-q4","type":"choice","stem":"被称为「党的历史上生死攸关的转折点」的会议是","answer":"B","explain":"1935 年 1 月遵义会议开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位，在危急关头挽救了党、挽救了红军、挽救了中国革命。","options":["八七会议","遵义会议","中共七大","中共二大"],"tags":["遵义会议","历史解释"]},{"id":"h8a-u5-q5","type":"choice","stem":"红军长征胜利结束的标志是","answer":"C","explain":"1936 年 10 月红军三大主力在甘肃会宁会师，标志长征胜利结束；1935 年 10 月中央红军到达吴起镇是中央红军长征的结束。","options":["1935 年 1 月遵义会议的召开","1935 年 10 月中央红军到达陕北吴起镇","1936 年 10 月红军三大主力在甘肃会宁会师","1937 年七七事变的爆发"],"tags":["长征","时空观念"]},{"id":"cat-8a-5-3-g2","type":"choice","stem":"下列关于「中国工农红军长征与遵义会议」的表述，错误的是","answer":"A","explain":"把长征结束的时间记成 1935 年——两个时间点分别对应「中央红军到达陕北」与「长征胜利结束」，注意题目问的是哪一个。正确表述：1935 年 10 月中央红军到达陕北吴起镇；1936 年 10 月红军三大主力在甘肃会宁会师，长征胜利结束。","options":["把长征结束的时间记成 1935 年。","1935 年 10 月中央红军到达陕北吴起镇；1936 年 10 月红军三大主力在甘肃会宁会师，长征胜利结束。","**遵义会议是党的历史上生死攸关的转折点**：它在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党从幼年走向成熟的标志。","**长征胜利使中国革命转危为安**：它保存了革命的基干力量，播下了革命种子，为开创抗日战争的新局面奠定了基础。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1935 年 1 月，中共中央在遵义召开政治局扩大会议，集中解决军事和组织问题，确立了毛泽东在党中央和红军的领导地位，是党的历史上生死攸关的转折点。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中国工农红军长征与遵义会议；遵义会议（1935 年 1 月）：集中解决了军事和组织问题，开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位，是党的历史上生死攸关的转折点，是中国共产党从幼年走向成熟的标志。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-6-1","title":"第16课 从九一八事变到西安事变","subtitle":"八年级上册 · 第六单元 中华民族的抗日战争","grade":"8a","tags":["八年级上册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第六单元 中华民族的抗日战争"},{"k":"课时","v":"第16课 从九一八事变到西安事变"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1931 年 9 月 18 日，日本关东军炸毁南满铁路柳条湖段，嫁祸中国军队，进攻沈阳，九一八事变爆发。国民政府实行不抵抗政策，东北三省沦陷。1936 年 12 月 12 日，张学良、杨虎城在西安扣押蒋介石，逼其停止内战、联共抗日，后经中共调停和平解决。"},{"type":"note","title":"本课主线 · 因果链","text":"日本发动九一八事变揭开侵华序幕，中国人民的局部抗战开始；七七事变后全民族抗战开始，国共第二次合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中国共产党发挥了中流砥柱作用；1945 年抗日战争取得完全胜利，是近代以来中国反抗外敌入侵第一次取得完全胜利的民族解放战争。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1931 年 9 月 18 日","九一八事变","日本关东军炸毁南满铁路柳条湖段并进攻沈阳北大营；中国人民的局部抗战开始，这也是中国人民抗日战争的起点 · 重点"],["1936 年 12 月 12 日","西安事变（双十二事变）","张学良、杨虎城扣押蒋介石逼蒋抗日，中共派周恩来等调停、和平解决；十年内战基本结束，抗日民族统一战线初步形成 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 西安事变：13 天改变时局","caption":"示意图：西安事变：13 天改变时局，详见下方「历史现场」","view":"tall","alt":"示意图：西安事变：13 天改变时局，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1936 年 12 月 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"蒋介石到西安督战，逼迫张学良、杨虎城…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"12 月 12 日凌晨","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"张学良、杨虎城发动兵谏，扣押蒋介石，…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"12 月 13 日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"中共中央召开政治局会议，确定和平解决…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"12 月 17—23 日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"周恩来与张学良、杨虎城及蒋介石代表谈…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"12 月 24 日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"蒋介石接受停止内战、联共抗日等条件","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"12 月 25 日","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"张学良陪蒋介石回南京，西安事变和平解…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"九一八事变与局部抗战：日本发动九一八事变侵占东北，中国人民的局部抗战开始；由于蒋介石的不抵抗政策，东北三省沦陷。","explain":"注意「局部抗战」（1931—1937，东北抗日义勇军、东北抗日联军等）与「全民族抗战」（1937 年起）的区别与联系。"},{"level":"重点","text":"西安事变的和平解决：标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。","explain":"中共主张和平解决，是从全民族利益出发，说明中国共产党以民族大义为重。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","**中国共产党是全民族抗战的中流砥柱**：最早举起抗日旗帜、提出全面抗战路线、开辟敌后战场、坚持抗战、反对投降，为抗战胜利作出了决定性贡献。","抗日战争是**近代以来中国反抗外敌入侵第一次取得完全胜利的民族解放战争**：它洗雪了近代以来的民族耻辱，提高了中国的国际地位，是中华民族由衰败走向振兴的重大转折点。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把「中国人民抗日战争的起点」记为 1937 年七七事变。","中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","「起点」与「全民族抗战开始」是两个不同层级的结论，是高频易错点。"],["认为西安事变是中国共产党发动的。","西安事变由张学良、杨虎城发动；中国共产党主张和平解决并派周恩来等参加调停。","把发动者与调停者混淆是常见错误，注意「逼蒋抗日」是张、杨的举动。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["「中流砥柱」的史实论证","要求用史实说明中国共产党在抗战中的作用，可举：倡导并维护抗日民族统一战线、提出全面抗战路线、开辟敌后战场、平型关大捷与百团大战、坚持抗战反对投降。"],["时间界定的辨析","围绕 1931、1936、1937、1945 四个年份考查「局部抗战／全民族抗战／抗战胜利」的不同结论，是高频细节题。"],["暴行类材料的情感与论证","给出南京大屠杀等史料，要求在情感态度上「牢记历史、反对战争」，同时落回「落后就要挨打、民族自强」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：抗战战场与交通线；道德与法治：国家安全与民族精神。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 西安事变：13 天改变时局","head":["时间","经过"],"rows":[["1936 年 12 月 4 日","蒋介石到西安督战，逼迫张学良、杨虎城「剿共」"],["12 月 12 日凌晨","张学良、杨虎城发动兵谏，扣押蒋介石，提出停止内战、联共抗日八项主张"],["12 月 13 日","中共中央召开政治局会议，确定和平解决方针，派周恩来赴西安"],["12 月 17—23 日","周恩来与张学良、杨虎城及蒋介石代表谈判"],["12 月 24 日","蒋介石接受停止内战、联共抗日等条件"],["12 月 25 日","张学良陪蒋介石回南京，西安事变和平解决"]]},{"type":"note","title":"现场解说","text":"西安事变和平解决，标志着十年内战基本结束，抗日民族统一战线初步形成。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["攘外必先安内","蒋介石推行的政策，先「围剿」红军再抗日，助长了日本侵略。","2024 部编版八上第 16 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"张学良","v":"东北军将领，西安事变发动者之一。 出处：《西安事变史》"},{"k":"杨虎城","v":"西北军将领，西安事变发动者之一。 出处：《西安事变史》"},{"k":"杨靖宇","v":"东北抗日联军领导人，1940 年壮烈牺牲。 出处：《中国共产党简史》"}]},{"type":"list","title":"延伸阅读","items":["西安事变的和平解决：中共从全民族利益出发，主张和平解决，派周恩来等赴西安调停。蒋介石被迫接受停止内战、联共抗日的主张，西安事变和平解决，成为扭转时局的关键。 出处：《中国共产党简史》","东北抗联：九一八后，东北人民组织抗日义勇军，后改编为东北抗日联军，杨靖宇、赵尚志等领导坚持斗争。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《西安事变史》","2024 部编版八上第 16 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8a-u6-q1","type":"choice","stem":"中国人民抗日战争的起点，也是中国局部抗战开始的事件是","answer":"A","explain":"1931 年九一八事变是中国人民抗日战争的起点，中国人民的局部抗战由此开始；1937 年七七事变标志全民族抗战开始。","options":["九一八事变","华北事变","七七事变","八一三事变"],"tags":["九一八事变","时空观念"]},{"id":"h8a-u6-q2","type":"choice","stem":"西安事变和平解决的最重要意义是","answer":"B","explain":"西安事变的和平解决，标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。","options":["迫使蒋介石放弃了反共立场","标志十年内战基本结束，抗日民族统一战线初步形成","使红军获得了合法地位","标志抗日战争的胜利"],"tags":["西安事变","历史解释"]},{"id":"cat-8a-6-1-g2","type":"choice","stem":"下列关于「从九一八事变到西安事变」的表述，错误的是","answer":"A","explain":"把「中国人民抗日战争的起点」记为 1937 年七七事变——「起点」与「全民族抗战开始」是两个不同层级的结论，是高频易错点。正确表述：中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","options":["把「中国人民抗日战争的起点」记为 1937 年七七事变。","中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","**中国共产党是全民族抗战的中流砥柱**：最早举起抗日旗帜、提出全面抗战路线、开辟敌后战场、坚持抗战、反对投降，为抗战胜利作出了决定性贡献。"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：中共从全民族利益出发，主张和平解决，派周恩来等赴西安调停。蒋介石被迫接受停止内战、联共抗日的主张，西安事变和平解决，成为扭转时局的关键。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"从九一八事变到西安事变；九一八事变与局部抗战：日本发动九一八事变侵占东北，中国人民的局部抗战开始；由于蒋介石的不抵抗政策，东北三省沦陷。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-6-1-g5","type":"choice","stem":"「九一八事变」发生于","answer":"A","explain":"本课时间轴：九一八事变（1931 年 9 月 18 日）。日本关东军炸毁南满铁路柳条湖段并进攻沈阳北大营；中国人民的局部抗战开始，这也是中国人民抗日战争的起点。其余三个时间是同一单元相邻课时的事件时间。","options":["1931 年 9 月 18 日","1936 年 12 月 12 日","1937 年 7 月 7 日","1937 年 12 月 13 日"],"difficulty":1,"tags":["八年级上册","第六单元","本课练习"]}]},{"id":"cat-8a-6-2","title":"第17课 七七事变与全民族抗战","subtitle":"八年级上册 · 第六单元 中华民族的抗日战争","grade":"8a","tags":["八年级上册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第六单元 中华民族的抗日战争"},{"k":"课时","v":"第17课 七七事变与全民族抗战"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1937 年 7 月 7 日，日军进攻卢沟桥，七七事变爆发，全民族抗战开始。8 月 13 日日军进攻上海，淞沪会战爆发。9 月，国民党公布中共提交的国共合作宣言，抗日民族统一战线正式建立。12 月 13 日南京沦陷，日军制造南京大屠杀。"},{"type":"note","title":"本课主线 · 因果链","text":"日本发动九一八事变揭开侵华序幕，中国人民的局部抗战开始；七七事变后全民族抗战开始，国共第二次合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中国共产党发挥了中流砥柱作用；1945 年抗日战争取得完全胜利，是近代以来中国反抗外敌入侵第一次取得完全胜利的民族解放战争。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1936 年 12 月 12 日","西安事变（双十二事变）","张学良、杨虎城扣押蒋介石逼蒋抗日，中共派周恩来等调停、和平解决；十年内战基本结束，抗日民族统一战线初步形成 · 重点"],["1937 年 7 月 7 日","七七事变（卢沟桥事变）","日本发动全面侵华战争，中国全民族抗战由此开始 · 重点"],["1937 年 12 月 13 日","南京大屠杀","日军攻陷南京后屠杀中国军民 30 万人以上，是日本侵华暴行的铁证"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1936 年 12 月 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"西安事变（双十二事变）","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1937 年 7 月 7…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"七七事变（卢沟桥事变）","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1937 年 12 月 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"南京大屠杀","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"西安事变的和平解决：标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。","explain":"中共主张和平解决，是从全民族利益出发，说明中国共产党以民族大义为重。"},{"level":"重点","text":"七七事变后，国共两党实现第二次合作，正式建立抗日民族统一战线；中国全民族抗战开始。","explain":"抗日民族统一战线的建立是抗战胜利的根本保证，答题时必须写出「全民族抗战」。"},{"level":"次重点","text":"南京大屠杀：1937 年 12 月日军攻陷南京后进行长达六周的大屠杀，被害中国军民 30 万人以上，是日本军国主义侵华暴行的铁证。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把「中国人民抗日战争的起点」记为 1937 年七七事变。","中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","「起点」与「全民族抗战开始」是两个不同层级的结论，是高频易错点。"]]},{"type":"table","title":"两次国共合作（同一主题的两次合作：背景、形式与结果）","head":["比较项","第一次国共合作（1924—1927）","第二次国共合作（1937—1945）"],"rows":[["背景","反对北洋军阀统治，国民革命需要力量联合","日本扩大侵华，民族危机空前严重"],["标志","1924 年国民党一大召开","1937 年七七事变后，国共实现第二次合作，抗日民族统一战线正式建立"],["合作方式","党内合作，共产党员以个人身份加入国民党","党外合作，红军改编为八路军、新四军，陕甘宁边区政府成立"],["主要成果","创办黄埔军校，北伐战争胜利进军","全民族抗战，取得抗日战争的完全胜利"],["结局","国民党右派叛变革命，合作破裂，国民革命失败","抗战胜利后国民党发动内战，合作破裂"],["共同启示","国共合作则两利、分裂则两伤，民族团结是战胜强敌的保证","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["「中流砥柱」的史实论证","要求用史实说明中国共产党在抗战中的作用，可举：倡导并维护抗日民族统一战线、提出全面抗战路线、开辟敌后战场、平型关大捷与百团大战、坚持抗战反对投降。"],["时间界定的辨析","围绕 1931、1936、1937、1945 四个年份考查「局部抗战／全民族抗战／抗战胜利」的不同结论，是高频细节题。"],["暴行类材料的情感与论证","给出南京大屠杀等史料，要求在情感态度上「牢记历史、反对战争」，同时落回「落后就要挨打、民族自强」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：抗战战场与交通线；道德与法治：国家安全与民族精神。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"佟麟阁","v":"国民革命军第二十九军副军长，1937 年北平南苑战斗中殉国。 出处：《中国共产党简史》"},{"k":"赵登禹","v":"第二十九军一三二师师长，1937 年南苑战斗中殉国。 出处：《中国共产党简史》"}]},{"type":"list","title":"延伸阅读","items":["南京大屠杀：1937 年 12 月 13 日，日军攻陷南京后，进行了长达六周的大屠杀，杀害中国军民 30 万人以上。远东国际军事法庭和南京审判战犯军事法庭均确认了这一事实。 出处：远东国际军事法庭判决书；《南京大屠杀史料集》","淞沪会战：1937 年 8 月至 11 月，中国军队在上海地区与日军激战三个月，粉碎了日本「三个月灭亡中国」的迷梦。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；远东国际军事法庭判决书","2024 部编版八上第 17 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】战争的伟力之最深厚的根源，存在于民众之中。——毛泽东《论持久战》（1938 年）\n【材料二】中国共产党为公布国共合作宣言提出：孙中山先生的三民主义为中国今日之必需，本党愿为其彻底实现而奋斗；取消一切推翻国民党政权的暴动政策，取消现在的苏维埃政府，取消红军名义及番号，改编为国民革命军。——据 1937 年《中共中央为公布国共合作宣言》\n【材料三】1945 年 8 月 15 日，日本天皇宣布无条件投降；9 月 2 日日本正式签署投降书；10 月 25 日，台湾光复，回到祖国怀抱。","source":"材料研读 · 中华民族的抗日战争"}],"questions":[{"id":"h8a-u6-m1-q1","type":"short","stem":"（1）依据材料一，说明毛泽东提出了怎样的抗战主张；结合材料二指出中国共产党为建立抗日民族统一战线作出了哪些努力。（6 分）","answer":"主张：抗日战争必须是全民族的抗战，要广泛发动和依靠人民群众，实行全面抗战路线（《论持久战》还指出抗战是持久战，最后胜利属于中国）。努力：发表国共合作宣言，表示愿为彻底实现三民主义而奋斗；取消推翻国民党政权的暴动政策，取消苏维埃政府，把红军改编为国民革命军，主动作出让步；促成西安事变的和平解决，最终推动国共实现第二次合作，正式建立抗日民族统一战线。","explain":"","tags":["全民族抗战","史料实证"],"rubric":["答出全民族抗战/全面抗战路线","答出发动依靠人民群众","答出发表国共合作宣言、改编红军等让步","答出推动国共第二次合作、建立统一战线"]},{"id":"h8a-u6-q1","type":"choice","stem":"中国人民抗日战争的起点，也是中国局部抗战开始的事件是","answer":"A","explain":"1931 年九一八事变是中国人民抗日战争的起点，中国人民的局部抗战由此开始；1937 年七七事变标志全民族抗战开始。","options":["九一八事变","华北事变","七七事变","八一三事变"],"tags":["九一八事变","时空观念"]},{"id":"h8a-u6-q2","type":"choice","stem":"西安事变和平解决的最重要意义是","answer":"B","explain":"西安事变的和平解决，标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。","options":["迫使蒋介石放弃了反共立场","标志十年内战基本结束，抗日民族统一战线初步形成","使红军获得了合法地位","标志抗日战争的胜利"],"tags":["西安事变","历史解释"]},{"id":"cat-8a-6-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 西安事变（双十二事变）\n② 七七事变（卢沟桥事变）\n③ 南京大屠杀","answer":"A","explain":"按时间顺序应为：①西安事变（双十二事变）（1936 年 12 月 12 日）→②七七事变（卢沟桥事变）（1937 年 7 月 7 日）→③南京大屠杀（1937 年 12 月 13 日）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-2-g2","type":"choice","stem":"下列关于「七七事变与全民族抗战」的表述，错误的是","answer":"A","explain":"把「中国人民抗日战争的起点」记为 1937 年七七事变——「起点」与「全民族抗战开始」是两个不同层级的结论，是高频易错点。正确表述：中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","options":["把「中国人民抗日战争的起点」记为 1937 年七七事变。","中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","西安事变的和平解决：标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1937 年 12 月 13 日，日军攻陷南京后，进行了长达六周的大屠杀，杀害中国军民 30 万人以上。远东国际军事法庭和南京审判战犯军事法庭均确认了这一事实。（远东国际军事法庭判决书；《南京大屠杀史料集》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"七七事变与全民族抗战；西安事变的和平解决：标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。","explain":"材料出自远东国际军事法庭判决书；《南京大屠杀史料集》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-6-3","title":"第18课 全民族抗战中的正面战场和敌后战场","subtitle":"八年级上册 · 第六单元 中华民族的抗日战争","grade":"8a","tags":["八年级上册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第六单元 中华民族的抗日战争"},{"k":"课时","v":"第18课 全民族抗战中的正面战场和敌后战场"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"全民族抗战中，国民党正面战场与共产党敌后战场相互配合。1938 年台儿庄战役取得重大胜利；八路军 1937 年平型关大捷，打破日军不可战胜的神话；1940 年彭德怀指挥百团大战，沉重打击日军。"},{"type":"note","title":"本课主线 · 因果链","text":"日本发动九一八事变揭开侵华序幕，中国人民的局部抗战开始；七七事变后全民族抗战开始，国共第二次合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中国共产党发挥了中流砥柱作用；1945 年抗日战争取得完全胜利，是近代以来中国反抗外敌入侵第一次取得完全胜利的民族解放战争。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1937 年 9 月","平型关大捷","八路军第 115 师取得的胜利，是全国抗战爆发后中国军队主动出击的第一个大胜仗"],["1938 年 3—4 月","台儿庄战役","李宗仁指挥，歼敌 1 万余人，是抗战以来中国正面战场取得的最大一场胜仗"],["1940 年下半年","百团大战","彭德怀指挥八路军 105 个团破袭日军交通线，有力打击了日军的侵略气焰，提高了共产党和八路军的威望"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1937 年 9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"平型关大捷","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1938 年 3—4 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"台儿庄战役","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1940 年下半年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"百团大战","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"两个战场：正面战场（淞沪会战、台儿庄战役、武汉会战、第三次长沙会战）与敌后战场（平型关大捷、百团大战、抗日根据地）相互配合，共同抗击日本侵略者。","explain":"台儿庄战役是「正面战场取得的最大一场胜仗」；百团大战是「敌后战场主动出击日军的最大规模战役」，两个「最大」不能互换。"},{"level":"重点","text":"抗日战争胜利的历史意义：它是近代以来中国反抗外敌入侵第一次取得完全胜利的民族解放战争；中国战场是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利、维护世界和平作出了巨大贡献；提高了中国的国际地位。","explain":"胜利原因：中国共产党发挥中流砥柱作用（提出全面抗战路线、开辟敌后战场、坚持抗战到底）；全民族抗战；正义的反侵略战争；世界反法西斯力量的支持。"},{"level":"选择题","text":"1935 年一二·九运动促进了抗日救亡运动的新高涨；1938 年武汉会战后抗日战争进入相持阶段；1945 年 10 月 25 日台湾光复，回到祖国怀抱。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","**中国共产党是全民族抗战的中流砥柱**：最早举起抗日旗帜、提出全面抗战路线、开辟敌后战场、坚持抗战、反对投降，为抗战胜利作出了决定性贡献。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把台儿庄战役与百团大战的战场和意义弄反。","台儿庄战役是正面战场取得的最大一场胜仗（李宗仁指挥，国民党军队）；百团大战是敌后战场主动出击日军的最大规模战役（彭德怀指挥，八路军）。","两个「最大」分别属于不同战场，材料题按「战场—指挥者—意义」三项对应作答。"]]},{"type":"table","title":"正面战场与敌后战场（抗日战争中的两个战场：相互配合、共同抗战）","head":["比较项","正面战场（国民党军队）","敌后战场（中国共产党领导）"],"rows":[["代表战役","淞沪会战、台儿庄战役、武汉会战、第三次长沙会战","平型关大捷、百团大战"],["作战方式","大兵团阵地战、会战","游击战、运动战，建立抗日根据地"],["作用","粉碎日军速战速决的企图，牵制大量日军","威胁日军后方，配合正面战场，逐步成为抗战的主战场"],["关系","两个战场相互配合、互为依存，共同构成全民族抗战","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["「中流砥柱」的史实论证","要求用史实说明中国共产党在抗战中的作用，可举：倡导并维护抗日民族统一战线、提出全面抗战路线、开辟敌后战场、平型关大捷与百团大战、坚持抗战反对投降。"],["时间界定的辨析","围绕 1931、1936、1937、1945 四个年份考查「局部抗战／全民族抗战／抗战胜利」的不同结论，是高频细节题。"],["暴行类材料的情感与论证","给出南京大屠杀等史料，要求在情感态度上「牢记历史、反对战争」，同时落回「落后就要挨打、民族自强」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：抗战战场与交通线；道德与法治：国家安全与民族精神。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"李宗仁","v":"国民党将领，指挥台儿庄战役。 出处：《李宗仁回忆录》"},{"k":"彭德怀","v":"八路军副总司令，指挥百团大战。 出处：《彭德怀自述》"}]},{"type":"list","title":"延伸阅读","items":["台儿庄战役：1938 年 3—4 月，李宗仁指挥中国军队在台儿庄地区与日军激战，歼敌一万余人，是抗战以来正面战场取得的最大胜利。 出处：《中国共产党简史》","百团大战：1940 年 8 月至 1941 年 1 月，八路军在彭德怀指挥下，出动 105 个团，破坏交通线、拔除据点，毙伤日伪军两万余人。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《彭德怀自述》","2024 部编版八上第 18 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8a-u6-q3","type":"choice","stem":"下列战役中，属于抗战以来中国正面战场取得的最大一场胜仗的是","answer":"B","explain":"1938 年台儿庄战役由李宗仁指挥，歼敌 1 万余人，是抗战以来中国正面战场取得的最大一场胜仗。平型关大捷与百团大战属于敌后战场的作战。","options":["平型关大捷","台儿庄战役","百团大战","第三次长沙会战"],"tags":["台儿庄战役","时空观念"]},{"id":"cat-8a-6-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 平型关大捷\n② 台儿庄战役\n③ 百团大战","answer":"A","explain":"按时间顺序应为：①平型关大捷（1937 年 9 月）→②台儿庄战役（1938 年 3—4 月）→③百团大战（1940 年下半年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-3-g2","type":"choice","stem":"下列关于「全民族抗战中的正面战场和敌后战场」的表述，错误的是","answer":"A","explain":"把台儿庄战役与百团大战的战场和意义弄反——两个「最大」分别属于不同战场，材料题按「战场—指挥者—意义」三项对应作答。正确表述：台儿庄战役是正面战场取得的最大一场胜仗（李宗仁指挥，国民党军队）；百团大战是敌后战场主动出击日军的最大规模战役（彭德怀指挥，八路军）。","options":["把台儿庄战役与百团大战的战场和意义弄反。","台儿庄战役是正面战场取得的最大一场胜仗（李宗仁指挥，国民党军队）；百团大战是敌后战场主动出击日军的最大规模战役（彭德怀指挥，八路军）。","**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","**中国共产党是全民族抗战的中流砥柱**：最早举起抗日旗帜、提出全面抗战路线、开辟敌后战场、坚持抗战、反对投降，为抗战胜利作出了决定性贡献。"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1938 年 3—4 月，李宗仁指挥中国军队在台儿庄地区与日军激战，歼敌一万余人，是抗战以来正面战场取得的最大胜利。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"全民族抗战中的正面战场和敌后战场；两个战场：正面战场（淞沪会战、台儿庄战役、武汉会战、第三次长沙会战）与敌后战场（平型关大捷、百团大战、抗日根据地）相互配合，共同抗击日本侵略者。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-6-3-g5","type":"choice","stem":"「平型关大捷」发生于","answer":"A","explain":"本课时间轴：平型关大捷（1937 年 9 月）。八路军第 115 师取得的胜利，是全国抗战爆发后中国军队主动出击的第一个大胜仗。其余三个时间是同一单元相邻课时的事件时间。","options":["1937 年 9 月","1931 年 9 月 18 日","1936 年 12 月 12 日","1937 年 7 月 7 日"],"difficulty":1,"tags":["八年级上册","第六单元","本课练习"]}]},{"id":"cat-8a-6-4","title":"第19课 抗日战争的胜利","subtitle":"八年级上册 · 第六单元 中华民族的抗日战争","grade":"8a","tags":["八年级上册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第六单元 中华民族的抗日战争"},{"k":"课时","v":"第19课 抗日战争的胜利"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1945 年 8 月，美国投掷原子弹，苏联对日宣战并出兵中国东北。8 月 15 日，日本天皇宣布无条件投降；9 月 2 日，日本在投降书上签字。10 月 25 日，台湾光复。抗日战争是中国近代以来抗击外敌入侵第一次取得完全胜利的民族解放战争。"},{"type":"note","title":"本课主线 · 因果链","text":"日本发动九一八事变揭开侵华序幕，中国人民的局部抗战开始；七七事变后全民族抗战开始，国共第二次合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中国共产党发挥了中流砥柱作用；1945 年抗日战争取得完全胜利，是近代以来中国反抗外敌入侵第一次取得完全胜利的民族解放战争。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1945 年 8 月 15 日—9 月 2 日","日本宣布无条件投降并签署投降书","9 月 3 日为中国人民抗日战争胜利纪念日；10 月 25 日台湾光复 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"tall","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":17,"text":"七七事变后，国共两党实现第二次合作，…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"选择题","anchor":"start","size":3.5,"tone":"muted"},{"t":"text","x":18.5,"y":45,"text":"1935 年一二·九运动促进了抗日救…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":73,"text":"**全民族抗战是抗战胜利的根本保证*…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":101,"text":"**中国共产党是全民族抗战的中流砥柱…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":129,"text":"抗战胜利的启示：**落后就要挨打，自…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"七七事变后，国共两党实现第二次合作，正式建立抗日民族统一战线；中国全民族抗战开始。","explain":"抗日民族统一战线的建立是抗战胜利的根本保证，答题时必须写出「全民族抗战」。"},{"level":"选择题","text":"1935 年一二·九运动促进了抗日救亡运动的新高涨；1938 年武汉会战后抗日战争进入相持阶段；1945 年 10 月 25 日台湾光复，回到祖国怀抱。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","**中国共产党是全民族抗战的中流砥柱**：最早举起抗日旗帜、提出全面抗战路线、开辟敌后战场、坚持抗战、反对投降，为抗战胜利作出了决定性贡献。","抗战胜利的启示：**落后就要挨打，自强才能自立**；只有民族团结、国家统一，才能战胜外来侵略；要牢记历史、珍爱和平、开创未来。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把「中国人民抗日战争的起点」记为 1937 年七七事变。","中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","「起点」与「全民族抗战开始」是两个不同层级的结论，是高频易错点。"],["把台儿庄战役与百团大战的战场和意义弄反。","台儿庄战役是正面战场取得的最大一场胜仗（李宗仁指挥，国民党军队）；百团大战是敌后战场主动出击日军的最大规模战役（彭德怀指挥，八路军）。","两个「最大」分别属于不同战场，材料题按「战场—指挥者—意义」三项对应作答。"]]},{"type":"table","title":"两次国共合作（同一主题的两次合作：背景、形式与结果）","head":["比较项","第一次国共合作（1924—1927）","第二次国共合作（1937—1945）"],"rows":[["背景","反对北洋军阀统治，国民革命需要力量联合","日本扩大侵华，民族危机空前严重"],["标志","1924 年国民党一大召开","1937 年七七事变后，国共实现第二次合作，抗日民族统一战线正式建立"],["合作方式","党内合作，共产党员以个人身份加入国民党","党外合作，红军改编为八路军、新四军，陕甘宁边区政府成立"],["主要成果","创办黄埔军校，北伐战争胜利进军","全民族抗战，取得抗日战争的完全胜利"],["结局","国民党右派叛变革命，合作破裂，国民革命失败","抗战胜利后国民党发动内战，合作破裂"],["共同启示","国共合作则两利、分裂则两伤，民族团结是战胜强敌的保证","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["「中流砥柱」的史实论证","要求用史实说明中国共产党在抗战中的作用，可举：倡导并维护抗日民族统一战线、提出全面抗战路线、开辟敌后战场、平型关大捷与百团大战、坚持抗战反对投降。"],["时间界定的辨析","围绕 1931、1936、1937、1945 四个年份考查「局部抗战／全民族抗战／抗战胜利」的不同结论，是高频细节题。"],["暴行类材料的情感与论证","给出南京大屠杀等史料，要求在情感态度上「牢记历史、反对战争」，同时落回「落后就要挨打、民族自强」的认识。"]]},{"type":"note","title":"跨学科视角","text":"地理：抗战战场与交通线；道德与法治：国家安全与民族精神。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["抗战胜利的原因：中国人民巨大的民族觉醒、空前的民族团结和英勇的民族抗争，是抗战胜利的决定性因素；世界反法西斯力量的配合也是重要条件。 出处：2024 部编版八上第 19 课","台湾光复：1945 年 10 月 25 日，中国战区台湾省受降仪式在台北举行，台湾重回祖国怀抱。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《抗日战争胜利档案》","2024 部编版八上第 19 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】战争的伟力之最深厚的根源，存在于民众之中。——毛泽东《论持久战》（1938 年）\n【材料二】中国共产党为公布国共合作宣言提出：孙中山先生的三民主义为中国今日之必需，本党愿为其彻底实现而奋斗；取消一切推翻国民党政权的暴动政策，取消现在的苏维埃政府，取消红军名义及番号，改编为国民革命军。——据 1937 年《中共中央为公布国共合作宣言》\n【材料三】1945 年 8 月 15 日，日本天皇宣布无条件投降；9 月 2 日日本正式签署投降书；10 月 25 日，台湾光复，回到祖国怀抱。","source":"材料研读 · 中华民族的抗日战争"}],"questions":[{"id":"h8a-u6-q1","type":"choice","stem":"中国人民抗日战争的起点，也是中国局部抗战开始的事件是","answer":"A","explain":"1931 年九一八事变是中国人民抗日战争的起点，中国人民的局部抗战由此开始；1937 年七七事变标志全民族抗战开始。","options":["九一八事变","华北事变","七七事变","八一三事变"],"tags":["九一八事变","时空观念"]},{"id":"h8a-u6-q2","type":"choice","stem":"西安事变和平解决的最重要意义是","answer":"B","explain":"西安事变的和平解决，标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。","options":["迫使蒋介石放弃了反共立场","标志十年内战基本结束，抗日民族统一战线初步形成","使红军获得了合法地位","标志抗日战争的胜利"],"tags":["西安事变","历史解释"]},{"id":"h8a-u6-q3","type":"choice","stem":"下列战役中，属于抗战以来中国正面战场取得的最大一场胜仗的是","answer":"B","explain":"1938 年台儿庄战役由李宗仁指挥，歼敌 1 万余人，是抗战以来中国正面战场取得的最大一场胜仗。平型关大捷与百团大战属于敌后战场的作战。","options":["平型关大捷","台儿庄战役","百团大战","第三次长沙会战"],"tags":["台儿庄战役","时空观念"]},{"id":"cat-8a-6-4-g2","type":"choice","stem":"下列关于「抗日战争的胜利」的表述，错误的是","answer":"A","explain":"把「中国人民抗日战争的起点」记为 1937 年七七事变——「起点」与「全民族抗战开始」是两个不同层级的结论，是高频易错点。正确表述：中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","options":["把「中国人民抗日战争的起点」记为 1937 年七七事变。","中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","**中国共产党是全民族抗战的中流砥柱**：最早举起抗日旗帜、提出全面抗战路线、开辟敌后战场、坚持抗战、反对投降，为抗战胜利作出了决定性贡献。"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：中国人民巨大的民族觉醒、空前的民族团结和英勇的民族抗争，是抗战胜利的决定性因素；世界反法西斯力量的配合也是重要条件。（2024 部编版八上第 19 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"抗日战争的胜利；七七事变后，国共两党实现第二次合作，正式建立抗日民族统一战线；中国全民族抗战开始。","explain":"材料出自2024 部编版八上第 19 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-7-1","title":"第20课 国民党挑起内战","subtitle":"八年级上册 · 第七单元 人民解放战争","grade":"8a","tags":["八年级上册","第七单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第七单元 人民解放战争"},{"k":"课时","v":"第20课 国民党挑起内战"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"抗战胜利后，中国面临两种前途、两种命运的抉择。1945 年 8 月，毛泽东赴重庆谈判，签订《双十协定》。1946 年 6 月，国民党军队进攻中原解放区，全面内战爆发。"},{"type":"note","title":"本课主线 · 因果链","text":"抗战胜利后，中国共产党为争取和平民主赴重庆谈判，但国民党于 1946 年发动全面内战；人民解放军以运动战粉碎敌人进攻，1947 年转入战略进攻，通过土地改革赢得亿万农民的支持，1948—1949 年三大战役基本消灭国民党军队主力，1949 年 4 月渡江战役解放南京，国民党在大陆的统治覆亡。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1945 年 8—10 月","重庆谈判","毛泽东赴重庆谈判，10 月 10 日国共双方签署《政府与中共代表会谈纪要》（《双十协定》），确定和平建国的基本方针 · 重点"],["1946 年 6 月","国民党军队进攻中原解放区","全面内战爆发 · 重点"],["1947 年 3 月","国民党军队重点进攻陕北和山东解放区","中共中央主动撤出延安，转战陕北，彭德怀率西北野战军接连取得胜利"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1945 年 8—10 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"重庆谈判","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1946 年 6 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"国民党军队进攻中原解放区","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1947 年 3 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"国民党军队重点进攻陕北和山东解放区","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"重庆谈判：蒋介石一面积极准备内战、一面三次电邀毛泽东赴重庆，企图赢得备战时间并把内战责任推给共产党；毛泽东赴重庆谈判是为了尽一切可能争取和平、揭穿蒋介石假和平真内战的阴谋、教育人民。","explain":"成果是 1945 年 10 月 10 日签署《双十协定》，但蒋介石并未履行，1946 年 6 月全面内战爆发。"},{"level":"次重点","text":"转战陕北与战略进攻：面对国民党的重点进攻，中共中央主动撤出延安、转战陕北；1947 年夏刘邓大军挺进大别山，揭开人民解放军战略进攻的序幕。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["国民党的失败是必然的：**发动内战不得人心，政治孤立、经济崩溃、失去民心**，其失败证明了「谁代表人民利益，谁就能赢得胜利」。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把全面内战爆发的标志记为重庆谈判破裂或《双十协定》被撕毁。","1946 年 6 月国民党军队进攻中原解放区，标志着全面内战爆发。","《双十协定》后蒋介石仍加紧备战，标志性事件必须是军事进攻，属高频细节。"]]},{"type":"table","title":"国共两党在解放战争中的两种命运（两种道路、两种命运的历史抉择）","head":["比较项","中国共产党","国民党"],"rows":[["政治主张","和平、民主、团结，建立新民主主义国家","坚持独裁统治，发动内战"],["与人民的关系","进行土地改革，实行耕者有其田，赢得农民支持","维护封建土地制度，横征暴敛，失去民心"],["军队与士气","人民解放军英勇作战，纪律严明，士气高昂","军队腐化，士气低落，大量起义与投诚"],["经济状况","解放区生产发展，人民踊跃支援前线","国统区通货膨胀、经济崩溃"],["历史结果","由防御转入进攻、决战，最终取得胜利","主力被消灭，1949 年 4 月南京解放，统治覆亡"],["结论","得民心者得天下，中国共产党代表最广大人民的根本利益，因此必然胜利","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["「人民的支持」类论证题","给出台词「淮海战役的胜利是人民群众用小车推出来的」等材料，要求用史实说明人民群众在解放战争中的作用，落脚在「得民心者得天下」。"],["阶段划分与事件排序","要求按「战略防御—战略进攻—战略决战—渡江战役」排列事件并说明每一阶段的标志性事件，考查时序与阶段特征。"],["谈判类史料的意图分析","以重庆谈判为切口，考查国共双方的谈判目的与《双十协定》的落实情况，答题要写出「蒋介石假和平真内战」与中共「争取和平」的双重立场。"]]},{"type":"note","title":"跨学科视角","text":"地理：三大战役的地域；道德与法治：人民至上与制度选择。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["双十协定","1945 年 10 月 10 日国共双方签订的会谈纪要，确定和平建国方针。","《中国共产党简史》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"毛泽东","v":"赴重庆谈判，领导人民解放战争。 出处：《毛泽东选集》第四卷"}]},{"type":"list","title":"延伸阅读","items":["重庆谈判：1945 年 8 月 28 日至 10 月 10 日，毛泽东应蒋介石邀请赴重庆谈判，双方签订《政府与中共代表会谈纪要》（《双十协定》），确定和平建国方针。 出处：《中国共产党简史》","转战陕北：1947 年 3 月，国民党军进攻延安，中共中央主动撤离，毛泽东、周恩来等转战陕北，指挥全国解放战争。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《毛泽东选集》第四卷","2024 部编版八上第 20 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8a-u7-q1","type":"choice","stem":"1945 年毛泽东赴重庆谈判的主要目的是","answer":"A","explain":"毛泽东赴重庆谈判是为了尽一切可能争取和平、避免内战，同时揭穿蒋介石假和平真内战的阴谋，教育人民、争取政治上的主动。","options":["争取和平民主，揭穿蒋介石假和平真内战的阴谋","与国民党共同建立联合政府","争取美国对中共的支持","拖延时间准备内战"],"tags":["重庆谈判","历史解释"]},{"id":"h8a-u7-q2","type":"choice","stem":"全面内战爆发的标志是","answer":"B","explain":"1946 年 6 月，国民党军队 20 多万人进攻中原解放区，标志着全面内战爆发。进攻延安与挺进大别山都发生在 1947 年。","options":["《双十协定》被撕毁","1946 年 6 月国民党军队进攻中原解放区","国民党军队进攻延安","刘邓大军挺进大别山"],"tags":["全面内战","时空观念"]},{"id":"h8a-u7-q3","type":"choice","stem":"揭开了人民解放军战略进攻序幕的事件是","answer":"B","explain":"1947 年夏，刘伯承、邓小平率晋冀鲁豫解放军主力挺进大别山，直接威胁国民党统治中心南京、武汉，揭开了人民解放军战略进攻的序幕。","options":["转战陕北","刘伯承、邓小平率部挺进大别山","辽沈战役开始","渡江战役开始"],"tags":["战略进攻","时空观念"]},{"id":"cat-8a-7-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 重庆谈判\n② 国民党军队进攻中原解放区\n③ 国民党军队重点进攻陕北和山东解放区","answer":"A","explain":"按时间顺序应为：①重庆谈判（1945 年 8—10 月）→②国民党军队进攻中原解放区（1946 年 6 月）→③国民党军队重点进攻陕北和山东解放区（1947 年 3 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"cat-8a-7-1-g2","type":"choice","stem":"下列关于「国民党挑起内战」的表述，错误的是","answer":"A","explain":"把全面内战爆发的标志记为重庆谈判破裂或《双十协定》被撕毁——《双十协定》后蒋介石仍加紧备战，标志性事件必须是军事进攻，属高频细节。正确表述：1946 年 6 月国民党军队进攻中原解放区，标志着全面内战爆发。","options":["把全面内战爆发的标志记为重庆谈判破裂或《双十协定》被撕毁。","1946 年 6 月国民党军队进攻中原解放区，标志着全面内战爆发。","国民党的失败是必然的：**发动内战不得人心，政治孤立、经济崩溃、失去民心**，其失败证明了「谁代表人民利益，谁就能赢得胜利」。","重庆谈判：蒋介石一面积极准备内战、一面三次电邀毛泽东赴重庆，企图赢得备战时间并把内战责任推给共产党；毛泽东赴重庆谈判是为了尽一切可能争取和平、揭穿蒋介石假和平真内战的阴谋、教育人民。"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"cat-8a-7-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1945 年 8 月 28 日至 10 月 10 日，毛泽东应蒋介石邀请赴重庆谈判，双方签订《政府与中共代表会谈纪要》（《双十协定》），确定和平建国方针。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"国民党挑起内战；重庆谈判：蒋介石一面积极准备内战、一面三次电邀毛泽东赴重庆，企图赢得备战时间并把内战责任推给共产党；毛泽东赴重庆谈判是为了尽一切可能争取和平、揭穿蒋介石假和平真内战的阴谋、教育人民。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第七单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-7-2","title":"第21课 人民解放战争的胜利","subtitle":"八年级上册 · 第七单元 人民解放战争","grade":"8a","tags":["八年级上册","第七单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第七单元 人民解放战争"},{"k":"课时","v":"第21课 人民解放战争的胜利"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1947 年，解放区进行土地改革，激发农民革命热情。1948 年 9 月至 1949 年 1 月，人民解放军进行辽沈、淮海、平津三大战役，基本消灭国民党军队主力。1949 年 4 月渡江战役，解放南京，国民党政权覆灭。"},{"type":"note","title":"本课主线 · 因果链","text":"抗战胜利后，中国共产党为争取和平民主赴重庆谈判，但国民党于 1946 年发动全面内战；人民解放军以运动战粉碎敌人进攻，1947 年转入战略进攻，通过土地改革赢得亿万农民的支持，1948—1949 年三大战役基本消灭国民党军队主力，1949 年 4 月渡江战役解放南京，国民党在大陆的统治覆亡。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1947 年","中国共产党颁布《中国土地法大纲》","解放区实行土地改革，实行耕者有其田，为解放战争胜利提供了人力物力保障"],["1948 年 9 月—1949 年 1 月","辽沈、淮海、平津三大战役","共歼灭和改编国民党军队 150 多万人，国民党军队主力基本被消灭 · 重点"],["1949 年 4 月","渡江战役，4 月 23 日南京解放","标志国民党在大陆的统治结束 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1947 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"中国共产党颁布《中国土地法大纲》","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1948 年 9 月—1…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"辽沈、淮海、平津三大战役","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1949 年 4 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"渡江战役，4 月 23 日南京解放","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"三大战役：辽沈战役（解放东北全境）、淮海战役（以徐州为中心，奠定解放长江以南各省的基础）、平津战役（北平和平解放，傅作义接受和平改编）。三大战役共歼灭和改编国民党军队 150 多万人，国民党军队主力基本被消灭。","explain":"按「名称—指挥者—地点—结果」四栏记忆，材料题常要求「任选一个战役说明其作用」。"},{"level":"重点","text":"渡江战役与南京解放：1949 年 4 月人民解放军发起渡江战役，4 月 23 日南京解放，标志国民党在大陆统治的结束；此后人民解放军继续向全国进军。","explain":"注意区分「南京解放」（1949 年 4 月 23 日，国民党在大陆统治结束）与「中华人民共和国成立」（1949 年 10 月 1 日）。"},{"level":"重点","text":"解放战争胜利的原因：中国共产党的正确领导与正确的战略战术（集中优势兵力、运动战、歼灭战）；人民群众的广泛支持（土改调动农民积极性，「人民群众用小车推出来的胜利」）；人民解放军英勇作战；国民党政治孤立、经济崩溃、失去民心。","explain":"「得民心者得天下」是本单元的核心结论：土地改革使亿万农民成为解放战争的坚强后盾。"},{"level":"次重点","text":"解放区土地改革：1947 年颁布《中国土地法大纲》，废除封建性及半封建性剥削的土地制度，实行耕者有其田，为解放战争提供了可靠的群众基础和物质保障。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["**得民心者得天下，失民心者失天下**：中国共产党通过土地改革满足了农民的土地要求，赢得人民群众的衷心拥护，这是解放战争迅速胜利的根本原因。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把刘邓大军挺进大别山与三大战役的性质混同。","挺进大别山是战略进攻的开始（1947 年夏）；三大战役是战略决战（1948 年 9 月—1949 年 1 月）。","「战略进攻」与「战略决战」是两个阶段，材料题常要求排序并说明阶段特征。"],["认为南京解放标志着新中国的成立。","1949 年 4 月 23 日南京解放，标志国民党在大陆统治的结束；中华人民共和国成立于 1949 年 10 月 1 日。","两个时间相差不到半年，但性质完全不同，时序类题目常设此陷阱。"]]},{"type":"table","title":"三大战役（人民解放军战略决战的三大战役）","head":["比较项","辽沈战役、淮海战役","平津战役"],"rows":[["时间","辽沈 1948 年 9 月—11 月；淮海 1948 年 11 月—1949 年 1 月","1948 年 11 月—1949 年 1 月"],["主要指挥者","林彪、罗荣桓（辽沈）；刘伯承、陈毅、邓小平、粟裕、谭震林（淮海）","东北野战军与华北军区部队共同进行"],["特点与结果","辽沈战役解放东北全境；淮海战役以徐州为中心，奠定解放长江以南各省的基础","北平和平解放，傅作义接受和平改编，华北全境基本解放"],["共同作用","三大战役共歼灭和改编国民党军队 150 多万人，国民党军队主力基本被消灭","同左"]]},{"type":"table","title":"国共两党在解放战争中的两种命运（两种道路、两种命运的历史抉择）","head":["比较项","中国共产党","国民党"],"rows":[["政治主张","和平、民主、团结，建立新民主主义国家","坚持独裁统治，发动内战"],["与人民的关系","进行土地改革，实行耕者有其田，赢得农民支持","维护封建土地制度，横征暴敛，失去民心"],["军队与士气","人民解放军英勇作战，纪律严明，士气高昂","军队腐化，士气低落，大量起义与投诚"],["经济状况","解放区生产发展，人民踊跃支援前线","国统区通货膨胀、经济崩溃"],["历史结果","由防御转入进攻、决战，最终取得胜利","主力被消灭，1949 年 4 月南京解放，统治覆亡"],["结论","得民心者得天下，中国共产党代表最广大人民的根本利益，因此必然胜利","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["「人民的支持」类论证题","给出台词「淮海战役的胜利是人民群众用小车推出来的」等材料，要求用史实说明人民群众在解放战争中的作用，落脚在「得民心者得天下」。"],["阶段划分与事件排序","要求按「战略防御—战略进攻—战略决战—渡江战役」排列事件并说明每一阶段的标志性事件，考查时序与阶段特征。"],["谈判类史料的意图分析","以重庆谈判为切口，考查国共双方的谈判目的与《双十协定》的落实情况，答题要写出「蒋介石假和平真内战」与中共「争取和平」的双重立场。"]]},{"type":"note","title":"跨学科视角","text":"地理：三大战役的地域；道德与法治：人民至上与制度选择。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["三大战役：辽沈战役（1948 年 9—11 月）、淮海战役（1948 年 11 月—1949 年 1 月）、平津战役（1948 年 11 月—1949 年 1 月），共歼灭和改编国民党军 154 万余人。 出处：《中国共产党简史》","渡江战役：1949 年 4 月 20 日，人民解放军发起渡江战役，4 月 23 日解放南京，宣告国民党在大陆统治的覆灭。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《毛泽东选集》第四卷","2024 部编版八上第 21 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】关于和平建国的基本方针，一致认为：中国抗日战争业已结束，和平建国的新阶段即将开始，必须共同努力，以和平、民主、团结、统一为基础……——《政府与中共代表会谈纪要》（1945 年 10 月 10 日）\n【材料二】废除封建性及半封建性剥削的土地制度，实行耕者有其田的土地制度。——《中国土地法大纲》（1947 年）\n【材料三】淮海战役的胜利是人民群众用小车推出来的。——陈毅\n【材料四】1949 年 4 月 23 日，人民解放军占领南京，统治中国 22 年的国民党政权覆亡。","source":"材料研读 · 人民解放战争"}],"questions":[{"id":"h8a-u7-q3","type":"choice","stem":"揭开了人民解放军战略进攻序幕的事件是","answer":"B","explain":"1947 年夏，刘伯承、邓小平率晋冀鲁豫解放军主力挺进大别山，直接威胁国民党统治中心南京、武汉，揭开了人民解放军战略进攻的序幕。","options":["转战陕北","刘伯承、邓小平率部挺进大别山","辽沈战役开始","渡江战役开始"],"tags":["战略进攻","时空观念"]},{"id":"h8a-u7-q4","type":"choice","stem":"奠定了解放长江以南各省基础的战役是","answer":"B","explain":"淮海战役以徐州为中心，共歼灭国民党军队 55 万余人，奠定了解放长江以南各省的基础。辽沈战役解放东北全境，平津战役使华北全境基本解放。","options":["辽沈战役","淮海战役","平津战役","渡江战役"],"tags":["淮海战役","时空观念"]},{"id":"h8a-u7-q5","type":"choice","stem":"标志国民党在大陆统治结束的事件是","answer":"B","explain":"1949 年 4 月，人民解放军发起渡江战役，4 月 23 日占领南京，标志国民党在大陆统治的结束。中华人民共和国成立于 1949 年 10 月 1 日。","options":["三大战役的胜利","1949 年 4 月 23 日南京解放","北平和平解放","中华人民共和国成立"],"tags":["渡江战役","时空观念"]},{"id":"cat-8a-7-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中国共产党颁布《中国土地法大纲》\n② 辽沈、淮海、平津三大战役\n③ 渡江战役，4 月 23 日南京解放","answer":"A","explain":"按时间顺序应为：①中国共产党颁布《中国土地法大纲》（1947 年）→②辽沈、淮海、平津三大战役（1948 年 9 月—1949 年 1 月）→③渡江战役，4 月 23 日南京解放（1949 年 4 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"cat-8a-7-2-g2","type":"choice","stem":"下列关于「人民解放战争的胜利」的表述，错误的是","answer":"A","explain":"把刘邓大军挺进大别山与三大战役的性质混同——「战略进攻」与「战略决战」是两个阶段，材料题常要求排序并说明阶段特征。正确表述：挺进大别山是战略进攻的开始（1947 年夏）；三大战役是战略决战（1948 年 9 月—1949 年 1 月）。","options":["把刘邓大军挺进大别山与三大战役的性质混同。","挺进大别山是战略进攻的开始（1947 年夏）；三大战役是战略决战（1948 年 9 月—1949 年 1 月）。","**得民心者得天下，失民心者失天下**：中国共产党通过土地改革满足了农民的土地要求，赢得人民群众的衷心拥护，这是解放战争迅速胜利的根本原因。","三大战役：辽沈战役（解放东北全境）、淮海战役（以徐州为中心，奠定解放长江以南各省的基础）、平津战役（北平和平解放，傅作义接受和平改编）。三大战役共歼灭和改编国民党军队 150 多万人，国民党军队主力基本被消灭。"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"cat-8a-7-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：辽沈战役（1948 年 9—11 月）、淮海战役（1948 年 11 月—1949 年 1 月）、平津战役（1948 年 11 月—1949 年 1 月），共歼灭和改编国民党军 154 万余人。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"人民解放战争的胜利；三大战役：辽沈战役（解放东北全境）、淮海战役（以徐州为中心，奠定解放长江以南各省的基础）、平津战役（北平和平解放，傅作义接受和平改编）。三大战役共歼灭和改编国民党军队 150 多万人，国民党军队主力基本被消灭。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第七单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8a-7-3","title":"第22课 活动课 探寻红色文化的历史基因","subtitle":"八年级上册 · 第七单元 人民解放战争","grade":"8a","tags":["八年级上册","第七单元","活动课"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第七单元 人民解放战争"},{"k":"课时","v":"第22课 活动课 探寻红色文化的历史基因"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"本课是活动课，通过革命遗址、纪念馆、红色故事等资源，探寻红色文化的历史基因，理解革命精神的内涵与当代价值。"},{"type":"note","title":"本课主线 · 因果链","text":"抗战胜利后，中国共产党为争取和平民主赴重庆谈判，但国民党于 1946 年发动全面内战；人民解放军以运动战粉碎敌人进攻，1947 年转入战略进攻，通过土地改革赢得亿万农民的支持，1948—1949 年三大战役基本消灭国民党军队主力，1949 年 4 月渡江战役解放南京，国民党在大陆的统治覆亡。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["1945 年 8—10 月","重庆谈判","毛泽东赴重庆谈判，10 月 10 日国共双方签署《政府与中共代表会谈纪要》（《双十协定》），确定和平建国的基本方针 · 重点"],["1946 年 6 月","国民党军队进攻中原解放区","全面内战爆发 · 重点"],["1947 年 3 月","国民党军队重点进攻陕北和山东解放区","中共中央主动撤出延安，转战陕北，彭德怀率西北野战军接连取得胜利"],["1947 年夏","刘伯承、邓小平率部挺进大别山","揭开人民解放军战略进攻的序幕 · 重点"],["1947 年","中国共产党颁布《中国土地法大纲》","解放区实行土地改革，实行耕者有其田，为解放战争胜利提供了人力物力保障"],["1948 年 9 月—1949 年 1 月","辽沈、淮海、平津三大战役","共歼灭和改编国民党军队 150 多万人，国民党军队主力基本被消灭 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1945 年 8—10 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"重庆谈判","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"1946 年 6 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"国民党军队进攻中原解放区","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1947 年 3 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"国民党军队重点进攻陕北和山东解放区","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"1947 年夏","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"刘伯承、邓小平率部挺进大别山","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"1947 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"中国共产党颁布《中国土地法大纲》","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1948 年 9 月—1…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"辽沈、淮海、平津三大战役","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题（本课单独考点较少，以下取本单元整体内容）","items":[{"level":"重点","text":"重庆谈判：蒋介石一面积极准备内战、一面三次电邀毛泽东赴重庆，企图赢得备战时间并把内战责任推给共产党；毛泽东赴重庆谈判是为了尽一切可能争取和平、揭穿蒋介石假和平真内战的阴谋、教育人民。","explain":"成果是 1945 年 10 月 10 日签署《双十协定》，但蒋介石并未履行，1946 年 6 月全面内战爆发。"},{"level":"重点","text":"三大战役：辽沈战役（解放东北全境）、淮海战役（以徐州为中心，奠定解放长江以南各省的基础）、平津战役（北平和平解放，傅作义接受和平改编）。三大战役共歼灭和改编国民党军队 150 多万人，国民党军队主力基本被消灭。","explain":"按「名称—指挥者—地点—结果」四栏记忆，材料题常要求「任选一个战役说明其作用」。"},{"level":"重点","text":"渡江战役与南京解放：1949 年 4 月人民解放军发起渡江战役，4 月 23 日南京解放，标志国民党在大陆统治的结束；此后人民解放军继续向全国进军。","explain":"注意区分「南京解放」（1949 年 4 月 23 日，国民党在大陆统治结束）与「中华人民共和国成立」（1949 年 10 月 1 日）。"},{"level":"重点","text":"解放战争胜利的原因：中国共产党的正确领导与正确的战略战术（集中优势兵力、运动战、歼灭战）；人民群众的广泛支持（土改调动农民积极性，「人民群众用小车推出来的胜利」）；人民解放军英勇作战；国民党政治孤立、经济崩溃、失去民心。","explain":"「得民心者得天下」是本单元的核心结论：土地改革使亿万农民成为解放战争的坚强后盾。"},{"level":"次重点","text":"转战陕北与战略进攻：面对国民党的重点进攻，中共中央主动撤出延安、转战陕北；1947 年夏刘邓大军挺进大别山，揭开人民解放军战略进攻的序幕。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["**中国共产党是中国人民革命事业的坚强领导核心**：正确的战略战术、坚强有力的领导与人民群众的支持，使人民解放军由弱变强、由防御转入进攻和决战。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把全面内战爆发的标志记为重庆谈判破裂或《双十协定》被撕毁。","1946 年 6 月国民党军队进攻中原解放区，标志着全面内战爆发。","《双十协定》后蒋介石仍加紧备战，标志性事件必须是军事进攻，属高频细节。"],["把刘邓大军挺进大别山与三大战役的性质混同。","挺进大别山是战略进攻的开始（1947 年夏）；三大战役是战略决战（1948 年 9 月—1949 年 1 月）。","「战略进攻」与「战略决战」是两个阶段，材料题常要求排序并说明阶段特征。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["「人民的支持」类论证题","给出台词「淮海战役的胜利是人民群众用小车推出来的」等材料，要求用史实说明人民群众在解放战争中的作用，落脚在「得民心者得天下」。"],["阶段划分与事件排序","要求按「战略防御—战略进攻—战略决战—渡江战役」排列事件并说明每一阶段的标志性事件，考查时序与阶段特征。"],["谈判类史料的意图分析","以重庆谈判为切口，考查国共双方的谈判目的与《双十协定》的落实情况，答题要写出「蒋介石假和平真内战」与中共「争取和平」的双重立场。"]]},{"type":"note","title":"跨学科视角","text":"地理：三大战役的地域；道德与法治：人民至上与制度选择。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["怎么做红色文化调查：确定主题—查找资料—实地走访—记录口述—整理成果，注意区分史料与传说，注明来源。 出处：2024 部编版八上第 22 课「活动课」方法提示"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版八上第 22 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8a-u7-q1","type":"choice","stem":"1945 年毛泽东赴重庆谈判的主要目的是","answer":"A","explain":"毛泽东赴重庆谈判是为了尽一切可能争取和平、避免内战，同时揭穿蒋介石假和平真内战的阴谋，教育人民、争取政治上的主动。","options":["争取和平民主，揭穿蒋介石假和平真内战的阴谋","与国民党共同建立联合政府","争取美国对中共的支持","拖延时间准备内战"],"tags":["重庆谈判","历史解释"]},{"id":"h8a-u7-q2","type":"choice","stem":"全面内战爆发的标志是","answer":"B","explain":"1946 年 6 月，国民党军队 20 多万人进攻中原解放区，标志着全面内战爆发。进攻延安与挺进大别山都发生在 1947 年。","options":["《双十协定》被撕毁","1946 年 6 月国民党军队进攻中原解放区","国民党军队进攻延安","刘邓大军挺进大别山"],"tags":["全面内战","时空观念"]},{"id":"h8a-u7-q3","type":"choice","stem":"揭开了人民解放军战略进攻序幕的事件是","answer":"B","explain":"1947 年夏，刘伯承、邓小平率晋冀鲁豫解放军主力挺进大别山，直接威胁国民党统治中心南京、武汉，揭开了人民解放军战略进攻的序幕。","options":["转战陕北","刘伯承、邓小平率部挺进大别山","辽沈战役开始","渡江战役开始"],"tags":["战略进攻","时空观念"]},{"id":"cat-8a-7-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 重庆谈判\n② 国民党军队进攻中原解放区\n③ 国民党军队重点进攻陕北和山东解放区\n④ 刘伯承、邓小平率部挺进大别山","answer":"A","explain":"按时间顺序应为：①重庆谈判（1945 年 8—10 月）→②国民党军队进攻中原解放区（1946 年 6 月）→③国民党军队重点进攻陕北和山东解放区（1947 年 3 月）→④刘伯承、邓小平率部挺进大别山（1947 年夏）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"cat-8a-7-3-g2","type":"choice","stem":"下列关于「活动课 探寻红色文化的历史基因」的表述，错误的是","answer":"A","explain":"把全面内战爆发的标志记为重庆谈判破裂或《双十协定》被撕毁——《双十协定》后蒋介石仍加紧备战，标志性事件必须是军事进攻，属高频细节。正确表述：1946 年 6 月国民党军队进攻中原解放区，标志着全面内战爆发。","options":["把全面内战爆发的标志记为重庆谈判破裂或《双十协定》被撕毁。","1946 年 6 月国民党军队进攻中原解放区，标志着全面内战爆发。","**中国共产党是中国人民革命事业的坚强领导核心**：正确的战略战术、坚强有力的领导与人民群众的支持，使人民解放军由弱变强、由防御转入进攻和决战。","重庆谈判：蒋介石一面积极准备内战、一面三次电邀毛泽东赴重庆，企图赢得备战时间并把内战责任推给共产党；毛泽东赴重庆谈判是为了尽一切可能争取和平、揭穿蒋介石假和平真内战的阴谋、教育人民。"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"cat-8a-7-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：确定主题—查找资料—实地走访—记录口述—整理成果，注意区分史料与传说，注明来源。（2024 部编版八上第 22 课「活动课」方法提示）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"活动课 探寻红色文化的历史基因；重庆谈判：蒋介石一面积极准备内战、一面三次电邀毛泽东赴重庆，企图赢得备战时间并把内战责任推给共产党；毛泽东赴重庆谈判是为了尽一切可能争取和平、揭穿蒋介石假和平真内战的阴谋、教育人民。","explain":"材料出自2024 部编版八上第 22 课「活动课」方法提示。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第七单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8b-1-1","title":"第1课 中华人民共和国成立","subtitle":"八年级下册 · 第一单元 中华人民共和国成立和社会主义制度建立","grade":"8b","tags":["八年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第一单元 中华人民共和国成立和社会主义制度建立"},{"k":"课时","v":"第1课 中华人民共和国成立"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1949 年 9 月，中国人民政治协商会议第一届全体会议在北平召开，通过《共同纲领》，确定国名、国旗、国歌、首都。10 月 1 日，开国大典在北京天安门广场举行，中华人民共和国中央人民政府成立。"},{"type":"note","title":"本课主线 · 因果链","text":"1949 年 10 月 1 日开国大典宣告中国人民从此站起来了；为巩固新生的人民政权，新中国完成西藏和平解放、赢得抗美援朝战争的胜利、完成土地改革，为国家由新民主主义向社会主义过渡准备了条件。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1949 年 9 月","中国人民政治协商会议第一届全体会议在北平召开","通过《中国人民政治协商会议共同纲领》，起临时宪法作用；决定国旗为五星红旗、以《义勇军进行曲》为代国歌、首都为北京、采用公元纪年"],["1949 年 10 月 1 日","开国大典，中华人民共和国中央人民政府成立","开辟了中国历史的新纪元，中国人民从此站起来了，成为国家的主人 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1949 年 9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"中国人民政治协商会议第一届全体会议在…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1949 年 10 月 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"开国大典，中华人民共和国中央人民政府…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"1949 年 10 月 1 日的开国大典，标志着中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利。","explain":"常见考法是「哪一事件标志中国人民从此站起来了」，答案是开国大典（新中国成立），不是政协会议召开。"},{"level":"次重点","text":"中国人民政治协商会议第一届全体会议通过的《共同纲领》，在 1954 年宪法颁布前起临时宪法的作用。","explain":"《共同纲领》是「起临时宪法作用的文件」，1954 年宪法才是我国第一部社会主义类型的宪法，两者不可混称。"},{"level":"选择题","text":"新中国成立的筹备：确定国名、国旗、代国歌、首都与公元纪年，决定在天安门广场建立人民英雄纪念碑；会议选举毛泽东为中央人民政府主席。","explain":"多为选择题的细节选项，记住「代国歌」三字——1982 年《义勇军进行曲》才被正式定为国歌。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利，中国人民从此站起来了，成为国家的主人，中国历史从此揭开了新的篇章。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。","土地改革彻底摧毁了在我国延续两千多年的封建土地制度，消灭了地主阶级，农民成为土地的主人，解放了农村生产力，为国家工业化建设准备了条件。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把《共同纲领》说成 1954 年宪法。","1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","「起临时宪法作用的文件」不等于「宪法」，这是两句不同的话。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["新中国成立的意义与家国情怀","常给开国大典照片、政协会议决定或群众欢庆的材料，要求概括新中国成立的历史意义，按「国内—国际」两层作答，并联系「中国人民从此站起来了」。"],["抗美援朝与英雄人物","以黄继光、邱少云或《朝鲜停战协定》材料设问，考「参战原因—战斗英雄—胜利意义」，答题落脚在「打破美军不可战胜的神话、提高国际地位、赢得和平环境」。"],["农村生产关系的三次调整","把土地改革、农业合作化、家庭联产承包责任制排成时间轴，要求指出每次调整后土地所有权的变化，是跨册大题的常见切口。"],["政权巩固的整体性","给西藏和平解放、抗美援朝、土地改革三组材料，要求说明它们共同的作用——巩固新生的人民政权，为经济建设创造条件。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：宪法、人民代表大会制度；语文：开国文献与新闻。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"曾联松","v":"五星红旗图案设计者。 出处：《中华人民共和国史》"},{"k":"聂耳","v":"《义勇军进行曲》作曲者。 出处：《中华人民共和国史》"}]},{"type":"list","title":"延伸阅读","items":["国旗与国歌：五星红旗由曾联松设计；《义勇军进行曲》由田汉作词、聂耳作曲，原为电影《风云儿女》主题歌，1949 年被定为代国歌。 出处：《中华人民共和国史》；2024 部编版八下第 1 课","《共同纲领》：全称《中国人民政治协商会议共同纲领》，起临时宪法作用，规定新中国是新民主主义国家。 出处：《共同纲领》原文"]},{"type":"list","title":"本课拓展出处","items":["《中华人民共和国史》；《共同纲领》原文","2024 部编版八下第 1 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8b-u1-q1","type":"choice","stem":"标志着中国人民从此站起来了、成为国家的主人的历史事件是","answer":"B","explain":"1949 年 10 月 1 日开国大典宣告中华人民共和国中央人民政府成立，中国人民从此站起来了，成为国家的主人。政协会议是成立前的筹备，西藏和平解放与抗美援朝是新中国成立后巩固政权的措施。","options":["中国人民政治协商会议第一届全体会议召开","开国大典，中华人民共和国成立","西藏和平解放","抗美援朝战争取得胜利"],"tags":["新中国成立","时空观念"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"cat-8b-1-1-g2","type":"choice","stem":"下列关于「中华人民共和国成立」的表述，错误的是","answer":"A","explain":"把《共同纲领》说成 1954 年宪法——「起临时宪法作用的文件」不等于「宪法」，这是两句不同的话。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","options":["把《共同纲领》说成 1954 年宪法。","1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利，中国人民从此站起来了，成为国家的主人，中国历史从此揭开了新的篇章。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：五星红旗由曾联松设计；《义勇军进行曲》由田汉作词、聂耳作曲，原为电影《风云儿女》主题歌，1949 年被定为代国歌。（《中华人民共和国史》；2024 部编版八下第 1 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中华人民共和国成立；1949 年 10 月 1 日的开国大典，标志着中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利。","explain":"材料出自《中华人民共和国史》；2024 部编版八下第 1 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-1-1-g5","type":"choice","stem":"「中国人民政治协商会议第一届全体会议在北平召开」发生于","answer":"A","explain":"本课时间轴：中国人民政治协商会议第一届全体会议在北平召开（1949 年 9 月）。通过《中国人民政治协商会议共同纲领》，起临时宪法作用；决定国旗为五星红旗、以《义勇军进行曲》为代国歌、首都为北京、采用公元纪年。其余三个时间是同一单元相邻课时的事件时间。","options":["1949 年 9 月","1950 年 6 月","1950 年 10 月","1951 年"],"difficulty":1,"tags":["八年级下册","第一单元","本课练习"]}]},{"id":"cat-8b-1-2","title":"第2课 巩固人民民主政权","subtitle":"八年级下册 · 第一单元 中华人民共和国成立和社会主义制度建立","grade":"8b","tags":["八年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第一单元 中华人民共和国成立和社会主义制度建立"},{"k":"课时","v":"第2课 巩固人民民主政权"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"新中国成立后，面临内忧外患。1950—1953 年进行抗美援朝战争，彭德怀任司令员，黄继光、邱少云等英勇牺牲。1950—1952 年在新解放区进行土地改革，废除封建土地制度。1951 年西藏和平解放，祖国大陆获得统一。"},{"type":"note","title":"本课主线 · 因果链","text":"1949 年 10 月 1 日开国大典宣告中国人民从此站起来了；为巩固新生的人民政权，新中国完成西藏和平解放、赢得抗美援朝战争的胜利、完成土地改革，为国家由新民主主义向社会主义过渡准备了条件。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1950 年 6 月","中央人民政府颁布《中华人民共和国土地改革法》，土地改革在全国展开","废除地主阶级封建剥削的土地所有制，实行农民的土地所有制 · 重点"],["1950 年 10 月","中国人民志愿军开赴朝鲜，抗美援朝战争开始","1953 年 7 月美国被迫签订《朝鲜停战协定》，抗美援朝战争胜利 · 重点"],["1951 年","西藏和平解放","祖国大陆获得统一，各族人民实现大团结 · 重点"],["1952 年底","全国大陆基本上完成土地改革","彻底摧毁了封建土地制度，农民成为土地的主人 · 重点"],["1953 年 7 月","美国被迫在《朝鲜停战协定》上签字，抗美援朝战争胜利","打破了美军不可战胜的神话，大大提高了我国的国际地位"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1950 年 6 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"中央人民政府颁布《中华人民共和国土地…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"1950 年 10 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"中国人民志愿军开赴朝鲜，抗美援朝战争…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1951 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"西藏和平解放","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"1952 年底","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"全国大陆基本上完成土地改革","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1953 年 7 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"美国被迫在《朝鲜停战协定》上签字，抗…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"抗美援朝（1950 年 10 月—1953 年 7 月）：中国人民志愿军赴朝作战，黄继光、邱少云等英雄献出生命；抗美援朝战争的胜利打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。","explain":"中国人民志愿军被誉为「最可爱的人」。答「意义」时必须写出「打破神话、提高国际地位、赢得和平环境」三层，只写「保卫了朝鲜」会丢分。"},{"level":"重点","text":"土地改革（1950—1952 年底）：废除地主阶级封建剥削的土地所有制，实行农民的土地所有制；消灭了地主阶级，农民成为土地的主人，人民政权更加巩固，解放了农村生产力，为国家工业化建设准备了条件。","explain":"这一条最爱与 1978 年家庭联产承包责任制联排比较，要能说清「土地改革后土地归农民私有」「农业合作化后土地归集体所有」「家庭联产承包责任制是公有制基础上改变经营方式」三种情形的差别。"},{"level":"次重点","text":"西藏和平解放（1951 年）的意义：祖国大陆获得统一，各族人民实现了大团结。","explain":"注意是「祖国大陆获得统一」；1965 年西藏自治区成立，是民族区域自治制度在西藏的实施。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。","土地改革彻底摧毁了在我国延续两千多年的封建土地制度，消灭了地主阶级，农民成为土地的主人，解放了农村生产力，为国家工业化建设准备了条件。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把抗美援朝战争开始的时间记成 1953 年。","1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","1950 年是「出兵」，1953 年是「停战」，两个时间点最容易被调换。"],["认为土地改革后土地归国家（或集体）所有。","《中华人民共和国土地改革法》规定废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，土地归农民私有。","土地变为集体所有是 1953—1956 年农业合作化的结果，不能提前。"],["认为 1951 年西藏和平解放标志祖国获得完全统一。","西藏和平解放标志着祖国大陆获得统一，各族人民实现了大团结；台湾问题尚未解决。","「祖国大陆统一」与「全国统一」表述不同，材料题常在此设分。"]]},{"type":"table","title":"1950—1952 年土地改革与 1953—1956 年农业合作化（跨时期对比：新中国成立后农村生产关系的两次调整）","head":["比较项","土地改革（1950—1952）","农业合作化（1953—1956）"],"rows":[["直接目的","废除封建土地制度，让农民获得土地","把个体小农经济改造为社会主义集体经济"],["土地所有权","归农民私有（农民土地所有制）","归集体所有（社会主义公有制）"],["性质","反封建的民主改革","社会主义改造"],["共同作用","都解放和发展了农村生产力，都巩固了人民政权","同左"]]},{"type":"table","title":"中国的土地改革与苏联的农业集体化（中外对比：社会主义国家改造农村的不同路径）","head":["比较项","中国","苏联"],"rows":[["时间","土地改革 1950—1952 年，农业合作化 1953—1956 年（分两步走）","1929 年开始，1937 年基本完成"],["方式","颁布法令、自愿互利、典型示范、国家帮助，逐步过渡","以行政手段强制推行，要求农民迅速加入集体农庄"],["结果","农民成为土地的主人，1956 年底社会主义基本制度建立","为工业化提供粮食和资金，但长期存在农业与农民积极性问题"],["共同点","都把个体农业引向集体化，都为国家工业化创造条件","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["新中国成立的意义与家国情怀","常给开国大典照片、政协会议决定或群众欢庆的材料，要求概括新中国成立的历史意义，按「国内—国际」两层作答，并联系「中国人民从此站起来了」。"],["抗美援朝与英雄人物","以黄继光、邱少云或《朝鲜停战协定》材料设问，考「参战原因—战斗英雄—胜利意义」，答题落脚在「打破美军不可战胜的神话、提高国际地位、赢得和平环境」。"],["农村生产关系的三次调整","把土地改革、农业合作化、家庭联产承包责任制排成时间轴，要求指出每次调整后土地所有权的变化，是跨册大题的常见切口。"],["政权巩固的整体性","给西藏和平解放、抗美援朝、土地改革三组材料，要求说明它们共同的作用——巩固新生的人民政权，为经济建设创造条件。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：宪法、人民代表大会制度；语文：开国文献与新闻。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["最可爱的人","魏巍战地通讯《谁是最可爱的人》中对抗美援朝志愿军的称呼。","魏巍《谁是最可爱的人》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"彭德怀","v":"中国人民志愿军司令员兼政治委员。 出处：《抗美援朝战争史》"},{"k":"黄继光","v":"志愿军特级战斗英雄，上甘岭战役中用身体堵枪眼。 出处：《抗美援朝战争史》"},{"k":"邱少云","v":"志愿军一级战斗英雄，潜伏中被燃烧弹烧身仍一动不动。 出处：《抗美援朝战争史》"}]},{"type":"list","title":"延伸阅读","items":["上甘岭战役：1952 年 10—11 月，志愿军在朝鲜上甘岭地区坚守阵地 43 天，打退敌军数百次进攻，涌现出黄继光等英雄。 出处：《抗美援朝战争史》","土地改革：1950 年颁布《中华人民共和国土地改革法》，到 1952 年底，除部分少数民族地区外，全国基本完成土地改革，三亿多农民分到土地。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《抗美援朝战争史》","2024 部编版八下第 2 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】毛泽东在中国人民政治协商会议第一届全体会议上的开幕词中说：「占人类总数四分之一的中国人从此站立起来了。」\n【材料二】《中华人民共和国土地改革法》规定：「废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，借以解放农村生产力，发展农业生产，为新中国的工业化开辟道路。」\n【材料三】到 1952 年底，除部分少数民族地区外，全国大陆基本上完成了土地改革，三亿多无地少地的农民分到了土地、农具、牲畜和房屋等，还免除了每年向地主缴纳的大量地租。","source":"材料研读 · 中华人民共和国的成立和巩固"}],"questions":[{"id":"h8b-u1-m1-q2","type":"short","stem":"（2）据材料二，土地改革废除的是什么制度、实行的是什么制度？据材料三并结合所学，说明土地改革的作用。（6 分）","answer":"废除地主阶级封建剥削的土地所有制，实行农民的土地所有制。作用：彻底摧毁了我国延续两千多年的封建土地制度，消灭了地主阶级；农民翻了身，成为土地的主人，人民政权更加巩固；大大解放了农村生产力，农业生产迅速恢复和发展，为国家工业化建设准备了条件。","explain":"","tags":["土地改革","历史解释"],"rubric":["答出「废除地主阶级封建剥削的土地所有制」","答出「实行农民的土地所有制」","答出「摧毁封建土地制度、消灭地主阶级」","答出「农民成为土地的主人／巩固人民政权」","答出「解放农村生产力／为国家工业化准备条件」"]},{"id":"h8b-u1-q1","type":"choice","stem":"标志着中国人民从此站起来了、成为国家的主人的历史事件是","answer":"B","explain":"1949 年 10 月 1 日开国大典宣告中华人民共和国中央人民政府成立，中国人民从此站起来了，成为国家的主人。政协会议是成立前的筹备，西藏和平解放与抗美援朝是新中国成立后巩固政权的措施。","options":["中国人民政治协商会议第一届全体会议召开","开国大典，中华人民共和国成立","西藏和平解放","抗美援朝战争取得胜利"],"tags":["新中国成立","时空观念"]},{"id":"h8b-u1-q2","type":"choice","stem":"1951 年西藏和平解放的重要意义是","answer":"A","explain":"西藏和平解放使祖国大陆获得统一，各族人民实现了大团结。民族区域自治制度在 1954 年宪法中确立为一项基本政治制度；西藏自治区成立于 1965 年；台湾问题尚未解决，不能说「祖国获得完全统一」。","options":["祖国大陆获得统一，各族人民实现大团结","标志着祖国获得完全统一","标志着民族区域自治制度正式确立","西藏自治区正式成立"],"tags":["西藏和平解放","时空观念"]},{"id":"h8b-u1-q4","type":"choice","stem":"1950—1952 年底土地改革完成后，我国农村土地的所有权状况是","answer":"D","explain":"土地改革废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，土地归农民私有。土地归集体所有是 1953—1956 年农业合作化的结果。","options":["归国家所有","归集体所有","归地主与农民共同所有","归农民所有"],"tags":["土地改革","历史解释"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"h8b-u1-q6","type":"choice","stem":"抗美援朝战争的胜利对中国最主要的影响是","answer":"D","explain":"抗美援朝战争的胜利打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。中国进入社会主义社会以 1956 年三大改造基本完成为标志，结束半殖民地半封建社会历史以新中国成立为标志。","options":["使中国完成了国家统一","使中国从此进入社会主义社会","结束了半殖民地半封建社会的历史","打破了美军不可战胜的神话，大大提高了我国的国际地位"],"tags":["抗美援朝","历史解释"]},{"id":"cat-8b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中央人民政府颁布《中华人民共和国土地改革法》，土…\n② 中国人民志愿军开赴朝鲜，抗美援朝战争开始\n③ 西藏和平解放\n④ 全国大陆基本上完成土地改革","answer":"A","explain":"按时间顺序应为：①中央人民政府颁布《中华人民共和国土地改革法》，土地改革在全国展开（1950 年 6 月）→②中国人民志愿军开赴朝鲜，抗美援朝战争开始（1950 年 10 月）→③西藏和平解放（1951 年）→④全国大陆基本上完成土地改革（1952 年底）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g2","type":"choice","stem":"下列关于「巩固人民民主政权」的表述，错误的是","answer":"A","explain":"把抗美援朝战争开始的时间记成 1953 年——1950 年是「出兵」，1953 年是「停战」，两个时间点最容易被调换。正确表述：1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","options":["把抗美援朝战争开始的时间记成 1953 年。","1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。","土地改革彻底摧毁了在我国延续两千多年的封建土地制度，消灭了地主阶级，农民成为土地的主人，解放了农村生产力，为国家工业化建设准备了条件。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1952 年 10—11 月，志愿军在朝鲜上甘岭地区坚守阵地 43 天，打退敌军数百次进攻，涌现出黄继光等英雄。（《抗美援朝战争史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"巩固人民民主政权；抗美援朝（1950 年 10 月—1953 年 7 月）：中国人民志愿军赴朝作战，黄继光、邱少云等英雄献出生命；抗美援朝战争的胜利打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。","explain":"材料出自《抗美援朝战争史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8b-1-3","title":"第3课 社会主义制度建立","subtitle":"八年级下册 · 第一单元 中华人民共和国成立和社会主义制度建立","grade":"8b","tags":["八年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第一单元 中华人民共和国成立和社会主义制度建立"},{"k":"课时","v":"第3课 社会主义制度建立"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1953 年起，中国实施第一个五年计划，集中力量发展重工业，1957 年超额完成。1954 年第一届全国人民代表大会召开，通过《中华人民共和国宪法》。1953—1956 年进行三大改造，实现对农业、手工业和资本主义工商业的社会主义改造。"},{"type":"note","title":"本课主线 · 因果链","text":"1953 年起实施的第一个五年计划奠定了我国社会主义工业化的初步基础，1954 年宪法确立了人民代表大会制度，1956 年底三大改造基本完成、社会主义基本制度在我国建立起来；此后党领导人民探索社会主义建设道路，既取得了巨大成就，也出现了「大跃进」、人民公社化运动和「文化大革命」等失误。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1954 年 9 月","第一届全国人民代表大会第一次会议在北京召开，通过《中华人民共和国宪法》","这是我国第一部社会主义类型的宪法，以国家根本法的形式确定了人民代表大会制度 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"1954 年宪法是我国第一部社会主义…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":27.17,"text":"三大改造（1953—1956 年底）…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":41.33,"text":"1956 年底三大改造基本完成，标志…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"1954 年宪法是我国第一部社会主义…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"1954 年宪法是我国第一部社会主义类型的宪法，也是我国有史以来真正反映人民利益的宪法；宪法规定中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主国家，以国家根本法的形式确定了人民代表大会制度。","explain":"人民代表大会制度是我国的根本政治制度。答题时「第一部社会主义类型的宪法」这几个字必须写全。"},{"level":"重点","text":"三大改造（1953—1956 年底）：农业和手工业通过建立生产合作社，走集体化道路；对资本主义工商业采取公私合营的方式，实行赎买政策。1956 年底基本完成，实现了生产资料私有制向社会主义公有制的转变，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段。","explain":"「赎买政策」是中国社会主义改造的创举。这一条是「只有社会主义才能救中国」的制度依据。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["1956 年底三大改造基本完成，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段；社会主义制度的建立是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础。","1954 年宪法是我国第一部社会主义类型的宪法，以国家根本法的形式确定了人民代表大会制度；人民代表大会制度是我国的根本政治制度。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把《共同纲领》与 1954 年宪法混为一谈。","1949 年《共同纲领》起临时宪法作用；1954 年宪法是我国第一部社会主义类型的宪法，以根本法形式确定了人民代表大会制度。","两者都是「宪法类」文件，但性质与地位不同，选择题常并列作选项。"],["认为三大改造完成后土地仍归农民个人所有。","农业合作化把农民个体所有变为集体所有，实现了生产资料私有制向社会主义公有制的转变。","与 1950—1952 年土地改革「实行农民的土地所有制」相区别，是农村生产关系变化的必考点。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["一五计划与工业化的起步","常以长春第一汽车制造厂、武汉长江大桥等成就的材料或数据设问，考「一五计划的特点（集中主要力量发展重工业）」与「意义（开始改变工业落后面貌，向社会主义工业化迈进）」。"],["制度确立：宪法与三大改造","1954 年宪法、人民代表大会制度、三大改造完成三则材料并置，落脚在「社会主义基本制度在我国建立起来」。"],["探索中的失误与教训","以大跃进、人民公社化运动或「文化大革命」材料设问，考「原因—后果—教训」，答题必须用语规范，先肯定良好愿望再指出违背客观经济规律。"],["英雄模范与时代精神","王进喜、焦裕禄、雷锋、邓稼先的人物卡片题，考「人物—事迹—精神」，常与家国情怀的论述题结合。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：社会主义建设道路；科学：两弹一星与国防科技。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"毛泽东","v":"领导一五计划和三大改造。 出处：《毛泽东选集》第五卷"}]},{"type":"list","title":"延伸阅读","items":["一五计划成就：长春第一汽车制造厂、沈阳第一机床厂、鞍山钢铁公司扩建、武汉长江大桥（1957 年建成）、青藏公路等建成通车。 出处：《中国共产党简史》","三大改造：对农业、手工业采取合作化道路，对资本主义工商业实行公私合营和赎买政策，1956 年底基本完成，社会主义制度在中国基本建立。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；1954 年《中华人民共和国宪法》","2024 部编版八下第 3 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】1954 年《中华人民共和国宪法》规定：「中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主国家。」「中华人民共和国的一切权力属于人民。人民行使权力的机关是全国人民代表大会和地方各级人民代表大会。」\n【材料二】到 1956 年底，全国参加农业生产合作社的农户占总农户的 96.3%，参加手工业合作社的手工业者占 90% 以上，私营工商业基本实现了全行业公私合营。\n【材料三】中共八大指出，我们国内的主要矛盾「已经是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，已经是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾」。","source":"材料研读 · 社会主义制度的建立与社会主义建设的探索"}],"questions":[{"id":"h8b-u2-m1-q1","type":"short","stem":"（1）据材料一，说明 1954 年宪法的性质和它确定的我国根本政治制度。（5 分）","answer":"1954 年宪法是我国第一部社会主义类型的宪法，也是我国有史以来真正反映人民利益的宪法。它以国家根本法的形式确定了人民代表大会制度；人民代表大会制度是我国的根本政治制度，人民行使权力的机关是全国人民代表大会和地方各级人民代表大会。","explain":"","tags":["1954 年宪法","制度创新"],"rubric":["答出「第一部社会主义类型的宪法」","答出「真正反映人民利益的宪法」","答出「以根本法形式确定人民代表大会制度」","答出「人民代表大会制度是我国的根本政治制度」"]},{"id":"h8b-u2-q2","type":"choice","stem":"1954 年《中华人民共和国宪法》的历史地位是","answer":"D","explain":"1954 年宪法是我国第一部社会主义类型的宪法，也是我国有史以来真正反映人民利益的宪法；起临时宪法作用的文件是 1949 年的《共同纲领》。","options":["我国第一部宪法性质的临时文件","我国第一部资产阶级民主主义宪法","我国第一部民族区域自治法","我国第一部社会主义类型的宪法"],"tags":["1954 年宪法","历史解释"]},{"id":"h8b-u2-q3","type":"choice","stem":"标志着社会主义基本制度在我国建立起来的事件是","answer":"A","explain":"1956 年底三大改造基本完成，实现了生产资料私有制向社会主义公有制的转变，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段。","options":["1956 年底三大改造基本完成","中华人民共和国成立","第一个五年计划超额完成","1954 年宪法的颁布"],"tags":["三大改造","历史解释"]},{"id":"h8b-u2-q4","type":"choice","stem":"被称为「探索建设社会主义道路的良好开端」的会议是","answer":"D","explain":"1956 年召开的中共八大正确分析了国内主要矛盾，提出集中力量发展社会生产力，是探索建设社会主义道路的良好开端。","options":["中共七大","第一届全国人民代表大会","中共十一届三中全会","中共八大"],"tags":["中共八大","历史解释"]},{"id":"cat-8b-1-3-g2","type":"choice","stem":"下列关于「社会主义制度建立」的表述，错误的是","answer":"A","explain":"把《共同纲领》与 1954 年宪法混为一谈——两者都是「宪法类」文件，但性质与地位不同，选择题常并列作选项。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年宪法是我国第一部社会主义类型的宪法，以根本法形式确定了人民代表大会制度。","options":["把《共同纲领》与 1954 年宪法混为一谈。","1949 年《共同纲领》起临时宪法作用；1954 年宪法是我国第一部社会主义类型的宪法，以根本法形式确定了人民代表大会制度。","1956 年底三大改造基本完成，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段；社会主义制度的建立是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础。","1954 年宪法是我国第一部社会主义类型的宪法，以国家根本法的形式确定了人民代表大会制度；人民代表大会制度是我国的根本政治制度。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：长春第一汽车制造厂、沈阳第一机床厂、鞍山钢铁公司扩建、武汉长江大桥（1957 年建成）、青藏公路等建成通车。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"社会主义制度建立；1954 年宪法是我国第一部社会主义类型的宪法，也是我国有史以来真正反映人民利益的宪法；宪法规定中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主国家，以国家根本法的形式确定了人民代表大会制度。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8b-1-4","title":"第4课 独立自主的和平外交","subtitle":"八年级下册 · 第一单元 中华人民共和国成立和社会主义制度建立","grade":"8b","tags":["八年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第一单元 中华人民共和国成立和社会主义制度建立"},{"k":"课时","v":"第4课 独立自主的和平外交"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"新中国成立后，奉行独立自主的和平外交政策。1953 年周恩来提出和平共处五项原则，1954 年参加日内瓦会议，1955 年出席万隆会议并提出「求同存异」方针，打开了新中国外交新局面。"},{"type":"note","title":"本课主线 · 因果链","text":"新中国成立后，人民海军、人民空军和导弹部队不断壮大，国防力量显著增强，为国家建设提供了安全保障；我国始终奉行独立自主的和平外交政策，从和平共处五项原则到新时代中国特色大国外交，走出了一条和平发展、合作共赢的道路，推动构建人类命运共同体。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1953 年 12 月","周恩来在接见印度代表团时首次提出和平共处五项原则","标志着新中国外交政策的成熟 · 重点"],["1954 年","中国第一次以世界五大国之一的身份参加日内瓦会议","周恩来访问印度、缅甸，中印、中缅一致同意以和平共处五项原则作为指导相互关系的基本原则"],["1955 年 4 月","万隆会议（第一次亚非会议）召开，周恩来提出「求同存异」的方针","这是第一次没有殖民主义国家参加的亚非国际会议 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1953 年 12 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"周恩来在接见印度代表团时首次提出和平…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1954 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"中国第一次以世界五大国之一的身份参加…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1955 年 4 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"万隆会议（第一次亚非会议）召开，周恩…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"和平共处五项原则：互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处。1953 年 12 月周恩来在接见印度代表团时首次提出，1954 年在中印、中缅联合声明中确立为指导相互关系的基本原则。","explain":"意义要写「标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生深远影响」。五项内容要能完整背出。"},{"level":"重点","text":"万隆会议（1955 年）：这是第一次没有殖民主义国家参加的亚非国际会议。周恩来针对一些国家代表的疑虑和攻击提出「求同存异」的方针，促进了会议的圆满成功，促进了中国同亚非各国的团结与合作。","explain":"「求同存异」中的「同」是反对殖民主义、维护民族独立、发展民族经济，「异」是社会制度和意识形态的差异。"},{"level":"重点","text":"新时代中国外交：奉行独立自主的和平外交政策，坚持走和平发展道路，推动构建人类命运共同体；提出共建「一带一路」倡议，积极参与全球治理，形成全方位、多层次、立体化的外交布局。","explain":"答题落脚在「中国是世界和平的建设者、全球发展的贡献者、国际秩序的维护者」，中国永不称霸、永不扩张。"},{"level":"次重点","text":"新中国成立初期的外交方针：奉行独立自主的和平外交政策，同苏联等社会主义国家建立外交关系，反对帝国主义的侵略政策和战争政策，以和平共处五项原则发展同邻近国家和新兴独立国家的关系。","explain":"1954 年日内瓦会议是中国第一次以世界五大国之一的身份参加的国际会议，注意与 1955 年万隆会议相区分。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["和平共处五项原则标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生了深远影响。","中国始终奉行独立自主的和平外交政策，坚持走和平发展道路，推动构建人类命运共同体；国家实力是国际地位的基础，「弱国无外交」。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为和平共处五项原则是 1954 年首次提出的。","1953 年 12 月周恩来在接见印度代表团时首次提出；1954 年周恩来访问印度、缅甸，双方一致同意以和平共处五项原则作为指导相互关系的基本原则。","「首次提出」与「共同倡导/确认」是两个时间点，最容易混。"],["把万隆会议与日内瓦会议混为一谈。","1954 年日内瓦会议是中国第一次以世界五大国之一的身份参加的国际会议；1955 年万隆会议是第一次没有殖民主义国家参加的亚非国际会议，周恩来在会上提出「求同存异」的方针。","两次会议的时间、性质、周恩来所起的作用各不相同。"]]},{"type":"table","title":"新中国成立初期与改革开放新时期的中国外交（跨时期对比：同一条和平外交政策的不同阶段）","head":["比较项","新中国成立初期","改革开放新时期（特别是十八大以来）"],"rows":[["国际环境","美苏冷战对峙，美国等敌视、封锁中国","世界多极化、经济全球化深入发展"],["方针理念","独立自主的和平外交政策，提出和平共处五项原则","坚持独立自主的和平外交政策，推动构建人类命运共同体，共建「一带一路」"],["主要成就","同苏联等国建交，参加日内瓦会议、万隆会议","恢复联合国合法席位、中美中日关系正常化，形成全方位外交布局，积极参与全球治理"],["共同点","都坚持独立自主，维护国家主权与世界和平，反对霸权主义","同左"]]},{"type":"table","title":"新中国外交与近代中国的屈辱外交（跨时期对比：国家地位决定外交地位）","head":["比较项","近代中国（1840—1949）","新中国（1949 年至今）"],"rows":[["国家状况","半殖民地半封建社会，国家贫弱","实现了民族独立和人民解放，人民当家作主"],["外交性质","屈辱外交，被迫签订不平等条约","独立自主的和平外交"],["结果","领土主权遭到破坏，国际地位低下","1971 年恢复在联合国的合法席位，国际地位不断提高"],["根本原因","综合国力（国家实力）是国际地位的基础","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["新中国外交政策的成熟","以和平共处五项原则、万隆会议的材料设问，考「内容—提出过程—意义」，标准答法是「标志着新中国外交政策的成熟，成为处理国与国之间关系的基本准则」。"],["20 世纪 70 年代的外交突破","把恢复联合国合法席位、中美《联合公报》、中日建交排成时间轴，要求说明三者之间的关联与共同原因，落脚在综合国力与国家利益。"],["国防现代化与国家安全","以人民海军空军、导弹部队的材料设问，考军事力量发展与国家安全、国际地位的关系，常与「两弹一星」合并考查。"],["人类命运共同体与全球治理","结合「一带一路」与全球治理的材料，考新时代中国外交的理念与贡献，答题要用「和平发展、合作共赢」等规范表述。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：独立自主的和平外交与国家安全；地理：联合国与全球治理格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["求同存异","周恩来在万隆会议上提出，主张各国在共同利益基础上超越意识形态分歧。","《周恩来选集》下卷"]]},{"type":"kv","title":"人物卡片","items":[{"k":"周恩来","v":"新中国外交事业的主要奠基人。 出处：《周恩来选集》"}]},{"type":"list","title":"延伸阅读","items":["和平共处五项原则：互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处，1953 年周恩来接见印度代表团时首次提出。 出处：《周恩来选集》下卷","万隆会议：1955 年 4 月在印度尼西亚万隆召开，29 个亚非国家参加。周恩来提出「求同存异」，促进会议圆满成功。 出处：《中华人民共和国外交史》"]},{"type":"list","title":"本课拓展出处","items":["《周恩来选集》；《中华人民共和国外交史》","2024 部编版八下第 4 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】1953 年 12 月，周恩来在接见印度代表团时说：「新中国成立后就确立了处理中印两国关系的原则，那就是互相尊重领土主权、互不侵犯、互不干涉内政、平等互惠和和平共处的原则。」\n【材料二】1971 年 10 月，第 26 届联合国大会通过决议：恢复中华人民共和国的一切权利，承认她的政府的代表为中国在联合国组织的唯一合法代表，并立即把台湾当局的代表从它在联合国组织及其所属一切机构中所非法占据的席位上驱逐出去。\n【材料三】1972 年中美《联合公报》中，美国方面声明：美国认识到，在台湾海峡两边的所有中国人都认为只有一个中国，台湾是中国的一部分。美国政府对这一立场不提出异议。","source":"材料研读 · 国防建设与外交成就"}],"questions":[{"id":"h8b-u5-m1-q1","type":"short","stem":"（1）据材料一，写出和平共处五项原则的基本内容，并说明它提出的意义。（6 分）","answer":"内容：互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处。意义：标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生了深远影响，也为我国发展同邻近国家和新兴独立国家的友好关系奠定了基础。","explain":"","tags":["和平共处五项原则","历史解释"],"rubric":["答出「互相尊重主权和领土完整、互不侵犯、互不干涉内政」","答出「平等互利、和平共处」","答出「标志新中国外交政策的成熟」","答出「成为处理国与国之间关系的基本准则」"]},{"id":"h8b-u5-q1","type":"choice","stem":"和平共处五项原则首次提出的时间和提出者是","answer":"A","explain":"1953 年 12 月周恩来在接见印度代表团时首次提出和平共处五项原则；1954 年周恩来访问印度、缅甸，双方一致同意以它作为指导相互关系的基本原则。","options":["1953 年 12 月，周恩来","1954 年，毛泽东","1955 年，周恩来","1971 年，周恩来"],"tags":["和平共处五项原则","时空观念"]},{"id":"h8b-u5-q2","type":"choice","stem":"在万隆会议上，周恩来提出的方针是","answer":"D","explain":"1955 年万隆会议是第一次没有殖民主义国家参加的亚非国际会议，周恩来提出「求同存异」的方针，促进了会议的圆满成功，促进了中国同亚非各国的团结与合作。","options":["独立自主","和平共处","一边倒","求同存异"],"tags":["万隆会议","历史解释"]},{"id":"h8b-u5-q5","type":"choice","stem":"1972 年中日两国正式建立外交关系，其直接推动因素是","answer":"B","explain":"1972 年中美关系开始走向正常化，直接推动了中日建交。中国恢复联合国合法席位（1971 年）有利于打开外交新局面，但不是中日建交的直接推动因素。","options":["中国恢复在联合国的合法席位","中美关系开始走向正常化","万隆会议的召开","和平共处五项原则的提出"],"tags":["中日建交","历史解释"]},{"id":"cat-8b-1-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 周恩来在接见印度代表团时首次提出和平共处五项原则\n② 中国第一次以世界五大国之一的身份参加日内瓦会议\n③ 万隆会议（第一次亚非会议）召开，周恩来提出「求同…","answer":"A","explain":"按时间顺序应为：①周恩来在接见印度代表团时首次提出和平共处五项原则（1953 年 12 月）→②中国第一次以世界五大国之一的身份参加日内瓦会议（1954 年）→③万隆会议（第一次亚非会议）召开，周恩来提出「求同存异」的方针（1955 年 4 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-4-g2","type":"choice","stem":"下列关于「独立自主的和平外交」的表述，错误的是","answer":"A","explain":"认为和平共处五项原则是 1954 年首次提出的——「首次提出」与「共同倡导/确认」是两个时间点，最容易混。正确表述：1953 年 12 月周恩来在接见印度代表团时首次提出；1954 年周恩来访问印度、缅甸，双方一致同意以和平共处五项原则作为指导相互关系的基本原则。","options":["认为和平共处五项原则是 1954 年首次提出的。","1953 年 12 月周恩来在接见印度代表团时首次提出；1954 年周恩来访问印度、缅甸，双方一致同意以和平共处五项原则作为指导相互关系的基本原则。","和平共处五项原则标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生了深远影响。","中国始终奉行独立自主的和平外交政策，坚持走和平发展道路，推动构建人类命运共同体；国家实力是国际地位的基础，「弱国无外交」。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处，1953 年周恩来接见印度代表团时首次提出。（《周恩来选集》下卷）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"独立自主的和平外交；和平共处五项原则：互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处。1953 年 12 月周恩来在接见印度代表团时首次提出，1954 年在中印、中缅联合声明中确立为指导相互关系的基本原则。","explain":"材料出自《周恩来选集》下卷。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8b-2-1","title":"第5课 艰辛探索与曲折发展","subtitle":"八年级下册 · 第二单元 社会主义建设道路的探索","grade":"8b","tags":["八年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第二单元 社会主义建设道路的探索"},{"k":"课时","v":"第5课 艰辛探索与曲折发展"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1956 年中共八大召开，正确分析国内主要矛盾，提出集中力量发展生产力。1958 年发动「大跃进」和人民公社化运动，违背经济规律，造成严重困难。1966—1976 年发生「文化大革命」，给党、国家和人民带来严重灾难。"},{"type":"note","title":"本课主线 · 因果链","text":"1953 年起实施的第一个五年计划奠定了我国社会主义工业化的初步基础，1954 年宪法确立了人民代表大会制度，1956 年底三大改造基本完成、社会主义基本制度在我国建立起来；此后党领导人民探索社会主义建设道路，既取得了巨大成就，也出现了「大跃进」、人民公社化运动和「文化大革命」等失误。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1958 年","「大跃进」和农村人民公社化运动在全国展开","急于求成，忽视客观经济规律，加上自然灾害等因素，造成国民经济严重困难 · 重点"],["1961—1965 年","实行「调整、巩固、充实、提高」的八字方针，调整国民经济","到 1965 年，国民经济调整任务基本完成"],["1966—1976 年","「文化大革命」","给党、国家和各族人民带来新中国成立后最严重的挫折，教训极其深刻"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1958 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"「大跃进」和农村人民公社化运动在全国…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1961—1965 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"实行「调整、巩固、充实、提高」的八字…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1966—1976 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"「文化大革命」","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"中共八大（1956 年）指出，国内的主要矛盾是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾；党和人民的主要任务是集中力量把我国尽快地从落后的农业国变为先进的工业国。","explain":"八大对主要矛盾的分析是正确的，是探索建设社会主义道路的良好开端；后来的失误正在于没有坚持这一正确分析。"},{"level":"重点","text":"「大跃进」和人民公社化运动是党在探索社会主义建设道路过程中的严重失误：反映了人民群众迫切要求改变经济文化落后状况的愿望，但急于求成，忽视了客观经济规律，加上自然灾害等因素，1959—1961 年我国国民经济发生严重困难。","explain":"教训：必须从国情出发、实事求是，按客观经济规律办事。答题时先肯定「愿望是好的」，再指出「忽视客观经济规律」，评价才完整。"},{"level":"重点","text":"「文化大革命」（1966—1976）给党、国家和各族人民带来新中国成立后最严重的挫折。教训：必须把经济建设作为一切工作的中心，必须加强社会主义民主法制建设，必须正确认识社会主要矛盾。","explain":"用语要规范：写「严重挫折」「深刻教训」，不夸大、不臆造。"},{"level":"选择题","text":"人民公社的特点是「一大二公」（规模大、公有化程度高），实行政社合一，严重挫伤了农民的生产积极性。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["1956 年底三大改造基本完成，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段；社会主义制度的建立是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础。","第一个五年计划的超额完成，使我国开始改变工业落后的面貌，向社会主义工业化迈进。","1954 年宪法是我国第一部社会主义类型的宪法，以国家根本法的形式确定了人民代表大会制度；人民代表大会制度是我国的根本政治制度。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为「大跃进」和人民公社化运动是成功的探索。","它们是党在探索社会主义建设道路过程中的严重失误，忽视了客观经济规律，人民公社化运动还严重挫伤了农民的生产积极性。","材料题要求「谈谈认识」，落脚点是「尊重客观经济规律、实事求是」，不能一味肯定。"],["认为中共八大对国内主要矛盾的分析是错误的。","八大的分析是正确的，是探索建设社会主义道路的良好开端；问题在于后来没有坚持这一正确分析。","常见的错项把「后来未坚持」写成「八大本身判断错误」。"]]},{"type":"table","title":"中共八大与中共十一届三中全会（跨时期对比：两次都正确分析主要矛盾的重要会议）","head":["比较项","中共八大（1956 年）","中共十一届三中全会（1978 年）"],"rows":[["主要贡献","正确分析国内主要矛盾，提出集中力量发展生产力","确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来，实行改革开放"],["历史地位","探索建设社会主义道路的良好开端","新中国成立以来党的历史上具有深远意义的伟大转折"],["结果不同","正确路线后来未能坚持，出现严重失误","开启了改革开放和社会主义现代化建设新时期"],["共同启示","必须从国情出发，坚持以经济建设为中心","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["一五计划与工业化的起步","常以长春第一汽车制造厂、武汉长江大桥等成就的材料或数据设问，考「一五计划的特点（集中主要力量发展重工业）」与「意义（开始改变工业落后面貌，向社会主义工业化迈进）」。"],["制度确立：宪法与三大改造","1954 年宪法、人民代表大会制度、三大改造完成三则材料并置，落脚在「社会主义基本制度在我国建立起来」。"],["探索中的失误与教训","以大跃进、人民公社化运动或「文化大革命」材料设问，考「原因—后果—教训」，答题必须用语规范，先肯定良好愿望再指出违背客观经济规律。"],["英雄模范与时代精神","王进喜、焦裕禄、雷锋、邓稼先的人物卡片题，考「人物—事迹—精神」，常与家国情怀的论述题结合。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：社会主义建设道路；科学：两弹一星与国防科技。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["八字方针：1961 年中共八届九中全会确定「调整、巩固、充实、提高」方针，国民经济逐步恢复。 出处：《中国共产党简史》","历史的教训：《关于建国以来党的若干历史问题的决议》指出，实践证明「文化大革命」不是也不可能是任何意义上的革命或社会进步。 出处：《关于建国以来党的若干历史问题的决议》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《关于建国以来党的若干历史问题的决议》","2024 部编版八下第 5 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】1954 年《中华人民共和国宪法》规定：「中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主国家。」「中华人民共和国的一切权力属于人民。人民行使权力的机关是全国人民代表大会和地方各级人民代表大会。」\n【材料二】到 1956 年底，全国参加农业生产合作社的农户占总农户的 96.3%，参加手工业合作社的手工业者占 90% 以上，私营工商业基本实现了全行业公私合营。\n【材料三】中共八大指出，我们国内的主要矛盾「已经是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，已经是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾」。","source":"材料研读 · 社会主义制度的建立与社会主义建设的探索"}],"questions":[{"id":"h8b-u2-m1-q2","type":"short","stem":"（2）材料二反映了什么历史现象？结合材料三，说明这一现象与中共八大召开的内在联系。（6 分）","answer":"材料二反映了 1956 年底我国基本完成了对农业、手工业和资本主义工商业的社会主义改造。联系：三大改造的完成，实现了生产资料私有制向社会主义公有制的转变，社会主义基本制度在我国建立起来，我国进入社会主义初级阶段；在这一基础上，中共八大正确分析了国内主要矛盾的变化，指出党和人民的主要任务是集中力量把我国尽快地从落后的农业国变为先进的工业国，成为探索建设社会主义道路的良好开端。","explain":"","tags":["三大改造","中共八大"],"rubric":["答出「三大改造基本完成」","答出「生产资料私有制向公有制转变／社会主义基本制度建立」","答出「我国进入社会主义初级阶段」","答出八大正确分析主要矛盾","答出八大的地位：良好开端"]},{"id":"h8b-u2-q4","type":"choice","stem":"被称为「探索建设社会主义道路的良好开端」的会议是","answer":"D","explain":"1956 年召开的中共八大正确分析了国内主要矛盾，提出集中力量发展社会生产力，是探索建设社会主义道路的良好开端。","options":["中共七大","第一届全国人民代表大会","中共十一届三中全会","中共八大"],"tags":["中共八大","历史解释"]},{"id":"h8b-u2-q5","type":"choice","stem":"「大跃进」和人民公社化运动给我们的最主要教训是","answer":"C","explain":"这两次失误反映了人民群众迫切改变落后面貌的愿望，但急于求成、忽视客观经济规律，造成 1959—1961 年国民经济严重困难。教训是必须从国情出发、实事求是、按客观经济规律办事。","options":["必须以阶级斗争为纲","必须优先发展重工业","必须从国情出发，按客观经济规律办事","必须加快生产资料公有化的速度"],"tags":["大跃进","唯物史观"]},{"id":"cat-8b-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 「大跃进」和农村人民公社化运动在全国展开\n② 实行「调整、巩固、充实、提高」的八字方针，调整国…\n③ 「文化大革命」","answer":"A","explain":"按时间顺序应为：①「大跃进」和农村人民公社化运动在全国展开（1958 年）→②实行「调整、巩固、充实、提高」的八字方针，调整国民经济（1961—1965 年）→③「文化大革命」（1966—1976 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-2-1-g2","type":"choice","stem":"下列关于「艰辛探索与曲折发展」的表述，错误的是","answer":"A","explain":"认为「大跃进」和人民公社化运动是成功的探索——材料题要求「谈谈认识」，落脚点是「尊重客观经济规律、实事求是」，不能一味肯定。正确表述：它们是党在探索社会主义建设道路过程中的严重失误，忽视了客观经济规律，人民公社化运动还严重挫伤了农民的生产积极性。","options":["认为「大跃进」和人民公社化运动是成功的探索。","它们是党在探索社会主义建设道路过程中的严重失误，忽视了客观经济规律，人民公社化运动还严重挫伤了农民的生产积极性。","1956 年底三大改造基本完成，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段；社会主义制度的建立是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础。","第一个五年计划的超额完成，使我国开始改变工业落后的面貌，向社会主义工业化迈进。"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1961 年中共八届九中全会确定「调整、巩固、充实、提高」方针，国民经济逐步恢复。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"艰辛探索与曲折发展；中共八大（1956 年）指出，国内的主要矛盾是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾；党和人民的主要任务是集中力量把我国尽快地从落后的农业国变为先进的工业国。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8b-2-2","title":"第6课 社会主义建设的巨大成就和先锋模范","subtitle":"八年级下册 · 第二单元 社会主义建设道路的探索","grade":"8b","tags":["八年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第二单元 社会主义建设道路的探索"},{"k":"课时","v":"第6课 社会主义建设的巨大成就和先锋模范"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"社会主义建设时期，各条战线涌现出大批英雄模范。王进喜带领钻井队在大庆艰苦创业；焦裕禄在兰考治理风沙盐碱；雷锋全心全意为人民服务；邓稼先、钱学森等投身「两弹一星」事业。1964 年第一颗原子弹爆炸成功，1967 年第一颗氢弹爆炸成功，1970 年「东方红一号」卫星发射成功。"},{"type":"note","title":"本课主线 · 因果链","text":"1953 年起实施的第一个五年计划奠定了我国社会主义工业化的初步基础，1954 年宪法确立了人民代表大会制度，1956 年底三大改造基本完成、社会主义基本制度在我国建立起来；此后党领导人民探索社会主义建设道路，既取得了巨大成就，也出现了「大跃进」、人民公社化运动和「文化大革命」等失误。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["1953 年","第一个五年计划开始执行","集中主要力量发展重工业，到 1957 年底超额完成 · 重点"],["1954 年 9 月","第一届全国人民代表大会第一次会议在北京召开，通过《中华人民共和国宪法》","这是我国第一部社会主义类型的宪法，以国家根本法的形式确定了人民代表大会制度 · 重点"],["1956 年底","对农业、手工业和资本主义工商业的社会主义改造基本完成","实现了生产资料私有制向社会主义公有制的转变，社会主义基本制度在我国建立起来 · 重点"],["1956 年","中国共产党第八次全国代表大会召开","正确分析国内主要矛盾，是探索建设社会主义道路的良好开端 · 重点"],["1957 年底","第一个五年计划超额完成","我国开始改变工业落后的面貌，向社会主义工业化迈进"],["1958 年","「大跃进」和农村人民公社化运动在全国展开","急于求成，忽视客观经济规律，加上自然灾害等因素，造成国民经济严重困难 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1953 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"第一个五年计划开始执行","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"1954 年 9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"第一届全国人民代表大会第一次会议在北…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1956 年底","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"对农业、手工业和资本主义工商业的社会…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"1956 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"中国共产党第八次全国代表大会召开","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"1957 年底","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"第一个五年计划超额完成","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1958 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"「大跃进」和农村人民公社化运动在全国…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"次重点","text":"社会主义建设时期的模范人物：王进喜（石油会战中的「铁人」）、焦裕禄（「党的好干部」）、雷锋（「解放军好战士」），以及邓稼先、钱学森等科学家，体现了自力更生、艰苦奋斗、全心全意为人民服务的精神。","explain":"常以「人物—事迹—精神」配对题出现，答精神要落到「艰苦奋斗、无私奉献、爱国主义」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["1956 年底三大改造基本完成，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段；社会主义制度的建立是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础。","第一个五年计划的超额完成，使我国开始改变工业落后的面貌，向社会主义工业化迈进。","1954 年宪法是我国第一部社会主义类型的宪法，以国家根本法的形式确定了人民代表大会制度；人民代表大会制度是我国的根本政治制度。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把《共同纲领》与 1954 年宪法混为一谈。","1949 年《共同纲领》起临时宪法作用；1954 年宪法是我国第一部社会主义类型的宪法，以根本法形式确定了人民代表大会制度。","两者都是「宪法类」文件，但性质与地位不同，选择题常并列作选项。"],["认为三大改造完成后土地仍归农民个人所有。","农业合作化把农民个体所有变为集体所有，实现了生产资料私有制向社会主义公有制的转变。","与 1950—1952 年土地改革「实行农民的土地所有制」相区别，是农村生产关系变化的必考点。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["一五计划与工业化的起步","常以长春第一汽车制造厂、武汉长江大桥等成就的材料或数据设问，考「一五计划的特点（集中主要力量发展重工业）」与「意义（开始改变工业落后面貌，向社会主义工业化迈进）」。"],["制度确立：宪法与三大改造","1954 年宪法、人民代表大会制度、三大改造完成三则材料并置，落脚在「社会主义基本制度在我国建立起来」。"],["探索中的失误与教训","以大跃进、人民公社化运动或「文化大革命」材料设问，考「原因—后果—教训」，答题必须用语规范，先肯定良好愿望再指出违背客观经济规律。"],["英雄模范与时代精神","王进喜、焦裕禄、雷锋、邓稼先的人物卡片题，考「人物—事迹—精神」，常与家国情怀的论述题结合。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：社会主义建设道路；科学：两弹一星与国防科技。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["铁人精神","以王进喜为代表的大庆石油工人艰苦创业、忘我拼搏的精神。","《中国共产党简史》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"王进喜","v":"大庆油田「铁人」，全国劳动模范。 出处：《中国共产党简史》"},{"k":"焦裕禄","v":"兰考县委书记，治理风沙盐碱，积劳成疾去世。 出处：《中国共产党简史》"},{"k":"雷锋","v":"解放军战士，全心全意为人民服务的楷模。 出处：《中国共产党简史》"},{"k":"邓稼先","v":"「两弹元勋」，中国核武器研制主要组织者。 出处：《中国共产党简史》"},{"k":"钱学森","v":"中国航天事业奠基人，参与「两弹一星」研制。 出处：《中国共产党简史》"}]},{"type":"list","title":"延伸阅读","items":["大庆油田：1959 年发现大庆油田，王进喜率 1205 钻井队参加会战，人拉肩扛运钻机、跳入泥浆池搅拌泥浆，被誉为「铁人」。 出处：《中国共产党简史》","两弹一星：「两弹一星」指原子弹、氢弹和人造地球卫星，是 20 世纪五六十年代中国在极端困难条件下取得的重大科技成就。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《两弹一星纪实》","2024 部编版八下第 6 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8b-u2-q6","type":"choice","stem":"在社会主义建设的火热年代，被誉为「党的好干部」、带领兰考人民治理内涝风沙盐碱的是","answer":"D","explain":"焦裕禄任河南兰考县委书记，带领群众治理内涝、风沙、盐碱，被誉为「党的好干部」。王进喜是大庆石油会战中的「铁人」，雷锋被誉为「解放军好战士」。","options":["王进喜","雷锋","邓稼先","焦裕禄"],"tags":["模范人物","家国情怀"]},{"id":"cat-8b-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 第一个五年计划开始执行\n② 第一届全国人民代表大会第一次会议在北京召开，通过…\n③ 对农业、手工业和资本主义工商业的社会主义改造基本…\n④ 中国共产党第八次全国代表大会召开","answer":"A","explain":"按时间顺序应为：①第一个五年计划开始执行（1953 年）→②第一届全国人民代表大会第一次会议在北京召开，通过《中华人民共和国宪法》（1954 年 9 月）→③对农业、手工业和资本主义工商业的社会主义改造基本完成（1956 年底）→④中国共产党第八次全国代表大会召开（1956 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-2-2-g2","type":"choice","stem":"下列关于「社会主义建设的巨大成就和先锋模范」的表述，错误的是","answer":"A","explain":"把《共同纲领》与 1954 年宪法混为一谈——两者都是「宪法类」文件，但性质与地位不同，选择题常并列作选项。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年宪法是我国第一部社会主义类型的宪法，以根本法形式确定了人民代表大会制度。","options":["把《共同纲领》与 1954 年宪法混为一谈。","1949 年《共同纲领》起临时宪法作用；1954 年宪法是我国第一部社会主义类型的宪法，以根本法形式确定了人民代表大会制度。","1956 年底三大改造基本完成，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段；社会主义制度的建立是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础。","第一个五年计划的超额完成，使我国开始改变工业落后的面貌，向社会主义工业化迈进。"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-2-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1959 年发现大庆油田，王进喜率 1205 钻井队参加会战，人拉肩扛运钻机、跳入泥浆池搅拌泥浆，被誉为「铁人」。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"社会主义建设的巨大成就和先锋模范；社会主义建设时期的模范人物：王进喜（石油会战中的「铁人」）、焦裕禄（「党的好干部」）、雷锋（「解放军好战士」），以及邓稼先、钱学森等科学家，体现了自力更生、艰苦奋斗、全心全意为人民服务的精神。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-2-2-g5","type":"choice","stem":"「第一个五年计划开始执行」发生于","answer":"A","explain":"本课时间轴：第一个五年计划开始执行（1953 年）。集中主要力量发展重工业，到 1957 年底超额完成。其余三个时间是同一单元相邻课时的事件时间。","options":["1953 年","1958 年","1961—1965 年","1966—1976 年"],"difficulty":1,"tags":["八年级下册","第二单元","本课练习"]}]},{"id":"cat-8b-2-3","title":"第7课 国防现代化起步和外交工作新突破","subtitle":"八年级下册 · 第二单元 社会主义建设道路的探索","grade":"8b","tags":["八年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第二单元 社会主义建设道路的探索"},{"k":"课时","v":"第7课 国防现代化起步和外交工作新突破"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"20 世纪六七十年代，中国国防现代化起步，外交工作取得突破。1971 年 10 月，第 26 届联合国大会恢复中华人民共和国在联合国的一切合法权利。1972 年 2 月，美国总统尼克松访华，中美发表《联合公报》；同年 9 月中日建交。"},{"type":"note","title":"本课主线 · 因果链","text":"新中国成立后，人民海军、人民空军和导弹部队不断壮大，国防力量显著增强，为国家建设提供了安全保障；我国始终奉行独立自主的和平外交政策，从和平共处五项原则到新时代中国特色大国外交，走出了一条和平发展、合作共赢的道路，推动构建人类命运共同体。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1966 年","中国组建战略导弹部队（后称第二炮兵部队）","2015 年更名为火箭军，我国国防力量进一步增强"],["1972 年 2 月","美国总统尼克松访华，中美双方签署《联合公报》","美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化 · 重点"],["1972 年 9 月","中日两国正式建立外交关系","中美关系的改善直接推动了中日建交"],["1979 年 1 月","中美正式建立外交关系","中美关系实现正常化，中国外交打开新局面 · 重点"],["2012 年","我国第一艘航空母舰「辽宁舰」交接入列","国防和军队现代化建设取得重大进展"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1966 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"中国组建战略导弹部队（后称第二炮兵部…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"1972 年 2 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"美国总统尼克松访华，中美双方签署《联…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1972 年 9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"中日两国正式建立外交关系","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"1979 年 1 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"中美正式建立外交关系","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"2012 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"我国第一艘航空母舰「辽宁舰」交接入列","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"中美关系走向正常化：1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","explain":"关键在台湾问题：美方承认只有一个中国是关系正常化的前提。中美关系改善直接推动中日建交，打开了中国外交的新局面。"},{"level":"次重点","text":"国防建设成就：1949 年 4 月人民海军第一支部队建立，1949 年 11 月人民空军领导机关成立，1966 年组建战略导弹部队，2012 年「辽宁舰」交接入列。国防力量的增强为社会主义现代化建设提供了安全保障。","explain":"常与第 6 单元的「两弹一星」联合设题，考「国防建设与国家安全、国际地位」的关系。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["中美关系正常化的前提和关键是台湾问题（一个中国原则）；中美关系的改善推动了中国外交新局面的出现。","国防建设是国家独立与安全的重要保障，人民军队是保卫国家主权和领土完整的坚强柱石。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为 1972 年中美签署《联合公报》就是中美建交。","1972 年尼克松访华、中美签署《联合公报》，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","「开始走向正常化」与「正式建交」相隔七年，是高频错项。"]]},{"type":"table","title":"新中国成立初期与改革开放新时期的中国外交（跨时期对比：同一条和平外交政策的不同阶段）","head":["比较项","新中国成立初期","改革开放新时期（特别是十八大以来）"],"rows":[["国际环境","美苏冷战对峙，美国等敌视、封锁中国","世界多极化、经济全球化深入发展"],["方针理念","独立自主的和平外交政策，提出和平共处五项原则","坚持独立自主的和平外交政策，推动构建人类命运共同体，共建「一带一路」"],["主要成就","同苏联等国建交，参加日内瓦会议、万隆会议","恢复联合国合法席位、中美中日关系正常化，形成全方位外交布局，积极参与全球治理"],["共同点","都坚持独立自主，维护国家主权与世界和平，反对霸权主义","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["新中国外交政策的成熟","以和平共处五项原则、万隆会议的材料设问，考「内容—提出过程—意义」，标准答法是「标志着新中国外交政策的成熟，成为处理国与国之间关系的基本准则」。"],["20 世纪 70 年代的外交突破","把恢复联合国合法席位、中美《联合公报》、中日建交排成时间轴，要求说明三者之间的关联与共同原因，落脚在综合国力与国家利益。"],["国防现代化与国家安全","以人民海军空军、导弹部队的材料设问，考军事力量发展与国家安全、国际地位的关系，常与「两弹一星」合并考查。"],["人类命运共同体与全球治理","结合「一带一路」与全球治理的材料，考新时代中国外交的理念与贡献，答题要用「和平发展、合作共赢」等规范表述。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：独立自主的和平外交与国家安全；地理：联合国与全球治理格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"尼克松","v":"美国总统，1972 年访华，推动中美关系正常化。 出处：《中华人民共和国外交史》"}]},{"type":"list","title":"延伸阅读","items":["乒乓外交：1971 年 4 月，美国乒乓球队应邀访华，以「小球转动大球」，推动中美关系解冻。 出处：《中华人民共和国外交史》","恢复联合国席位：1971 年 10 月 25 日，第 26 届联合国大会以压倒多数通过第 2758 号决议，恢复中华人民共和国在联合国的一切合法权利。 出处：联合国大会第 2758 号决议"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《中华人民共和国外交史》","2024 部编版八下第 7 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】1953 年 12 月，周恩来在接见印度代表团时说：「新中国成立后就确立了处理中印两国关系的原则，那就是互相尊重领土主权、互不侵犯、互不干涉内政、平等互惠和和平共处的原则。」\n【材料二】1971 年 10 月，第 26 届联合国大会通过决议：恢复中华人民共和国的一切权利，承认她的政府的代表为中国在联合国组织的唯一合法代表，并立即把台湾当局的代表从它在联合国组织及其所属一切机构中所非法占据的席位上驱逐出去。\n【材料三】1972 年中美《联合公报》中，美国方面声明：美国认识到，在台湾海峡两边的所有中国人都认为只有一个中国，台湾是中国的一部分。美国政府对这一立场不提出异议。","source":"材料研读 · 国防建设与外交成就"}],"questions":[{"id":"h8b-u5-q4","type":"choice","stem":"中美关系开始走向正常化的标志是","answer":"B","explain":"1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","options":["1971 年基辛格秘密访华","1972 年尼克松访华，中美双方签署《联合公报》","1972 年中日两国正式建立外交关系","1979 年中美正式建立外交关系"],"tags":["中美关系","时空观念"]},{"id":"h8b-u5-q5","type":"choice","stem":"1972 年中日两国正式建立外交关系，其直接推动因素是","answer":"B","explain":"1972 年中美关系开始走向正常化，直接推动了中日建交。中国恢复联合国合法席位（1971 年）有利于打开外交新局面，但不是中日建交的直接推动因素。","options":["中国恢复在联合国的合法席位","中美关系开始走向正常化","万隆会议的召开","和平共处五项原则的提出"],"tags":["中日建交","历史解释"]},{"id":"cat-8b-2-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中国组建战略导弹部队（后称第二炮兵部队）\n② 美国总统尼克松访华，中美双方签署《联合公报》\n③ 中日两国正式建立外交关系\n④ 中美正式建立外交关系","answer":"A","explain":"按时间顺序应为：①中国组建战略导弹部队（后称第二炮兵部队）（1966 年）→②美国总统尼克松访华，中美双方签署《联合公报》（1972 年 2 月）→③中日两国正式建立外交关系（1972 年 9 月）→④中美正式建立外交关系（1979 年 1 月）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-2-3-g2","type":"choice","stem":"下列关于「国防现代化起步和外交工作新突破」的表述，错误的是","answer":"A","explain":"认为 1972 年中美签署《联合公报》就是中美建交——「开始走向正常化」与「正式建交」相隔七年，是高频错项。正确表述：1972 年尼克松访华、中美签署《联合公报》，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","options":["认为 1972 年中美签署《联合公报》就是中美建交。","1972 年尼克松访华、中美签署《联合公报》，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","中美关系正常化的前提和关键是台湾问题（一个中国原则）；中美关系的改善推动了中国外交新局面的出现。","国防建设是国家独立与安全的重要保障，人民军队是保卫国家主权和领土完整的坚强柱石。"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-2-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1971 年 4 月，美国乒乓球队应邀访华，以「小球转动大球」，推动中美关系解冻。（《中华人民共和国外交史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"国防现代化起步和外交工作新突破；中美关系走向正常化：1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","explain":"材料出自《中华人民共和国外交史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8b-3-1","title":"第8课 伟大的历史转折","subtitle":"八年级下册 · 第三单元 改革开放与中国特色社会主义的开创","grade":"8b","tags":["八年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第三单元 改革开放与中国特色社会主义的开创"},{"k":"课时","v":"第8课 伟大的历史转折"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1978 年 5 月，《光明日报》发表《实践是检验真理的唯一标准》，引发真理标准问题大讨论，为十一届三中全会奠定思想基础。1978 年 12 月，中共十一届三中全会在北京召开，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1978 年 12 月","中共十一届三中全会召开","确定解放思想、实事求是的指导方针，把党和国家工作中心转移到经济建设上来，实行改革开放 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"中共十一届三中全会的伟大转折：冲破长…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"中共十一届三中全会是新中国成立以来党…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"中共十一届三中全会的伟大转折：冲破长期「左」的错误的严重束缚，确定了解放思想、实事求是的指导方针；停止使用「以阶级斗争为纲」的口号，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策；实际上形成了以邓小平为核心的党的第二代中央领导集体。","explain":"意义要写成「新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期」。注意区分「进入社会主义初级阶段」（1956 年）与「伟大转折」（1978 年）。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把十一届三中全会的意义说成「标志我国进入社会主义社会」。","我国进入社会主义初级阶段以 1956 年三大改造基本完成为标志；十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折。","两个时间点、两种表述，是选择题最常见的错项组合。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["实事求是","一切从实际出发、理论联系实际、在实践中检验真理和发展真理的思想路线。","《邓小平文选》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"邓小平","v":"改革开放和社会主义现代化建设的总设计师。 出处：《邓小平文选》"}]},{"type":"list","title":"延伸阅读","items":["十一届三中全会的意义：是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。 出处：《中国共产党简史》","真理标准问题讨论：1978 年 5 月 11 日《光明日报》发表特约评论员文章《实践是检验真理的唯一标准》，引发全国讨论，冲破了「两个凡是」的束缚。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《邓小平文选》","2024 部编版八下第 8 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8b-u3-q1","type":"choice","stem":"中共十一届三中全会之所以被称为「新中国成立以来党的历史上具有深远意义的伟大转折」，主要是因为它","answer":"B","explain":"十一届三中全会冲破长期「左」的错误的严重束缚，确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来、实行改革开放，开启了改革开放和社会主义现代化建设新时期。建立社会主义市场经济体制的目标由 1992 年中共十四大提出。","options":["确立了毛泽东思想的指导地位","作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策","提出了建立社会主义市场经济体制的目标","宣布我国进入社会主义初级阶段"],"tags":["十一届三中全会","历史解释"]},{"id":"cat-8b-3-1-g2","type":"choice","stem":"下列关于「伟大的历史转折」的表述，错误的是","answer":"A","explain":"把十一届三中全会的意义说成「标志我国进入社会主义社会」——两个时间点、两种表述，是选择题最常见的错项组合。正确表述：我国进入社会主义初级阶段以 1956 年三大改造基本完成为标志；十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折。","options":["把十一届三中全会的意义说成「标志我国进入社会主义社会」。","我国进入社会主义初级阶段以 1956 年三大改造基本完成为标志；十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","中共十一届三中全会的伟大转折：冲破长期「左」的错误的严重束缚，确定了解放思想、实事求是的指导方针；停止使用「以阶级斗争为纲」的口号，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策；实际上形成了以邓小平为核心的党的第二代中央领导集体。"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"伟大的历史转折；中共十一届三中全会的伟大转折：冲破长期「左」的错误的严重束缚，确定了解放思想、实事求是的指导方针；停止使用「以阶级斗争为纲」的口号，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策；实际上形成了以邓小平为核心的党的第二代中央领导集体。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-3-1-g5","type":"choice","stem":"「中共十一届三中全会召开」发生于","answer":"A","explain":"本课时间轴：中共十一届三中全会召开（1978 年 12 月）。确定解放思想、实事求是的指导方针，把党和国家工作中心转移到经济建设上来，实行改革开放。其余三个时间是同一单元相邻课时的事件时间。","options":["1978 年 12 月","1978 年冬","1980 年","1984 年"],"difficulty":1,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-3-1-g6","type":"choice","stem":"下列考点中，属于「伟大的历史转折」的是","answer":"A","explain":"本课考点（重点）：中共十一届三中全会的伟大转折：冲破长期「左」的错误的严重束缚，确定了解放思想、实事求是的指导方针；停止使用「以阶级斗争为纲」的口号，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策；实际上形成了以邓小平为核心的党的第二代中央领导集体。其余三项是同一单元相邻课时的考点。","options":["中共十一届三中全会的伟大转折：冲破长期「左」的错误的严重束缚，确定了解放思想、实事求是的…","家庭联产承包责任制：在土地公有制的基础上，把土地长期承包给各家各户使用，实行家庭经营、自…","经济特区与对外开放格局：1980 年设立深圳、珠海、汕头、厦门四个经济特区，1988 年…","1992 年邓小平南方谈话与中共十四大：南方谈话进一步解放思想，强调「发展才是硬道理」，…"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]}]},{"id":"cat-8b-3-2","title":"第9课 改革开放的起步","subtitle":"八年级下册 · 第三单元 改革开放与中国特色社会主义的开创","grade":"8b","tags":["八年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第三单元 改革开放与中国特色社会主义的开创"},{"k":"课时","v":"第9课 改革开放的起步"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"改革先从农村开始。1978 年，安徽凤阳小岗村 18 户农民签订「大包干」契约，实行分田包干到户。1980 年，中央决定在深圳、珠海、汕头、厦门设立经济特区。1984 年起，城市经济体制改革全面展开，国有企业推行承包经营责任制。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1978 年冬","安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏","家庭联产承包责任制由此逐步推广到全国农村"],["1980 年","深圳、珠海、汕头、厦门设立经济特区","深圳成为经济特区的代表和对外开放的「窗口」 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1978 年冬","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"安徽凤阳小岗村农民率先实行分田包干到…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1980 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"深圳、珠海、汕头、厦门设立经济特区","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"家庭联产承包责任制：在土地公有制的基础上，把土地长期承包给各家各户使用，实行家庭经营、自负盈亏。它激发了农民的劳动热情，带来农村生产力的大解放，农业生产和农民收入均有很大提高。","explain":"要能一句话说清性质：在坚持土地公有制的前提下改变经营管理方式，不是土地私有化。这是中考最爱设的陷阱。"},{"level":"重点","text":"经济特区与对外开放格局：1980 年设立深圳、珠海、汕头、厦门四个经济特区，1988 年海南建省并成为经济特区；特区主要「特」在实行特殊的经济政策和经济管理体制。对外开放形成「经济特区—沿海开放城市—沿海经济开放区—内地」的全方位、多层次、宽领域格局。","explain":"深圳从边陲小镇发展为现代化城市，是经济特区的代表和对外开放的「窗口」，材料题常用它的变化设问。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["家庭联产承包责任制是在坚持土地公有制的前提下改变经营管理方式，没有改变土地公有性质，也不是土地私有化。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。"],["认为经济特区就是特别行政区。","经济特区是实行特殊经济政策和经济管理体制的区域，仍然实行社会主义制度；特别行政区则按「一国两制」保留原有的资本主义制度和生活方式。","「特区」与「特别行政区」一字之差，性质完全不同，也常与第 4 单元的港澳问题联合设题。"]]},{"type":"table","title":"家庭联产承包责任制与 1950—1952 年土地改革（跨时期对比：农村改革的两种「分田」）","head":["比较项","土地改革（1950—1952）","家庭联产承包责任制（1978 年起）"],"rows":[["土地所有权","归农民私有","归集体公有，土地所有权不变"],["经营方式","农民个体经营","家庭承包经营，自负盈亏"],["要解决的问题","废除封建土地制度，让农民获得土地","改变人民公社体制下过于集中、平均主义的弊端，调动农民生产积极性"],["共同作用","都解放和发展了农村生产力，提高了农民的生产积极性","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["小岗村红手印：1978 年 11 月，小岗村 18 户农民按下红手印，约定「交够国家的，留足集体的，剩下都是自己的」，拉开农村改革序幕。 出处：《中国共产党简史》","经济特区：1980 年设立深圳、珠海、汕头、厦门四个经济特区，1988 年海南建省并设经济特区，成为对外开放的窗口。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《邓小平文选》","2024 部编版八下第 9 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】《关于建国以来党的若干历史问题的决议》指出：「一九七八年十二月召开的十一届三中全会，是建国以来我党历史上具有深远意义的伟大转折。」\n【材料二】1978 年冬，安徽凤阳小岗村的 18 户农民签订契约，实行分田包干到户、自负盈亏。此后这一做法在全国逐步推广，到 1983 年，全国农村普遍实行了家庭联产承包责任制。\n【材料三】邓小平在 1992 年南方谈话中说：「计划多一点还是市场多一点，不是社会主义与资本主义的本质区别。计划经济不等于社会主义，资本主义也有计划；市场经济不等于资本主义，社会主义也有市场。计划和市场都是经济手段。」","source":"材料研读 · 中国特色社会主义道路"}],"questions":[{"id":"h8b-u3-q2","type":"choice","stem":"实行家庭联产承包责任制后，我国农村土地的所有权和经营权状况是","answer":"C","explain":"家庭联产承包责任制是在土地公有制的基础上改变经营管理方式，土地所有权仍归集体，农民通过承包获得经营权和收益，因而不是土地私有化。","options":["土地所有权和经营权都归农民","土地所有权归国家，经营权归农民","土地所有权归集体，农民获得承包经营权","土地所有权归农民，经营权归集体"],"tags":["家庭联产承包责任制","历史解释"]},{"id":"h8b-u3-q4","type":"choice","stem":"1980 年我国设立的经济特区中，被称为对外开放「窗口」的是","answer":"C","explain":"1980 年我国设立深圳、珠海、汕头、厦门四个经济特区，其中深圳从边陲小镇迅速发展为现代化城市，成为经济特区的代表和对外开放的「窗口」。","options":["珠海","汕头","深圳","厦门"],"tags":["经济特区","时空观念"]},{"id":"cat-8b-3-2-g2","type":"choice","stem":"下列关于「改革开放的起步」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","家庭联产承包责任制是在坚持土地公有制的前提下改变经营管理方式，没有改变土地公有性质，也不是土地私有化。","家庭联产承包责任制：在土地公有制的基础上，把土地长期承包给各家各户使用，实行家庭经营、自负盈亏。它激发了农民的劳动热情，带来农村生产力的大解放，农业生产和农民收入均有很大提高。"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-3-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1978 年 11 月，小岗村 18 户农民按下红手印，约定「交够国家的，留足集体的，剩下都是自己的」，拉开农村改革序幕。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"改革开放的起步；家庭联产承包责任制：在土地公有制的基础上，把土地长期承包给各家各户使用，实行家庭经营、自负盈亏。它激发了农民的劳动热情，带来农村生产力的大解放，农业生产和农民收入均有很大提高。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-3-2-g5","type":"choice","stem":"「安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏」发生于","answer":"A","explain":"本课时间轴：安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏（1978 年冬）。家庭联产承包责任制由此逐步推广到全国农村。其余三个时间是同一单元相邻课时的事件时间。","options":["1978 年冬","1978 年 12 月","1984 年","1992 年"],"difficulty":1,"tags":["八年级下册","第三单元","本课练习"]}]},{"id":"cat-8b-3-3","title":"第10课 改革开放和社会主义现代化建设的全面展开","subtitle":"八年级下册 · 第三单元 改革开放与中国特色社会主义的开创","grade":"8b","tags":["八年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第三单元 改革开放与中国特色社会主义的开创"},{"k":"课时","v":"第10课 改革开放和社会主义现代化建设的全面展开"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1992 年初，邓小平视察武昌、深圳、珠海、上海等地，发表南方谈话，强调发展才是硬道理。同年中共十四大提出建立社会主义市场经济体制的目标。2001 年 12 月，中国正式加入世界贸易组织。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1984 年","开放大连、天津、青岛、上海、广州等 14 个沿海港口城市","此后开辟沿海经济开放区，1990 年开发开放上海浦东"],["1992 年","邓小平南方谈话；中共十四大提出建立社会主义市场经济体制的目标","进一步解放思想，把改革开放和社会主义现代化建设推进到新阶段 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1984 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"开放大连、天津、青岛、上海、广州等 …","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1992 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"邓小平南方谈话；中共十四大提出建立社…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"1992 年邓小平南方谈话与中共十四大：南方谈话进一步解放思想，强调「发展才是硬道理」，指出计划和市场都是经济手段；中共十四大明确提出建立社会主义市场经济体制的目标。","explain":"「计划和市场都是经济手段」这句话是理解社会主义市场经济体制的关键，也是常考的材料原句。"},{"level":"选择题","text":"社会主义市场经济体制的建立过程：1992 年中共十四大提出目标，此后逐步推进，到 21 世纪初社会主义市场经济体制初步建立。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。","只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。"],["认为经济特区就是特别行政区。","经济特区是实行特殊经济政策和经济管理体制的区域，仍然实行社会主义制度；特别行政区则按「一国两制」保留原有的资本主义制度和生活方式。","「特区」与「特别行政区」一字之差，性质完全不同，也常与第 4 单元的港澳问题联合设题。"]]},{"type":"table","title":"中国的改革开放与苏联的改革（戈尔巴乔夫改革）（中外对比：两条改革道路的不同结局）","head":["比较项","中国（1978 年起）","苏联（1985 年起）"],"rows":[["改革的立足点","从农村起步，逐步推向城市，坚持社会主义制度与四项基本原则","先经济后政治，后期放弃党的领导地位、背离社会主义方向"],["经济体制","逐步建立社会主义市场经济体制","未能建立起有效的新体制，经济秩序混乱"],["结果","综合国力大幅提升，人民生活显著改善，走出中国特色社会主义道路","1991 年苏联解体"],["启示","改革必须从本国国情出发，坚持正确方向，处理好改革发展稳定的关系","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["发展才是硬道理","邓小平南方谈话中的名言，强调抓住时机发展经济。","《邓小平文选》第三卷"]]},{"type":"list","title":"延伸阅读","items":["南方谈话：邓小平指出「计划多一点还是市场多一点，不是社会主义与资本主义的本质区别」，澄清了姓「资」姓「社」的困惑。 出处：《邓小平文选》第三卷","加入世贸组织：2001 年 12 月 11 日，中国正式成为世界贸易组织成员，对外开放进入新阶段。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《邓小平文选》第三卷","2024 部编版八下第 10 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】《关于建国以来党的若干历史问题的决议》指出：「一九七八年十二月召开的十一届三中全会，是建国以来我党历史上具有深远意义的伟大转折。」\n【材料二】1978 年冬，安徽凤阳小岗村的 18 户农民签订契约，实行分田包干到户、自负盈亏。此后这一做法在全国逐步推广，到 1983 年，全国农村普遍实行了家庭联产承包责任制。\n【材料三】邓小平在 1992 年南方谈话中说：「计划多一点还是市场多一点，不是社会主义与资本主义的本质区别。计划经济不等于社会主义，资本主义也有计划；市场经济不等于资本主义，社会主义也有市场。计划和市场都是经济手段。」","source":"材料研读 · 中国特色社会主义道路"}],"questions":[{"id":"h8b-u3-q1","type":"choice","stem":"中共十一届三中全会之所以被称为「新中国成立以来党的历史上具有深远意义的伟大转折」，主要是因为它","answer":"B","explain":"十一届三中全会冲破长期「左」的错误的严重束缚，确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来、实行改革开放，开启了改革开放和社会主义现代化建设新时期。建立社会主义市场经济体制的目标由 1992 年中共十四大提出。","options":["确立了毛泽东思想的指导地位","作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策","提出了建立社会主义市场经济体制的目标","宣布我国进入社会主义初级阶段"],"tags":["十一届三中全会","历史解释"]},{"id":"h8b-u3-q3","type":"choice","stem":"明确提出建立社会主义市场经济体制目标的会议是","answer":"D","explain":"1992 年中共十四大明确提出建立社会主义市场经济体制的目标。同年邓小平南方谈话指出计划和市场都是经济手段，为这一目标提供了思想基础。","options":["中共十二大","中共十三大","中共十五大","中共十四大"],"tags":["十四大","时空观念"]},{"id":"cat-8b-3-3-g2","type":"choice","stem":"下列关于「改革开放和社会主义现代化建设的全…」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-3-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：邓小平指出「计划多一点还是市场多一点，不是社会主义与资本主义的本质区别」，澄清了姓「资」姓「社」的困惑。（《邓小平文选》第三卷）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"改革开放和社会主义现代化建设的全面展开；1992 年邓小平南方谈话与中共十四大：南方谈话进一步解放思想，强调「发展才是硬道理」，指出计划和市场都是经济手段；中共十四大明确提出建立社会主义市场经济体制的目标。","explain":"材料出自《邓小平文选》第三卷。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-3-3-g5","type":"choice","stem":"「开放大连、天津、青岛、上海、广州等 14 个沿海港口城市」发生于","answer":"A","explain":"本课时间轴：开放大连、天津、青岛、上海、广州等 14 个沿海港口城市（1984 年）。此后开辟沿海经济开放区，1990 年开发开放上海浦东。其余三个时间是同一单元相邻课时的事件时间。","options":["1984 年","1978 年 12 月","1978 年冬","1980 年"],"difficulty":1,"tags":["八年级下册","第三单元","本课练习"]}]},{"id":"cat-8b-3-4","title":"第11课 社会主义初级阶段基本路线","subtitle":"八年级下册 · 第三单元 改革开放与中国特色社会主义的开创","grade":"8b","tags":["八年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第三单元 改革开放与中国特色社会主义的开创"},{"k":"课时","v":"第11课 社会主义初级阶段基本路线"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1987 年中共十三大系统阐述社会主义初级阶段理论，提出「一个中心、两个基本点」的基本路线，制定「三步走」发展战略。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1997 年","中共十五大把邓小平理论确立为党的指导思想","中国特色社会主义理论体系逐步形成"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"中国特色社会主义理论体系：邓小平理论…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":27.17,"text":"中共十一届三中全会是新中国成立以来党…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":41.33,"text":"改革开放是决定当代中国命运的关键一招…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"只有社会主义才能救中国，只有中国特色…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"按「会议—理论—地位」配对记忆；习近平新时代中国特色社会主义思想在中共十九大写入党章、2018 年写入宪法。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。","只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。"],["认为经济特区就是特别行政区。","经济特区是实行特殊经济政策和经济管理体制的区域，仍然实行社会主义制度；特别行政区则按「一国两制」保留原有的资本主义制度和生活方式。","「特区」与「特别行政区」一字之差，性质完全不同，也常与第 4 单元的港澳问题联合设题。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["基本路线：领导和团结全国各族人民，以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生，艰苦创业，为把我国建设成为富强、民主、文明的社会主义现代化国家而奋斗。 出处：中共十三大报告","三步走战略：第一步解决温饱，第二步达到小康，第三步到 21 世纪中叶基本实现现代化。 出处：中共十三大报告"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；十三大报告","2024 部编版八下第 11 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8b-u3-q1","type":"choice","stem":"中共十一届三中全会之所以被称为「新中国成立以来党的历史上具有深远意义的伟大转折」，主要是因为它","answer":"B","explain":"十一届三中全会冲破长期「左」的错误的严重束缚，确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来、实行改革开放，开启了改革开放和社会主义现代化建设新时期。建立社会主义市场经济体制的目标由 1992 年中共十四大提出。","options":["确立了毛泽东思想的指导地位","作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策","提出了建立社会主义市场经济体制的目标","宣布我国进入社会主义初级阶段"],"tags":["十一届三中全会","历史解释"]},{"id":"h8b-u3-q2","type":"choice","stem":"实行家庭联产承包责任制后，我国农村土地的所有权和经营权状况是","answer":"C","explain":"家庭联产承包责任制是在土地公有制的基础上改变经营管理方式，土地所有权仍归集体，农民通过承包获得经营权和收益，因而不是土地私有化。","options":["土地所有权和经营权都归农民","土地所有权归国家，经营权归农民","土地所有权归集体，农民获得承包经营权","土地所有权归农民，经营权归集体"],"tags":["家庭联产承包责任制","历史解释"]},{"id":"h8b-u3-q3","type":"choice","stem":"明确提出建立社会主义市场经济体制目标的会议是","answer":"D","explain":"1992 年中共十四大明确提出建立社会主义市场经济体制的目标。同年邓小平南方谈话指出计划和市场都是经济手段，为这一目标提供了思想基础。","options":["中共十二大","中共十三大","中共十五大","中共十四大"],"tags":["十四大","时空观念"]},{"id":"cat-8b-3-4-g2","type":"choice","stem":"下列关于「社会主义初级阶段基本路线」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-3-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：领导和团结全国各族人民，以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生，艰苦创业，为把我国建设成为富强、民主、文明的社会主义现代化国家而奋斗。（中共十三大报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"社会主义初级阶段基本路线；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自中共十三大报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8b-4-1","title":"第12课 加快改革开放和社会主义现代化建设步伐","subtitle":"八年级下册 · 第四单元 中国特色社会主义迈向21世纪","grade":"8b","tags":["八年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第四单元 中国特色社会主义迈向21世纪"},{"k":"课时","v":"第12课 加快改革开放和社会主义现代化建设步伐"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1992 年南方谈话和中共十四大后，改革开放步伐加快。1997 年中共十五大把邓小平理论确立为党的指导思想。国有企业改革、金融体制改革、住房制度改革等全面推进。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1992 年","邓小平南方谈话；中共十四大提出建立社会主义市场经济体制的目标","进一步解放思想，把改革开放和社会主义现代化建设推进到新阶段 · 重点"],["1997 年","中共十五大把邓小平理论确立为党的指导思想","中国特色社会主义理论体系逐步形成"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1992 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"邓小平南方谈话；中共十四大提出建立社…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1997 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"中共十五大把邓小平理论确立为党的指导…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"1992 年邓小平南方谈话与中共十四大：南方谈话进一步解放思想，强调「发展才是硬道理」，指出计划和市场都是经济手段；中共十四大明确提出建立社会主义市场经济体制的目标。","explain":"「计划和市场都是经济手段」这句话是理解社会主义市场经济体制的关键，也是常考的材料原句。"},{"level":"重点","text":"中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"按「会议—理论—地位」配对记忆；习近平新时代中国特色社会主义思想在中共十九大写入党章、2018 年写入宪法。"},{"level":"选择题","text":"社会主义市场经济体制的建立过程：1992 年中共十四大提出目标，此后逐步推进，到 21 世纪初社会主义市场经济体制初步建立。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。","只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。"],["认为经济特区就是特别行政区。","经济特区是实行特殊经济政策和经济管理体制的区域，仍然实行社会主义制度；特别行政区则按「一国两制」保留原有的资本主义制度和生活方式。","「特区」与「特别行政区」一字之差，性质完全不同，也常与第 4 单元的港澳问题联合设题。"]]},{"type":"table","title":"中国的改革开放与苏联的改革（戈尔巴乔夫改革）（中外对比：两条改革道路的不同结局）","head":["比较项","中国（1978 年起）","苏联（1985 年起）"],"rows":[["改革的立足点","从农村起步，逐步推向城市，坚持社会主义制度与四项基本原则","先经济后政治，后期放弃党的领导地位、背离社会主义方向"],["经济体制","逐步建立社会主义市场经济体制","未能建立起有效的新体制，经济秩序混乱"],["结果","综合国力大幅提升，人民生活显著改善，走出中国特色社会主义道路","1991 年苏联解体"],["启示","改革必须从本国国情出发，坚持正确方向，处理好改革发展稳定的关系","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["十五大：1997 年 9 月在北京召开，把邓小平理论确立为党的指导思想，提出社会主义初级阶段的基本纲领。 出处：中共十五大报告"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；十五大报告","2024 部编版八下第 12 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】《关于建国以来党的若干历史问题的决议》指出：「一九七八年十二月召开的十一届三中全会，是建国以来我党历史上具有深远意义的伟大转折。」\n【材料二】1978 年冬，安徽凤阳小岗村的 18 户农民签订契约，实行分田包干到户、自负盈亏。此后这一做法在全国逐步推广，到 1983 年，全国农村普遍实行了家庭联产承包责任制。\n【材料三】邓小平在 1992 年南方谈话中说：「计划多一点还是市场多一点，不是社会主义与资本主义的本质区别。计划经济不等于社会主义，资本主义也有计划；市场经济不等于资本主义，社会主义也有市场。计划和市场都是经济手段。」","source":"材料研读 · 中国特色社会主义道路"}],"questions":[{"id":"h8b-u3-q1","type":"choice","stem":"中共十一届三中全会之所以被称为「新中国成立以来党的历史上具有深远意义的伟大转折」，主要是因为它","answer":"B","explain":"十一届三中全会冲破长期「左」的错误的严重束缚，确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来、实行改革开放，开启了改革开放和社会主义现代化建设新时期。建立社会主义市场经济体制的目标由 1992 年中共十四大提出。","options":["确立了毛泽东思想的指导地位","作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策","提出了建立社会主义市场经济体制的目标","宣布我国进入社会主义初级阶段"],"tags":["十一届三中全会","历史解释"]},{"id":"h8b-u3-q3","type":"choice","stem":"明确提出建立社会主义市场经济体制目标的会议是","answer":"D","explain":"1992 年中共十四大明确提出建立社会主义市场经济体制的目标。同年邓小平南方谈话指出计划和市场都是经济手段，为这一目标提供了思想基础。","options":["中共十二大","中共十三大","中共十五大","中共十四大"],"tags":["十四大","时空观念"]},{"id":"cat-8b-4-1-g2","type":"choice","stem":"下列关于「加快改革开放和社会主义现代化建设…」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1997 年 9 月在北京召开，把邓小平理论确立为党的指导思想，提出社会主义初级阶段的基本纲领。（中共十五大报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"加快改革开放和社会主义现代化建设步伐；1992 年邓小平南方谈话与中共十四大：南方谈话进一步解放思想，强调「发展才是硬道理」，指出计划和市场都是经济手段；中共十四大明确提出建立社会主义市场经济体制的目标。","explain":"材料出自中共十五大报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-4-1-g7","type":"choice","stem":"关于「加快改革开放和社会主义现代化建设…」，下列表述正确的有\n① 中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开…\n② 改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中…\n③ 只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色…\n④ 认为家庭联产承包责任制是把土地分给农民个人所有。","answer":"A","explain":"①②③均取本课必背结论与考点；④错误——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」，正确表述应为：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["八年级下册","第四单元","本课练习"]}]},{"id":"cat-8b-4-2","title":"第13课 中国特色社会主义事业取得新成就","subtitle":"八年级下册 · 第四单元 中国特色社会主义迈向21世纪","grade":"8b","tags":["八年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第四单元 中国特色社会主义迈向21世纪"},{"k":"课时","v":"第13课 中国特色社会主义事业取得新成就"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"进入 21 世纪，中国综合国力显著增强。2001 年加入世贸组织；2002 年中共十六大把「三个代表」重要思想确立为指导思想；2007 年中共十七大提出科学发展观。1997 年香港回归，1999 年澳门回归。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1999 年 12 月 20 日","中国政府对澳门恢复行使主权，澳门特别行政区成立","标志着中国人民在完成祖国统一大业的道路上又迈出了重要一步 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"tall","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":17,"text":"中国特色社会主义理论体系：邓小平理论…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":39.4,"text":"我国已建立内蒙古（1947）、新疆（…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":61.8,"text":"「一国两制」：在一个中国的前提下，国…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":84.2,"text":"香港、澳门回归祖国的意义：标志着中国…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":106.6,"text":"台湾问题与祖国统一：解决台湾问题的基…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":129,"text":"袁隆平与籼型杂交水稻：1973 年成…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"按「会议—理论—地位」配对记忆；习近平新时代中国特色社会主义思想在中共十九大写入党章、2018 年写入宪法。"},{"level":"重点","text":"我国已建立内蒙古（1947）、新疆（1955）、广西（1958）、宁夏（1958）、西藏（1965）五个省级民族自治区。民族区域自治保障了少数民族当家作主的权利，维护了民族团结和国家统一。","explain":"常以「最早成立的自治区」设问，答案是内蒙古自治区；也要记住五个自治区的名称与大体时间。"},{"level":"重点","text":"「一国两制」：在一个中国的前提下，国家的主体坚持社会主义制度，香港、澳门、台湾保持原有的资本主义制度和生活方式长期不变。它是完成祖国统一大业的基本方针。","explain":"「一国」是前提和基础，「两制」是并存，但国家主体是社会主义制度——这句话不能漏。"},{"level":"重点","text":"香港、澳门回归祖国的意义：标志着中国人民洗雪了百年国耻，在完成祖国统一大业的道路上迈出了重要一步；是「一国两制」伟大构想的成功实践。","explain":"材料题必问「港澳为什么能顺利回归」：根本原因是改革开放后我国综合国力的增强和国际地位的提高，同时「一国两制」方针和中英、中葡联合声明提供了保障。"},{"level":"重点","text":"台湾问题与祖国统一：解决台湾问题的基本方针是「和平统一、一国两制」；坚持一个中国原则是两岸关系和平发展的政治基础，「九二共识」的核心是海峡两岸均坚持一个中国原则。","explain":"要能说明台湾自古以来就是中国领土：三国时期孙权派卫温到夷洲、元朝设澎湖巡检司、清朝设台湾府并建省、1945 年抗日战争胜利后台湾光复。"},{"level":"重点","text":"袁隆平与籼型杂交水稻：1973 年成功培育，被称为「杂交水稻之父」；杂交水稻的大面积推广，为解决中国人的吃饭问题和世界性饥饿问题作出了重大贡献。","explain":"材料题常以粮食产量数据设问，考「科技是第一生产力」「科学家精神」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["民族区域自治制度是我国的一项基本政治制度，保障了少数民族当家作主的权利，维护了民族团结和国家统一，为实现各民族共同繁荣奠定了基础。","「两弹一星」的研制成功，打破了帝国主义的核垄断，增强了我国的国防实力，极大提高了我国的国际地位；科技创新是综合国力竞争的决定性因素。","袁隆平的杂交水稻、屠呦呦的青蒿素表明，科技成就能够造福人类；我国科技工作者具有自力更生、艰苦奋斗、勇于创新的精神。","建设创新型国家要坚持自主创新，把科技自立自强作为国家发展的战略支撑，尊重劳动、尊重知识、尊重人才、尊重创造。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为袁隆平培育成功籼型杂交水稻是在 20 世纪 90 年代。","1973 年袁隆平成功培育出籼型杂交水稻，他被称为「杂交水稻之父」。","时间与人物必须一并记牢，材料题常以此考查「科技成就的年代定位」。"]]},{"type":"table","title":"新中国的科技成就与第三次科技革命（中外对比：中国科技发展与世界科技浪潮）","head":["比较项","中国（1949 年至今）","世界（20 世纪四五十年代以来）"],"rows":[["主要领域","核技术、航天技术、农业科技、医药研究","原子能、计算机、航天技术、生物工程"],["发展路径","从学习引进到自主创新，部分领域达到世界先进水平","以信息技术为核心，科学技术转化为生产力的速度大大加快"],["标志性成就","两弹一星、籼型杂交水稻、青蒿素、载人航天","电子计算机、互联网、基因工程、空间技术"],["共同影响","都极大推动了生产力发展，深刻改变了社会生活和国际格局","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["一国两制","在一个中国的前提下，国家主体坚持社会主义制度，港澳台保持原有资本主义制度长期不变。","《邓小平文选》第三卷"]]},{"type":"list","title":"延伸阅读","items":["香港、澳门回归：1997 年 7 月 1 日香港回归，1999 年 12 月 20 日澳门回归，是「一国两制」构想的成功实践。 出处：《中国共产党简史》","「三个代表」：中国共产党始终代表中国先进生产力的发展要求，代表中国先进文化的前进方向，代表中国最广大人民的根本利益。 出处：中共十六大报告"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；十六大、十七大报告","2024 部编版八下第 13 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】邓小平指出：「如果六十年代以来中国没有原子弹、氢弹，没有发射卫星，中国就不能叫有重要影响的大国，就没有现在这样的国际地位。这些东西反映一个民族的能力，也是一个民族、一个国家兴旺发达的标志。」\n【材料二】屠呦呦在获得诺贝尔奖后说：「青蒿素是传统中医药送给世界人民的礼物，对防治疟疾等传染性疾病、维护世界人民健康具有重要意义。」\n【材料三】20 世纪六七十年代，我国经济发展水平较低、商品供应不足，人们购买粮食、布料等生活必需品要凭票证；改革开放后，市场上的商品日益丰富，人们的衣着变得丰富多彩，住房条件明显改善，出行可以选择高铁、飞机，通信手段从书信、电报发展到手机和互联网。","source":"材料研读 · 科技文化与社会生活"}],"questions":[{"id":"h8b-u6-m1-q2","type":"short","stem":"（2）据材料二、三，说明科技进步与人民生活变化的关系，并分析改革开放后人民生活水平提高的原因。（6 分）","answer":"关系：科技进步推动生产力发展，为改善人民生活提供物质基础；科技成就（如杂交水稻、青蒿素）直接造福人民、保障人民健康，科技进步也改变了人们的出行与通信方式。原因：①实行改革开放，经济快速发展，生产力水平提高，这是根本原因；②实行家庭联产承包责任制等经济体制改革，调动了生产积极性；③科技进步与商品供应日益丰富；④国家重视改善民生，人民生活水平和消费观念不断变化。","explain":"","tags":["社会生活变迁","历史解释"],"rubric":["答出「科技进步推动生产力发展、提供物质基础」","答出「科技成就直接造福人民健康／改变生活方式」","答出「改革开放、经济发展是根本原因」","答出「经济体制改革调动生产积极性」","答出「消费观念变化／国家重视民生」"]},{"id":"h8b-u6-q6","type":"choice","stem":"改革开放以来我国人民生活水平大幅提高的根本原因是","answer":"C","explain":"社会生活变迁的根本原因是改革开放促进经济发展、生产力水平提高，为改善人民生活提供了物质基础；消费观念变化、科技进步是重要原因而非根本原因。","options":["人们消费观念的变化","科技进步改变了生活方式","改革开放促进了经济发展和生产力提高","国外商品大量进入中国市场"],"tags":["社会生活变迁","唯物史观"]},{"id":"cat-8b-4-2-g2","type":"choice","stem":"下列关于「中国特色社会主义事业取得新成就」的表述，错误的是","answer":"A","explain":"认为袁隆平培育成功籼型杂交水稻是在 20 世纪 90 年代——时间与人物必须一并记牢，材料题常以此考查「科技成就的年代定位」。正确表述：1973 年袁隆平成功培育出籼型杂交水稻，他被称为「杂交水稻之父」。","options":["认为袁隆平培育成功籼型杂交水稻是在 20 世纪 90 年代。","1973 年袁隆平成功培育出籼型杂交水稻，他被称为「杂交水稻之父」。","民族区域自治制度是我国的一项基本政治制度，保障了少数民族当家作主的权利，维护了民族团结和国家统一，为实现各民族共同繁荣奠定了基础。","「两弹一星」的研制成功，打破了帝国主义的核垄断，增强了我国的国防实力，极大提高了我国的国际地位；科技创新是综合国力竞争的决定性因素。"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-4-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1997 年 7 月 1 日香港回归，1999 年 12 月 20 日澳门回归，是「一国两制」构想的成功实践。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中国特色社会主义事业取得新成就；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-4-2-g5","type":"choice","stem":"「中国政府对澳门恢复行使主权，澳门特别行政区成立」发生于","answer":"A","explain":"本课时间轴：中国政府对澳门恢复行使主权，澳门特别行政区成立（1999 年 12 月 20 日）。标志着中国人民在完成祖国统一大业的道路上又迈出了重要一步。其余三个时间是同一单元相邻课时的事件时间。","options":["1999 年 12 月 20 日","1992 年","1997 年","1964 年 10 月"],"difficulty":1,"tags":["八年级下册","第四单元","本课练习"]}]},{"id":"cat-8b-4-3","title":"第14课 国防和外交工作新局面","subtitle":"八年级下册 · 第四单元 中国特色社会主义迈向21世纪","grade":"8b","tags":["八年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第四单元 中国特色社会主义迈向21世纪"},{"k":"课时","v":"第14课 国防和外交工作新局面"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"进入 21 世纪，中国国防和军队现代化建设加快推进，外交上积极参与多边合作。2001 年上海合作组织成立，同年博鳌亚洲论坛成立。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1953 年 12 月","周恩来在接见印度代表团时首次提出和平共处五项原则","标志着新中国外交政策的成熟 · 重点"],["1966 年","中国组建战略导弹部队（后称第二炮兵部队）","2015 年更名为火箭军，我国国防力量进一步增强"],["1971 年 10 月","第 26 届联合国大会恢复中华人民共和国在联合国的一切合法权利","恢复中国安理会常任理事国席位，是中国外交的重大胜利 · 重点"],["1972 年 9 月","中日两国正式建立外交关系","中美关系的改善直接推动了中日建交"],["1979 年 1 月","中美正式建立外交关系","中美关系实现正常化，中国外交打开新局面 · 重点"],["2012 年","我国第一艘航空母舰「辽宁舰」交接入列","国防和军队现代化建设取得重大进展"],["2013 年","习近平提出共建「一带一路」倡议","我国推动构建人类命运共同体，形成全方位、多层次、立体化的外交布局"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1953 年 12 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"周恩来在接见印度代表团时首次提出和平…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":29.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":32.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":29.67,"text":"1966 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":35.67,"text":"中国组建战略导弹部队（后称第二炮兵部…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":36.07,"x2":14,"y2":47.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":51.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":48.33,"text":"1971 年 10 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":54.33,"text":"第 26 届联合国大会恢复中华人民共…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":54.73,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1972 年 9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"中日两国正式建立外交关系","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":85.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":88.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":85.67,"text":"1979 年 1 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":91.67,"text":"中美正式建立外交关系","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":92.07,"x2":14,"y2":103.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":107.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":104.33,"text":"2012 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":110.33,"text":"我国第一艘航空母舰「辽宁舰」交接入列","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":110.73,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"2013 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"习近平提出共建「一带一路」倡议","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"和平共处五项原则：互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处。1953 年 12 月周恩来在接见印度代表团时首次提出，1954 年在中印、中缅联合声明中确立为指导相互关系的基本原则。","explain":"意义要写「标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生深远影响」。五项内容要能完整背出。"},{"level":"重点","text":"1971 年 10 月，第 26 届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利，恢复中国安理会常任理事国席位，并把台湾当局的代表从联合国及其所属一切机构中驱逐出去。","explain":"这是中国外交的重大胜利，也是广大发展中国家支持的结果。注意用「恢复」而不是「加入」——中国是联合国创始会员国。"},{"level":"重点","text":"中美关系走向正常化：1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","explain":"关键在台湾问题：美方承认只有一个中国是关系正常化的前提。中美关系改善直接推动中日建交，打开了中国外交的新局面。"},{"level":"重点","text":"新时代中国外交：奉行独立自主的和平外交政策，坚持走和平发展道路，推动构建人类命运共同体；提出共建「一带一路」倡议，积极参与全球治理，形成全方位、多层次、立体化的外交布局。","explain":"答题落脚在「中国是世界和平的建设者、全球发展的贡献者、国际秩序的维护者」，中国永不称霸、永不扩张。"},{"level":"次重点","text":"国防建设成就：1949 年 4 月人民海军第一支部队建立，1949 年 11 月人民空军领导机关成立，1966 年组建战略导弹部队，2012 年「辽宁舰」交接入列。国防力量的增强为社会主义现代化建设提供了安全保障。","explain":"常与第 6 单元的「两弹一星」联合设题，考「国防建设与国家安全、国际地位」的关系。"},{"level":"次重点","text":"新中国成立初期的外交方针：奉行独立自主的和平外交政策，同苏联等社会主义国家建立外交关系，反对帝国主义的侵略政策和战争政策，以和平共处五项原则发展同邻近国家和新兴独立国家的关系。","explain":"1954 年日内瓦会议是中国第一次以世界五大国之一的身份参加的国际会议，注意与 1955 年万隆会议相区分。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["和平共处五项原则标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生了深远影响。","1971 年恢复中华人民共和国在联合国的一切合法权利，是中国外交的重大胜利，也是广大发展中国家支持的结果；中国是联合国创始会员国和安理会常任理事国。","中美关系正常化的前提和关键是台湾问题（一个中国原则）；中美关系的改善推动了中国外交新局面的出现。","中国始终奉行独立自主的和平外交政策，坚持走和平发展道路，推动构建人类命运共同体；国家实力是国际地位的基础，「弱国无外交」。","国防建设是国家独立与安全的重要保障，人民军队是保卫国家主权和领土完整的坚强柱石。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为 1971 年中国「加入」联合国。","1971 年第 26 届联大恢复中华人民共和国在联合国的一切合法权利，中国是联合国创始会员国和安理会常任理事国。","表述差别决定得分：应为「恢复合法席位」，不是「加入」。"],["认为 1972 年中美签署《联合公报》就是中美建交。","1972 年尼克松访华、中美签署《联合公报》，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","「开始走向正常化」与「正式建交」相隔七年，是高频错项。"]]},{"type":"table","title":"新中国成立初期与改革开放新时期的中国外交（跨时期对比：同一条和平外交政策的不同阶段）","head":["比较项","新中国成立初期","改革开放新时期（特别是十八大以来）"],"rows":[["国际环境","美苏冷战对峙，美国等敌视、封锁中国","世界多极化、经济全球化深入发展"],["方针理念","独立自主的和平外交政策，提出和平共处五项原则","坚持独立自主的和平外交政策，推动构建人类命运共同体，共建「一带一路」"],["主要成就","同苏联等国建交，参加日内瓦会议、万隆会议","恢复联合国合法席位、中美中日关系正常化，形成全方位外交布局，积极参与全球治理"],["共同点","都坚持独立自主，维护国家主权与世界和平，反对霸权主义","同左"]]},{"type":"table","title":"新中国外交与近代中国的屈辱外交（跨时期对比：国家地位决定外交地位）","head":["比较项","近代中国（1840—1949）","新中国（1949 年至今）"],"rows":[["国家状况","半殖民地半封建社会，国家贫弱","实现了民族独立和人民解放，人民当家作主"],["外交性质","屈辱外交，被迫签订不平等条约","独立自主的和平外交"],["结果","领土主权遭到破坏，国际地位低下","1971 年恢复在联合国的合法席位，国际地位不断提高"],["根本原因","综合国力（国家实力）是国际地位的基础","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["上海合作组织：2001 年 6 月，中国、俄罗斯、哈萨克斯坦、吉尔吉斯斯坦、塔吉克斯坦、乌兹别克斯坦六国在上海签署成立宣言。 出处：《上海合作组织成立宣言》","博鳌亚洲论坛：2001 年 2 月在海南博鳌成立，是第一个总部设在中国的国际会议组织。 出处：博鳌亚洲论坛官方资料"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；《上海合作组织成立宣言》","2024 部编版八下第 14 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】1953 年 12 月，周恩来在接见印度代表团时说：「新中国成立后就确立了处理中印两国关系的原则，那就是互相尊重领土主权、互不侵犯、互不干涉内政、平等互惠和和平共处的原则。」\n【材料二】1971 年 10 月，第 26 届联合国大会通过决议：恢复中华人民共和国的一切权利，承认她的政府的代表为中国在联合国组织的唯一合法代表，并立即把台湾当局的代表从它在联合国组织及其所属一切机构中所非法占据的席位上驱逐出去。\n【材料三】1972 年中美《联合公报》中，美国方面声明：美国认识到，在台湾海峡两边的所有中国人都认为只有一个中国，台湾是中国的一部分。美国政府对这一立场不提出异议。","source":"材料研读 · 国防建设与外交成就"}],"questions":[{"id":"h8b-u5-m1-q2","type":"short","stem":"（2）据材料二、三并结合所学，分析 20 世纪 70 年代中国外交取得重大成就的原因。（6 分）","answer":"①中国综合国力增强、国际地位提高；②中国政府坚持独立自主的和平外交政策，积极发展同各国的友好关系；③广大发展中国家（第三世界国家）的支持，使恢复联合国合法席位的努力取得成功；④中国基于国家利益调整对外关系，中美双方都有改善关系的需要，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化，并直接推动了中日建交，打开了中国外交的新局面。","explain":"","tags":["20 世纪 70 年代外交","史料实证"],"rubric":["答出「综合国力增强、国际地位提高」","答出「独立自主的和平外交政策」","答出「发展中国家的支持」","答出「中美双方基于国家利益的需要」","答出「中美关系正常化推动中日建交」"]},{"id":"h8b-u5-q3","type":"choice","stem":"关于 1971 年中国在联合国合法席位的表述，正确的是","answer":"C","explain":"中国是联合国创始会员国和安理会常任理事国，1971 年第 26 届联大是「恢复」中华人民共和国在联合国的一切合法权利，并把台湾当局的代表驱逐出去。","options":["中国在这一年加入联合国","中国在这一年成为联合国安理会非常任理事国","第 26 届联大恢复中华人民共和国在联合国的一切合法权利","中国在这一年恢复了世界贸易组织成员地位"],"tags":["恢复联合国合法席位","历史解释"]},{"id":"h8b-u5-q4","type":"choice","stem":"中美关系开始走向正常化的标志是","answer":"B","explain":"1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","options":["1971 年基辛格秘密访华","1972 年尼克松访华，中美双方签署《联合公报》","1972 年中日两国正式建立外交关系","1979 年中美正式建立外交关系"],"tags":["中美关系","时空观念"]},{"id":"h8b-u5-q5","type":"choice","stem":"1972 年中日两国正式建立外交关系，其直接推动因素是","answer":"B","explain":"1972 年中美关系开始走向正常化，直接推动了中日建交。中国恢复联合国合法席位（1971 年）有利于打开外交新局面，但不是中日建交的直接推动因素。","options":["中国恢复在联合国的合法席位","中美关系开始走向正常化","万隆会议的召开","和平共处五项原则的提出"],"tags":["中日建交","历史解释"]},{"id":"h8b-u5-q6","type":"choice","stem":"新时代中国特色大国外交倡导的重要理念是","answer":"A","explain":"新时代中国奉行独立自主的和平外交政策，提出共建「一带一路」倡议，推动构建人类命运共同体，积极参与全球治理，形成全方位、多层次、立体化的外交布局。","options":["构建人类命运共同体","文明冲突论","霸权稳定论","闭关自守"],"tags":["新时代外交","家国情怀"]},{"id":"cat-8b-4-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 周恩来在接见印度代表团时首次提出和平共处五项原则\n② 中国组建战略导弹部队（后称第二炮兵部队）\n③ 第 26 届联合国大会恢复中华人民共和国在联合国…\n④ 中日两国正式建立外交关系","answer":"A","explain":"按时间顺序应为：①周恩来在接见印度代表团时首次提出和平共处五项原则（1953 年 12 月）→②中国组建战略导弹部队（后称第二炮兵部队）（1966 年）→③第 26 届联合国大会恢复中华人民共和国在联合国的一切合法权利（1971 年 10 月）→④中日两国正式建立外交关系（1972 年 9 月）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-4-3-g2","type":"choice","stem":"下列关于「国防和外交工作新局面」的表述，错误的是","answer":"A","explain":"认为 1971 年中国「加入」联合国——表述差别决定得分：应为「恢复合法席位」，不是「加入」。正确表述：1971 年第 26 届联大恢复中华人民共和国在联合国的一切合法权利，中国是联合国创始会员国和安理会常任理事国。","options":["认为 1971 年中国「加入」联合国。","1971 年第 26 届联大恢复中华人民共和国在联合国的一切合法权利，中国是联合国创始会员国和安理会常任理事国。","和平共处五项原则标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生了深远影响。","1971 年恢复中华人民共和国在联合国的一切合法权利，是中国外交的重大胜利，也是广大发展中国家支持的结果；中国是联合国创始会员国和安理会常任理事国。"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-4-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：2001 年 6 月，中国、俄罗斯、哈萨克斯坦、吉尔吉斯斯坦、塔吉克斯坦、乌兹别克斯坦六国在上海签署成立宣言。（《上海合作组织成立宣言》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"国防和外交工作新局面；和平共处五项原则：互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处。1953 年 12 月周恩来在接见印度代表团时首次提出，1954 年在中印、中缅联合声明中确立为指导相互关系的基本原则。","explain":"材料出自《上海合作组织成立宣言》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8b-5-1","title":"第15课 开始全面建设小康社会","subtitle":"八年级下册 · 第五单元 在新形势下坚持和发展中国特色社会主义","grade":"8b","tags":["八年级下册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第五单元 在新形势下坚持和发展中国特色社会主义"},{"k":"课时","v":"第15课 开始全面建设小康社会"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"2002 年中共十六大提出全面建设小康社会的奋斗目标，科学发展观逐步形成。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["1978 年 12 月","中共十一届三中全会召开","确定解放思想、实事求是的指导方针，把党和国家工作中心转移到经济建设上来，实行改革开放 · 重点"],["1978 年冬","安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏","家庭联产承包责任制由此逐步推广到全国农村"],["1980 年","深圳、珠海、汕头、厦门设立经济特区","深圳成为经济特区的代表和对外开放的「窗口」 · 重点"],["1984 年","开放大连、天津、青岛、上海、广州等 14 个沿海港口城市","此后开辟沿海经济开放区，1990 年开发开放上海浦东"],["1992 年","邓小平南方谈话；中共十四大提出建立社会主义市场经济体制的目标","进一步解放思想，把改革开放和社会主义现代化建设推进到新阶段 · 重点"],["1997 年","中共十五大把邓小平理论确立为党的指导思想","中国特色社会主义理论体系逐步形成"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1978 年 12 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"中共十一届三中全会召开","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"1978 年冬","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"安徽凤阳小岗村农民率先实行分田包干到…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1980 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"深圳、珠海、汕头、厦门设立经济特区","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"1984 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"开放大连、天津、青岛、上海、广州等 …","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"1992 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"邓小平南方谈话；中共十四大提出建立社…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1997 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"中共十五大把邓小平理论确立为党的指导…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"按「会议—理论—地位」配对记忆；习近平新时代中国特色社会主义思想在中共十九大写入党章、2018 年写入宪法。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。","只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。"],["认为经济特区就是特别行政区。","经济特区是实行特殊经济政策和经济管理体制的区域，仍然实行社会主义制度；特别行政区则按「一国两制」保留原有的资本主义制度和生活方式。","「特区」与「特别行政区」一字之差，性质完全不同，也常与第 4 单元的港澳问题联合设题。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["全面建设小康社会：十六大提出，要在本世纪头二十年，集中力量全面建设惠及十几亿人口的更高水平的小康社会。 出处：中共十六大报告"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；十六大报告","2024 部编版八下第 15 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8b-u3-q1","type":"choice","stem":"中共十一届三中全会之所以被称为「新中国成立以来党的历史上具有深远意义的伟大转折」，主要是因为它","answer":"B","explain":"十一届三中全会冲破长期「左」的错误的严重束缚，确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来、实行改革开放，开启了改革开放和社会主义现代化建设新时期。建立社会主义市场经济体制的目标由 1992 年中共十四大提出。","options":["确立了毛泽东思想的指导地位","作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策","提出了建立社会主义市场经济体制的目标","宣布我国进入社会主义初级阶段"],"tags":["十一届三中全会","历史解释"]},{"id":"h8b-u3-q2","type":"choice","stem":"实行家庭联产承包责任制后，我国农村土地的所有权和经营权状况是","answer":"C","explain":"家庭联产承包责任制是在土地公有制的基础上改变经营管理方式，土地所有权仍归集体，农民通过承包获得经营权和收益，因而不是土地私有化。","options":["土地所有权和经营权都归农民","土地所有权归国家，经营权归农民","土地所有权归集体，农民获得承包经营权","土地所有权归农民，经营权归集体"],"tags":["家庭联产承包责任制","历史解释"]},{"id":"h8b-u3-q3","type":"choice","stem":"明确提出建立社会主义市场经济体制目标的会议是","answer":"D","explain":"1992 年中共十四大明确提出建立社会主义市场经济体制的目标。同年邓小平南方谈话指出计划和市场都是经济手段，为这一目标提供了思想基础。","options":["中共十二大","中共十三大","中共十五大","中共十四大"],"tags":["十四大","时空观念"]},{"id":"cat-8b-5-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中共十一届三中全会召开\n② 安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏\n③ 深圳、珠海、汕头、厦门设立经济特区\n④ 开放大连、天津、青岛、上海、广州等 14 个沿海…","answer":"A","explain":"按时间顺序应为：①中共十一届三中全会召开（1978 年 12 月）→②安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏（1978 年冬）→③深圳、珠海、汕头、厦门设立经济特区（1980 年）→④开放大连、天津、青岛、上海、广州等 14 个沿海港口城市（1984 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-1-g2","type":"choice","stem":"下列关于「开始全面建设小康社会」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：十六大提出，要在本世纪头二十年，集中力量全面建设惠及十几亿人口的更高水平的小康社会。（中共十六大报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"开始全面建设小康社会；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自中共十六大报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8b-5-2","title":"第16课 夺取全面建设小康社会新胜利","subtitle":"八年级下册 · 第五单元 在新形势下坚持和发展中国特色社会主义","grade":"8b","tags":["八年级下册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第五单元 在新形势下坚持和发展中国特色社会主义"},{"k":"课时","v":"第16课 夺取全面建设小康社会新胜利"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"2007 年中共十七大对全面建设小康社会提出新要求；2012 年中共十八大提出全面建成小康社会。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["2012 年","中共十八大召开","十八大以来，中国特色社会主义进入新时代"],["2021 年","中国共产党成立 100 周年，我国全面建成小康社会，实现第一个百年奋斗目标","脱贫攻坚战取得全面胜利，历史性地解决了绝对贫困问题 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"2012 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"中共十八大召开","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"2021 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"中国共产党成立 100 周年，我国全…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"按「会议—理论—地位」配对记忆；习近平新时代中国特色社会主义思想在中共十九大写入党章、2018 年写入宪法。"},{"level":"重点","text":"中共十八大以来，中国特色社会主义进入新时代；2021 年中国共产党成立 100 周年，我国全面建成小康社会，实现第一个百年奋斗目标，历史性地解决了绝对贫困问题；中共二十大提出以中国式现代化全面推进中华民族伟大复兴。","explain":"要注意「全面建成小康社会」与「全面建成社会主义现代化强国」的时间区别：前者 2021 年已实现，后者是本世纪中叶的目标。"},{"level":"次重点","text":"脱贫攻坚战取得全面胜利：现行标准下 9899 万农村贫困人口全部脱贫，832 个贫困县全部摘帽，12.8 万个贫困村全部出列，创造了人类减贫史上的奇迹。","explain":"数据出自 2021 年全国脱贫攻坚总结表彰大会的权威表述，答题时可引用，但要与「全面建成小康社会」放在同一时间节点上。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。","只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为我国已经建成社会主义现代化强国。","2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","「全面建成小康社会」与「全面建成社会主义现代化强国」阶段不同，表述不能互换。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["科学发展观：第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。 出处：中共十八大报告"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；十七大、十八大报告","2024 部编版八下第 16 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8b-u3-q5","type":"choice","stem":"2021 年我国取得的重大成就是","answer":"D","explain":"2021 年中国共产党成立 100 周年，我国全面建成小康社会，历史性地解决了绝对贫困问题，实现了第一个百年奋斗目标。加入世界贸易组织是 2001 年，建成社会主义现代化强国是本世纪中叶的目标。","options":["加入世界贸易组织","建成社会主义现代化强国","基本实现社会主义现代化","全面建成小康社会，实现第一个百年奋斗目标"],"tags":["新时代","家国情怀"]},{"id":"h8b-u3-q6","type":"choice","stem":"把习近平新时代中国特色社会主义思想确立为党的指导思想的会议是","answer":"B","explain":"2017 年中共十九大把习近平新时代中国特色社会主义思想确立为党的指导思想；中共十八大以来，中国特色社会主义进入新时代；中共二十大提出以中国式现代化全面推进中华民族伟大复兴。","options":["中共十八大","中共十九大","中共二十大","中共十八届三中全会"],"tags":["中共十九大","理论体系"]},{"id":"cat-8b-5-2-g2","type":"choice","stem":"下列关于「夺取全面建设小康社会新胜利」的表述，错误的是","answer":"A","explain":"认为我国已经建成社会主义现代化强国——「全面建成小康社会」与「全面建成社会主义现代化强国」阶段不同，表述不能互换。正确表述：2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","options":["认为我国已经建成社会主义现代化强国。","2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。（中共十八大报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"夺取全面建设小康社会新胜利；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自中共十八大报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-5-2-g7","type":"choice","stem":"关于「夺取全面建设小康社会新胜利」，下列表述正确的有\n① 中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开…\n② 改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中…\n③ 只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色…\n④ 认为我国已经建成社会主义现代化强国。","answer":"A","explain":"①②③均取本课必背结论与考点；④错误——「全面建成小康社会」与「全面建成社会主义现代化强国」阶段不同，表述不能互换，正确表述应为：2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["八年级下册","第五单元","本课练习"]}]},{"id":"cat-8b-5-3","title":"第17课 推进国防军队建设和外交工作","subtitle":"八年级下册 · 第五单元 在新形势下坚持和发展中国特色社会主义","grade":"8b","tags":["八年级下册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第五单元 在新形势下坚持和发展中国特色社会主义"},{"k":"课时","v":"第17课 推进国防军队建设和外交工作"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"这一时期，国防和军队现代化建设持续推进，中国积极参与上海合作组织、博鳌亚洲论坛等多边机制，推动地区合作。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1953 年 12 月","周恩来在接见印度代表团时首次提出和平共处五项原则","标志着新中国外交政策的成熟 · 重点"],["1966 年","中国组建战略导弹部队（后称第二炮兵部队）","2015 年更名为火箭军，我国国防力量进一步增强"],["1971 年 10 月","第 26 届联合国大会恢复中华人民共和国在联合国的一切合法权利","恢复中国安理会常任理事国席位，是中国外交的重大胜利 · 重点"],["1972 年 9 月","中日两国正式建立外交关系","中美关系的改善直接推动了中日建交"],["1979 年 1 月","中美正式建立外交关系","中美关系实现正常化，中国外交打开新局面 · 重点"],["2012 年","我国第一艘航空母舰「辽宁舰」交接入列","国防和军队现代化建设取得重大进展"],["2013 年","习近平提出共建「一带一路」倡议","我国推动构建人类命运共同体，形成全方位、多层次、立体化的外交布局"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1953 年 12 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"周恩来在接见印度代表团时首次提出和平…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":29.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":32.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":29.67,"text":"1966 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":35.67,"text":"中国组建战略导弹部队（后称第二炮兵部…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":36.07,"x2":14,"y2":47.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":51.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":48.33,"text":"1971 年 10 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":54.33,"text":"第 26 届联合国大会恢复中华人民共…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":54.73,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1972 年 9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"中日两国正式建立外交关系","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":85.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":88.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":85.67,"text":"1979 年 1 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":91.67,"text":"中美正式建立外交关系","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":92.07,"x2":14,"y2":103.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":107.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":104.33,"text":"2012 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":110.33,"text":"我国第一艘航空母舰「辽宁舰」交接入列","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":110.73,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"2013 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"习近平提出共建「一带一路」倡议","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"和平共处五项原则：互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处。1953 年 12 月周恩来在接见印度代表团时首次提出，1954 年在中印、中缅联合声明中确立为指导相互关系的基本原则。","explain":"意义要写「标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生深远影响」。五项内容要能完整背出。"},{"level":"重点","text":"1971 年 10 月，第 26 届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利，恢复中国安理会常任理事国席位，并把台湾当局的代表从联合国及其所属一切机构中驱逐出去。","explain":"这是中国外交的重大胜利，也是广大发展中国家支持的结果。注意用「恢复」而不是「加入」——中国是联合国创始会员国。"},{"level":"重点","text":"中美关系走向正常化：1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","explain":"关键在台湾问题：美方承认只有一个中国是关系正常化的前提。中美关系改善直接推动中日建交，打开了中国外交的新局面。"},{"level":"重点","text":"新时代中国外交：奉行独立自主的和平外交政策，坚持走和平发展道路，推动构建人类命运共同体；提出共建「一带一路」倡议，积极参与全球治理，形成全方位、多层次、立体化的外交布局。","explain":"答题落脚在「中国是世界和平的建设者、全球发展的贡献者、国际秩序的维护者」，中国永不称霸、永不扩张。"},{"level":"次重点","text":"国防建设成就：1949 年 4 月人民海军第一支部队建立，1949 年 11 月人民空军领导机关成立，1966 年组建战略导弹部队，2012 年「辽宁舰」交接入列。国防力量的增强为社会主义现代化建设提供了安全保障。","explain":"常与第 6 单元的「两弹一星」联合设题，考「国防建设与国家安全、国际地位」的关系。"},{"level":"次重点","text":"新中国成立初期的外交方针：奉行独立自主的和平外交政策，同苏联等社会主义国家建立外交关系，反对帝国主义的侵略政策和战争政策，以和平共处五项原则发展同邻近国家和新兴独立国家的关系。","explain":"1954 年日内瓦会议是中国第一次以世界五大国之一的身份参加的国际会议，注意与 1955 年万隆会议相区分。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["和平共处五项原则标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生了深远影响。","1971 年恢复中华人民共和国在联合国的一切合法权利，是中国外交的重大胜利，也是广大发展中国家支持的结果；中国是联合国创始会员国和安理会常任理事国。","中美关系正常化的前提和关键是台湾问题（一个中国原则）；中美关系的改善推动了中国外交新局面的出现。","中国始终奉行独立自主的和平外交政策，坚持走和平发展道路，推动构建人类命运共同体；国家实力是国际地位的基础，「弱国无外交」。","国防建设是国家独立与安全的重要保障，人民军队是保卫国家主权和领土完整的坚强柱石。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为 1972 年中美签署《联合公报》就是中美建交。","1972 年尼克松访华、中美签署《联合公报》，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","「开始走向正常化」与「正式建交」相隔七年，是高频错项。"]]},{"type":"table","title":"新中国成立初期与改革开放新时期的中国外交（跨时期对比：同一条和平外交政策的不同阶段）","head":["比较项","新中国成立初期","改革开放新时期（特别是十八大以来）"],"rows":[["国际环境","美苏冷战对峙，美国等敌视、封锁中国","世界多极化、经济全球化深入发展"],["方针理念","独立自主的和平外交政策，提出和平共处五项原则","坚持独立自主的和平外交政策，推动构建人类命运共同体，共建「一带一路」"],["主要成就","同苏联等国建交，参加日内瓦会议、万隆会议","恢复联合国合法席位、中美中日关系正常化，形成全方位外交布局，积极参与全球治理"],["共同点","都坚持独立自主，维护国家主权与世界和平，反对霸权主义","同左"]]},{"type":"table","title":"新中国外交与近代中国的屈辱外交（跨时期对比：国家地位决定外交地位）","head":["比较项","近代中国（1840—1949）","新中国（1949 年至今）"],"rows":[["国家状况","半殖民地半封建社会，国家贫弱","实现了民族独立和人民解放，人民当家作主"],["外交性质","屈辱外交，被迫签订不平等条约","独立自主的和平外交"],["结果","领土主权遭到破坏，国际地位低下","1971 年恢复在联合国的合法席位，国际地位不断提高"],["根本原因","综合国力（国家实力）是国际地位的基础","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["国防现代化：坚持走中国特色强军之路，推进机械化信息化复合发展，提高国防和军队现代化水平。 出处：《中国共产党简史》"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》","2024 部编版八下第 17 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】1953 年 12 月，周恩来在接见印度代表团时说：「新中国成立后就确立了处理中印两国关系的原则，那就是互相尊重领土主权、互不侵犯、互不干涉内政、平等互惠和和平共处的原则。」\n【材料二】1971 年 10 月，第 26 届联合国大会通过决议：恢复中华人民共和国的一切权利，承认她的政府的代表为中国在联合国组织的唯一合法代表，并立即把台湾当局的代表从它在联合国组织及其所属一切机构中所非法占据的席位上驱逐出去。\n【材料三】1972 年中美《联合公报》中，美国方面声明：美国认识到，在台湾海峡两边的所有中国人都认为只有一个中国，台湾是中国的一部分。美国政府对这一立场不提出异议。","source":"材料研读 · 国防建设与外交成就"}],"questions":[{"id":"h8b-u5-m1-q2","type":"short","stem":"（2）据材料二、三并结合所学，分析 20 世纪 70 年代中国外交取得重大成就的原因。（6 分）","answer":"①中国综合国力增强、国际地位提高；②中国政府坚持独立自主的和平外交政策，积极发展同各国的友好关系；③广大发展中国家（第三世界国家）的支持，使恢复联合国合法席位的努力取得成功；④中国基于国家利益调整对外关系，中美双方都有改善关系的需要，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化，并直接推动了中日建交，打开了中国外交的新局面。","explain":"","tags":["20 世纪 70 年代外交","史料实证"],"rubric":["答出「综合国力增强、国际地位提高」","答出「独立自主的和平外交政策」","答出「发展中国家的支持」","答出「中美双方基于国家利益的需要」","答出「中美关系正常化推动中日建交」"]},{"id":"h8b-u5-q4","type":"choice","stem":"中美关系开始走向正常化的标志是","answer":"B","explain":"1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","options":["1971 年基辛格秘密访华","1972 年尼克松访华，中美双方签署《联合公报》","1972 年中日两国正式建立外交关系","1979 年中美正式建立外交关系"],"tags":["中美关系","时空观念"]},{"id":"h8b-u5-q5","type":"choice","stem":"1972 年中日两国正式建立外交关系，其直接推动因素是","answer":"B","explain":"1972 年中美关系开始走向正常化，直接推动了中日建交。中国恢复联合国合法席位（1971 年）有利于打开外交新局面，但不是中日建交的直接推动因素。","options":["中国恢复在联合国的合法席位","中美关系开始走向正常化","万隆会议的召开","和平共处五项原则的提出"],"tags":["中日建交","历史解释"]},{"id":"h8b-u5-q6","type":"choice","stem":"新时代中国特色大国外交倡导的重要理念是","answer":"A","explain":"新时代中国奉行独立自主的和平外交政策，提出共建「一带一路」倡议，推动构建人类命运共同体，积极参与全球治理，形成全方位、多层次、立体化的外交布局。","options":["构建人类命运共同体","文明冲突论","霸权稳定论","闭关自守"],"tags":["新时代外交","家国情怀"]},{"id":"cat-8b-5-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 周恩来在接见印度代表团时首次提出和平共处五项原则\n② 中国组建战略导弹部队（后称第二炮兵部队）\n③ 第 26 届联合国大会恢复中华人民共和国在联合国…\n④ 中日两国正式建立外交关系","answer":"A","explain":"按时间顺序应为：①周恩来在接见印度代表团时首次提出和平共处五项原则（1953 年 12 月）→②中国组建战略导弹部队（后称第二炮兵部队）（1966 年）→③第 26 届联合国大会恢复中华人民共和国在联合国的一切合法权利（1971 年 10 月）→④中日两国正式建立外交关系（1972 年 9 月）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-3-g2","type":"choice","stem":"下列关于「推进国防军队建设和外交工作」的表述，错误的是","answer":"A","explain":"认为 1972 年中美签署《联合公报》就是中美建交——「开始走向正常化」与「正式建交」相隔七年，是高频错项。正确表述：1972 年尼克松访华、中美签署《联合公报》，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","options":["认为 1972 年中美签署《联合公报》就是中美建交。","1972 年尼克松访华、中美签署《联合公报》，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","和平共处五项原则标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生了深远影响。","1971 年恢复中华人民共和国在联合国的一切合法权利，是中国外交的重大胜利，也是广大发展中国家支持的结果；中国是联合国创始会员国和安理会常任理事国。"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：坚持走中国特色强军之路，推进机械化信息化复合发展，提高国防和军队现代化水平。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"推进国防军队建设和外交工作；和平共处五项原则：互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处。1953 年 12 月周恩来在接见印度代表团时首次提出，1954 年在中印、中缅联合声明中确立为指导相互关系的基本原则。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-8b-6-1","title":"第18课 擘画中国梦宏伟蓝图","subtitle":"八年级下册 · 第六单元 中国特色社会主义进入新时代","grade":"8b","tags":["八年级下册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第六单元 中国特色社会主义进入新时代"},{"k":"课时","v":"第18课 擘画中国梦宏伟蓝图"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"2012 年 11 月，习近平在参观《复兴之路》展览时提出实现中华民族伟大复兴的中国梦，强调「两个一百年」奋斗目标。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["2012 年","中共十八大召开","十八大以来，中国特色社会主义进入新时代"],["2017 年","中共十九大召开，把习近平新时代中国特色社会主义思想确立为党的指导思想","我国社会主要矛盾已转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"2012 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"中共十八大召开","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"2017 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"中共十九大召开，把习近平新时代中国特…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"按「会议—理论—地位」配对记忆；习近平新时代中国特色社会主义思想在中共十九大写入党章、2018 年写入宪法。"},{"level":"重点","text":"中共十八大以来，中国特色社会主义进入新时代；2021 年中国共产党成立 100 周年，我国全面建成小康社会，实现第一个百年奋斗目标，历史性地解决了绝对贫困问题；中共二十大提出以中国式现代化全面推进中华民族伟大复兴。","explain":"要注意「全面建成小康社会」与「全面建成社会主义现代化强国」的时间区别：前者 2021 年已实现，后者是本世纪中叶的目标。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。","中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。"],["认为经济特区就是特别行政区。","经济特区是实行特殊经济政策和经济管理体制的区域，仍然实行社会主义制度；特别行政区则按「一国两制」保留原有的资本主义制度和生活方式。","「特区」与「特别行政区」一字之差，性质完全不同，也常与第 4 单元的港澳问题联合设题。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["中国梦：实现中华民族伟大复兴，是近代以来中华民族最伟大的梦想，基本内涵是国家富强、民族振兴、人民幸福。 出处：习近平《在参观〈复兴之路〉展览时的讲话》","两个一百年：到中国共产党成立一百年时全面建成小康社会，到新中国成立一百年时建成富强民主文明和谐美丽的社会主义现代化强国。 出处：中共十九大报告"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；习近平《在参观〈复兴之路〉展览时的讲话》","2024 部编版八下第 18 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8b-u3-q6","type":"choice","stem":"把习近平新时代中国特色社会主义思想确立为党的指导思想的会议是","answer":"B","explain":"2017 年中共十九大把习近平新时代中国特色社会主义思想确立为党的指导思想；中共十八大以来，中国特色社会主义进入新时代；中共二十大提出以中国式现代化全面推进中华民族伟大复兴。","options":["中共十八大","中共十九大","中共二十大","中共十八届三中全会"],"tags":["中共十九大","理论体系"]},{"id":"cat-8b-6-1-g2","type":"choice","stem":"下列关于「擘画中国梦宏伟蓝图」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。","中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。"],"difficulty":2,"tags":["八年级下册","第六单元","本课练习"]},{"id":"cat-8b-6-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：实现中华民族伟大复兴，是近代以来中华民族最伟大的梦想，基本内涵是国家富强、民族振兴、人民幸福。（习近平《在参观〈复兴之路〉展览时的讲话》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"擘画中国梦宏伟蓝图；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自习近平《在参观〈复兴之路〉展览时的讲话》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-6-1-g5","type":"choice","stem":"「中共十八大召开」发生于","answer":"A","explain":"本课时间轴：中共十八大召开（2012 年）。十八大以来，中国特色社会主义进入新时代。其余三个时间是同一单元相邻课时的事件时间。","options":["2012 年","2017 年","2021 年","2022 年"],"difficulty":1,"tags":["八年级下册","第六单元","本课练习"]},{"id":"cat-8b-6-1-g7","type":"choice","stem":"关于「擘画中国梦宏伟蓝图」，下列表述正确的有\n① 改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中…\n② 中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要…\n③ 中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表…\n④ 认为家庭联产承包责任制是把土地分给农民个人所有。","answer":"A","explain":"①②③均取本课必背结论与考点；④错误——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」，正确表述应为：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["八年级下册","第六单元","本课练习"]}]},{"id":"cat-8b-6-2","title":"第19课 （课题以新版教材实际编排为准）","subtitle":"八年级下册 · 第六单元 中国特色社会主义进入新时代","grade":"8b","tags":["八年级下册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第六单元 中国特色社会主义进入新时代"},{"k":"课时","v":"第19课 （课题以新版教材实际编排为准）"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"中共十八大以来，中国特色社会主义进入新时代。2021 年，中国全面建成小康社会，历史性地解决了绝对贫困问题。2022 年中共二十大提出以中国式现代化全面推进中华民族伟大复兴。"},{"type":"note","title":"本课主线 · 因果链","text":"1978 年中共十一届三中全会实现伟大转折，开启了改革开放和社会主义现代化建设新时期；农村改革与经济特区先行，1992 年南方谈话和中共十四大确立社会主义市场经济体制的目标，中国特色社会主义理论体系逐步形成；中共十八大以来中国特色社会主义进入新时代，2021 年我国全面建成小康社会、实现第一个百年奋斗目标。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["2012 年","中共十八大召开","十八大以来，中国特色社会主义进入新时代"],["2017 年","中共十九大召开，把习近平新时代中国特色社会主义思想确立为党的指导思想","我国社会主要矛盾已转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"],["2021 年","中国共产党成立 100 周年，我国全面建成小康社会，实现第一个百年奋斗目标","脱贫攻坚战取得全面胜利，历史性地解决了绝对贫困问题 · 重点"],["2022 年","中共二十大召开","提出以中国式现代化全面推进中华民族伟大复兴"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"2012 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"中共十八大召开","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"2017 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"中共十九大召开，把习近平新时代中国特…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"2021 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"中国共产党成立 100 周年，我国全…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"2022 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"中共二十大召开","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"按「会议—理论—地位」配对记忆；习近平新时代中国特色社会主义思想在中共十九大写入党章、2018 年写入宪法。"},{"level":"重点","text":"中共十八大以来，中国特色社会主义进入新时代；2021 年中国共产党成立 100 周年，我国全面建成小康社会，实现第一个百年奋斗目标，历史性地解决了绝对贫困问题；中共二十大提出以中国式现代化全面推进中华民族伟大复兴。","explain":"要注意「全面建成小康社会」与「全面建成社会主义现代化强国」的时间区别：前者 2021 年已实现，后者是本世纪中叶的目标。"},{"level":"次重点","text":"脱贫攻坚战取得全面胜利：现行标准下 9899 万农村贫困人口全部脱贫，832 个贫困县全部摘帽，12.8 万个贫困村全部出列，创造了人类减贫史上的奇迹。","explain":"数据出自 2021 年全国脱贫攻坚总结表彰大会的权威表述，答题时可引用，但要与「全面建成小康社会」放在同一时间节点上。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为我国已经建成社会主义现代化强国。","2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","「全面建成小康社会」与「全面建成社会主义现代化强国」阶段不同，表述不能互换。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["伟大转折与制度创新","以十一届三中全会公报、小岗村契约等材料设问，考「思想路线—工作中心—历史意义」三步，落脚在「伟大转折」与「新时期」。"],["改革开放与人民生活变迁","把家庭联产承包责任制、经济特区、加入世界贸易组织的材料排成时间轴，要求概括改革开放的进程与作用，常与第 6 单元的社会生活变迁合并成大题。"],["新时代与中国式现代化","以脱贫攻坚、全面建成小康社会的材料设问，考「十八大以来的历史性成就」与「中国式现代化」，要求联系道路自信、理论自信、制度自信、文化自信。"],["理论体系与指导思想","按会议与理论配对（十五大—邓小平理论、十九大—习近平新时代中国特色社会主义思想），考「马克思主义中国化时代化」的线索。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：改革开放与基本路线；地理：经济特区与沿海开放格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["脱贫攻坚：2013 年提出精准扶贫，到 2020 年底，现行标准下 9899 万农村贫困人口全部脱贫，832 个贫困县全部摘帽。 出处：《中国共产党简史》；全国脱贫攻坚总结表彰大会","中国式现代化：是人口规模巨大的现代化、全体人民共同富裕的现代化、物质文明和精神文明相协调的现代化、人与自然和谐共生的现代化、走和平发展道路的现代化。 出处：中共二十大报告"]},{"type":"list","title":"本课拓展出处","items":["《中国共产党简史》；中共二十大报告","2024 部编版八下第 19 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中国共产党百年历程与道路选择","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-03"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h8b-u3-q5","type":"choice","stem":"2021 年我国取得的重大成就是","answer":"D","explain":"2021 年中国共产党成立 100 周年，我国全面建成小康社会，历史性地解决了绝对贫困问题，实现了第一个百年奋斗目标。加入世界贸易组织是 2001 年，建成社会主义现代化强国是本世纪中叶的目标。","options":["加入世界贸易组织","建成社会主义现代化强国","基本实现社会主义现代化","全面建成小康社会，实现第一个百年奋斗目标"],"tags":["新时代","家国情怀"]},{"id":"h8b-u3-q6","type":"choice","stem":"把习近平新时代中国特色社会主义思想确立为党的指导思想的会议是","answer":"B","explain":"2017 年中共十九大把习近平新时代中国特色社会主义思想确立为党的指导思想；中共十八大以来，中国特色社会主义进入新时代；中共二十大提出以中国式现代化全面推进中华民族伟大复兴。","options":["中共十八大","中共十九大","中共二十大","中共十八届三中全会"],"tags":["中共十九大","理论体系"]},{"id":"cat-8b-6-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中共十八大召开\n② 中共十九大召开，把习近平新时代中国特色社会主义思…\n③ 中国共产党成立 100 周年，我国全面建成小康社…\n④ 中共二十大召开","answer":"A","explain":"按时间顺序应为：①中共十八大召开（2012 年）→②中共十九大召开，把习近平新时代中国特色社会主义思想确立为党的指导思想（2017 年）→③中国共产党成立 100 周年，我国全面建成小康社会，实现第一个百年奋斗目标（2021 年）→④中共二十大召开（2022 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第六单元","本课练习"]},{"id":"cat-8b-6-2-g2","type":"choice","stem":"下列关于「（课题以新版教材实际编排为准）」的表述，错误的是","answer":"A","explain":"认为我国已经建成社会主义现代化强国——「全面建成小康社会」与「全面建成社会主义现代化强国」阶段不同，表述不能互换。正确表述：2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","options":["认为我国已经建成社会主义现代化强国。","2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。","中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。"],"difficulty":2,"tags":["八年级下册","第六单元","本课练习"]},{"id":"cat-8b-6-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：2013 年提出精准扶贫，到 2020 年底，现行标准下 9899 万农村贫困人口全部脱贫，832 个贫困县全部摘帽。（《中国共产党简史》；全国脱贫攻坚总结表彰大会）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"（课题以新版教材实际编排为准）；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自《中国共产党简史》；全国脱贫攻坚总结表彰大会。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]}];
